                    ulong index;
                    var leftOverride = false;
                    var rightOverride = false;
                    if (!hasRight || (hasLeft && comparison < 0))
                    {
                        index = leftKey;
                        leftOverride = true;
                        leftIndex++;
                        leftLoaded = false;
                    }
                    else if (!hasLeft || comparison > 0)
                    {
                        index = rightKey;
                        rightOverride = true;
                        rightIndex++;
                        rightLoaded = false;
                    }
                    else
