                        new BigInteger(TemplateBytes.Length));
                    var mergedBytes = MeetPayload(leftValue, rightValue);
                    ChargeWork();
                    var equalsTemplate = PayloadEquals(
                        mergedBytes, mergedTemplate);
                    if (!equalsTemplate)
                    {
                        ChargeWork(9);
                        emit(index, mergedBytes, candidateScratch);
                    }
                }
            }

