        internal bool TryGetGenericUniqueProperty(int formalOrdinal,
            out bool isUnique) =>
            _genericUniqueProperties.TryGetValue(formalOrdinal,
                out isUnique);

        internal void SetGenericUniqueProperty(int formalOrdinal,
            bool isUnique)
        {
            if (formalOrdinal < 0)
            {
                throw Invalid();
            }
            _genericUniqueProperties[formalOrdinal] = isUnique;
        }

        internal void CopyGenericUniqueProperties(
            InitializationState source)
        {
            _genericUniqueProperties.Clear();
            foreach (var (ordinal, isUnique)
                in source._genericUniqueProperties)
            {
                _genericUniqueProperties.Add(ordinal, isUnique);
            }
        }

        internal bool TryGetBooleanValue(int variable, out bool value)
        {
            if (_booleanValues is not null
                && (uint)variable < (uint)_booleanValues.Length
                && _booleanValues[variable] is 0 or 1)
            {
                value = _booleanValues[variable] == 1;
                return true;
            }

            value = false;
            return false;
        }

        internal void SetBooleanValue(int variable, bool value)
        {
            if (_booleanValues is not null
                && (uint)variable < (uint)_booleanValues.Length)
            {
                _booleanValues[variable] = value ? (sbyte)1 : (sbyte)0;
            }
        }

        internal void JoinBooleanValues(InitializationState left,
            bool leftCompletes, InitializationState right,
            bool rightCompletes)
        {
            if (_booleanValues is null)
            {
                return;
            }
            if (!leftCompletes && !rightCompletes)
            {
                Array.Fill(_booleanValues, (sbyte)-1);
                return;
            }
            if (!rightCompletes)
            {
                Array.Copy(left._booleanValues!, _booleanValues,
                    _booleanValues.Length);
                return;
            }
            if (!leftCompletes)
            {
                Array.Copy(right._booleanValues!, _booleanValues,
                    _booleanValues.Length);
                return;
            }

            for (var index = 0; index < _booleanValues.Length; index++)
            {
                var leftValue = left._booleanValues![index];
                var rightValue = right._booleanValues![index];
                _booleanValues[index] = leftValue == rightValue
                    ? leftValue : (sbyte)-1;
            }
        }

        internal void AddConditionalInitializedTarget(
            BoundExpression condition, bool result,
            ProvenanceAnchor target)
        {
            if (!TracksConditionalOutputReadFacts
                || condition.Type != PrimitiveType.Bool
                || target.Kind is not (
                    ProvenanceAnchorKind.IncomingReference
                    or ProvenanceAnchorKind.IncomingReferencePlace
                    or ProvenanceAnchorKind.IncomingReferenceField))
            {
                throw Invalid();
            }

            _conditionalInitializedTargets ??= new(
                ReferenceEqualityComparer.Instance);
            if (!_conditionalInitializedTargets.TryGetValue(condition,
                out var targets))
            {
                targets = [[], []];
                _conditionalInitializedTargets.Add(condition, targets);
            }
            targets[result ? 1 : 0].Add(target);
        }

        internal Dictionary<BoundExpression,
            HashSet<ProvenanceAnchor>[]>? ConditionalInitializedTargets
            => _conditionalInitializedTargets;

        internal void ClearConditionalInitializedTargets()
            => _conditionalInitializedTargets = null;

        internal void JoinConditionalInitializedTargets(
            InitializationState left, bool leftCompletes,
            InitializationState right, bool rightCompletes)
        {
            if (!leftCompletes && !rightCompletes)
            {
                ClearConditionalInitializedTargets();
                return;
            }
            if (!rightCompletes)
            {
                CopyConditionalInitializedTargets(left);
                return;
            }
            if (!leftCompletes)
            {
                CopyConditionalInitializedTargets(right);
                return;
            }

            var joined = new Dictionary<BoundExpression,
                HashSet<ProvenanceAnchor>[]>(
                    ReferenceEqualityComparer.Instance);
            if (left._conditionalInitializedTargets is not null
                && right._conditionalInitializedTargets is not null)
            {
                foreach (var (condition, leftTargets)
                    in left._conditionalInitializedTargets)
                {
                    if (!right._conditionalInitializedTargets.TryGetValue(
                        condition, out var rightTargets))
                    {
                        continue;
                    }

                    var commonTargets = new[] {
                        new HashSet<ProvenanceAnchor>(leftTargets[0]),
                        new HashSet<ProvenanceAnchor>(leftTargets[1]),
                    };
                    commonTargets[0].IntersectWith(rightTargets[0]);
                    commonTargets[1].IntersectWith(rightTargets[1]);
                    if (commonTargets[0].Count != 0
                        || commonTargets[1].Count != 0)
                    {
                        joined.Add(condition, commonTargets);
                    }
                }
            }
            _conditionalInitializedTargets = joined.Count == 0
                ? null : joined;
        }

        private void CopyConditionalInitializedTargets(
            InitializationState source)
        {
            _conditionalInitializedTargets = null;
            if (source._conditionalInitializedTargets is null)
            {
                return;
            }

            _conditionalInitializedTargets = new(
                ReferenceEqualityComparer.Instance);
            foreach (var (condition, targets)
                in source._conditionalInitializedTargets)
            {
                _conditionalInitializedTargets.Add(condition, [
                    new HashSet<ProvenanceAnchor>(targets[0]),
                    new HashSet<ProvenanceAnchor>(targets[1]),
                ]);
            }
        }

        internal void MergeGenericUniqueProperties(
            InitializationState left, InitializationState right)
        {
            var common = new List<KeyValuePair<int, bool>>();
            foreach (var (ordinal, isUnique)
                in left._genericUniqueProperties)
            {
                if (right._genericUniqueProperties.TryGetValue(ordinal,
                    out var rightIsUnique)
                    && rightIsUnique == isUnique)
                {
                    common.Add(new KeyValuePair<int, bool>(ordinal,
                        isUnique));
                }
            }
            _genericUniqueProperties.Clear();
            foreach (var (ordinal, isUnique) in common)
            {
                _genericUniqueProperties.Add(ordinal, isUnique);
            }
        }

        internal InitializationState(BoundProgram program, int length,
            bool hasNativeOutputContracts, bool hasDoesNotReturnFunctions,
            bool tracksConditionalOutputReadFacts)
            : this(program, length, new Dictionary<BoundExpression, byte>(ReferenceEqualityComparer.Instance),
                new Dictionary<BoundExpression, byte>(ReferenceEqualityComparer.Instance),
                new Dictionary<BoundExpression, byte>(ReferenceEqualityComparer.Instance),
                new Dictionary<BoundExpression, bool>(ReferenceEqualityComparer.Instance),
                new Dictionary<BoundExpression, byte>(ReferenceEqualityComparer.Instance),
                new Dictionary<BoundExpression, byte>(ReferenceEqualityComparer.Instance),
                new Dictionary<BoundCall, bool>(ReferenceEqualityComparer.Instance),
                new Dictionary<BoundCall,
                    InitializationPostconditionCallFact>(
                        ReferenceEqualityComparer.Instance),
                hasNativeOutputContracts, hasDoesNotReturnFunctions,
                tracksConditionalOutputReadFacts,
                new FieldGenerationContext(), new Dictionary<FieldGenerationKey, long>(),
                new Dictionary<NestedOwnerStateKey, NestedOwnerFieldState>())
        {
        }

        private InitializationState(BoundProgram program, int length,
            Dictionary<BoundExpression, byte> canBeFacts, Dictionary<BoundExpression, byte> flowFacts,
            Dictionary<BoundExpression, byte> completionShapeFacts,
            Dictionary<BoundExpression, bool> completionFacts,
            Dictionary<BoundExpression, byte> nativeOutputFlowFacts,
            Dictionary<BoundExpression, byte>
                initializationPostconditionFlowShapes,
            Dictionary<BoundCall, bool>
                initializationPostconditionCallCandidates,
            Dictionary<BoundCall,
                InitializationPostconditionCallFact>
                initializationPostconditionCallFactSnapshots,
            bool hasNativeOutputContracts, bool hasDoesNotReturnFunctions,
            bool tracksConditionalOutputReadFacts,
            FieldGenerationContext fieldGenerationContext,
            Dictionary<FieldGenerationKey, long> fieldPlaceGenerations,
            Dictionary<NestedOwnerStateKey, NestedOwnerFieldState> nestedOwnerStates)
        {
            Program = program;
            HasNativeOutputContracts = hasNativeOutputContracts;
            HasDoesNotReturnFunctions = hasDoesNotReturnFunctions;
            TracksConditionalOutputReadFacts
                = tracksConditionalOutputReadFacts;
            _booleanValues = tracksConditionalOutputReadFacts
                ? new sbyte[length] : null;
            if (_booleanValues is not null)
            {
                Array.Fill(_booleanValues, (sbyte)-1);
            }
            _possibilities = new byte[length];
            _possibleFieldMasks = new uint[length];
            _staticFieldPossibilities
                = new byte[program.StaticFields.Length];
            _fieldGenerationContext = fieldGenerationContext;
            _fieldPlaceGenerations = fieldPlaceGenerations;
            _nestedOwnerStates = nestedOwnerStates;
            _canBeFacts = canBeFacts;
            _flowFacts = flowFacts;
            _completionShapeFacts = completionShapeFacts;
            _completionFacts = completionFacts;
            _nativeOutputFlowFacts = nativeOutputFlowFacts;
            _initializationPostconditionFlowShapes
                = initializationPostconditionFlowShapes;
            _initializationPostconditionCallCandidates
                = initializationPostconditionCallCandidates;
            _initializationPostconditionCallFactSnapshots
                = initializationPostconditionCallFactSnapshots;
            _integerSymbols = new long[length];
            _nativeOutputDestinations = new NativeOutputDestinationState?[length];
            _nativeOutputResults = new NativeOutputCallFact?[length];
            _initializationPostconditionResults
                = new InitializationPostconditionCallFact?[length];
            _initializationPostconditionAliasFacts
                = new InitializationPostconditionAliasFact?[length];
            Array.Fill(_possibilities, (byte)1);
            Array.Fill(_staticFieldPossibilities, (byte)1);
        }

        internal int Length => _possibilities.Length;
        internal uint[] PossibleFieldMasks => _possibleFieldMasks;
        internal Dictionary<BoundExpression, byte> CanBeFacts => _canBeFacts;
        internal Dictionary<BoundExpression, byte> FlowFacts => _flowFacts;
        internal Dictionary<BoundExpression, byte> CompletionShapeFacts
            => _completionShapeFacts;
        internal Dictionary<BoundExpression, bool> CompletionFacts => _completionFacts;

        internal void InitializeIntegerFacts(BoundFunction function)
        {
            if (function.Variables.Length != Length)
            {
                throw Invalid();
            }
            TracksIntegerFacts = RequiresNoFailureProof(function);
            if (!TracksIntegerFacts)
            {
                return;
            }
            for (var variable = 0; variable < function.Variables.Length;
                variable++)
            {
                var type = function.Variables[variable].Type;
                if (!TryGetIntegerTypeRange(type, out var range))
                {
                    continue;
                }
                SetIntegerValue(variable, type, range, null);
            }
            if (TryGetIntegerTypeRange(PrimitiveType.Int32,
                    out var lengthRange))
            {
                for (var buffer = 0; buffer < Program.Buffers.Length;
                    buffer++)
                {
                    var symbol = Interlocked.Increment(
                        ref s_integerSymbolId);
                    _bufferLengthSymbols.Add(buffer, symbol);
                    _integerSymbolTypes.Add(symbol, PrimitiveType.Int32);
                    _integerSymbolRanges.Add(symbol, new IntegerInterval(
                        BigInteger.Zero, lengthRange.Upper));
                }
            }
        }

        internal bool TryGetIntegerSymbol(int variable,
            out long symbol, out PrimitiveType type)
        {
            if ((uint)variable < (uint)_integerSymbols.Length
                && _integerSymbols[variable] is long found and not 0
                && _integerSymbolTypes.TryGetValue(found, out type))
            {
                symbol = found;
                return true;
            }
            symbol = 0;
            type = default;
            return false;
        }

        internal bool TryGetIntegerSymbolType(long symbol,
            out PrimitiveType type) =>
            _integerSymbolTypes.TryGetValue(symbol, out type);

        internal bool TryGetIntegerSymbolRange(long symbol,
            out IntegerInterval range) =>
            _integerSymbolRanges.TryGetValue(symbol, out range);

        internal bool TryGetIntegerSymbolDefinition(long symbol,
            out IntegerLinearExpression expression) =>
            _integerSymbolDefinitions.TryGetValue(symbol, out expression!);

        internal bool TryGetBufferLengthSymbol(int buffer, out long symbol) =>
            _bufferLengthSymbols.TryGetValue(buffer, out symbol);

        internal void SetIntegerValue(int variable, PrimitiveType type,
            IntegerInterval? range, IntegerLinearExpression? definition)
        {
            if ((uint)variable >= (uint)_integerSymbols.Length)
            {
                throw Invalid();
            }
            if (!TracksIntegerFacts)
            {
                return;
            }
            if (!TryGetIntegerTypeRange(type, out var typeRange))
            {
                _integerSymbols[variable] = 0;
                return;
            }

            var symbol = Interlocked.Increment(ref s_integerSymbolId);
            _integerSymbols[variable] = symbol;
            _integerSymbolTypes[symbol] = type;
            _integerSymbolRanges[symbol] = range is IntegerInterval value
                ? IntersectIntegerInterval(value, typeRange) ?? typeRange
                : typeRange;
            if (definition is not null)
            {
                _integerSymbolDefinitions[symbol] = definition;
            }
        }

        internal void AssignIntegerValue(int variable, PrimitiveType type,
            IntegerValueFacts facts) =>
            SetIntegerValue(variable, type, facts.Range,
                facts.LinearExpression);

        internal IntegerValueFacts CaptureIntegerValue(
            BoundExpression value, ref int remaining)
        {
            if (!TracksIntegerFacts)
            {
                return default;
            }
            var hasRange = TryGetIntegerInterval(value, this, ref remaining,
                out var range);
            var hasLinearExpression = TryGetIntegerLinearExpression(value,
                this, out var linearExpression);
            return new IntegerValueFacts(hasRange ? range : null,
                hasLinearExpression ? linearExpression : null);
        }

        internal IntegerLinearExpression CreateIntegerSymbolForm(int variable)
        {
            if (!TryGetIntegerSymbol(variable, out var symbol, out _))
            {
                throw Invalid();
            }
            return CreateIntegerLinearExpression(
                ImmutableDictionary<long, BigInteger>.Empty.Add(symbol,
                    BigInteger.One), BigInteger.Zero);
        }

        internal void AddIntegerConstraint(
            IntegerLinearExpression expression, ref int remaining)
        {
            if (!TracksIntegerFacts)
            {
                return;
            }
            if (_integerConstraints.Count >= 1024
                || _integerConstraints.Any(constraint =>
                    AreEquivalent(constraint.Expression, expression)))
            {
                return;
            }
            Count(ref remaining, 0);
            _integerConstraints.Add(new IntegerLinearConstraint(expression));
            PropagateIntegerConstraints(ref remaining);
        }

        internal void ExcludeIntegerEndpoint(long symbol, BigInteger value,
            ref int remaining)
        {
            if (!TracksIntegerFacts)
            {
                return;
            }
            Count(ref remaining, 0);
            if (!_integerSymbolRanges.TryGetValue(symbol, out var current))
            {
                return;
            }
            if (value == current.Lower)
            {
                current = current with {
                    Lower = current.Lower + BigInteger.One,
                };
            }
            else if (value == current.Upper)
            {
                current = current with {
                    Upper = current.Upper - BigInteger.One,
                };
            }
            if (current.Lower <= current.Upper)
            {
                _integerSymbolRanges[symbol] = current;
                PropagateIntegerConstraints(ref remaining);
            }
        }

        internal bool TryProveIntegerExpressionWithin(
            IntegerLinearExpression expression, PrimitiveType type,
            ref int remaining)
        {
            if (!TracksIntegerFacts
                || !TryGetIntegerTypeRange(type, out var requiredRange))
            {
                return false;
            }
            if (!TryGetLinearInterval(expression, this, ref remaining,
                    out var range))
            {
                return false;
            }
            if (range.Lower >= requiredRange.Lower
                && range.Upper <= requiredRange.Upper)
            {
                return true;
            }
            var lower = range.Lower;
            var upper = range.Upper;
            foreach (var constraint in _integerConstraints)
            {
                Count(ref remaining, 0);
                if (TryGetUpperBoundFromConstraint(expression,
                        constraint.Expression, this, out var constrainedUpper))
                {
                    upper = BigInteger.Min(upper, constrainedUpper);
                }
                var negated = NegateIntegerLinearExpression(expression);
                if (TryGetUpperBoundFromConstraint(negated,
                        constraint.Expression, this, out var negatedUpper))
                {
                    lower = BigInteger.Max(lower, -negatedUpper);
                }
            }
            return lower >= requiredRange.Lower
                && upper <= requiredRange.Upper;
        }

        internal bool TryProveIntegerExpressionAtMost(
            IntegerLinearExpression expression, BigInteger maximum,
            ref int remaining)
        {
            if (!TracksIntegerFacts
                || !TryGetLinearInterval(expression, this,
                    ref remaining, out var range))
            {
                return false;
            }
            var upper = range.Upper;
            foreach (var constraint in _integerConstraints)
            {
                Count(ref remaining, 0);
                if (TryGetUpperBoundFromConstraint(expression,
                        constraint.Expression, this, out var constrainedUpper))
                {
                    upper = BigInteger.Min(upper, constrainedUpper);
                }
            }
            return upper <= maximum;
        }

        internal void HavocIntegerVariable(int variable, PrimitiveType type)
        {
            if (!TracksIntegerFacts)
            {
                return;
            }
            SetIntegerValue(variable, type, null, null);
        }

        internal void HavocIntegerValues()
        {
            if (!TracksIntegerFacts)
            {
                return;
            }
            _integerSymbolDefinitions.Clear();
            _integerConstraints.Clear();
            for (var variable = 0; variable < Length; variable++)
            {
                if (TryGetIntegerSymbol(variable, out _, out var type))
                {
                    SetIntegerValue(variable, type, null, null);
                }
            }
        }

        private void PropagateIntegerConstraints(ref int remaining)
        {
            var maximumPasses = Math.Min(8, _integerConstraints.Count);
            for (var pass = 0; pass < maximumPasses; pass++)
            {
                var changed = false;
                foreach (var constraint in _integerConstraints)
                {
                    foreach (var (symbol, coefficient)
                        in constraint.Expression.Coefficients)
                    {
                        Count(ref remaining, 0);
                        if (coefficient.IsZero
                            || !_integerSymbolRanges.TryGetValue(symbol,
                                out var currentRange))
                        {
                            continue;
                        }

                        var restMinimum = constraint.Expression.Constant;
                        foreach (var (otherSymbol, otherCoefficient)
                            in constraint.Expression.Coefficients)
                        {
                            if (otherSymbol == symbol)
                            {
                                continue;
                            }
                            Count(ref remaining, 0);
                            if (!_integerSymbolRanges.TryGetValue(otherSymbol,
                                    out var otherRange))
                            {
                                continue;
                            }
                            restMinimum += otherCoefficient.Sign >= 0
                                ? otherCoefficient * otherRange.Lower
                                : otherCoefficient * otherRange.Upper;
                        }

                        var nextRange = currentRange;
                        if (coefficient.Sign > 0)
                        {
                            var maximum = FloorDivide(-restMinimum,
                                coefficient);
                            nextRange = nextRange with {
                                Upper = BigInteger.Min(nextRange.Upper,
                                    maximum),
                            };
                        }
                        else
                        {
                            var minimum = CeilingDivide(restMinimum,
                                BigInteger.Negate(coefficient));
                            nextRange = nextRange with {
                                Lower = BigInteger.Max(nextRange.Lower,
                                    minimum),
                            };
                        }

                        if (nextRange.Lower > nextRange.Upper)
                        {
                            ResetIntegerSymbolRanges();
                            return;
                        }
                        if (nextRange != currentRange)
                        {
                            _integerSymbolRanges[symbol] = nextRange;
                            changed = true;
                        }
                    }
                }
                if (!changed)
                {
                    return;
                }
            }
        }

        private void ResetIntegerSymbolRanges()
        {
            _integerConstraints.Clear();
            foreach (var (symbol, type) in _integerSymbolTypes)
            {
                if (TryGetIntegerTypeRange(type, out var range))
                {
                    _integerSymbolRanges[symbol] = range;
                }
            }
        }

        internal void CopyIntegerFacts(InitializationState source)
        {
            TracksIntegerFacts = source.TracksIntegerFacts;
            Array.Copy(source._integerSymbols, _integerSymbols,
                _integerSymbols.Length);
            if (!TracksIntegerFacts)
            {
                _integerSymbolTypes.Clear();
                _integerSymbolRanges.Clear();
                _integerSymbolDefinitions.Clear();
                _integerConstraints.Clear();
                return;
            }
            _integerSymbolTypes.Clear();
            foreach (var entry in source._integerSymbolTypes)
            {
                _integerSymbolTypes.Add(entry.Key, entry.Value);
            }
            _integerSymbolRanges.Clear();
            foreach (var entry in source._integerSymbolRanges)
            {
                _integerSymbolRanges.Add(entry.Key, entry.Value);
            }
            _integerSymbolDefinitions.Clear();
            foreach (var entry in source._integerSymbolDefinitions)
            {
                _integerSymbolDefinitions.Add(entry.Key, entry.Value);
            }
            _integerConstraints = [.. source._integerConstraints];
            _bufferLengthSymbols.Clear();
            foreach (var entry in source._bufferLengthSymbols)
            {
                _bufferLengthSymbols.Add(entry.Key, entry.Value);
            }
        }

        internal void MergeIntegerFacts(InitializationState other)
        {
            if (!TracksIntegerFacts || !other.TracksIntegerFacts)
            {
                return;
            }
            for (var index = 0; index < _integerSymbols.Length; index++)
            {
                MergeIntegerSymbol(index, other);
            }
            MergeIntegerMetadata(other);
        }

        internal bool MergeIntegerFactsForLoop(
            InitializationState entryState,
            InitializationState? backState,
            BoundFunction function,
            HashSet<int> priorDeclarations)
        {
            if (!TracksIntegerFacts || !entryState.TracksIntegerFacts
                || (backState is not null
                    && !backState.TracksIntegerFacts))
            {
                return false;
            }
            var oldSymbols = (long[])_integerSymbols.Clone();
            var oldRanges = new Dictionary<long, IntegerInterval>(
                _integerSymbolRanges);
            var oldTypes = new Dictionary<long, PrimitiveType>(
                _integerSymbolTypes);
            CopyIntegerFacts(entryState);
            var changed = false;
            for (var variable = 0; variable < _integerSymbols.Length;
                variable++)
            {
                var localToIteration
                    = variable >= function.ParameterCount
                        + (function.IsConstructor ? 1 : 0)
                    && !priorDeclarations.Contains(variable);
                var entrySymbol = entryState._integerSymbols[variable];
                var backSymbol = backState?._integerSymbols[variable]
                    ?? entrySymbol;
                if (localToIteration || entrySymbol == 0
                    || backSymbol == 0)
                {
                    if (_integerSymbols[variable] != 0)
                    {
                        changed = true;
                    }
                    _integerSymbols[variable] = 0;
                    continue;
                }

                if (entrySymbol == backSymbol)
                {
                    _integerSymbols[variable] = entrySymbol;
                    var entryRange = entryState._integerSymbolRanges[
                        entrySymbol];
                    var backRange = backState is null
                        ? entryRange
                        : backState._integerSymbolRanges[backSymbol];
                    var joined = new IntegerInterval(
                        BigInteger.Min(entryRange.Lower, backRange.Lower),
                        BigInteger.Max(entryRange.Upper, backRange.Upper));
                    _integerSymbolRanges[entrySymbol] = joined;
                    changed |= oldSymbols[variable] != entrySymbol
                        || !oldRanges.TryGetValue(entrySymbol,
                            out var previousRange)
                        || previousRange != joined;
                    continue;
                }

                if (!entryState._integerSymbolTypes.TryGetValue(entrySymbol,
                        out var type)
                    || !TryGetIntegerTypeRange(type, out var typeRange))
                {
                    throw Invalid();
                }
                var widenedSymbol = oldSymbols[variable];
                if (widenedSymbol == entrySymbol
                    || widenedSymbol == backSymbol
                    || !oldTypes.TryGetValue(widenedSymbol,
                        out var widenedType)
                    || widenedType != type
                    || !oldRanges.TryGetValue(widenedSymbol,
                        out var previousWidenedRange)
                    || previousWidenedRange != typeRange)
                {
                    widenedSymbol = Interlocked.Increment(
                        ref s_integerSymbolId);
                }
                _integerSymbols[variable] = widenedSymbol;
                _integerSymbolTypes[widenedSymbol] = type;
                _integerSymbolRanges[widenedSymbol] = typeRange;
                _ = _integerSymbolDefinitions.Remove(widenedSymbol);
                changed |= oldSymbols[variable] != widenedSymbol
                    || !oldRanges.TryGetValue(widenedSymbol,
                        out var oldWidenedRange)
                    || oldWidenedRange != typeRange;
            }

            if (backState is not null)
            {
                MergeIntegerMetadata(backState);
            }
            return changed;
        }

        internal bool TryGetNativeOutputFlowEffect(BoundExpression expression, out bool hasEffect)
        {
            if (_nativeOutputFlowFacts.TryGetValue(expression, out var facts)
                && (facts & NativeOutputFlowAnalyzedFact) != 0)
            {
                hasEffect = (facts & NativeOutputFlowEffectFact) != 0;
                return true;
            }
            hasEffect = false;
            return false;
        }

        internal void RecordNativeOutputFlowEffect(BoundExpression expression, bool hasEffect)
        {
            _ = _nativeOutputFlowFacts.TryGetValue(expression,
                out var facts);
            _nativeOutputFlowFacts[expression] = (byte)(
                (facts & ~(NativeOutputFlowAnalyzedFact
                    | NativeOutputFlowEffectFact))
                | NativeOutputFlowAnalyzedFact
                | (hasEffect ? NativeOutputFlowEffectFact : 0));
        }

        internal bool TryGetNativePointerExtentFlowEffect(
            BoundExpression expression, out bool hasEffect)
        {
            if (_nativeOutputFlowFacts.TryGetValue(expression,
                    out var facts)
                && (facts & NativePointerExtentFlowAnalyzedFact) != 0)
            {
                hasEffect = (facts
                    & NativePointerExtentFlowEffectFact) != 0;
                return true;
            }
            hasEffect = false;
            return false;
        }

        internal void RecordNativePointerExtentFlowEffect(
            BoundExpression expression, bool hasEffect)
        {
            _ = _nativeOutputFlowFacts.TryGetValue(expression,
                out var facts);
            _nativeOutputFlowFacts[expression] = (byte)(
                (facts & ~(NativePointerExtentFlowAnalyzedFact
                    | NativePointerExtentFlowEffectFact))
                | NativePointerExtentFlowAnalyzedFact
                | (hasEffect
                    ? NativePointerExtentFlowEffectFact : 0));
        }

        internal void Fill(bool value, int start, int count) =>
            FillPossibilities(value, start, count);

        private void FillPossibilities(bool value, int start, int count)
        {
            Array.Fill(_possibilities, value ? (byte)2 : (byte)1,
                start, count);
            if (!value)
            {
                Array.Clear(_integerSymbols, start, count);
            }
        }

        internal bool IsStaticFieldInitialized(int index)
            => (uint)index < (uint)_staticFieldPossibilities.Length
                && _staticFieldPossibilities[index] == 2;

        internal bool MayBeStaticFieldInitialized(int index)
            => (uint)index < (uint)_staticFieldPossibilities.Length
                && (_staticFieldPossibilities[index] & 2) != 0;

        internal void MarkStaticFieldInitialized(int index)
        {
            if ((uint)index >= (uint)_staticFieldPossibilities.Length)
            {
                throw Invalid();
            }
            _staticFieldPossibilities[index] = 2;
        }

        internal void InitializeStaticFieldStates(BoundFunction function)
        {
            Array.Fill(_staticFieldPossibilities, (byte)1);
            if (function.StaticFieldInitializerIndex >= 0)
            {
                var current = Program.StaticFields[
                    function.StaticFieldInitializerIndex];
                foreach (var (field, index) in Program.StaticFields.Select(
                             static (field, index) => (field, index)))
                {
                    if (field.EagerGroupIndex == current.EagerGroupIndex
                        && !field.IsLazy
                        && field.InitializerFunctionIndex >= 0
                        && (current.IsLazy
                            || field.DeclarationOrdinal
                                < current.DeclarationOrdinal))
                    {
                        MarkStaticFieldInitialized(index);
                    }
                }
                return;
            }

            if (function.StaticConstructorIdentity is not
                    BoundStaticConstructorIdentity identity)
            {
                return;
            }

            foreach (var (field, index) in Program.StaticFields.Select(
                         static (field, index) => (field, index)))
            {
                if (!field.IsLazy
                    && field.Owner.Name == identity.OwnerName
                    && field.InitializerFunctionIndex >= 0)
                {
                    MarkStaticFieldInitialized(index);
                }
            }
        }

        internal void MarkEagerGroupInitialized(int groupIndex)
        {
            if ((uint)groupIndex
                >= (uint)Program.StaticInitializationGroups.Length)
            {
                throw Invalid();
            }
            foreach (var (field, index) in Program.StaticFields.Select(
                         static (field, index) => (field, index)))
            {
                if (field.EagerGroupIndex == groupIndex && !field.IsLazy)
                {
                    MarkStaticFieldInitialized(index);
                }
            }
        }

        internal bool MergeStaticFieldStates(
            InitializationState first, InitializationState second)
        {
            var changed = false;
            for (var index = 0;
                index < _staticFieldPossibilities.Length; index++)
            {
                var value = (byte)(first._staticFieldPossibilities[index]
                    | second._staticFieldPossibilities[index]);
                changed |= value != _staticFieldPossibilities[index];
                _staticFieldPossibilities[index] = value;
            }
            return changed;
        }

        internal void JoinStaticFieldStates(
            InitializationState first, bool firstCompletes,
            InitializationState second, bool secondCompletes)
        {
            if (firstCompletes && secondCompletes)
            {
                _ = MergeStaticFieldStates(first, second);
            }
            else if (firstCompletes)
            {
                CopyStaticFieldStates(first);
            }
            else if (secondCompletes)
            {
                CopyStaticFieldStates(second);
            }
            else
            {
                CopyStaticFieldStates(first);
            }
        }

        internal bool MergeStaticFieldStatesFromLoop(
            InitializationState entry, InitializationState? back)
        {
            var changed = false;
            for (var index = 0;
                index < _staticFieldPossibilities.Length; index++)
            {
                var value = back is null
                    ? entry._staticFieldPossibilities[index]
                    : (byte)(entry._staticFieldPossibilities[index]
                        | back._staticFieldPossibilities[index]);
                changed |= value != _staticFieldPossibilities[index];
                _staticFieldPossibilities[index] = value;
            }
            return changed;
        }

        internal void CopyStaticFieldStates(InitializationState source)
        {
            Array.Copy(source._staticFieldPossibilities,
                _staticFieldPossibilities,
                _staticFieldPossibilities.Length);
        }

        internal bool HasNativeOutputState(int index) =>
            (uint)index < (uint)Length
                && (_nativeOutputDestinations[index] is not null || _nativeOutputResults[index] is not null);

        private void SetNativeOutputState(int index, NativeOutputDestinationState? destination,
            NativeOutputCallFact? result)
        {
            var hadState = HasNativeOutputState(index);
            _nativeOutputDestinations[index] = destination;
            _nativeOutputResults[index] = result;
            var hasState = HasNativeOutputState(index);
            if (hadState != hasState)
            {
                _nativeOutputStateCount += hasState ? 1 : -1;
            }
        }

        internal bool this[int index]
        {
            get
            {
                return _possibilities[index] == 2;
            }
            set
            {
                _possibilities[index] = value ? (byte)2 : (byte)1;
                if (_booleanValues is not null)
                {
                    _booleanValues[index] = -1;
                }
                if (!value)
                {
                    _integerSymbols[index] = 0;
                }
            }
        }

        internal bool IsVacant(int index) =>
            (_possibilities[index] & (2 | 8)) == 0 && !IsNativeOutputReserved(index);

        internal bool HasConsumedInitializationAuthority(
            ProvenanceAnchor descriptor)
            => _consumedInitializationAuthorities.Contains(descriptor);

        internal void ConsumeInitializationAuthority(
            ProvenanceAnchor descriptor)
        {
            if (descriptor.Kind
                    != ProvenanceAnchorKind.IncomingReferenceDescriptor
                && (descriptor.Storage is not StorageKey storage
                    || !storage.IsKnown))
            {
                throw Invalid();
            }
            _ = _consumedInitializationAuthorities.Add(descriptor);
        }

        internal bool HasActiveInitializationReservation(
            ProvenanceAnchor target) =>
            _activeInitializationReservations.Any(active =>
                InitializationReservationTargetsOverlap(active, target));

        internal void ReserveInitializationReferenceTargets(
            IReadOnlySet<ProvenanceAnchor> targets, TextSpan span)
        {
            foreach (var target in targets)
            {
                if (_activeInitializationReservations.Any(active =>
                    InitializationReservationTargetsOverlap(active, target)))
                {
                    throw InvalidEffect(span, "CheckedReference");
                }
            }

            _activeInitializationReservations.UnionWith(targets);
        }

        internal void ReleaseInitializationReferenceTargets(
            IEnumerable<ProvenanceAnchor> targets)
        {
            foreach (var target in targets)
            {
                _ = _activeInitializationReservations.Remove(target);
            }
        }

        internal void ClearActiveInitializationReservations() =>
            _activeInitializationReservations.Clear();

        internal byte IncomingReferenceInitializationPossibilities(
            ProvenanceAnchor target)
        {
            if (target.Kind is not (ProvenanceAnchorKind.IncomingReference
                or ProvenanceAnchorKind.IncomingReferenceContents
                or ProvenanceAnchorKind.IncomingReferencePlace
                or ProvenanceAnchorKind.IncomingReferenceField))
            {
                throw Invalid();
            }
            return _incomingReferenceInitializationStates.TryGetValue(
                target, out var possibilities)
                ? possibilities : (byte)1;
        }

        internal bool IsIncomingReferenceDefinitelyInitialized(
            ProvenanceAnchor target)
            => IncomingReferenceInitializationPossibilities(target) == 2;

        internal bool IsIncomingReferenceDefinitelyVacant(
            ProvenanceAnchor target)
        {
            if (IncomingReferenceInitializationPossibilities(target) != 1)
            {
                return false;
            }

            var projection = target.IncomingProjection
                ?? StorageProjection.WholeObject;
            foreach (var (candidate, possibilities)
                in _incomingReferenceInitializationStates)
            {
                if (candidate.Identity != target.Identity
                    || candidate.IncomingReferenceDepth
                        != target.IncomingReferenceDepth
                    || candidate.Kind is not (
                        ProvenanceAnchorKind.IncomingReferencePlace
                        or ProvenanceAnchorKind.IncomingReferenceField)
                    || (possibilities & 2) == 0
                    || candidate.IncomingProjection is not StorageProjection
                        candidateProjection
                    || !projection.ProjectionPath.IsPrefixOf(
                        candidateProjection.ProjectionPath)
                    || projection.ProjectionPath.Segments.Length
                        == candidateProjection.ProjectionPath.Segments.Length)
                {
                    continue;
                }

                return false;
            }

            return true;
        }

        internal bool IncomingReferenceMayBeInitialized(
            ProvenanceAnchor target)
            => (IncomingReferenceInitializationPossibilities(target) & 2) != 0;

        internal bool IncomingReferenceMayBeVacant(
            ProvenanceAnchor target)
            => (IncomingReferenceInitializationPossibilities(target) & 1) != 0;

        internal void SetIncomingReferenceInitializationPossibilities(
            ProvenanceAnchor target, byte possibilities,
            bool invalidateConditionalFacts = true)
        {
            if (target.Kind is not (ProvenanceAnchorKind.IncomingReference
                    or ProvenanceAnchorKind.IncomingReferenceContents
                    or ProvenanceAnchorKind.IncomingReferencePlace
                    or ProvenanceAnchorKind.IncomingReferenceField)
                || possibilities is 0 or > 3)
            {
                throw Invalid();
            }
            if (invalidateConditionalFacts)
            {
                ClearConditionalInitializedTargets();
            }
            if (possibilities == 1)
            {
                _ = _incomingReferenceInitializationStates.Remove(target);
            }
            else
            {
                _incomingReferenceInitializationStates[target] = possibilities;
            }
        }

        internal bool IsPrivateReferentInitialized(ProvenanceAnchor target)
            => IsIncomingReferenceDefinitelyInitialized(target);

        internal void MarkPrivateReferentInitialized(ProvenanceAnchor target)
        {
            if (target.Kind is not (ProvenanceAnchorKind.IncomingReference
                or ProvenanceAnchorKind.IncomingReferenceContents
                or ProvenanceAnchorKind.IncomingReferencePlace
                or ProvenanceAnchorKind.IncomingReferenceField))
            {
                throw Invalid();
            }
            SetIncomingReferenceInitializationPossibilities(target, 2);
        }

        internal bool IsNativeOutputReserved(int index) =>
            (uint)index < (uint)Length
                && _nativeOutputDestinations[index] is { IsReserved: true };

        internal bool HasRetiredValue(int index) => (_possibilities[index] & 4) != 0;
        internal bool HasPartialValue(int index) => (_possibilities[index] & 8) != 0;

        internal uint PossibleFieldMask(int index) =>
            (uint)index < (uint)Length ? _possibleFieldMasks[index] : throw Invalid();

        internal long FieldPlaceGeneration(int variable, StorageProjection projection)
        {
            if ((uint)variable >= (uint)Length
                || (byte)projection.Kind > (byte)StorageProjectionKind.InlineFieldPath
                || (projection.Kind == StorageProjectionKind.InlineFieldPath
                    && projection.FieldPath.Segments.IsEmpty))
            {
                throw Invalid();
            }

            var generation = 0L;
            var generationDepth = -1;
            if (projection.Kind is StorageProjectionKind.UnknownElement
                or StorageProjectionKind.UnknownArrayElement)
            {
                return _fieldPlaceGenerations.Any(pair => pair.Key.Variable == variable
                    && pair.Key.Projection.Kind is StorageProjectionKind.WholeObject
                        or StorageProjectionKind.InlineFieldPath)
                    ? StorageKey.UnknownGeneration : generation;
            }

            foreach (var (key, candidate) in _fieldPlaceGenerations)
            {
                if (key.Variable != variable
                    || !IsGenerationAncestor(key.Projection, projection, out var candidateDepth)
                    || candidateDepth <= generationDepth)
                {
                    continue;
                }
                generation = candidate;
                generationDepth = candidateDepth;
            }
            return generation;
        }

        internal void AdvanceFieldPlaceGeneration(int variable,
            StorageProjection projection, TextSpan span)
        {
            if ((uint)variable >= (uint)Length
                || projection.Kind is not (StorageProjectionKind.WholeObject
                    or StorageProjectionKind.InlineFieldPath)
                || (projection.Kind == StorageProjectionKind.InlineFieldPath
                    && projection.FieldPath.Segments.IsEmpty))
            {
                throw Invalid(span);
            }

            var generation = _fieldGenerationContext.Get(
                variable, projection, ScopeActivation, span);
            foreach (var key in _fieldPlaceGenerations.Keys.Where(key =>
                key.Variable == variable
                && PlaceGenerationAffectedBy(projection, key.Projection)).ToArray())
            {
                _fieldPlaceGenerations[key] = generation;
            }
            _fieldPlaceGenerations[new FieldGenerationKey(variable, projection)] = generation;
        }

        internal bool CopyFieldPlaceGenerations(int variable, InitializationState other)
        {
            if (ReferenceEquals(this, other))
            {
                return false;
            }
            var previous = _fieldPlaceGenerations
                .Where(pair => pair.Key.Variable == variable)
                .ToDictionary(static pair => pair.Key, static pair => pair.Value);
            var next = other._fieldPlaceGenerations
                .Where(pair => pair.Key.Variable == variable)
                .ToDictionary(static pair => pair.Key, static pair => pair.Value);
            ResetFieldPlaceGenerations(variable);
            foreach (var (key, generation) in next)
            {
                _fieldPlaceGenerations.Add(key, generation);
            }
            return !GenerationMapsEqual(previous, next);
        }

        internal bool MergeFieldPlaceGenerations(int variable, InitializationState other)
        {
            return MergeFieldPlaceGenerations(variable, this, other);
        }

        internal bool MergeFieldPlaceGenerations(int variable,
            InitializationState first, InitializationState second)
        {
            var firstValues = first._fieldPlaceGenerations
                .Where(pair => pair.Key.Variable == variable)
                .ToDictionary(static pair => pair.Key, static pair => pair.Value);
            var secondValues = second._fieldPlaceGenerations
                .Where(pair => pair.Key.Variable == variable)
                .ToDictionary(static pair => pair.Key, static pair => pair.Value);
            var keys = new HashSet<FieldGenerationKey>(firstValues.Keys);
            keys.UnionWith(secondValues.Keys);
            var previous = _fieldPlaceGenerations
                .Where(pair => pair.Key.Variable == variable)
                .ToDictionary(static pair => pair.Key, static pair => pair.Value);
            var next = new Dictionary<FieldGenerationKey, long>(keys.Count);
            ResetFieldPlaceGenerations(variable);
            foreach (var key in keys)
            {
                var firstGeneration = firstValues.TryGetValue(key, out var current)
                    ? current : 0;
                var secondGeneration = secondValues.TryGetValue(key, out var other)
                    ? other : 0;
                next.Add(key, firstGeneration == secondGeneration
                    ? firstGeneration : StorageKey.UnknownGeneration);
            }
            foreach (var (key, generation) in next)
            {
                _fieldPlaceGenerations.Add(key, generation);
            }
            return !GenerationMapsEqual(previous, next);
        }

        private void ResetFieldPlaceGenerations(int variable)
        {
            foreach (var key in _fieldPlaceGenerations.Keys
                .Where(key => key.Variable == variable).ToArray())
            {
                _ = _fieldPlaceGenerations.Remove(key);
            }
        }

        private static bool GenerationMapsEqual(
            Dictionary<FieldGenerationKey, long> left,
            Dictionary<FieldGenerationKey, long> right)
        {
            return left.Count == right.Count
                && left.All(pair => right.TryGetValue(pair.Key, out var generation)
                    && generation == pair.Value);
        }

        private static bool IsGenerationAncestor(
            StorageProjection generation, StorageProjection place, out int depth)
        {
            if (generation.Kind == StorageProjectionKind.WholeObject)
            {
                depth = 0;
                return true;
            }
            if (generation.Kind == StorageProjectionKind.InlineFieldPath
                && place.Kind == StorageProjectionKind.InlineFieldPath
                && generation.FieldPath.IsPrefixOf(place.FieldPath))
            {
                depth = generation.FieldPath.Segments.Length;
                return true;
            }
            depth = -1;
            return false;
        }

        private static bool PlaceGenerationAffectedBy(
            StorageProjection mutation, StorageProjection place)
        {
            if (mutation.Kind == StorageProjectionKind.WholeObject)
            {
                return true;
            }
            return mutation.Kind == StorageProjectionKind.InlineFieldPath
                && place.Kind == StorageProjectionKind.InlineFieldPath
                && mutation.FieldPath.IsPrefixOf(place.FieldPath);
        }

        internal NestedOwnerFieldState NestedOwnerFields(
            int variable, FieldProjectionPath ownerPath, PrimitiveType type)
        {
            if ((uint)variable >= (uint)Length
                || ownerPath.Segments.IsEmpty
                || !IsUnique(Program, type)
                || !HasFields(Program, type))
            {
                throw Invalid();
            }

            var fullMask = FullMask(Program, type);
            return NestedOwnerFields(variable, ownerPath, type, fullMask);
        }

        internal NestedOwnerFieldState NestedOwnerFields(
            int variable, FieldProjectionPath ownerPath, PrimitiveType type,
            uint initialMask)
        {
            if ((uint)variable >= (uint)Length
                || ownerPath.Segments.IsEmpty
                || !SupportsNestedOwnerFieldState(type)
                || (initialMask & ~FullMask(Program, type)) != 0)
            {
                throw Invalid();
            }

            var fullMask = FullMask(Program, type);
            var key = new NestedOwnerStateKey(variable, ownerPath);
            if (!_nestedOwnerStates.TryGetValue(key, out var fields))
            {
                return new NestedOwnerFieldState(
                    type, fullMask, initialMask, initialMask);
            }
            if (fields.Type != type || fields.FullMask != fullMask
                || (fields.DefiniteMask & ~fields.PossibleMask) != 0
                || (fields.DefiniteMask & ~fullMask) != 0
                || (fields.PossibleMask & ~fullMask) != 0)
            {
                throw Invalid();
            }
            return fields;
        }

        internal void SetNestedOwnerFields(
            int variable, FieldProjectionPath ownerPath, NestedOwnerFieldState fields)
        {
            if ((uint)variable >= (uint)Length || ownerPath.Segments.IsEmpty
                || !SupportsNestedOwnerFieldState(fields.Type)
                || fields.FullMask != FullMask(Program, fields.Type)
                || (fields.DefiniteMask & ~fields.PossibleMask) != 0
                || (fields.DefiniteMask & ~fields.FullMask) != 0
                || (fields.PossibleMask & ~fields.FullMask) != 0)
            {
                throw Invalid();
            }

            var key = new NestedOwnerStateKey(variable, ownerPath);
            if (fields.IsComplete && IsUnique(Program, fields.Type))
            {
                _ = _nestedOwnerStates.Remove(key);
            }
            else
            {
                _nestedOwnerStates[key] = fields;
            }
        }

        private bool SupportsNestedOwnerFieldState(PrimitiveType type) =>
            HasFields(Program, type) && !ManagedClassTypes.IsClass(type)
            && (IsUnique(Program, type)
                || CarriesRawUnionPayloadFacts(Program, type)
                || NativeFixedArrayContract
                    .HasInlineFixedArrayFieldStorage(type, Program.Structures,
                        Program.NativeFixedArrayTypes)
                || IsInlineStructStorage(type, Program)
                || (Program.NativeLoweringAgreement
                        == CompilationOptions.WindowsX64NormalBackingAgreement
                    && (int)type >= 100
                    && (int)type - 100 < Program.Structures.Length));

        internal void ResetNestedOwnerStates(int variable)
        {
            foreach (var key in _nestedOwnerStates.Keys
                .Where(key => key.Variable == variable).ToArray())
            {
                _ = _nestedOwnerStates.Remove(key);
            }
        }

        internal void ResetNestedOwnerSubtree(
            int variable, FieldProjectionPath ownerPath)
        {
            if ((uint)variable >= (uint)Length || ownerPath.Segments.IsEmpty)
            {
                throw Invalid();
            }
            foreach (var key in _nestedOwnerStates.Keys.Where(key =>
                key.Variable == variable && ownerPath.IsPrefixOf(key.OwnerPath)).ToArray())
            {
                _ = _nestedOwnerStates.Remove(key);
            }
        }

        internal bool CopyNestedOwnerStates(int variable, InitializationState other)
        {
            if (ReferenceEquals(this, other))
            {
                return false;
            }
            var previous = _nestedOwnerStates
                .Where(pair => pair.Key.Variable == variable)
                .ToDictionary(static pair => pair.Key, static pair => pair.Value);
            var next = other._nestedOwnerStates
                .Where(pair => pair.Key.Variable == variable)
                .ToDictionary(static pair => pair.Key, static pair => pair.Value);
            ResetNestedOwnerStates(variable);
            foreach (var (key, fields) in next)
            {
                _nestedOwnerStates.Add(key, fields);
            }
            return !NestedOwnerMapsEqual(previous, next);
        }

        internal bool MergeNestedOwnerStates(int variable, InitializationState other)
            => MergeNestedOwnerStates(variable, this, other);

        internal bool MergeNestedOwnerStates(
            int variable, InitializationState first, InitializationState second)
        {
            var firstValues = first._nestedOwnerStates
                .Where(pair => pair.Key.Variable == variable)
                .ToDictionary(static pair => pair.Key, static pair => pair.Value);
            var secondValues = second._nestedOwnerStates
                .Where(pair => pair.Key.Variable == variable)
                .ToDictionary(static pair => pair.Key, static pair => pair.Value);
            var keys = new HashSet<NestedOwnerStateKey>(firstValues.Keys);
            keys.UnionWith(secondValues.Keys);
            var previous = _nestedOwnerStates
                .Where(pair => pair.Key.Variable == variable)
                .ToDictionary(static pair => pair.Key, static pair => pair.Value);
            var next = new Dictionary<NestedOwnerStateKey, NestedOwnerFieldState>(keys.Count);
            ResetNestedOwnerStates(variable);
            foreach (var key in keys)
            {
                var hasFirst = firstValues.TryGetValue(key, out var firstState);
                var hasSecond = secondValues.TryGetValue(key, out var secondState);
                var template = hasFirst ? firstState : secondState;
                var firstFields = hasFirst ? firstState : template with {
                    DefiniteMask = template.FullMask,
                    PossibleMask = template.FullMask,
                };
                var secondFields = hasSecond ? secondState : template with {
                    DefiniteMask = template.FullMask,
                    PossibleMask = template.FullMask,
                };
                if (firstFields.Type != secondFields.Type
                    || firstFields.FullMask != secondFields.FullMask)
                {
                    throw Invalid();
                }
                var fields = new NestedOwnerFieldState(firstFields.Type,
                    firstFields.FullMask,
                    firstFields.DefiniteMask & secondFields.DefiniteMask,
                    firstFields.PossibleMask | secondFields.PossibleMask);
                if (!fields.IsComplete)
                {
                    next.Add(key, fields);
                }
            }
            foreach (var (key, fields) in next)
            {
                _nestedOwnerStates.Add(key, fields);
            }
            return !NestedOwnerMapsEqual(previous, next);
        }

        private static bool NestedOwnerMapsEqual(
            Dictionary<NestedOwnerStateKey, NestedOwnerFieldState> left,
            Dictionary<NestedOwnerStateKey, NestedOwnerFieldState> right)
        {
            return left.Count == right.Count
                && left.All(pair => right.TryGetValue(pair.Key, out var fields)
                    && fields == pair.Value);
        }

        internal void SetPossibleFieldMask(int index, uint mask)
        {
            if ((uint)index >= (uint)Length)
            {
                throw Invalid();
            }
            _possibleFieldMasks[index] = mask;
        }

        internal void MarkPartialValue(int index)
        {
            if ((uint)index >= (uint)Length)
            {
                throw Invalid();
            }
            _possibilities[index] = 8;
        }

        internal void ActivateStorage(int index, long generation)
        {
            ResetFieldPlaceGenerations(index);
            ResetNestedOwnerStates(index);
            ClearRawUnionPayloadFacts(index);
            Dependencies?.ActivateStorage(index, generation, ScopeActivation);
        }

        internal int EnterBlockActivation(TextSpan span) =>
            Dependencies?.EnterBlockActivation(ScopeActivation, span) ?? ScopeActivation;

        internal bool IsStorageScopeActive(int activation)
            => activation == BackingDependencies.RootScopeActivation
                || _activeStorageScopes.Any(scope => scope.Activation == activation);

        internal int EnterLoopActivation(TextSpan span, bool isReentry) =>
            Dependencies?.EnterLoopActivation(ScopeActivation, span, isReentry) ?? ScopeActivation;

        internal void EnterStorageScope(BoundBlock block)
        {
            if (Dependencies is not null)
            {
                _activeStorageScopes.Add(new ActiveStorageScope(ScopeActivation, block));
            }
        }

        internal void ExitStorageScope(BoundBlock block)
        {
            if (Dependencies is null)
            {
                return;
            }
            if (_activeStorageScopes.Count == 0
                || !ReferenceEquals(_activeStorageScopes[^1].Block, block)
                || _activeStorageScopes[^1].Activation != ScopeActivation)
            {
                throw Invalid();
            }
            _activeStorageScopes.RemoveAt(_activeStorageScopes.Count - 1);
        }

        internal void CheckAndExitStorageScopesTo(int activation)
        {
            if (Dependencies is null)
            {
                return;
            }
            var targetIndex = activation == 0 ? -1
                : _activeStorageScopes.FindLastIndex(scope => scope.Activation == activation);
            if (activation != 0 && targetIndex < 0)
            {
                throw Invalid();
            }

            for (var index = _activeStorageScopes.Count - 1; index > targetIndex; index--)
            {
                CheckNativePointerScopeExit(_activeStorageScopes[index].Block, this);
            }
            _activeStorageScopes.RemoveRange(targetIndex + 1,
                _activeStorageScopes.Count - targetIndex - 1);
        }

        internal void AdvanceStorageGeneration(int index, long generation)
        {
            ResetFieldPlaceGenerations(index);
            ResetNestedOwnerStates(index);
            ClearRawUnionPayloadFacts(index);
            Dependencies?.RetireStorage(index, generation);
        }

        internal void Retire(int index, long generation)
        {
            InvalidateInitializationPostconditionAliasBinding(index);
            _possibilities[index] = 4;
            if (_booleanValues is not null)
            {
                _booleanValues[index] = -1;
            }
            _possibleFieldMasks[index] = 0;
            ClearRawUnionPayloadFacts(index);
            SetNativeOutputState(index, null, null);
            _initializationPostconditionResults[index] = null;
            Dependencies?.ClearNativePointerProvenance(index);
            AdvanceStorageGeneration(index, generation);
        }

        internal byte Possibilities(int index) => _possibilities[index];

        internal void SetPossibilities(int index, byte value)
        {
            _possibilities[index] = value;
            if (value != 2)
            {
                _integerSymbols[index] = 0;
            }
        }

        internal void MarkConditional(int index)
        {
            _possibilities[index] = 3;
            if (_booleanValues is not null)
            {
                _booleanValues[index] = -1;
            }
            SetNativeOutputState(index, null, null);
            _initializationPostconditionResults[index] = null;
            if (_integerSymbolTypes.TryGetValue(
                    _integerSymbols[index], out var type))
            {
                HavocIntegerVariable(index, type);
            }
        }

        internal void Merge(int index, InitializationState other)
        {
            MergeIntegerSymbol(index, other);
            if (index == 0)
            {
                MergeIntegerMetadata(other);
            }
            _consumedInitializationAuthorities.UnionWith(
                other._consumedInitializationAuthorities);
            _activeInitializationReservations.UnionWith(
                other._activeInitializationReservations);
            _ = MergeIncomingReferenceInitializationStates(other);
            _possibilities[index] |= other._possibilities[index];
            _possibleFieldMasks[index] |= other._possibleFieldMasks[index];
            _ = MergeStaticFieldStates(this, other);
            _ = MergeRawUnionInitializedBytes(index, other);
            _ = MergeFieldPlaceGenerations(index, other);
            _ = MergeNestedOwnerStates(index, other);
            MergeNativeOutputSlot(index, _nativeOutputDestinations[index], _nativeOutputResults[index],
                other._nativeOutputDestinations[index], other._nativeOutputResults[index]);
            _initializationPostconditionResults[index]
                = ReferenceEquals(
                    _initializationPostconditionResults[index],
                    other._initializationPostconditionResults[index])
                    ? _initializationPostconditionResults[index] : null;
            _initializationPostconditionAliasFacts[index]
                = MergeInitializationPostconditionAliasFacts(
                    _initializationPostconditionAliasFacts[index],
                    other._initializationPostconditionAliasFacts[index]);
            _initializationPostconditionCallFacts.Clear();
            if (Dependencies is not null && other.Dependencies is not null)
            {
                _ = Dependencies.MergeSlot(index, other.Dependencies);
            }
            else if (Dependencies is not null || other.Dependencies is not null)
            {
                throw Invalid();
            }
        }

        private bool MergeIncomingReferenceInitializationStates(
            InitializationState other)
        {
            var changed = false;
            var targets = new HashSet<ProvenanceAnchor>(
                _incomingReferenceInitializationStates.Keys);
            targets.UnionWith(
                other._incomingReferenceInitializationStates.Keys);
            foreach (var target in targets)
            {
                var possibilities
                    = (byte)(IncomingReferenceInitializationPossibilities(
                        target)
                        | other.IncomingReferenceInitializationPossibilities(
                            target));
                var previous
                    = IncomingReferenceInitializationPossibilities(target);
                if (previous != possibilities)
                {
                    SetIncomingReferenceInitializationPossibilities(target,
                        possibilities, invalidateConditionalFacts: false);
                    changed = true;
                }
            }
            return changed;
        }

        internal void JoinIncomingReferenceInitializationStates(
            InitializationState left, bool leftCompletes,
            InitializationState right, bool rightCompletes)
        {
            for (var index = 0; index < Length; index++)
            {
                _initializationPostconditionAliasFacts[index]
                    = leftCompletes && rightCompletes
                        ? MergeInitializationPostconditionAliasFacts(
                            left._initializationPostconditionAliasFacts[index],
                            right._initializationPostconditionAliasFacts[index])
                        : leftCompletes
                            ? left._initializationPostconditionAliasFacts[index]
                            : rightCompletes
                                ? right._initializationPostconditionAliasFacts[index]
                                : null;
            }
            _incomingReferenceInitializationStates.Clear();
            _consumedInitializationAuthorities.Clear();
            _activeInitializationReservations.Clear();
            _initializationPostconditionCallFacts.Clear();

            var targets = new HashSet<ProvenanceAnchor>();
            if (leftCompletes)
            {
                targets.UnionWith(
                    left._incomingReferenceInitializationStates.Keys);
                _consumedInitializationAuthorities.UnionWith(
                    left._consumedInitializationAuthorities);
                _activeInitializationReservations.UnionWith(
                    left._activeInitializationReservations);
            }
            if (rightCompletes)
            {
                targets.UnionWith(
                    right._incomingReferenceInitializationStates.Keys);
                _consumedInitializationAuthorities.UnionWith(
                    right._consumedInitializationAuthorities);
                _activeInitializationReservations.UnionWith(
                    right._activeInitializationReservations);
            }

            foreach (var target in targets)
            {
                var possibilities = (byte)0;
                if (leftCompletes)
                {
                    possibilities |=
                        left.IncomingReferenceInitializationPossibilities(
                            target);
                }
                if (rightCompletes)
                {
                    possibilities |=
                        right.IncomingReferenceInitializationPossibilities(
                            target);
                }
                SetIncomingReferenceInitializationPossibilities(target,
                    possibilities, invalidateConditionalFacts: false);
            }
        }

        private void MergeIntegerSymbol(int index,
            InitializationState other)
        {
            var left = _integerSymbols[index];
            var right = other._integerSymbols[index];
            if (left == 0 || right == 0
                || !_integerSymbolTypes.TryGetValue(left,
                    out var leftType)
                || !other._integerSymbolTypes.TryGetValue(right,
                    out var rightType)
                || leftType != rightType)
            {
                _integerSymbols[index] = 0;
                return;
            }

            var leftRange = _integerSymbolRanges[left];
            var rightRange = other._integerSymbolRanges[right];
            if (left == right)
            {
                _integerSymbolRanges[left] = new IntegerInterval(
                    BigInteger.Min(leftRange.Lower, rightRange.Lower),
                    BigInteger.Max(leftRange.Upper, rightRange.Upper));
                return;
            }

            var symbol = Interlocked.Increment(ref s_integerSymbolId);
            _integerSymbols[index] = symbol;
            _integerSymbolTypes[symbol] = leftType;
            var range = new IntegerInterval(
                BigInteger.Min(leftRange.Lower, rightRange.Lower),
                BigInteger.Max(leftRange.Upper, rightRange.Upper));
            _integerSymbolRanges[symbol]
                = TryGetIntegerTypeRange(leftType, out var typeRange)
                    ? IntersectIntegerInterval(range, typeRange) ?? typeRange
                    : range;
        }

        private void MergeIntegerMetadata(InitializationState other)
        {
            var commonDefinitions = new Dictionary<long,
                IntegerLinearExpression>();
            foreach (var (symbol, definition) in _integerSymbolDefinitions)
            {
                if (other._integerSymbolDefinitions.TryGetValue(symbol,
                        out var otherDefinition)
                    && AreEquivalent(definition, otherDefinition))
                {
                    commonDefinitions.Add(symbol, definition);
                }
            }
            _integerSymbolDefinitions.Clear();
            foreach (var entry in commonDefinitions)
            {
                _integerSymbolDefinitions.Add(entry.Key, entry.Value);
            }

            var commonConstraints = new List<IntegerLinearConstraint>();
            foreach (var constraint in _integerConstraints)
            {
                if (other._integerConstraints.Any(candidate =>
                        AreEquivalent(constraint.Expression,
                            candidate.Expression)))
                {
                    commonConstraints.Add(constraint);
                }
            }
            _integerConstraints = commonConstraints;
        }

        internal bool MergeProvenanceSlot(int index, InitializationState other)
        {
            var changed = index == 0
                && MergeIncomingReferenceInitializationStates(other);
            if (Dependencies is not null && other.Dependencies is not null)
            {
                return Dependencies.MergeSlot(index, other.Dependencies)
                    || changed;
            }
            if (Dependencies is not null || other.Dependencies is not null)
            {
                throw Invalid();
            }
            return changed;
        }

        internal bool CopyProvenanceSlot(int index, InitializationState other)
        {
            if (Dependencies is not null && other.Dependencies is not null)
            {
                return Dependencies.CopySlot(index, other.Dependencies);
            }
            if (Dependencies is not null || other.Dependencies is not null)
            {
                throw Invalid();
            }
            return false;
        }

        private void ChargeRepeatRootListHeader()
            => ChargeRepeatRootListHeader(RepeatResources);

        internal static void ChargeRepeatRootListHeader(
            RepeatResourceLedger resources)
            => resources.ConsumeWork(2);

        private void ChargeRepeatRootListHeaderForFirstEntry()
        {
            if (_rawUnionArrayElementBytes.Count == 0)
            {
                ChargeRepeatRootListHeader();
            }
        }

        private void ChargeRepeatRoot(StorageProjection prefix)
            => ChargeRepeatRoot(RepeatResources, prefix);

        internal static void ChargeRepeatRoot(
            RepeatResourceLedger resources, StorageProjection prefix)
        {
            ChargeRepeatRootHeader(resources);
            ChargeRepeatRootPath(resources, prefix);
        }

        private static void ChargeRepeatRootHeader(
            RepeatResourceLedger resources)
            => resources.ConsumeWork(5);

        private static void ChargeRepeatRootPath(
            RepeatResourceLedger resources, StorageProjection prefix)
        {
            var segments = prefix.ProjectionPath.Segments;
            if (segments.IsEmpty)
            {
                return;
            }

            resources.ConsumeWork(2);
            foreach (var _ in segments)
            {
                resources.ConsumeWork(3);
            }
        }

        internal static BigInteger RawUnionArrayRootLogicalBytes(
            StorageProjection prefix)
        {
            var pathLength = prefix.ProjectionPath.Segments.Length;
            return pathLength == 0
                ? new BigInteger(32)
                : new BigInteger(48) + (16 * pathLength);
        }

        internal static BigInteger RawUnionArrayFactsLogicalBytes(
            IReadOnlyDictionary<StorageProjection,
                RawUnionArrayElementState> values)
            => RawUnionArrayFactsLogicalBytes(values, out _);

        internal static BigInteger RawUnionArrayFactsLogicalBytes(
            IReadOnlyDictionary<StorageProjection,
                RawUnionArrayElementState> values,
            out RepeatResourceLedger? resources)
        {
            ArgumentNullException.ThrowIfNull(values);
            resources = null;
            if (values.Count == 0)
            {
                return BigInteger.Zero;
            }

            using var enumerator = values.GetEnumerator();
            if (!enumerator.MoveNext())
            {
                throw Invalid();
            }

            var firstState = enumerator.Current.Value ?? throw Invalid();
            var stateResources = firstState.Resources;
            resources = stateResources;
            ChargeRepeatRootListHeader(stateResources);
            var bytes = new BigInteger(16);
            do
            {
                var (prefix, state) = enumerator.Current;
                if (state is null || !ReferenceEquals(state.Resources,
                        stateResources))
                {
                    throw Invalid();
                }

                ChargeRepeatRoot(stateResources, prefix);
                bytes += RawUnionArrayRootLogicalBytes(prefix)
                    + state.LogicalBytes();
            }
            while (enumerator.MoveNext());

            return bytes;
        }

        private BigInteger RawUnionArrayLogicalBytes()
        {
            if (_rawUnionArrayElementBytes.Count == 0)
            {
                return BigInteger.Zero;
            }

            ChargeRepeatRootListHeader();
            var bytes = new BigInteger(16);
            foreach (var (key, state) in _rawUnionArrayElementBytes)
            {
                ChargeRepeatRoot(key.ArrayPrefix);
                var pathLength = key.ArrayPrefix.ProjectionPath.Segments.Length;
                bytes += 32;
                if (pathLength != 0)
                {
                    bytes += 16 + (16 * pathLength);
                }
                bytes += state.LogicalBytes();
            }
            return bytes;
        }

        private void ChargeRepeatRootLookup(RawUnionArrayStateKey target)
        {
            if (_rawUnionArrayElementBytes.Count == 0)
            {
                RepeatResources.ConsumeWork();
                return;
            }

            ChargeRepeatRootListHeader();
            foreach (var (key, _) in _rawUnionArrayElementBytes)
            {
                ChargeRepeatRoot(key.ArrayPrefix);
                RepeatResources.ConsumeWork();
                if (key == target)
                {
                    return;
                }
            }
            RepeatResources.ConsumeWork();
        }

        private bool HasRawUnionArrayPrefixMatch(int variable,
            StorageProjection prefix)
        {
            if (_rawUnionArrayElementBytes.Count != 0)
            {
                ChargeRepeatRootListHeader();
            }

            foreach (var (key, _) in _rawUnionArrayElementBytes)
            {
                RepeatResources.ConsumeWork();
                RepeatResources.ConsumeWork();
                RepeatResources.ConsumeWork(5);
                RepeatResources.ConsumeWork();
                if (key.Variable != variable)
                {
                    continue;
                }

                if (StorageProjectionPathIsPrefixOf(RepeatResources,
                        prefix.ProjectionPath,
                        key.ArrayPrefix.ProjectionPath))
                {
                    RepeatResources.ConsumeWork();
                    return true;
                }
            }

            RepeatResources.ConsumeWork();
            RepeatResources.ConsumeWork();
            return false;
        }

        internal static bool StorageProjectionPathIsPrefixOf(
            RepeatResourceLedger resources,
            StorageProjectionPath query,
            StorageProjectionPath candidate)
        {
            using var repeatFrame = resources.EnterFrame();

            bool Complete(bool result)
            {
                repeatFrame.Complete();
                return result;
            }

            resources.ConsumeWork(8);
            var querySegments = query.Segments;
            var candidateSegments = candidate.Segments;
            resources.ConsumeWork(2);
            resources.ConsumeWork();
            if (querySegments.Length > candidateSegments.Length)
            {
                return Complete(false);
            }

            for (var index = 0; index < querySegments.Length; index++)
            {
                resources.ConsumeWork(2);
                resources.ConsumeWork(2);
                var querySegment = querySegments[index];
                var candidateSegment = candidateSegments[index];
                resources.ConsumeWork(2);
                switch (querySegment.Kind)
                {
                    case StorageProjectionSegmentKind.Field:
                        resources.ConsumeWork();
                        if (candidateSegment.Kind
                            != StorageProjectionSegmentKind.Field)
                        {
                            return Complete(false);
                        }

                        resources.ConsumeWork(2);
                        resources.ConsumeWork();
                        if (querySegment.OwnerType
                            != candidateSegment.OwnerType)
                        {
                            return Complete(false);
                        }

                        resources.ConsumeWork(2);
                        resources.ConsumeWork();
                        if (querySegment.Field != candidateSegment.Field)
                        {
                            return Complete(false);
                        }
                        break;
                    case StorageProjectionSegmentKind.ArrayIndex:
                        resources.ConsumeWork();
                        if (candidateSegment.Kind
                            != StorageProjectionSegmentKind.ArrayIndex)
                        {
                            return Complete(false);
                        }

                        resources.ConsumeWork(2);
                        resources.ConsumeWork();
                        if (querySegment.Start != candidateSegment.Start)
                        {
                            return Complete(false);
                        }
                        break;
                    case StorageProjectionSegmentKind.ArrayRange:
                        resources.ConsumeWork();
                        if (candidateSegment.Kind
                            == StorageProjectionSegmentKind.ArrayIndex)
                        {
                            resources.ConsumeWork(2);
                            resources.ConsumeWork();
                            if (candidateSegment.Start < querySegment.Start)
                            {
                                return Complete(false);
                            }

                            resources.ConsumeWork();
                            var offset
                                = candidateSegment.Start - querySegment.Start;
                            resources.ConsumeWork();
                            resources.ConsumeWork();
                            if (offset >= querySegment.Length)
                            {
                                return Complete(false);
                            }
                        }
                        else
                        {
                            resources.ConsumeWork();
                            if (candidateSegment.Kind
                                != StorageProjectionSegmentKind.ArrayRange)
                            {
                                return Complete(false);
                            }

                            resources.ConsumeWork();
                            var candidateLength = candidateSegment.Length;
                            resources.ConsumeWork();
                            if (candidateLength == 0)
                            {
                                return Complete(false);
                            }

                            resources.ConsumeWork(2);
                            resources.ConsumeWork();
                            if (candidateSegment.Start < querySegment.Start)
                            {
                                return Complete(false);
                            }

                            resources.ConsumeWork();
                            var offset
                                = candidateSegment.Start - querySegment.Start;
                            resources.ConsumeWork();
                            var queryLength = querySegment.Length;
                            resources.ConsumeWork();
                            if (offset >= queryLength)
                            {
                                return Complete(false);
                            }

                            resources.ConsumeWork();
                            var remaining = queryLength - offset;
                            resources.ConsumeWork();
                            if (candidateLength > remaining)
                            {
                                return Complete(false);
                            }
                        }
                        break;
                    default:
                        throw Invalid();
                }
            }

            resources.ConsumeWork();
            return Complete(true);
        }

        internal InitializationState Clone()
            => Clone(_repeatSnapshotScope);

        internal void SetRepeatSnapshotScope(
            RepeatSnapshotReservationScope? snapshotScope)
            => _repeatSnapshotScope = snapshotScope;

        internal BigInteger GetRawUnionArrayStateBytes()
            => RawUnionArrayLogicalBytes();

        private void ReplaceRepeatSnapshotStateLease(
            RepeatResourceLedger.StateLease output)
        {
            if (_repeatSnapshotScope is RepeatSnapshotReservationScope scope
                && scope.TracksState(this))
            {
                scope.ReplaceState(this, output);
                return;
            }

            if (!IsCallableRoot)
            {
                return;
            }
            if (!output.IsOwnedBy(RepeatResources) || output.IsPersistent)
            {
                throw Invalid();
            }

            if (output.ReservedBytes.IsZero)
            {
                _repeatPersistentStateLease?.Dispose();
                _repeatPersistentStateLease = null;
                return;
            }

            _repeatPersistentStateLease
                ??= RepeatResources.ReservePersistentState(BigInteger.Zero);
            if (!_repeatPersistentStateLease.IsPersistent
                || !_repeatPersistentStateLease.IsOwnedBy(RepeatResources))
            {
                throw Invalid();
            }
            _repeatPersistentStateLease.Remove(
                _repeatPersistentStateLease.ReservedBytes);
            _repeatPersistentStateLease.TransferFrom(output,
                output.ReservedBytes, BigInteger.Zero);
        }

        private RepeatResourceLedger.StateLease? ReserveRawUnionArrayInputState(
            BigInteger bytes)
        {
            if (_repeatPersistentStateLease is RepeatResourceLedger.StateLease lease
                && lease.ReservedBytes != bytes)
            {
                throw Invalid();
            }

            if (RepeatResources.IsStateTreeReservationActive
                || _repeatPersistentStateLease is not null
                || _repeatSnapshotScope?.TracksState(this) == true
                || bytes.IsZero)
            {
                return null;
            }

            return RepeatResources.ReserveState(bytes);
        }

        internal InitializationState Clone(
            RepeatSnapshotReservationScope? snapshotScope)
        {
            var repeatStateBytes = RawUnionArrayLogicalBytes();
            using var repeatFrame = repeatStateBytes.IsZero
                ? null : RepeatResources.EnterFrame();
            using var repeatInputState
                = snapshotScope?.TracksState(this) == true
                    || _repeatSnapshotScope?.TracksState(this) == true
                    ? null
                    : ReserveRawUnionArrayInputState(repeatStateBytes);
            var repeatOutputState
                = RepeatResources.ReserveState(BigInteger.Zero);
            var repeatOutputStateTransferred = false;
            try
            {
                var clonedDependencies = Dependencies?.Clone();

                var result = new InitializationState(Program, Length,
                    _canBeFacts, _flowFacts, _completionShapeFacts,
                    _completionFacts, _nativeOutputFlowFacts,
                    _initializationPostconditionFlowShapes,
                    _initializationPostconditionCallCandidates,
                    _initializationPostconditionCallFactSnapshots,
                    HasNativeOutputContracts, HasDoesNotReturnFunctions,
                    TracksConditionalOutputReadFacts,
                    _fieldGenerationContext,
                    new Dictionary<FieldGenerationKey, long>(
                        _fieldPlaceGenerations),
                    new Dictionary<NestedOwnerStateKey,
                        NestedOwnerFieldState>(_nestedOwnerStates)) {
                    StatementInputs = StatementInputs,
                    StatementInputSnapshotScope
                        = StatementInputSnapshotScope,
                    Dependencies = clonedDependencies,
                    NativePointerCaptureEffects
                        = NativePointerCaptureEffects,
                    RawUnionReturnCoverage = RawUnionReturnCoverage,
                    RawUnionReturnCoverageSummaries
                        = RawUnionReturnCoverageSummaries,
                    RepeatResources = RepeatResources,
                    ScopeActivation = ScopeActivation,
                };
                result.CopyIntegerFacts(this);
                if (_booleanValues is not null)
                {
                    Array.Copy(_booleanValues, result._booleanValues!,
                        Length);
                }
                result.CopyConditionalInitializedTargets(this);
                result._activeStorageScopes.AddRange(_activeStorageScopes);
                result._consumedInitializationAuthorities.UnionWith(
                    _consumedInitializationAuthorities);
                result.CopyGenericUniqueProperties(this);
                foreach (var (target, possibilities)
                    in _incomingReferenceInitializationStates)
                {
                    result._incomingReferenceInitializationStates.Add(
                        target, possibilities);
                }
                Array.Copy(_possibilities, result._possibilities, Length);
                Array.Copy(_possibleFieldMasks, result._possibleFieldMasks,
                    Length);
                result.CopyStaticFieldStates(this);
                Array.Copy(_nativeOutputDestinations,
                    result._nativeOutputDestinations, Length);
                Array.Copy(_nativeOutputResults,
                    result._nativeOutputResults, Length);
                result._nativeOutputStateCount = _nativeOutputStateCount;
                Array.Copy(_initializationPostconditionResults,
                    result._initializationPostconditionResults, Length);
                Array.Copy(_initializationPostconditionAliasFacts,
                    result._initializationPostconditionAliasFacts, Length);
                foreach (var (call, fact)
                    in _initializationPostconditionCallFacts)
                {
                    result._initializationPostconditionCallFacts.Add(call,
                        fact);
                }
                foreach (var (variable, bytes)
                    in _rawUnionInitializedBytes)
                {
                    result._rawUnionInitializedBytes.Add(variable,
                        (byte[])bytes.Clone());
                }
                if (_rawUnionArrayElementBytes.Count != 0)
                {
                    ChargeRepeatRootListHeader();
                    repeatOutputState.Add(16);
                    foreach (var (key, state)
                        in _rawUnionArrayElementBytes)
                    {
                        ChargeRepeatRoot(key.ArrayPrefix);
                        repeatOutputState.Add(
                            RawUnionArrayRootLogicalBytes(
                                key.ArrayPrefix));
                        var clonedState = state.CloneTo(
                            repeatOutputState);
                        result._rawUnionArrayElementBytes.Add(key,
                            clonedState);
                    }
                }

                repeatFrame?.Complete();
                if (snapshotScope is not null)
                {
                    snapshotScope.TrackState(result, repeatOutputState);
                    repeatOutputStateTransferred = true;
                }
                return result;
            }
            finally
            {
                if (!repeatOutputStateTransferred)
                {
                    repeatOutputState.Dispose();
                }
            }
        }

        internal void CopyTo(InitializationState destination)
        {
            if (!ReferenceEquals(RepeatResources, destination.RepeatResources))
            {
                throw Invalid();
            }
            var sourceRepeatBytes = RawUnionArrayLogicalBytes();
            var destinationRepeatBytes
                = destination.RawUnionArrayLogicalBytes();
            using var repeatFrame = sourceRepeatBytes.IsZero
                    && destinationRepeatBytes.IsZero
                ? null : RepeatResources.EnterFrame();
            using var repeatSourceState
                = ReserveRawUnionArrayInputState(sourceRepeatBytes);
            using var repeatDestinationState
                = destination.ReserveRawUnionArrayInputState(
                    destinationRepeatBytes);
            using var repeatOutputState = RepeatResources.ReserveState(
                BigInteger.Zero);
            if (_rawUnionArrayElementBytes.Count != 0)
            {
                ChargeRepeatRootListHeader();
                repeatOutputState.Add(16);
            }
            var rawUnionArrayReplacement
                = new SortedDictionary<RawUnionArrayStateKey,
                    RawUnionArrayElementState>(
                        RawUnionArrayStateKeyComparer.Instance);
            if (_rawUnionArrayElementBytes.Count != 0)
            {
                foreach (var (key, state) in _rawUnionArrayElementBytes)
                {
                    ChargeRepeatRoot(key.ArrayPrefix);
                    repeatOutputState.Add(
                        RawUnionArrayRootLogicalBytes(key.ArrayPrefix));
                    var clonedState = state.CloneTo(repeatOutputState);
                    rawUnionArrayReplacement.Add(key, clonedState);
                }
            }
            repeatFrame?.Complete();
            Array.Copy(_possibilities, destination._possibilities, Length);
            Array.Copy(_possibleFieldMasks, destination._possibleFieldMasks, Length);
            destination.CopyStaticFieldStates(this);
            Array.Copy(_nativeOutputDestinations, destination._nativeOutputDestinations, Length);
            Array.Copy(_nativeOutputResults, destination._nativeOutputResults, Length);
            Array.Copy(_initializationPostconditionResults,
                destination._initializationPostconditionResults, Length);
            Array.Copy(_initializationPostconditionAliasFacts,
                destination._initializationPostconditionAliasFacts, Length);
            if (_booleanValues is not null)
            {
                Array.Copy(_booleanValues, destination._booleanValues!,
                    Length);
            }
            destination.CopyConditionalInitializedTargets(this);
            destination._initializationPostconditionCallFacts.Clear();
            foreach (var (call, fact)
                in _initializationPostconditionCallFacts)
            {
                destination._initializationPostconditionCallFacts.Add(call,
                    fact);
            }
            destination._fieldGenerationContext = _fieldGenerationContext;
            destination._fieldPlaceGenerations = new Dictionary<FieldGenerationKey, long>(
                _fieldPlaceGenerations);
            destination._nestedOwnerStates =
                new Dictionary<NestedOwnerStateKey, NestedOwnerFieldState>(_nestedOwnerStates);
            destination._consumedInitializationAuthorities.Clear();
            destination._consumedInitializationAuthorities.UnionWith(
                _consumedInitializationAuthorities);
            destination._activeInitializationReservations.Clear();
            destination._activeInitializationReservations.UnionWith(
                _activeInitializationReservations);
            destination._incomingReferenceInitializationStates.Clear();
            foreach (var (target, possibilities)
                in _incomingReferenceInitializationStates)
            {
                destination._incomingReferenceInitializationStates.Add(
                    target, possibilities);
            }
            destination.CopyGenericUniqueProperties(this);
            destination._rawUnionInitializedBytes.Clear();
            foreach (var (variable, bytes) in _rawUnionInitializedBytes)
            {
                destination._rawUnionInitializedBytes.Add(variable,
                    (byte[])bytes.Clone());
            }
            destination._rawUnionArrayElementBytes = rawUnionArrayReplacement;
            destination.ReplaceRepeatSnapshotStateLease(repeatOutputState);
            destination._nativeOutputStateCount = _nativeOutputStateCount;
            destination.ScopeActivation = ScopeActivation;
            destination.CopyIntegerFacts(this);
            destination._activeStorageScopes.Clear();
            destination._activeStorageScopes.AddRange(_activeStorageScopes);
            if (Dependencies is not null && destination.Dependencies is not null)
            {
                Dependencies.CopyTo(destination.Dependencies);
            }
            else if (Dependencies is not null || destination.Dependencies is not null)
            {
                throw Invalid();
            }
        }

        internal void MarkAssigned(int index)
        {
            _possibilities[index] = 2;
            if (_booleanValues is not null)
            {
                _booleanValues[index] = -1;
            }
            SetNativeOutputState(index, null, null);
            _initializationPostconditionResults[index] = null;
            if (_integerSymbolTypes.TryGetValue(
                    _integerSymbols[index], out var type))
            {
                HavocIntegerVariable(index, type);
            }
        }

        internal void InitializeRawUnionPayloadFacts(int variable,
            byte[] initializedBytes)
        {
            ArgumentNullException.ThrowIfNull(initializedBytes);
            if ((uint)variable >= (uint)Length
                || initializedBytes.Length == 0
                || _rawUnionInitializedBytes.ContainsKey(variable))
            {
                throw Invalid();
            }

            _rawUnionInitializedBytes.Add(variable,
                (byte[])initializedBytes.Clone());
        }

        internal byte[] GetRawUnionInitializedBytes(int variable)
        {
            if (!TryGetRawUnionInitializedBytes(variable,
                    out var initializedBytes))
            {
                throw Invalid();
            }

            return initializedBytes;
        }

        internal bool TryGetRawUnionInitializedBytes(int variable,
            out byte[] initializedBytes)
        {
            if (_rawUnionInitializedBytes.TryGetValue(variable,
                    out var storedBytes))
            {
                initializedBytes = (byte[])storedBytes.Clone();
                return true;
            }

            initializedBytes = [];
            return false;
        }

        internal void SetRawUnionInitializedBytes(int variable,
            ReadOnlySpan<byte> initializedBytes)
        {
            if (!_rawUnionInitializedBytes.TryGetValue(variable,
                    out var currentBytes)
                || currentBytes.Length != initializedBytes.Length)
            {
                throw Invalid();
            }

            _rawUnionInitializedBytes[variable] = initializedBytes.ToArray();
        }

        internal void ReplaceRawUnionPayloadRange(int variable,
            int offset, ReadOnlySpan<byte> initializedBytes)
        {
            if (!_rawUnionInitializedBytes.TryGetValue(variable,
                    out var currentBytes)
                || offset < 0 || offset > currentBytes.Length
                || initializedBytes.Length > currentBytes.Length - offset)
            {
                throw Invalid();
            }

            Array.Clear(currentBytes, offset, initializedBytes.Length);
            for (var index = 0; index < initializedBytes.Length; index++)
            {
                currentBytes[offset + index] = initializedBytes[index];
            }
        }

        internal void ClearRawUnionPayloadFacts(int variable)
        {
            if (_rawUnionInitializedBytes.TryGetValue(variable,
                    out var initializedBytes))
            {
                Array.Clear(initializedBytes);
            }
            ClearRawUnionArrayFacts(variable);
        }

        internal void ClearRawUnionArrayFacts(int variable)
            => ClearRawUnionArrayFacts(variable,
                StorageProjection.WholeObject);

        internal void ClearRawUnionArrayFacts(int variable,
            StorageProjection prefix)
        {
            if ((uint)variable >= (uint)Length)
            {
                throw Invalid();
            }

            var inputBytes = RawUnionArrayLogicalBytes();
            using var repeatFrame = RepeatResources.EnterFrame();
            using var inputState
                = ReserveRawUnionArrayInputState(inputBytes);
            using var outputState
                = RepeatResources.ReserveState(BigInteger.Zero);
            var retained = new SortedDictionary<RawUnionArrayStateKey,
                RawUnionArrayElementState>(
                    RawUnionArrayStateKeyComparer.Instance);
            var outputHeaderWritten = false;
            foreach (var (key, state) in _rawUnionArrayElementBytes)
            {
                ChargeRepeatRoot(key.ArrayPrefix);
                if (key.Variable != variable
                    || !StorageProjectionPathIsPrefixOf(RepeatResources,
                        prefix.ProjectionPath,
                        key.ArrayPrefix.ProjectionPath))
                {
                    if (!outputHeaderWritten)
                    {
                        ChargeRepeatRootListHeader();
                        outputState.Add(16);
                        outputHeaderWritten = true;
                    }
                    ChargeRepeatRoot(key.ArrayPrefix);
                    outputState.Add(RawUnionArrayRootLogicalBytes(
                        key.ArrayPrefix));
                    retained.Add(key, state.CloneTo(outputState));
                }
                else
                {
                    RepeatResources.ConsumeWork();
                }
            }
            repeatFrame.Complete();
            _rawUnionArrayElementBytes = retained;
            ReplaceRepeatSnapshotStateLease(outputState);
        }

        internal bool CopyRawUnionArrayFacts(int destination,
            int source)
            => CopyRawUnionArrayFacts(destination,
                StorageProjection.WholeObject, source,
                StorageProjection.WholeObject);

        internal bool CopyRawUnionArrayFacts(int destination,
            StorageProjection destinationPrefix, int source,
            StorageProjection sourcePrefix)
        {
            if ((uint)destination >= (uint)Length
                || (uint)source >= (uint)Length)
            {
                throw Invalid();
            }
            if (destination == source
                && destinationPrefix == sourcePrefix)
            {
                return false;
            }

            var inputBytes = RawUnionArrayLogicalBytes();
            using var repeatFrame = RepeatResources.EnterFrame();
            using var repeatInputState
                = ReserveRawUnionArrayInputState(inputBytes);
            using var repeatOutputState
                = RepeatResources.ReserveState(BigInteger.Zero);
            var replacement = new SortedDictionary<RawUnionArrayStateKey,
                RawUnionArrayElementState>(
                    RawUnionArrayStateKeyComparer.Instance);
            var outputHeaderWritten = false;

            var leftEnumerator = _rawUnionArrayElementBytes.GetEnumerator();
            var rightEnumerator = _rawUnionArrayElementBytes.GetEnumerator();
            var hasLeft = false;
            var hasRight = false;
            var leftKey = default(RawUnionArrayStateKey);
            var rightKey = default(RawUnionArrayStateKey);
            RawUnionArrayElementState? leftState = null;
            RawUnionArrayElementState? rightState = null;

            void AdvanceLeft()
            {
                hasLeft = false;
                leftState = null;
                while (true)
                {
                    if (!leftEnumerator.MoveNext())
                    {
                        RepeatResources.ConsumeWork();
                        return;
                    }

                    RepeatResources.ConsumeWork();
                    var candidateKey = leftEnumerator.Current.Key;
                    ChargeRepeatRoot(candidateKey.ArrayPrefix);
                    RepeatResources.ConsumeWork(2);
                    if (candidateKey.Variable == destination
                        && StorageProjectionPathIsPrefixOf(RepeatResources,
                            destinationPrefix.ProjectionPath,
                            candidateKey.ArrayPrefix.ProjectionPath))
                    {
                        continue;
                    }

                    leftKey = candidateKey;
                    leftState = leftEnumerator.Current.Value;
                    hasLeft = true;
                    return;
                }
            }

            void AdvanceRight()
            {
                hasRight = false;
                rightState = null;
                while (true)
                {
                    if (!rightEnumerator.MoveNext())
                    {
                        RepeatResources.ConsumeWork();
                        return;
                    }

                    RepeatResources.ConsumeWork();
                    var candidateKey = rightEnumerator.Current.Key;
                    ChargeRepeatRoot(candidateKey.ArrayPrefix);
                    RepeatResources.ConsumeWork(2);
                    if (candidateKey.Variable != source
                        || !StorageProjectionPathIsPrefixOf(RepeatResources,
                            sourcePrefix.ProjectionPath,
                            candidateKey.ArrayPrefix.ProjectionPath))
                    {
                        continue;
                    }

                    var prefix = StorageProjection.Rebase(
                        destinationPrefix, sourcePrefix,
                        candidateKey.ArrayPrefix, RepeatResources);
                    if (prefix.Kind
                        == StorageProjectionKind.UnknownElement)
                    {
                        throw Invalid();
                    }
                    rightKey = new RawUnionArrayStateKey(destination, prefix);
                    rightState = rightEnumerator.Current.Value;
                    hasRight = true;
                    return;
                }
            }

            void AppendOutput(RawUnionArrayStateKey key,
                RawUnionArrayElementState state)
            {
                if (!outputHeaderWritten)
                {
                    ChargeRepeatRootListHeader();
                    repeatOutputState.Add(16);
                    outputHeaderWritten = true;
                }
                ChargeRepeatRoot(key.ArrayPrefix);
                repeatOutputState.Add(RawUnionArrayRootLogicalBytes(
                    key.ArrayPrefix));
                var output = state.CloneTo(repeatOutputState);
                if (!replacement.TryAdd(key, output))
                {
                    throw Invalid();
                }
            }

            AdvanceLeft();
            AdvanceRight();
            while (hasLeft || hasRight)
            {
                var comparison = 0;
                if (hasLeft && hasRight)
                {
                    RepeatResources.ConsumeWork();
                    comparison = RawUnionArrayStateKeyComparer.Instance
                        .Compare(leftKey, rightKey);
                    if (comparison == 0)
                    {
                        throw Invalid();
                    }
                }

                if (!hasRight || (hasLeft && comparison < 0))
                {
                    AppendOutput(leftKey, leftState ?? throw Invalid());
                    AdvanceLeft();
                }
                else
                {
                    AppendOutput(rightKey, rightState ?? throw Invalid());
                    AdvanceRight();
                }
            }
            var changed = !RawUnionArrayFactPrefixEquals(
                _rawUnionArrayElementBytes, replacement, destination,
                destinationPrefix);
            repeatFrame.Complete();
            _rawUnionArrayElementBytes = replacement;
            ReplaceRepeatSnapshotStateLease(repeatOutputState);
            return changed;
        }

        internal SortedDictionary<StorageProjection,
            RawUnionArrayElementState> SnapshotRawUnionArrayFacts(
            int variable, StorageProjection prefix,
            ref int remaining, int depth,
            out RepeatResourceLedger.StateLease? outputState)
        {
            outputState = null;
            Count(ref remaining, depth);
            if ((uint)variable >= (uint)Length)
            {
                throw Invalid();
            }

            using var repeatFrame = RepeatResources.EnterFrame();
            using var inputState = ReserveRawUnionArrayInputState(
                RawUnionArrayLogicalBytes());
            var snapshotState = RepeatResources.ReserveState(
                BigInteger.Zero);
            var snapshotStateTransferred = false;
            try
            {
                var result = new SortedDictionary<StorageProjection,
                    RawUnionArrayElementState>(
                        StorageProjectionComparer.Instance);
                var outputHeaderWritten = false;
                foreach (var (key, state) in _rawUnionArrayElementBytes)
                {
                    Count(ref remaining, depth + 1);
                    ChargeRepeatRoot(key.ArrayPrefix);
                    RepeatResources.ConsumeWork();
                    if (key.Variable != variable
                        || !StorageProjectionPathIsPrefixOf(RepeatResources,
                            prefix.ProjectionPath,
                            key.ArrayPrefix.ProjectionPath))
                    {
                        continue;
                    }

                    var relativePrefix = StorageProjection.Rebase(
                        StorageProjection.WholeObject, prefix,
                        key.ArrayPrefix, RepeatResources);
                    if (relativePrefix.Kind
                        == StorageProjectionKind.UnknownElement)
                    {
                        throw Invalid();
                    }
                    var rootBytes
                        = RawUnionArrayRootLogicalBytes(relativePrefix);
                    if (!outputHeaderWritten)
                    {
                        ChargeRepeatRootListHeader();
                        snapshotState.Add(16);
                        outputHeaderWritten = true;
                    }
                    ChargeRepeatRoot(relativePrefix);
                    snapshotState.Add(rootBytes);
                    var snapshot = state.CloneTo(snapshotState);
                    if (!result.TryAdd(relativePrefix, snapshot))
                    {
                        throw Invalid();
                    }
                }

                if (result.Count == 0)
                {
                    repeatFrame.Complete();
                    return result;
                }

                repeatFrame.Complete();
                outputState = snapshotState;
                snapshotStateTransferred = true;
                return result;
            }
            finally
            {
                if (!snapshotStateTransferred)
                {
                    snapshotState.Dispose();
                }
            }
        }

        private bool TryGetNextRawUnionArraySnapshot(
            ref SortedDictionary<StorageProjection,
                RawUnionArrayElementState>.Enumerator snapshots,
            ref int remaining, int depth, int variable,
            StorageProjection destinationPrefix,
            RepeatResourceLedger.StateLease snapshotInputs,
            out RawUnionArrayStateKey key,
            out RawUnionArrayElementState state)
        {
            if (!snapshots.MoveNext())
            {
                RepeatResources.ConsumeWork();
                key = default;
                state = null!;
                return false;
            }

            RepeatResources.ConsumeWork();
            Count(ref remaining, depth + 1);
            var relativePrefix = snapshots.Current.Key;
            state = snapshots.Current.Value;
            if (state is null
                || !NativeFixedArrayContract.MatchesLayout(state.Layout,
                    Program)
                || !CarriesRawUnionPayloadFacts(
                    Program, state.Layout.ElementType))
            {
                throw Invalid();
            }

            ChargeRepeatRoot(relativePrefix);
            var arrayPrefix = StorageProjection.Rebase(
                destinationPrefix, StorageProjection.WholeObject,
                relativePrefix, RepeatResources);
            if (arrayPrefix.Kind == StorageProjectionKind.UnknownElement)
            {
                throw Invalid();
            }

            key = new RawUnionArrayStateKey(variable, arrayPrefix);
            snapshotInputs.Add(RawUnionArrayRootLogicalBytes(relativePrefix)
                + state.LogicalBytes());
            return true;
        }

        internal bool SetRawUnionArrayFacts(int variable,
            StorageProjection destinationPrefix,
            SortedDictionary<StorageProjection,
                RawUnionArrayElementState> snapshots,
            ref int remaining, int depth)
        {
            Count(ref remaining, depth);
            if ((uint)variable >= (uint)Length || snapshots is null)
            {
                throw Invalid();
            }

            var inputBytes = RawUnionArrayLogicalBytes();
            using var inputState
                = ReserveRawUnionArrayInputState(inputBytes);
            using var snapshotInputs
                = RepeatResources.ReserveState(BigInteger.Zero);
            if (snapshots.Count != 0)
            {
                ChargeRepeatRootListHeader();
                snapshotInputs.Add(16);
            }
            using var outputState
                = RepeatResources.ReserveState(BigInteger.Zero);
            var replacement = new SortedDictionary<RawUnionArrayStateKey,
                RawUnionArrayElementState>(
                    RawUnionArrayStateKeyComparer.Instance);
            var outputHeaderWritten = false;
            var leftEnumerator = _rawUnionArrayElementBytes.GetEnumerator();
            var rightEnumerator = snapshots.GetEnumerator();
            var hasLeft = false;
            var leftKey = default(RawUnionArrayStateKey);
            RawUnionArrayElementState? leftState = null;

            void AdvanceLeft()
            {
                hasLeft = false;
                leftState = null;
                while (true)
                {
                    if (!leftEnumerator.MoveNext())
                    {
                        RepeatResources.ConsumeWork();
                        return;
                    }

                    RepeatResources.ConsumeWork();
                    var candidateKey = leftEnumerator.Current.Key;
                    ChargeRepeatRoot(candidateKey.ArrayPrefix);
                    RepeatResources.ConsumeWork(2);
                    if (candidateKey.Variable == variable
                        && StorageProjectionPathIsPrefixOf(RepeatResources,
                            destinationPrefix.ProjectionPath,
                            candidateKey.ArrayPrefix.ProjectionPath))
                    {
                        continue;
                    }

                    leftKey = candidateKey;
                    leftState = leftEnumerator.Current.Value;
                    hasLeft = true;
                    return;
                }
            }

            void AppendOutput(RawUnionArrayStateKey key,
                RawUnionArrayElementState state)
            {
                if (!outputHeaderWritten)
                {
                    ChargeRepeatRootListHeader();
                    outputState.Add(16);
                    outputHeaderWritten = true;
                }

                ChargeRepeatRoot(key.ArrayPrefix);
                outputState.Add(RawUnionArrayRootLogicalBytes(
                    key.ArrayPrefix));
                var output = state.CloneTo(outputState);
                if (!replacement.TryAdd(key, output))
                {
                    throw Invalid();
                }
            }

            AdvanceLeft();
            var hasRight = TryGetNextRawUnionArraySnapshot(ref rightEnumerator,
                ref remaining, depth, variable, destinationPrefix,
                snapshotInputs, out var rightKey, out var rightState);
            while (hasLeft || hasRight)
            {
                var comparison = 0;
                if (hasLeft && hasRight)
                {
                    RepeatResources.ConsumeWork();
                    comparison = RawUnionArrayStateKeyComparer.Instance
                        .Compare(leftKey, rightKey);
                    if (comparison == 0)
                    {
                        throw Invalid();
                    }
                }

                if (!hasRight || (hasLeft && comparison < 0))
                {
                    AppendOutput(leftKey, leftState ?? throw Invalid());
                    AdvanceLeft();
                }
                else
                {
                    AppendOutput(rightKey, rightState ?? throw Invalid());
                    hasRight = TryGetNextRawUnionArraySnapshot(
                        ref rightEnumerator, ref remaining, depth, variable,
                        destinationPrefix, snapshotInputs, out rightKey,
                        out rightState);
                }
            }

            var changed = !RawUnionArrayFactPrefixEquals(
                _rawUnionArrayElementBytes, replacement, variable,
                destinationPrefix);
            _rawUnionArrayElementBytes = replacement;
            ReplaceRepeatSnapshotStateLease(outputState);
            return changed;
        }

        internal void SetRawUnionArrayElementBytes(int variable,
            StorageProjection arrayPrefix,
            BoundNativeFixedArrayLayout layout, ulong? elementIndex,
            ReadOnlySpan<byte> initializedBytes)
        {
            if ((uint)variable >= (uint)Length
                || !NativeFixedArrayContract.MatchesLayout(layout, Program)
                || !CarriesRawUnionPayloadFacts(Program,
                    layout.ElementType))
            {
                throw Invalid();
            }

            var defaultBytes = GuaranteedInitializedPayloadBytes(
                layout.ElementType, Program);
            if (initializedBytes.Length != defaultBytes.Length)
            {
                throw Invalid();
            }

            var key = new RawUnionArrayStateKey(variable, arrayPrefix);
            ChargeRepeatRootLookup(key);
            var hasExactState = _rawUnionArrayElementBytes.TryGetValue(
                key, out var currentState);
            if (arrayPrefix.Kind == StorageProjectionKind.WholeObject
                || arrayPrefix.ProjectionPath.IsConcrete
                || hasExactState)
            {
                if (hasExactState && elementIndex is ulong exactIndex)
                {
                    var existingState = currentState ?? throw Invalid();
                    if (existingState.Layout != layout)
                    {
                        throw Invalid();
                    }
                    _ = ReplaceRawUnionArrayElementState(key,
                        existingState, exactIndex, initializedBytes);
                    return;
                }

                if (hasExactState && elementIndex is null)
                {
                    var existingState = currentState ?? throw Invalid();
                    if (existingState.Layout != layout)
                    {
                        throw Invalid();
                    }

                    using var exactUnknownWriteFrame
                        = RepeatResources.EnterFrame();
                    using var exactUnknownWriteOutput
                        = RepeatResources.ReserveState(BigInteger.Zero);
                    SortedDictionary<RawUnionArrayStateKey,
                        RawUnionArrayElementState>? exactUnknownReplacement
                        = null;
                    var exactUnknownHeaderWritten = false;
                    var exactUnknownChanged = false;
                    foreach (var (candidateKey, candidateState)
                        in _rawUnionArrayElementBytes)
                    {
                        RepeatResources.ConsumeWork(
                            (ulong)candidateKey.ArrayPrefix.ProjectionPath
                                .Segments.Length + 1);
                        if (candidateKey == key)
                        {
                            EnsureRawUnionArrayRootOutputList(
                                ref exactUnknownReplacement,
                                ref exactUnknownHeaderWritten,
                                exactUnknownWriteOutput);
                            ChargeRepeatRoot(candidateKey.ArrayPrefix);
                            exactUnknownWriteOutput.Add(
                                RawUnionArrayRootLogicalBytes(
                                    candidateKey.ArrayPrefix));
                            var updatedState
                                = candidateState.CreateUnknownIndexWrite(
                                    initializedBytes,
                                    exactUnknownWriteOutput,
                                    out var exactStateChanged);
                            exactUnknownReplacement!.Add(candidateKey,
                                updatedState);
                            exactUnknownChanged = exactStateChanged;
                        }
                        else
                        {
                            AppendRawUnionArrayRootClone(
                                ref exactUnknownReplacement,
                                ref exactUnknownHeaderWritten,
                                candidateKey, candidateState,
                                exactUnknownWriteOutput);
                        }
                    }

                    if (exactUnknownChanged)
                    {
                        exactUnknownWriteFrame.Complete();
                        _rawUnionArrayElementBytes
                            = exactUnknownReplacement ?? throw Invalid();
                        ReplaceRepeatSnapshotStateLease(
                            exactUnknownWriteOutput);
                    }
                    else
                    {
                        exactUnknownWriteFrame.Complete();
                    }
                    return;
                }

                using var repeatFrame = RepeatResources.EnterFrame();
                RawUnionArrayElementState? templateState = null;
                RepeatResourceLedger.StateLease? templateStateLease = null;
                var hasTemplateState = !hasExactState
                    && TryGetRawUnionArrayTemplateState(variable,
                        arrayPrefix, layout, out templateState,
                        out templateStateLease);
                using var templateStateOwner = templateStateLease;
                if (!hasExactState && elementIndex is ulong selectedIndex)
                {
                    _ = InsertRawUnionArrayElementState(key, layout,
