            using var repeatFrame = RepeatResources.EnterFrame();
            if (hasState && elementIndex is ulong exactIndex
                && locationIsExact)
            {
                var existingState = currentState ?? throw Invalid();
                if (existingState.Layout != layout)
                {
                    throw Invalid();
