                        fieldMasks[i] = !trueCompletes ? falseMasks[i] : !falseCompletes ? trueMasks[i]
                            : trueMasks[i] & falseMasks[i];
                        initialized.SetPossibleFieldMask(i, !trueCompletes
                            ? falseState.PossibleFieldMask(i)
                            : !falseCompletes ? trueState.PossibleFieldMask(i)
                            : trueState.PossibleFieldMask(i) | falseState.PossibleFieldMask(i));
                        if (trueCompletes && falseCompletes)
                        {
                            _ = initialized.MergeRawUnionInitializedBytes(i,
                                trueState, falseState);
                            _ = initialized.MergeFieldPlaceGenerations(i,
                                trueState, falseState);
                            _ = initialized.MergeNestedOwnerStates(i,
                                trueState, falseState);
                        }
                        else if (trueCompletes)
                        {
                            _ = initialized.CopyRawUnionInitializedBytes(i,
                                trueState);
                            _ = initialized.CopyFieldPlaceGenerations(i, trueState);
                            _ = initialized.CopyNestedOwnerStates(i, trueState);
                        }
                        else if (falseCompletes)
                        {
                            _ = initialized.CopyRawUnionInitializedBytes(i,
                                falseState);
                            _ = initialized.CopyFieldPlaceGenerations(i, falseState);
                            _ = initialized.CopyNestedOwnerStates(i, falseState);
                        }
                        if (trueCompletes && falseCompletes)
                        {
                            _ = initialized.CopyProvenanceSlot(i, trueState);
                            _ = initialized.MergeProvenanceSlot(i, falseState);
                        }
                        else if (trueCompletes)
                        {
                            _ = initialized.CopyProvenanceSlot(i, trueState);
                        }
                        else if (falseCompletes)
                        {
                            _ = initialized.CopyProvenanceSlot(i, falseState);
                        }
                    }
                    if (trueCompletes && falseCompletes)
                    {
                        initialized.CopyIntegerFacts(trueState);
                        initialized.MergeIntegerFacts(falseState);
                    }
                    else if (trueCompletes)
                    {
                        initialized.CopyIntegerFacts(trueState);
                    }
                    else if (falseCompletes)
                    {
                        initialized.CopyIntegerFacts(falseState);
                    }
                    initialized.JoinStaticFieldStates(trueState,
                        trueCompletes, falseState, falseCompletes);
                    _ = initialized.MergeNativeOutputState(trueState, trueCompletes,
                        falseState, falseCompletes);
                }
                break;
            }
            case BoundIndirectCall call:
                VerifyIndirectCall(call, function, program);
                var indirectSignature = program.NativeFunctionPointerSignatures[
                    NativeFunctionPointerTypes.Index(call.Target.Type)];
                var indirectStagedDependencyCount = initialized.Dependencies?.Staged.Count ?? 0;
                try
                {
                    if (!EvaluateExpression(call.Target, initialized, fieldMasks, declarations,
                        function, program, ref remaining, depth + 1, failures))
                    {
                        foreach (var argument in call.Arguments)
                        {
                            ValidateUnreachableExpression(argument, initialized, fieldMasks,
                                declarations, function, program, ref remaining, depth + 1);
                        }
                        break;
                    }

                    var indirectCallCompletes = true;
                    var indirectOutputTargets = new HashSet<int>();
                    for (var index = 0; index < call.Arguments.Length; index++)
                    {
                        var argument = call.Arguments[index];
                        if (!indirectCallCompletes)
                        {
                            ValidateUnreachableExpression(argument, initialized, fieldMasks,
                                declarations, function, program, ref remaining, depth + 1);
                            continue;
                        }

                        var isNativeOutput = indirectSignature.OutputStates.Any(outputState =>
                            outputState.FormalOrdinal == (uint)index);
                        if (isNativeOutput)
                        {
                            if (!NativeFunctionPointerContract.TryGetNativeOutputContract(
                                indirectSignature, index, program.NativePointerTypes,
                                out var output)
                                || output is null
                                || argument is not BoundNativeOutputReservation reservation
                                || !MatchesReservation(reservation, output, function, program)
                                || !indirectOutputTargets.Add(reservation.Variable))
                            {
                                throw InvalidEffect(call.Span, "NativeImport");
                            }
                            VerifyNativeOutputReservation(reservation, output,
                                initialized, fieldMasks, declarations, function, program,
                                ref remaining, depth + 1, failures);
                            StageIndirectDependencySource(call, index, argument,
                                indirectSignature, initialized, program,
                                ref remaining, depth + 1);
                            continue;
                        }

                        var nativeParameter = indirectSignature.NativeParameters
                            .FirstOrDefault(parameter => parameter.ParameterIndex == index);
                        if (nativeParameter is not null
                            && argument is BoundNativeStorageAddress address)
                        {
                            VerifyDirectNativeParameterAddress(address, nativeParameter,
                                initialized, fieldMasks, declarations, function, program,
                                ref remaining, depth + 1, failures);
                            StageIndirectDependencySource(call, index, argument,
                                indirectSignature, initialized, program,
                                ref remaining, depth + 1);
                            continue;
                        }

                        indirectCallCompletes = EvaluateExpression(argument, initialized,
                            fieldMasks, declarations, function, program, ref remaining,
                            depth + 1, failures);
                        if (indirectCallCompletes)
                        {
                            if (nativeParameter is not null
                                && argument is not BoundNativeStorageAddress
                                && !DirectNativeImportContract.IsStringPointerArgument(
                                    argument, nativeParameter, program))
                            {
                                VerifyNativeParameterValueExtent(argument,
                                    nativeParameter, call.IsUnsafeAuthorized,
                                    initialized, function, program,
                                    ref remaining, depth + 1);
                            }
                            StageIndirectDependencySource(call, index, argument,
                                indirectSignature, initialized, program,
                                ref remaining, depth + 1);
                        }
                    }

                    if (!indirectCallCompletes)
                    {
                        initialized.CancelUninvokedNativeOutputReservations();
                    }
                    if (indirectCallCompletes)
                    {
                        VerifyStagedNativeParameterExtents(call, indirectSignature,
                            initialized, function, program, ref remaining, depth + 1);
                        if (initialized.Dependencies is BackingDependencies dependencies
                            && MayWriteNativePointerStorage(call, program))
                        {
                            dependencies.MarkAllNativePointerProvenanceUnknown();
                            dependencies.InvalidateAllCopyOriginValues(
                                program, ref remaining, depth + 1);
                        }
                        InvalidateNativePointerExtentsForCall(
                            call, indirectSignature, initialized, program);
                        initialized.HavocIntegerValues();
                        if (indirectSignature.OutputStates.IsEmpty)
                        {
                            initialized.InvalidateNativeOutputCorrelations();
                        }
                        else
                        {
                            ApplyNativeOutputIndirectCallEffects(call,
                                indirectSignature, initialized, ref remaining);
                        }
                        failures?.Add(initialized, fieldMasks);
                        initialized.ClearConditionalInitializedTargets();
                    }
                }
                finally
                {
                    if (initialized.Dependencies is BackingDependencies stagedDependencies)
                    {
                        stagedDependencies.Staged.RemoveRange(indirectStagedDependencyCount,
                            stagedDependencies.Staged.Count - indirectStagedDependencyCount);
                    }
                }
                break;
            case BoundCall call:
                VerifyCallExpression(call, initialized, fieldMasks,
                    declarations, function, program, ref remaining,
                    depth, failures, statementCompound,
                    cleanupCounterStep,
                    program.AllowUnmaterializedInterfaceDefaults);
                break;
            default:
                throw Invalid();
        }
    }

    private static bool VerifyDefaultInitializationOutputs(
        InitializationState initialized, uint[] fieldMasks,
        BoundFunction function, BoundProgram program, bool? booleanResult,
        TextSpan span, ref int remaining, int depth)
    {
        var parameterOffset = function.IsConstructor ? 1 : 0;
        if (initialized.Dependencies is not BackingDependencies dependencies)
        {
            if (function.Variables
                .Skip(parameterOffset)
                .Take(function.ParameterCount)
                .Any(static parameter => parameter.IsInit))
            {
                throw Invalid(span);
            }
            return true;
        }

        for (var parameterIndex = parameterOffset;
            parameterIndex < function.ParameterCount + parameterOffset;
            parameterIndex++)
        {
            Count(ref remaining, depth);
            var parameter = function.Variables[parameterIndex];
            if (!parameter.IsInit || parameter.IsOut)
            {
                continue;
            }
            if (!CheckedReferenceTypeContract.IsValidType(
                    parameter.Type, program.CheckedReferenceTypes)
                || program.CheckedReferenceTypes[
                    CheckedReferenceTypes.Index(parameter.Type)] is not {
                        IsInitialization: true,
                        IsGarbageCollected: false,
                        IsOptional: false,
                    })
            {
                throw InvalidEffect(span, "CheckedReference");
            }

            if (HasExplicitInitializationOutputPostcondition(
                function, parameterIndex, ref remaining, depth + 1))
            {
                continue;
            }
            if (function.ReturnType == PrimitiveType.Bool
                && booleanResult is not bool)
            {
                throw Invalid(span);
            }

            var destination = new BoundRead(parameterIndex,
                parameter.Type, span);
            var targets = ReferenceTargetsOfExpression(destination,
                dependencies, initialized, function, program,
                ref remaining, depth + 1, fieldMasks);
            if (targets.Count == 0)
            {
                throw Invalid(span);
            }

            var mustBeLive = function.ReturnType != PrimitiveType.Bool
                || booleanResult == true;
            foreach (var target in targets)
            {
                var definitelyLive = ReferenceTargetIsInitialized(target,
                        program.CheckedReferenceTypes[
                            CheckedReferenceTypes.Index(parameter.Type)]
                            .ReferentType,
                        span, initialized, fieldMasks, function, program,
                        ref remaining, depth + 1);
                var satisfiesOutput = mustBeLive
                    ? definitelyLive
                    : ReferenceTargetIsVacant(target, initialized,
                        fieldMasks, program);
                if (!satisfiesOutput)
                {
                    throw Invalid(span);
                }
            }
        }

        return true;
    }

    private static bool HasExplicitInitializationOutputPostcondition(
        BoundFunction function, int parameterIndex, ref int remaining,
        int depth)
    {
        foreach (var clause in function.DeclarationContractClauses)
        {
            Count(ref remaining, depth);
            if (clause.Phase
                    == BoundDeclarationContractPhase.NormalPostcondition
                && ReferencesInitializationOutput(clause.Predicate,
                    parameterIndex, ref remaining, depth + 1))
            {
                return true;
            }
        }

        return false;
    }

    private static bool HasInitializationReferenceOutput(
        BoundFunction function, BoundProgram program)
    {
        var parameterOffset = function.IsConstructor ? 1 : 0;
        for (var index = parameterOffset;
            index < function.ParameterCount + parameterOffset; index++)
        {
            if (IsInitializationReferenceOutputParameter(
                function, index, program))
            {
                return true;
            }
        }

        return false;
    }

    private static bool IsInitializationReferenceOutputParameter(
        BoundFunction function, int parameterSlot, BoundProgram program)
    {
        var parameterOffset = function.IsConstructor ? 1 : 0;
        if (parameterSlot < parameterOffset
            || parameterSlot >= function.ParameterCount + parameterOffset
            || parameterSlot >= function.Variables.Length)
        {
            return false;
        }

        var parameter = function.Variables[parameterSlot];
        return parameter.IsInit && !parameter.IsOut
            && CheckedReferenceTypeContract.IsValidType(
                parameter.Type, program.CheckedReferenceTypes)
            && program.CheckedReferenceTypes[
                CheckedReferenceTypes.Index(parameter.Type)]
                is {
                    IsInitialization: true,
                    IsGarbageCollected: false,
                    IsOptional: false,
                };
    }

    private static bool HasInitializationReferenceOutputCall(
        BoundCall call, BoundProgram program)
    {
        if ((uint)call.Function >= (uint)program.Functions.Length)
        {
            return false;
        }

        var target = program.Functions[call.Function];
        var parameterOffset = target.IsConstructor ? 1 : 0;
        for (var argumentIndex = 0;
            argumentIndex < call.Arguments.Length; argumentIndex++)
        {
            if (IsInitializationReferenceOutputParameter(target,
                    call.ParameterIndex(argumentIndex) + parameterOffset,
                    program))
            {
                return true;
            }
        }

        return false;
    }

    private static void ApplyInitializationReferenceOutputArgument(
        BoundCall call, BoundFunction target, int argumentIndex,
        BoundExpression argument, InitializationState state,
        uint[] fieldMasks,
        bool maybeInitialized, ref int remaining, int depth)
    {
        var parameterOffset = target.IsConstructor ? 1 : 0;
        if (!IsInitializationReferenceOutputParameter(target,
                call.ParameterIndex(argumentIndex) + parameterOffset,
                state.Program)
            || state.Dependencies is not BackingDependencies dependencies)
        {
            throw InvalidEffect(call.Span, "CheckedReference");
        }

        var targets = ReferenceTargetsOfExpression(argument, dependencies,
            state, dependencies.Function, state.Program, ref remaining,
            depth, state.PossibleFieldMasks);
        if (targets.Count == 0)
        {
            throw InvalidEffect(argument.Span, "CheckedReference");
        }
        ApplyInitializationReferenceOutputTargets(targets, state,
            fieldMasks, dependencies, argument.Span, maybeInitialized);
    }

    private static void ApplyInitializationReferenceOutputTargets(
        IReadOnlyCollection<ProvenanceAnchor> targets,
        InitializationState state, uint[] fieldMasks,
        BackingDependencies dependencies,
        TextSpan span, bool maybeInitialized)
    {
        if (targets.Count == 0)
        {
            throw InvalidEffect(span, "CheckedReference");
        }

        var firstTarget = targets.First();
        var allTargetsAreOneLocalPlace
            = firstTarget.Kind == ProvenanceAnchorKind.ReferencePlace
            && firstTarget.Storage is StorageKey firstStorage
            && targets.All(referenceTarget =>
                referenceTarget.Kind == ProvenanceAnchorKind.ReferencePlace
                && referenceTarget.Identity == firstTarget.Identity
                && referenceTarget.Storage is StorageKey targetStorage
                && targetStorage.Site == firstStorage.Site
                && targetStorage.Projection == firstStorage.Projection);
        foreach (var referenceTarget in targets)
        {
            if (maybeInitialized
                || (targets.Count > 1 && !allTargetsAreOneLocalPlace))
            {
                SetInitializationPostconditionTargetMaybeInitialized(
                    referenceTarget, state, fieldMasks,
                    dependencies.Function, state.Program, span);
            }
            else
            {
                SetInitializationPostconditionTargetInitialized(
                    referenceTarget, state, fieldMasks,
                    dependencies.Function, state.Program, span);
            }
        }
    }

    private static bool ReferencesInitializationOutput(
        BoundExpression expression, int parameterIndex,
        ref int remaining, int depth)
    {
        Count(ref remaining, depth);
        if (expression is BoundReferenceInitializationTest test
            && ContainsVariableRead(test.Descriptor, parameterIndex,
                ref remaining, depth + 1))
        {
            return true;
        }
        if (expression is BoundReferenceRead read
            && ContainsVariableRead(read.Descriptor, parameterIndex,
                ref remaining, depth + 1))
        {
            return true;
        }
        foreach (var nested in expression.NestedExpressions)
        {
            if (ReferencesInitializationOutput(nested, parameterIndex,
                ref remaining, depth + 1))
            {
                return true;
            }
        }
        return false;
    }

    private static bool ContainsVariableRead(BoundExpression expression,
        int variable, ref int remaining, int depth)
    {
        Count(ref remaining, depth);
        if (expression is BoundRead read && read.Variable == variable)
        {
            return true;
        }
        foreach (var nested in expression.NestedExpressions)
        {
            if (ContainsVariableRead(nested, variable, ref remaining,
                depth + 1))
            {
                return true;
            }
        }
        return false;
    }

    private static bool VerifyNormalDeclarationPostconditions(
        InitializationState initialized, uint[] fieldMasks,
        HashSet<int> declarations, BoundFunction function,
        BoundProgram program, ref int remaining, int depth,
        FailureEdges? failures)
    {
        foreach (var clause in function.DeclarationContractClauses)
        {
            Count(ref remaining, depth);
            if (clause.Phase
                != BoundDeclarationContractPhase.NormalPostcondition)
            {
                continue;
            }

            var beforePostcondition = initialized.Clone();
            var beforeMasks = (uint[])fieldMasks.Clone();
            Expression(clause.Predicate, initialized, fieldMasks,
                declarations, function, program, ref remaining, depth + 1,
                failures);
            beforePostcondition.CopyTo(initialized);
            beforeMasks.CopyTo(fieldMasks, 0);

            if (!CanCompleteNormally(clause.Predicate, initialized, program,
                ref remaining, depth + 1))
            {
                return false;
            }
            if (CanBe(clause.Predicate, false, ref remaining, initialized))
            {
                var failedState = Outcome(clause.Predicate, initialized,
                    false, ref remaining);
                var failedMasks = (uint[])fieldMasks.Clone();
                MarkOutMasks(failedState, failedMasks, function, program);
                failures?.Add(failedState, failedMasks);
            }
            if (!CanBe(clause.Predicate, true, ref remaining, initialized))
            {
                return false;
            }

            var acceptedState = Outcome(clause.Predicate, initialized,
                true, ref remaining);
            acceptedState.CopyTo(initialized);
            MarkOutMasks(initialized, fieldMasks, function, program);
        }
        return true;
    }

    private sealed record InitializationPostconditionTargetFact(
        ProvenanceAnchor Target, byte TruePossibilities,
        byte FalsePossibilities);

    private sealed record InitializationPostconditionAliasTargetFact(
        ProvenanceAnchor Descriptor,
        ImmutableHashSet<ProvenanceAnchor> Targets);

    private sealed record InitializationPostconditionAliasFact(
        ProvenanceAnchor Descriptor,
        ImmutableHashSet<ProvenanceAnchor> Targets,
        byte Possibilities);

    private sealed record InitializationPostconditionCallFact(
        bool CanReturnTrue, bool CanReturnFalse,
        ImmutableArray<InitializationPostconditionTargetFact> Targets,
        ImmutableArray<InitializationPostconditionAliasTargetFact> Aliases = default);

    private sealed record InitializationPostconditionCallClause(
        BoundExpression Predicate,
        Dictionary<BoundExpression, ProvenanceAnchor> Targets,
        TextSpan Span,
        ProvenanceAnchor? AliasDescriptor = null,
        ImmutableHashSet<ProvenanceAnchor>? AliasTargets = null);

    private static InitializationPostconditionAliasFact?
        MergeInitializationPostconditionAliasFacts(
            InitializationPostconditionAliasFact? left,
            InitializationPostconditionAliasFact? right)
    {
        if (left is null || right is null
            || left.Descriptor != right.Descriptor
            || !left.Targets.SetEquals(right.Targets))
        {
            return null;
        }

        return left with {
            Possibilities = (byte)(left.Possibilities | right.Possibilities),
        };
    }

    private static bool InitializationPostconditionCallFactReferencesAlias(
        InitializationPostconditionCallFact fact, int variable)
        => !fact.Aliases.IsDefaultOrEmpty
            && fact.Aliases.Any(alias =>
                alias.Descriptor.Identity == variable);

    private static bool TryGetDefaultInitializationPostconditionTarget(
        InitializationPostconditionCallClause clause,
        out ProvenanceAnchor target)
    {
        target = default;
        if (clause.Predicate is not BoundConditional {
                Condition: BoundContractReturnValue {
                    Type: PrimitiveType.Bool,
                },
                WhenTrue: BoundReferenceInitializationTest initializedTest,
                WhenFalse: BoundUnary {
                    Operator: TokenKind.Bang,
                    Operand: BoundReferenceInitializationTest vacantTest,
                },
            }
            || !ReferenceEquals(initializedTest.Descriptor,
                vacantTest.Descriptor)
            || !clause.Targets.TryGetValue(initializedTest.Descriptor,
                out target)
            || !clause.Targets.TryGetValue(vacantTest.Descriptor,
                out var vacantTarget)
            || target != vacantTarget)
        {
            return false;
        }
        return true;
    }

    private static bool TryGetDefaultInitializationPostconditionAlias(
        InitializationPostconditionCallClause clause,
        out InitializationPostconditionAliasTargetFact alias)
    {
        alias = null!;
        if (clause.Predicate is not BoundConditional {
                Condition: BoundContractReturnValue {
                    Type: PrimitiveType.Bool,
                },
                WhenTrue: BoundReferenceInitializationTest initializedTest,
                WhenFalse: BoundUnary {
                    Operator: TokenKind.Bang,
                    Operand: BoundReferenceInitializationTest vacantTest,
                },
            }
            || !ReferenceEquals(initializedTest.Descriptor,
                vacantTest.Descriptor)
            || clause.AliasDescriptor is not ProvenanceAnchor descriptor
            || clause.AliasTargets is not { Count: > 1 } targets)
        {
            return false;
        }

        alias = new InitializationPostconditionAliasTargetFact(
            descriptor, targets);
        return true;
    }

    private static void ApplyInitializationPostconditionEffects(
        BoundCall call, BoundFunction target,
        InitializationState initialized, uint[] fieldMasks,
        BoundFunction function, BoundProgram program,
        FailureEdges? failures, ref int remaining, int depth,
        out ImmutableArray<InitializationPostconditionCallClause>
            callResultClauses)
    {
        var correlatedClauses = ImmutableArray.CreateBuilder<
            InitializationPostconditionCallClause>();
        callResultClauses = [];
        var parameterOffset = target.IsConstructor ? 1 : 0;
        var hasNormalPostconditions = target.DeclarationContractClauses.Any(
            static clause => clause.Phase
                == BoundDeclarationContractPhase.NormalPostcondition);
        var hasInitializationReferenceParameter
            = HasInitializationReferenceOutput(target, program);
        if (!hasInitializationReferenceParameter
            && !hasNormalPostconditions)
        {
            return;
        }
        if (initialized.Dependencies is not BackingDependencies dependencies)
        {
            throw InvalidEffect(call.Span, "CheckedReference");
        }
        if (target.DoesNotReturn)
        {
            return;
        }

        var initializationOutputTargets
            = new Dictionary<int, HashSet<ProvenanceAnchor>>();
        var initializationOutputTargetsByExpression
            = new Dictionary<BoundExpression,
                HashSet<ProvenanceAnchor>>(ReferenceEqualityComparer.Instance);
        if (hasInitializationReferenceParameter)
        {
            for (var argumentIndex = 0;
                argumentIndex < call.Arguments.Length; argumentIndex++)
            {
                Count(ref remaining, depth);
                var parameterIndex = call.ParameterIndex(argumentIndex)
                    + parameterOffset;
                if (parameterIndex < parameterOffset
                    || parameterIndex >= target.ParameterCount + parameterOffset)
                {
                    throw Invalid(call.Span);
                }

                var parameter = target.Variables[parameterIndex];
                if (!parameter.IsInit)
                {
                    continue;
                }
                if (parameter.IsOut
                    || !CheckedReferenceTypeContract.IsValidType(
                        parameter.Type, program.CheckedReferenceTypes)
                    || !program.CheckedReferenceTypes[
                        CheckedReferenceTypes.Index(parameter.Type)]
                        .IsInitialization)
                {
                    throw InvalidEffect(call.Span, "CheckedReference");
                }

                var targets = ReferenceTargetsOfExpression(
                    call.Arguments[argumentIndex], dependencies, initialized,
                    function, program, ref remaining, depth + 1, fieldMasks);
                if (targets.Count == 0)
                {
                    throw InvalidEffect(call.Arguments[argumentIndex].Span,
                        "CheckedReference");
                }
                if (!initializationOutputTargets.TryAdd(parameterIndex,
                    targets))
                {
                    throw Invalid(call.Span);
                }
                initializationOutputTargetsByExpression[
                    call.Arguments[argumentIndex]] = targets;
                foreach (var targetReference in targets)
                {
                    SetInitializationPostconditionTargetMaybeInitialized(
                        targetReference, initialized, fieldMasks, function,
                        program, call.Arguments[argumentIndex].Span);
                }
            }
        }

        if (hasNormalPostconditions)
        {
            foreach (var clause in target.DeclarationContractClauses)
            {
            Count(ref remaining, depth);
            if (clause.Phase
                != BoundDeclarationContractPhase.NormalPostcondition
                || !TryRewriteInitializationPostcondition(
                    clause.Predicate, call, target, parameterOffset,
                    null, ref remaining, depth + 1, out var predicate)
                || !IsSupportedInitializationPostconditionPredicate(
                    predicate, ref remaining, depth + 1)
                || !TryCollectInitializationPostconditionTargets(predicate,
                    dependencies, initialized, fieldMasks, function,
                    program, ref remaining, depth + 1, out var targets,
                    out _, initializationOutputTargetsByExpression)
                || targets.Count == 0)
            {
                continue;
            }
            if (ContainsInitializationPostconditionResult(predicate,
                ref remaining, depth + 1))
            {
                correlatedClauses.Add(
                    new InitializationPostconditionCallClause(predicate,
                        targets, clause.Span));
            }

            var predicateInput = initialized.Clone();
            var predicateInputMasks = (uint[])fieldMasks.Clone();
            foreach (var referenceTarget in targets.Values.Distinct())
            {
                SetInitializationPostconditionTargetMaybeInitialized(
                    referenceTarget, predicateInput, predicateInputMasks,
                    function, program, clause.Span);
            }

            if (failures is not null
                && CanBeInitializationPostcondition(predicate, false,
                    predicateInput, targets, function, program,
                    ref remaining, depth + 1))
            {
                var failureState
                    = OutcomeInitializationPostcondition(predicate,
                        predicateInput, false, targets, function, program,
                        ref remaining, depth + 1);
                failures.Add(failureState,
                    (uint[])failureState.PossibleFieldMasks.Clone());
            }

            if (CanBeInitializationPostcondition(predicate, true,
                predicateInput, targets, function, program,
                ref remaining, depth + 1))
            {
                var acceptedState
                    = OutcomeInitializationPostcondition(predicate,
                        predicateInput, true, targets, function, program,
                        ref remaining, depth + 1);
                acceptedState.CopyTo(initialized);
                Array.Copy(acceptedState.PossibleFieldMasks, fieldMasks,
                    fieldMasks.Length);
            }
        }
        }

        foreach (var (parameterIndex, targets)
            in initializationOutputTargets)
        {
            var argumentIndex = -1;
            for (var index = 0; index < call.Arguments.Length; index++)
            {
                if (call.ParameterIndex(index) + parameterOffset
                    == parameterIndex)
                {
                    argumentIndex = index;
                    break;
                }
            }
            if (argumentIndex < 0)
            {
                throw Invalid(call.Span);
            }

            var argument = call.Arguments[argumentIndex];
            if (target.ReturnType == PrimitiveType.Bool)
            {
                var initializedTest
                    = new BoundReferenceInitializationTest(argument,
                        argument.Span);
                var vacantTest = new BoundUnary(TokenKind.Bang,
                    initializedTest, PrimitiveType.Bool, argument.Span);
                var defaultPredicate = new BoundConditional(
                    new BoundContractReturnValue(PrimitiveType.Bool,
                        argument.Span),
                    initializedTest, vacantTest, PrimitiveType.Bool,
                    argument.Span);
                if (targets.Count == 1)
                {
                    var defaultTargets
                        = new Dictionary<BoundExpression,
                            ProvenanceAnchor>(
                                ReferenceEqualityComparer.Instance) {
                            [argument] = targets.Single(),
                        };
                    correlatedClauses.Add(
                        new InitializationPostconditionCallClause(
                            defaultPredicate, defaultTargets,
                            argument.Span));
                }
                else if (targets.Count > 1
                    && argument is BoundReferenceReborrow)
                {
                    var descriptorPlaces
                        = ReferenceDescriptorPlacesOfExpression(argument,
                            dependencies, initialized, function, program,
                            ref remaining, depth + 1, fieldMasks);
                    if (descriptorPlaces.Count == 1
                        && descriptorPlaces.Single().Kind is
                            ProvenanceAnchorKind.ReferenceDescriptor
                            or ProvenanceAnchorKind.IncomingReferenceDescriptor)
                    {
                        correlatedClauses.Add(
                            new InitializationPostconditionCallClause(
                                defaultPredicate,
                                new Dictionary<BoundExpression,
                                    ProvenanceAnchor>(
                                        ReferenceEqualityComparer.Instance),
                                argument.Span,
                                descriptorPlaces.Single(),
                                    ImmutableHashSet.CreateRange(targets)));
                    }
                }
                continue;
            }

            if (HasExplicitInitializationOutputPostcondition(target,
                parameterIndex, ref remaining, depth + 1))
            {
                continue;
            }

            if (targets.Count == 1)
            {
                SetInitializationPostconditionTargetInitialized(
                    targets.Single(), initialized, fieldMasks, function,
                    program, argument.Span);
            }
            else
            {
                foreach (var referenceTarget in targets)
                {
                    SetInitializationPostconditionTargetMaybeInitialized(
                        referenceTarget, initialized, fieldMasks, function,
                        program, argument.Span);
                }
            }
        }
        callResultClauses = correlatedClauses.ToImmutable();
    }

    private static BoundExpression ReplaceInitializationPostconditionResult(
        BoundExpression expression, bool result)
    {
        if (expression is BoundContractReturnValue returnValue)
        {
            return returnValue.Type == PrimitiveType.Bool
                ? new BoundConstant(result ? 1 : 0, PrimitiveType.Bool,
                    returnValue.Span)
                : expression;
        }

        var replacements = new Dictionary<BoundExpression,
            BoundExpression>(ReferenceEqualityComparer.Instance);
        foreach (var nested in expression.NestedExpressions)
        {
            var rewritten = ReplaceInitializationPostconditionResult(
                nested, result);
            if (!ReferenceEquals(nested, rewritten))
            {
                replacements[nested] = rewritten;
            }
        }

        return replacements.Count == 0 ? expression
            : expression.RewriteNestedExpressions(nested =>
                replacements.TryGetValue(nested, out var replacement)
                    ? replacement : nested);
    }

    private static InitializationPostconditionCallFact?
        CreateInitializationPostconditionCallFact(
            BoundFunction target,
            ImmutableArray<InitializationPostconditionCallClause>
                callResultClauses,
            InitializationState initialized, uint[] fieldMasks,
            BoundFunction function, BoundProgram program,
            ref int remaining, int depth)
    {
        if (target.ReturnType != PrimitiveType.Bool
            || callResultClauses.IsDefaultOrEmpty)
        {
            return null;
        }

        var trueState = initialized.Clone();
        var falseState = initialized.Clone();
        var trueMasks = (uint[])fieldMasks.Clone();
        var falseMasks = (uint[])fieldMasks.Clone();
        var canReturnTrue = true;
        var canReturnFalse = true;
        var targets = new HashSet<ProvenanceAnchor>();
        var aliases = ImmutableArray.CreateBuilder<
            InitializationPostconditionAliasTargetFact>();
        foreach (var clause in callResultClauses)
        {
            Count(ref remaining, depth);
            if (TryGetDefaultInitializationPostconditionTarget(clause,
                    out var defaultTarget))
            {
                _ = targets.Add(defaultTarget);
                SetInitializationPostconditionTargetInitialized(
                    defaultTarget, trueState, trueMasks, function, program,
                    clause.Span);
                SetInitializationPostconditionTargetVacant(defaultTarget,
                    falseState, falseMasks, function, program, clause.Span);
                continue;
            }
            if (TryGetDefaultInitializationPostconditionAlias(clause,
                    out var alias))
            {
                aliases.Add(alias);
                foreach (var destination in alias.Targets)
                {
                    _ = targets.Add(destination);
                    if (canReturnTrue)
                    {
                        SetInitializationPostconditionTargetMaybeInitialized(
                            destination, trueState, trueMasks, function,
                            program, clause.Span);
                    }
                    if (canReturnFalse)
                    {
                        SetInitializationPostconditionTargetMaybeInitialized(
                            destination, falseState, falseMasks, function,
                            program, clause.Span);
                    }
                }
                continue;
            }
            if (canReturnTrue)
            {
                var truePredicate
                    = ReplaceInitializationPostconditionResult(
                        clause.Predicate, true);
                if (!IsSupportedInitializationPostconditionPredicate(
                        truePredicate, ref remaining, depth + 1))
                {
                    return null;
                }

                foreach (var destination in clause.Targets.Values.Distinct())
                {
                    _ = targets.Add(destination);
                }
                var predicateInput = trueState.Clone();
                var predicateInputMasks = (uint[])trueMasks.Clone();
                foreach (var destination in clause.Targets.Values.Distinct())
                {
                    SetInitializationPostconditionTargetMaybeInitialized(
                        destination, predicateInput, predicateInputMasks,
                        function, program, clause.Span);
                }
                if (!CanBeInitializationPostcondition(truePredicate, true,
                    predicateInput, clause.Targets, function, program,
                    ref remaining, depth + 1))
                {
                    canReturnTrue = false;
                }
                else
                {
                    var acceptedState
                        = OutcomeInitializationPostcondition(
                            truePredicate, predicateInput, true,
                            clause.Targets, function, program,
                            ref remaining, depth + 1);
                    acceptedState.CopyTo(trueState);
                    Array.Copy(acceptedState.PossibleFieldMasks,
                        trueMasks, trueMasks.Length);
                }
            }

            if (canReturnFalse)
            {
                var falsePredicate
                    = ReplaceInitializationPostconditionResult(
                        clause.Predicate, false);
                if (!IsSupportedInitializationPostconditionPredicate(
                    falsePredicate, ref remaining, depth + 1))
                {
                    return null;
                }

                foreach (var destination in clause.Targets.Values.Distinct())
                {
                    _ = targets.Add(destination);
                }
                var predicateInput = falseState.Clone();
                var predicateInputMasks = (uint[])falseMasks.Clone();
                foreach (var destination in clause.Targets.Values.Distinct())
                {
                    SetInitializationPostconditionTargetMaybeInitialized(
                        destination, predicateInput, predicateInputMasks,
                        function, program, clause.Span);
                }
                if (!CanBeInitializationPostcondition(falsePredicate, true,
                    predicateInput, clause.Targets, function, program,
                    ref remaining, depth + 1))
                {
                    canReturnFalse = false;
                }
                else
                {
                    var acceptedState
                        = OutcomeInitializationPostcondition(
                            falsePredicate, predicateInput, true,
                            clause.Targets, function, program,
                            ref remaining, depth + 1);
                    acceptedState.CopyTo(falseState);
                    Array.Copy(acceptedState.PossibleFieldMasks,
                        falseMasks, falseMasks.Length);
                }
            }
        }

        if (targets.Count == 0)
        {
            return null;
        }

        var destinations = ImmutableArray.CreateBuilder<
            InitializationPostconditionTargetFact>(targets.Count);
        foreach (var destination in targets)
        {
            if (IsIncomingInitializationReferenceTarget(
                destination, function, program))
            {
                destinations.Add(new InitializationPostconditionTargetFact(
                    destination,
                    InitializationPostconditionTargetPossibilities(
                        destination, trueState, trueMasks, program),
                    InitializationPostconditionTargetPossibilities(
                        destination, falseState, falseMasks, program)));
                continue;
            }
            if (destination.Kind is not (
                    ProvenanceAnchorKind.ReferencePlace
                    or ProvenanceAnchorKind.NormalBackingPlace)
                || destination.Storage is not StorageKey storage
                || storage.Projection.Kind is not (
                    StorageProjectionKind.WholeObject
                    or StorageProjectionKind.InlineFieldPath)
                || !storage.IsKnown
                || (uint)destination.Identity >= (uint)initialized.Length)
            {
                return null;
            }

            var placeGeneration = initialized.FieldPlaceGeneration(
                destination.Identity, storage.Projection);
            var versionedTarget = destination with {
                Storage = storage with {
                    PlaceGeneration = placeGeneration,
                },
            };
            destinations.Add(new InitializationPostconditionTargetFact(
                versionedTarget,
                InitializationPostconditionTargetPossibilities(
                    versionedTarget, trueState, trueMasks, program),
                InitializationPostconditionTargetPossibilities(
                    versionedTarget, falseState, falseMasks, program)));
        }

        return new InitializationPostconditionCallFact(canReturnTrue,
            canReturnFalse, destinations.MoveToImmutable(),
            aliases.ToImmutable());
    }

    private static bool IsIncomingInitializationReferenceTarget(
        ProvenanceAnchor target, BoundFunction function,
        BoundProgram program)
    {
        if (target.Kind is not (
                ProvenanceAnchorKind.IncomingReference
                or ProvenanceAnchorKind.IncomingReferenceContents
                or ProvenanceAnchorKind.IncomingReferencePlace
                or ProvenanceAnchorKind.IncomingReferenceField)
            || target.Storage is not null)
        {
            return false;
        }

        var parameterOffset = function.IsConstructor ? 1 : 0;
        if (target.Identity < parameterOffset
            || target.Identity >= function.ParameterCount + parameterOffset
            || !function.Variables[target.Identity].IsInit
            || function.Variables[target.Identity].IsOut
            || !CheckedReferenceTypeContract.IsValidType(
                function.Variables[target.Identity].Type,
                program.CheckedReferenceTypes))
        {
            return false;
        }

        return program.CheckedReferenceTypes[
            CheckedReferenceTypes.Index(
                function.Variables[target.Identity].Type)]
            is {
                IsInitialization: true,
                IsGarbageCollected: false,
                IsOptional: false,
            };
    }

    private static byte InitializationPostconditionTargetPossibilities(
        ProvenanceAnchor target, InitializationState initialized,
        uint[] fieldMasks, BoundProgram program)
    {
        var possibilities = (byte)0;
        if (ReferenceTargetMayBeVacant(target, initialized, fieldMasks,
            program))
        {
            possibilities |= 1;
        }
        if (ReferenceTargetMayBeLive(target, initialized, fieldMasks,
            program))
        {
            possibilities |= 2;
        }
        return possibilities;
    }

    private static InitializationPostconditionCallFact?
        TryCreateInitializationPostconditionCallFact(
            BoundCall call, InitializationState initialized,
            ref int remaining, int depth)
    {
        Count(ref remaining, depth);
        if (call.Type != PrimitiveType.Bool
            || (uint)call.Function
                >= (uint)initialized.Program.Functions.Length
            || initialized.Dependencies
                is not BackingDependencies dependencies)
        {
            return null;
        }

        if (initialized.TryGetInitializationPostconditionCallFactSnapshot(
                call, out var cachedFact)
            && IsInitializationPostconditionCallFactCurrent(cachedFact,
                initialized))
        {
            return cachedFact;
        }

        var target = initialized.Program.Functions[call.Function];
        if (!initialized.TryGetInitializationPostconditionCallCandidate(
                call, out var isCandidate))
        {
            isCandidate = HasInitializationPostconditionCallCandidate(call,
                initialized.Program, ref remaining, depth + 1);
            initialized.RecordInitializationPostconditionCallCandidate(
                call, isCandidate);
        }
        if (!isCandidate)
        {
            return null;
        }
        if (!target.DeclarationContractClauses.Any(static clause =>
                clause.Phase
                    == BoundDeclarationContractPhase.NormalPostcondition)
            && HasInitializationReferenceOutput(target,
                initialized.Program))
        {
            var createdDefaultFact
                = TryCreateDefaultInitializationPostconditionCallFact(
                call, target, initialized, dependencies.Function,
                initialized.Program, ref remaining, depth + 1);
            if (createdDefaultFact is not null)
            {
                initialized
                    .RecordInitializationPostconditionCallFactSnapshot(
                        call, createdDefaultFact);
            }
            return createdDefaultFact;
        }
        var state = initialized.Clone();
        var fieldMasks = (uint[])initialized.PossibleFieldMasks.Clone();
        InvalidateInitializationPostconditionResultsForCall(call, target,
            state, fieldMasks, dependencies.Function, initialized.Program,
            ref remaining, depth + 1);
        ApplyInitializationPostconditionEffects(call, target, state,
            fieldMasks, dependencies.Function, initialized.Program, null,
            ref remaining, depth + 1, out var correlatedClauses);
        var callFact = CreateInitializationPostconditionCallFact(target,
            correlatedClauses, state, fieldMasks, dependencies.Function,
            initialized.Program, ref remaining, depth + 1);
        if (callFact is not null)
        {
            initialized.RecordInitializationPostconditionCallFactSnapshot(
                call, callFact);
        }
        return callFact;
    }

    private static InitializationPostconditionCallFact?
        TryCreateDefaultInitializationPostconditionCallFact(
            BoundCall call, BoundFunction target,
            InitializationState initialized, BoundFunction function,
            BoundProgram program, ref int remaining, int depth)
    {
        var targets = new HashSet<ProvenanceAnchor>();
        var ambiguousTargets = new HashSet<ProvenanceAnchor>();
        var aliases = ImmutableArray.CreateBuilder<
            InitializationPostconditionAliasTargetFact>();
        var parameterOffset = target.IsConstructor ? 1 : 0;
        for (var argumentIndex = 0;
            argumentIndex < call.Arguments.Length; argumentIndex++)
        {
            Count(ref remaining, depth);
            var parameterIndex = call.ParameterIndex(argumentIndex)
                + parameterOffset;
            if (parameterIndex < parameterOffset
                || parameterIndex >= target.ParameterCount
                    + parameterOffset)
            {
                throw Invalid(call.Span);
            }
            if (!IsInitializationReferenceOutputParameter(target,
                    parameterIndex, program))
            {
                continue;
            }

            var argumentTargets = ReferenceTargetsOfExpression(
                call.Arguments[argumentIndex],
                initialized.Dependencies
                    ?? throw InvalidEffect(call.Span,
                        "CheckedReference"),
                initialized, function, program, ref remaining, depth + 1,
                initialized.PossibleFieldMasks);
            if (argumentTargets.Count == 0)
            {
                return null;
            }
            if (argumentTargets.Count == 1)
            {
                _ = targets.Add(argumentTargets.Single());
                continue;
            }

            var argument = call.Arguments[argumentIndex];
            if (argument is not BoundReferenceReborrow)
            {
                return null;
            }
            var descriptorPlaces = ReferenceDescriptorPlacesOfExpression(
                argument, initialized.Dependencies
                    ?? throw InvalidEffect(call.Span,
                        "CheckedReference"),
                initialized, function, program, ref remaining, depth + 1,
                initialized.PossibleFieldMasks);
            if (descriptorPlaces.Count != 1
                || descriptorPlaces.Single().Kind is not (
                    ProvenanceAnchorKind.ReferenceDescriptor
                    or ProvenanceAnchorKind.IncomingReferenceDescriptor))
            {
                return null;
            }

            var candidateTargets
                = ImmutableHashSet.CreateRange(argumentTargets);
            aliases.Add(new InitializationPostconditionAliasTargetFact(
            descriptorPlaces.Single(), candidateTargets));
            targets.UnionWith(argumentTargets);
            ambiguousTargets.UnionWith(argumentTargets);
        }
        if (targets.Count == 0)
        {
            return null;
        }

        var result = ImmutableArray.CreateBuilder<
            InitializationPostconditionTargetFact>(targets.Count);
        foreach (var targetFact in targets)
        {
            if (IsIncomingInitializationReferenceTarget(targetFact,
                    function, program))
            {
                result.Add(new InitializationPostconditionTargetFact(
                    targetFact,
                    ambiguousTargets.Contains(targetFact) ? (byte)3 : (byte)2,
                    ambiguousTargets.Contains(targetFact) ? (byte)3 : (byte)1));
                continue;
            }
            if (targetFact.Kind is not (
                    ProvenanceAnchorKind.ReferencePlace
                    or ProvenanceAnchorKind.NormalBackingPlace)
                || targetFact.Storage is not StorageKey storage
                || storage.Projection.Kind is not (
                    StorageProjectionKind.WholeObject
                    or StorageProjectionKind.InlineFieldPath)
                || !storage.IsKnown
                || (uint)targetFact.Identity >= (uint)initialized.Length)
            {
                return null;
            }

            result.Add(new InitializationPostconditionTargetFact(
                targetFact with {
                    Storage = storage with {
                        PlaceGeneration = initialized.FieldPlaceGeneration(
                            targetFact.Identity, storage.Projection),
                    },
                }, ambiguousTargets.Contains(targetFact)
                    ? (byte)3 : (byte)2,
                ambiguousTargets.Contains(targetFact)
                    ? (byte)3 : (byte)1));
        }

        return new InitializationPostconditionCallFact(true, true,
            result.MoveToImmutable(), aliases.ToImmutable());
    }

    private static InitializationPostconditionCallFact?
        InitializationPostconditionResultForValue(
            BoundExpression expression, InitializationState initialized,
            int resultVariable)
    {
        expression = UnwrapUnsafeExpression(expression);
        InitializationPostconditionCallFact? fact;
        if (expression is BoundCall call
            && initialized.TryGetInitializationPostconditionCallFact(
                call, out var callFact))
        {
            fact = callFact;
            initialized.ClearInitializationPostconditionCallFact(call);
        }
        else if (expression is BoundRead read
            && (uint)read.Variable < (uint)initialized.Length)
        {
            fact = initialized.InitializationPostconditionResult(
                read.Variable);
        }
        else
        {
            return null;
        }

        return fact is not null
            && fact.Targets.All(target =>
                target.Target.Identity != resultVariable)
            && IsInitializationPostconditionCallFactCurrent(fact,
                initialized)
            ? fact : null;
    }

    private static void InvalidateInitializationPostconditionResultsForCall(
        BoundCall call, BoundFunction target,
        InitializationState initialized, uint[] fieldMasks,
        BoundFunction function, BoundProgram program,
        ref int remaining, int depth)
    {
        var mutations = new HashSet<(int Variable,
            StorageProjection Projection)>();
        var receiverOffset = target.DeclaringStruct is not null
            && !target.IsStatic ? 1 : 0;
        var hasUnknownMutation = false;
        if (receiverOffset != 0 && !target.Variables.IsDefaultOrEmpty
            && target.Variables[0].IsMutable)
        {
            if (call.Arguments.IsEmpty)
            {
                hasUnknownMutation = true;
            }
            else if (call.Arguments[0]
                is BoundMutableReceiverLoan mutableReceiver)
            {
                _ = mutations.Add((mutableReceiver.Variable,
                    StorageProjection.WholeObject));
            }
            else if (TryGetReferencePlaceStorage(call.Arguments[0],
                function, program, allowInitializationLocal: true,
                out var receiverVariable, out var receiverProjection))
            {
                _ = mutations.Add((receiverVariable, receiverProjection));
            }
            else
            {
                hasUnknownMutation = true;
            }
        }

        for (var argumentIndex = 0;
            argumentIndex < call.Arguments.Length; argumentIndex++)
        {
            Count(ref remaining, depth);
            var argument = call.Arguments[argumentIndex];
            var parameterIndex = call.ParameterIndex(argumentIndex);
            if (receiverOffset != 0 && parameterIndex == 0)
            {
                continue;
            }
            if ((uint)parameterIndex >= (uint)target.Variables.Length)
            {
                hasUnknownMutation = true;
                continue;
            }

            var parameter = target.Variables[parameterIndex];
            var mayWrite = parameter.IsOut || parameter.IsInit;
            if (CheckedReferenceTypeContract.IsValidType(parameter.Type,
                program.CheckedReferenceTypes))
            {
                var reference = program.CheckedReferenceTypes[
                    CheckedReferenceTypes.Index(parameter.Type)];
                mayWrite |= reference.IsWritable
                    || reference.IsInitialization;
            }
            if (mayWrite)
            {
                if (argument is BoundOutArgument output)
                {
                    _ = mutations.Add((output.Variable,
                        StorageProjection.WholeObject));
                }
                else if (argument is BoundNativeOutputReservation
                    reservation)
                {
                    _ = mutations.Add((reservation.Variable,
                        StorageProjection.WholeObject));
                }
                else if (initialized.Dependencies
                    is BackingDependencies dependencies)
                {
                    foreach (var referenceTarget
                        in ReferenceTargetsOfExpression(argument,
                            dependencies, initialized, function, program,
                            ref remaining, depth + 1, fieldMasks))
                    {
                        if (referenceTarget.Storage is StorageKey storage
                            && (referenceTarget.Kind is
                                ProvenanceAnchorKind.ReferencePlace
                                or ProvenanceAnchorKind.NormalBackingPlace))
                        {
                            _ = mutations.Add((referenceTarget.Identity,
                                storage.Projection));
                        }
                        else
                        {
                            hasUnknownMutation = true;
                        }
                    }
                }
                else
                {
                    hasUnknownMutation = true;
                }
                continue;
            }

            if (NativePointerTypeContract.IsValidType(argument.Type,
                program.NativePointerTypes)
                || argument.Type is PrimitiveType.NativeRawPointer
                    or PrimitiveType.NativeUtf16ZPointer
                    or PrimitiveType.NativeUtf8ZPointer
                || (ManagedClassTypes.IsClass(argument.Type)
                    && ManagedClassTypes.IsWritable(argument.Type))
                || ((target.IsExternal
                        || target.DirectNativeImport is not null
                        || target.NativeVTableMethod is not null)
                    && ManagedClassTypes.IsClass(argument.Type)))
            {
                hasUnknownMutation = true;
            }
        }

        InvalidateInitializationPostconditionResultsForPlaces(
            initialized, mutations, hasUnknownMutation);
    }

    private static void InvalidateInitializationPostconditionResultsForPlaces(
        InitializationState initialized,
        IReadOnlySet<(int Variable, StorageProjection Projection)> mutations,
        bool hasUnknownMutation)
    {
        initialized.InvalidateInitializationPostconditionAliasFactsForPlaces(
            mutations, hasUnknownMutation);
        for (var statusVariable = 0;
            statusVariable < initialized.Length; statusVariable++)
        {
            var fact = initialized.InitializationPostconditionResult(
                statusVariable);
            if (fact is null)
            {
                continue;
            }

            if (hasUnknownMutation
                || mutations.Any(mutation =>
                    (mutation.Variable == statusVariable
                        && InitializationStoragePlacesOverlap(
                            mutation.Projection,
                            StorageProjection.WholeObject))
                    || fact.Targets.Any(destination =>
                        destination.Target.Identity == mutation.Variable
                        && destination.Target.Storage
                            is StorageKey storage
                        && InitializationStoragePlacesOverlap(
                            mutation.Projection, storage.Projection))
                    || (!fact.Aliases.IsDefaultOrEmpty
                        && fact.Aliases.Any(alias =>
                            InitializationPostconditionAliasTargetsAffectedByPlaces(
                                alias.Targets, mutations,
                                hasUnknownMutation)))))
            {
                initialized.SetInitializationPostconditionResult(
                    statusVariable, null);
            }
        }
    }

    private static bool InitializationPostconditionCallFactAffectedByPlaces(
        InitializationPostconditionCallFact fact,
        IReadOnlySet<(int Variable, StorageProjection Projection)> mutations,
        bool hasUnknownMutation)
        => hasUnknownMutation
            || fact.Targets.Any(target => mutations.Any(mutation =>
                target.Target.Identity == mutation.Variable
                && target.Target.Storage is StorageKey storage
                && InitializationStoragePlacesOverlap(
                    mutation.Projection, storage.Projection)))
            || (!fact.Aliases.IsDefaultOrEmpty
                && fact.Aliases.Any(alias =>
                    InitializationPostconditionAliasTargetsAffectedByPlaces(
                        alias.Targets, mutations, hasUnknownMutation)));

    private static bool InitializationPostconditionAliasTargetsAffectedByPlaces(
        ImmutableHashSet<ProvenanceAnchor> targets,
        IReadOnlySet<(int Variable, StorageProjection Projection)> mutations,
        bool hasUnknownMutation)
        => hasUnknownMutation
            || targets.Any(target => mutations.Any(mutation =>
                target.Identity == mutation.Variable
                && target.Storage is StorageKey storage
                && InitializationStoragePlacesOverlap(
                    mutation.Projection, storage.Projection)));

    private static bool InitializationStoragePlacesOverlap(
        StorageProjection left, StorageProjection right)
    {
        if (left.Kind == StorageProjectionKind.WholeObject
            || right.Kind == StorageProjectionKind.WholeObject)
        {
            return true;
        }
        if (left.Kind != StorageProjectionKind.InlineFieldPath
            || right.Kind != StorageProjectionKind.InlineFieldPath)
        {
            return true;
        }

        return left.FieldPath.IsPrefixOf(right.FieldPath)
            || right.FieldPath.IsPrefixOf(left.FieldPath);
    }

    private static bool InitializationReservationTargetsOverlap(
        ProvenanceAnchor left, ProvenanceAnchor right)
    {
        var leftIsIncomingReference = left.Kind is
            ProvenanceAnchorKind.IncomingReference
                or ProvenanceAnchorKind.IncomingReferenceContents
                or ProvenanceAnchorKind.IncomingReferencePlace
                or ProvenanceAnchorKind.IncomingReferenceField;
        var rightIsIncomingReference = right.Kind is
            ProvenanceAnchorKind.IncomingReference
                or ProvenanceAnchorKind.IncomingReferenceContents
                or ProvenanceAnchorKind.IncomingReferencePlace
                or ProvenanceAnchorKind.IncomingReferenceField;
        if (leftIsIncomingReference && rightIsIncomingReference)
        {
            return left.Identity == right.Identity
                && InitializationStoragePlacesOverlap(
                    left.IncomingProjection
                        ?? StorageProjection.WholeObject,
                    right.IncomingProjection
                        ?? StorageProjection.WholeObject);
        }

        if (left.Kind == ProvenanceAnchorKind.IncomingReferenceDescriptor
            && right.Kind
                == ProvenanceAnchorKind.IncomingReferenceDescriptor)
        {
            return left.Identity == right.Identity;
        }

        var leftIsPlace = left.Kind is ProvenanceAnchorKind.ReferencePlace
            or ProvenanceAnchorKind.NormalBackingPlace;
        var rightIsPlace = right.Kind is ProvenanceAnchorKind.ReferencePlace
            or ProvenanceAnchorKind.NormalBackingPlace;
        var leftIsDescriptor = left.Kind
            == ProvenanceAnchorKind.ReferenceDescriptor;
        var rightIsDescriptor = right.Kind
            == ProvenanceAnchorKind.ReferenceDescriptor;
        if ((leftIsPlace && rightIsPlace)
            || (leftIsDescriptor && rightIsDescriptor))
        {
            if (left.Storage is not StorageKey leftStorage
                || right.Storage is not StorageKey rightStorage)
            {
                return true;
            }

            return leftStorage.Activation == rightStorage.Activation
                && leftStorage.Site == rightStorage.Site
                && (!leftStorage.Instance.IsKnown
                    || !rightStorage.Instance.IsKnown
                    || leftStorage.Instance == rightStorage.Instance)
                && InitializationStoragePlacesOverlap(
                    leftStorage.Projection, rightStorage.Projection);
        }

        return false;
    }

    private static bool HasActiveInitializationReservationForPlace(
        int variable, StorageProjection projection,
        InitializationState initialized)
    {
        if ((uint)variable >= (uint)initialized.Length
            || initialized.Dependencies
                is not BackingDependencies dependencies)
        {
            return false;
        }

        foreach (var instance in dependencies.StorageInstanceSet(variable))
        {
            var place = ProvenanceAnchor.ForReferencePlace(
                dependencies.FunctionActivation, variable, instance,
                projection);
            var descriptor = ProvenanceAnchor.ForReferenceDescriptor(
                dependencies.FunctionActivation, variable, instance,
                projection, initialized.FieldPlaceGeneration(variable,
                    projection));
            if (initialized.HasActiveInitializationReservation(place)
                || initialized.HasActiveInitializationReservation(
                    descriptor))
            {
                return true;
            }
        }

        return false;
    }

    private static bool IsInitializationPostconditionCallFactCurrent(
        InitializationPostconditionCallFact fact,
        InitializationState initialized)
    {
        foreach (var target in fact.Targets)
        {
            if (initialized.Dependencies is BackingDependencies
                    incomingDependencies
                && IsIncomingInitializationReferenceTarget(
                    target.Target, incomingDependencies.Function,
                    initialized.Program))
            {
                continue;
            }
            if (target.Target.Kind is not (
                    ProvenanceAnchorKind.ReferencePlace
                    or ProvenanceAnchorKind.NormalBackingPlace)
                || target.Target.Storage is not StorageKey storage
                || (uint)target.Target.Identity >= (uint)initialized.Length
                || initialized.Dependencies
                    is not BackingDependencies dependencies
                || HasUnknownStorageInstances(
                    dependencies.StorageInstanceSet(target.Target.Identity))
                || dependencies.StorageInstanceSet(target.Target.Identity).Count
                    != 1
                || !dependencies.StorageInstanceSet(target.Target.Identity)
                    .Contains(storage.Instance)
                || initialized.FieldPlaceGeneration(target.Target.Identity,
                    storage.Projection) != storage.PlaceGeneration)
            {
                return false;
            }
        }
        if (!fact.Aliases.IsDefaultOrEmpty)
        {
            foreach (var alias in fact.Aliases)
            {
                if (!IsInitializationPostconditionAliasTargetCurrent(
                    alias, initialized))
                {
                    return false;
                }
            }
        }
        return true;
    }

    private static bool IsInitializationPostconditionAliasTargetCurrent(
        InitializationPostconditionAliasTargetFact alias,
        InitializationState initialized)
    {
        if (initialized.Dependencies is not BackingDependencies dependencies
            || (uint)alias.Descriptor.Identity
                >= (uint)dependencies.ReferenceTargets.Length
            || dependencies.ReferenceTargets[alias.Descriptor.Identity]
                is not { Count: > 0 } currentTargets
            || !currentTargets.SetEquals(alias.Targets))
        {
            return false;
        }

        var descriptorType = dependencies.Function.Variables[
            alias.Descriptor.Identity].Type;
        if (!CheckedReferenceTypeContract.IsValidType(descriptorType,
                initialized.Program.CheckedReferenceTypes)
            || !initialized.Program.CheckedReferenceTypes[
                CheckedReferenceTypes.Index(descriptorType)].IsInitialization)
        {
            return false;
        }

        if (alias.Descriptor.Kind
            == ProvenanceAnchorKind.IncomingReferenceDescriptor)
        {
            return IsReferenceParameterSlot(dependencies.Function,
                alias.Descriptor.Identity);
        }
        if (alias.Descriptor.Kind
                != ProvenanceAnchorKind.ReferenceDescriptor
            || alias.Descriptor.Storage is not StorageKey storage
            || !storage.IsKnown
            || HasUnknownStorageInstances(
                dependencies.StorageInstanceSet(
                    alias.Descriptor.Identity))
            || dependencies.StorageInstanceSet(
                alias.Descriptor.Identity).Count != 1
            || !dependencies.StorageInstanceSet(alias.Descriptor.Identity)
                .Contains(storage.Instance)
            || initialized.FieldPlaceGeneration(
                alias.Descriptor.Identity, storage.Projection)
                != storage.PlaceGeneration)
        {
            return false;
        }

        foreach (var target in alias.Targets)
        {
            if (IsIncomingInitializationReferenceTarget(target,
                    dependencies.Function, initialized.Program))
            {
                continue;
            }
            if (target.Kind is not (
                    ProvenanceAnchorKind.ReferencePlace
                    or ProvenanceAnchorKind.NormalBackingPlace)
                || target.Storage is not StorageKey targetStorage
                || (uint)target.Identity >= (uint)initialized.Length
                || HasUnknownStorageInstances(
                    dependencies.StorageInstanceSet(target.Identity))
                || dependencies.StorageInstanceSet(target.Identity).Count
                    != 1
                || !dependencies.StorageInstanceSet(target.Identity)
                    .Contains(targetStorage.Instance)
                || initialized.FieldPlaceGeneration(target.Identity,
                    targetStorage.Projection)
                    != targetStorage.PlaceGeneration)
            {
                return false;
            }
        }

        return true;
    }

    private static byte InitializationPostconditionAliasPossibilities(
        BoundExpression descriptor,
        IReadOnlySet<ProvenanceAnchor> targets,
        BackingDependencies dependencies, InitializationState initialized,
        BoundFunction function, BoundProgram program,
        ref int remaining, int depth, uint[]? fieldMasks)
    {
        var descriptorPlaces = ReferenceDescriptorPlacesOfExpression(
            descriptor, dependencies, initialized, function, program,
            ref remaining, depth + 1, fieldMasks);
        var possibilities = (byte)0;
        foreach (var descriptorPlace in descriptorPlaces)
        {
            if (descriptorPlace.Kind is not (
                    ProvenanceAnchorKind.ReferenceDescriptor
                    or ProvenanceAnchorKind.IncomingReferenceDescriptor)
                || (uint)descriptorPlace.Identity
                    >= (uint)initialized.Length
                || initialized.InitializationPostconditionAliasResult(
                    descriptorPlace.Identity)
                    is not InitializationPostconditionAliasFact aliasFact
                || aliasFact.Descriptor != descriptorPlace
                || !aliasFact.Targets.SetEquals(targets)
                || !IsInitializationPostconditionAliasTargetCurrent(
                    new InitializationPostconditionAliasTargetFact(
                        aliasFact.Descriptor, aliasFact.Targets),
                    initialized))
            {
                continue;
            }

            possibilities |= aliasFact.Possibilities;
        }
        return possibilities;
    }

    private static void ApplyInitializationPostconditionCallFact(
        InitializationPostconditionCallFact fact, bool result,
        InitializationState initialized)
    {
        if (!IsInitializationPostconditionCallFactCurrent(fact,
            initialized))
        {
            return;
        }

        foreach (var target in fact.Targets)
        {
            var possibilities = result ? target.TruePossibilities
                : target.FalsePossibilities;
            if (possibilities is not (1 or 2))
            {
                continue;
            }

            if (initialized.Dependencies is BackingDependencies dependencies
                && IsIncomingInitializationReferenceTarget(
                    target.Target, dependencies.Function,
                    initialized.Program))
            {
                initialized.SetIncomingReferenceInitializationPossibilities(
                    target.Target, possibilities);
                continue;
            }
            if (target.Target.Storage is not StorageKey storage
                || initialized.Dependencies is not BackingDependencies
                    placeDependencies)
            {
                continue;
            }
            SetReferencePlaceInitializationState(target.Target.Identity,
                storage.Projection, possibilities == 2, initialized,
                initialized.PossibleFieldMasks, placeDependencies.Function,
                initialized.Program, default);
        }
        if (!fact.Aliases.IsDefaultOrEmpty)
        {
            foreach (var alias in fact.Aliases)
            {
                initialized.SetInitializationPostconditionAliasResult(
                    alias.Descriptor.Identity,
                    new InitializationPostconditionAliasFact(
                        alias.Descriptor, alias.Targets,
                        result ? (byte)2 : (byte)1));
            }
        }
    }

    private static bool ContainsInitializationPostconditionResult(
        BoundExpression expression, ref int remaining, int depth)
    {
        Count(ref remaining, depth);
        if (expression is BoundContractReturnValue)
        {
            return true;
        }
        foreach (var nested in expression.NestedExpressions)
        {
            if (ContainsInitializationPostconditionResult(nested,
                ref remaining, depth + 1))
            {
                return true;
            }
        }
        return false;
    }

    private static bool TryRewriteInitializationPostcondition(
        BoundExpression expression, BoundCall call, BoundFunction target,
        int parameterOffset, bool? callResult, ref int remaining, int depth,
        out BoundExpression rewritten)
    {
        Count(ref remaining, depth);
        if (expression is BoundContractReturnValue returnValue)
        {
            if (callResult is bool result)
            {
                rewritten = new BoundConstant(result ? 1 : 0,
                    PrimitiveType.Bool, returnValue.Span);
                return returnValue.Type == PrimitiveType.Bool;
            }
            rewritten = expression;
            return true;
        }
        if (expression is BoundRead read)
        {
            if ((uint)read.Variable >= (uint)target.Variables.Length
                || target.Variables[read.Variable].Type != read.Type)
            {
                rewritten = expression;
                return false;
            }

            var parameterIndex = read.Variable - parameterOffset;
            if (parameterIndex < 0
                || parameterIndex >= target.ParameterCount)
            {
                rewritten = expression;
                return false;
            }

            for (var index = 0; index < call.Arguments.Length; index++)
            {
                Count(ref remaining, depth + 1);
                if (call.ParameterIndex(index) + parameterOffset
                    == read.Variable)
                {
                    var argument = call.Arguments[index];
                    rewritten = argument;
                    return argument.Type == read.Type;
                }
            }

            rewritten = expression;
            return false;
        }

        var replacements
            = new Dictionary<BoundExpression, BoundExpression>(
                ReferenceEqualityComparer.Instance);
        foreach (var nested in expression.NestedExpressions)
        {
            if (!TryRewriteInitializationPostcondition(nested, call,
                target, parameterOffset, callResult, ref remaining,
                depth + 1,
                out var rewrittenNested))
            {
                rewritten = expression;
                return false;
            }
            replacements[nested] = rewrittenNested;
        }

        rewritten = expression.RewriteNestedExpressions(nested =>
            replacements.TryGetValue(nested, out var replacement)
                ? replacement : nested);
        return true;
    }

    private static bool IsSupportedInitializationPostconditionPredicate(
        BoundExpression expression, ref int remaining, int depth)
    {
        Count(ref remaining, depth);
        if (expression is BoundUnary { Operator: TokenKind.Bang } unary)
        {
            return IsSupportedInitializationPostconditionPredicate(
                unary.Operand, ref remaining, depth + 1);
        }
        if (expression is BoundUnsafeExpression unsafeExpression
            && expression.Type == PrimitiveType.Bool)
        {
            return IsSupportedInitializationPostconditionPredicate(
                unsafeExpression.Expression, ref remaining, depth + 1);
        }
        if (expression is BoundBinary {
                Operator: TokenKind.AmpersandAmpersand
                    or TokenKind.PipePipe,
            } logical)
        {
            return IsSupportedInitializationPostconditionPredicate(
                    logical.Left, ref remaining, depth + 1)
                && IsSupportedInitializationPostconditionPredicate(
                    logical.Right, ref remaining, depth + 1);
        }
        if (expression is BoundConditional {
                Type: PrimitiveType.Bool,
            } conditional)
        {
            return IsSupportedInitializationPostconditionPredicate(
                    conditional.Condition, ref remaining, depth + 1)
                && IsSupportedInitializationPostconditionPredicate(
                    conditional.WhenTrue, ref remaining, depth + 1)
                && IsSupportedInitializationPostconditionPredicate(
                    conditional.WhenFalse, ref remaining, depth + 1);
        }
        if (expression is BoundCall or BoundIndirectCall
            or BoundNominalUpdate or BoundCoalesce
            or BoundIsNull or BoundIsSome or BoundIsVariablePattern)
        {
            return false;
        }
        return !ContainsUnsupportedInitializationPostconditionNode(
            expression.NestedExpressions, ref remaining, depth + 1);
    }

    private static bool ContainsUnsupportedInitializationPostconditionNode(
        ImmutableArray<BoundExpression> expressions,
        ref int remaining, int depth)
    {
        foreach (var expression in expressions)
        {
            Count(ref remaining, depth);
            if (expression is BoundUnary { Operator: TokenKind.Bang }
                or BoundConditional or BoundCall or BoundIndirectCall
                or BoundNominalUpdate or BoundCoalesce or BoundIsNull
                or BoundIsSome or BoundIsVariablePattern
                or BoundIsInitialized
                or BoundReferenceInitializationTest
                or BoundBinary {
                    Operator: TokenKind.AmpersandAmpersand
                        or TokenKind.PipePipe,
                })
            {
                return true;
            }
            if (ContainsUnsupportedInitializationPostconditionNode(
                expression.NestedExpressions, ref remaining, depth + 1))
            {
                return true;
            }
        }
        return false;
    }

    private static bool TryCollectInitializationPostconditionTargets(
        BoundExpression expression, BackingDependencies dependencies,
        InitializationState initialized, uint[] fieldMasks,
        BoundFunction function, BoundProgram program,
        ref int remaining, int depth,
        out Dictionary<BoundExpression, ProvenanceAnchor> targets,
        out HashSet<ProvenanceAnchor> ambiguousTargets,
        IReadOnlyDictionary<BoundExpression,
            HashSet<ProvenanceAnchor>>? knownCallTargets = null)
    {
        targets = new Dictionary<BoundExpression, ProvenanceAnchor>(
            ReferenceEqualityComparer.Instance);
        ambiguousTargets = [];
        var valid = TryCollectInitializationPostconditionTargetsCore(
            expression, dependencies, initialized, fieldMasks, function,
            program, targets, ambiguousTargets, ref remaining, depth,
            knownCallTargets);
        if (valid && ambiguousTargets.Count == 0)
        {
            return true;
        }

        var maybeTargets = new HashSet<ProvenanceAnchor>(ambiguousTargets);
        maybeTargets.UnionWith(targets.Values);
        foreach (var target in maybeTargets)
        {
            SetInitializationPostconditionTargetMaybeInitialized(target,
                initialized, fieldMasks, function, program,
                expression.Span);
        }
        targets.Clear();
        return false;
    }

    private static bool TryCollectInitializationPostconditionTargetsCore(
        BoundExpression expression, BackingDependencies dependencies,
        InitializationState initialized, uint[] fieldMasks,
        BoundFunction function, BoundProgram program,
        Dictionary<BoundExpression, ProvenanceAnchor> targets,
        HashSet<ProvenanceAnchor> ambiguousTargets,
        ref int remaining, int depth,
        IReadOnlyDictionary<BoundExpression,
            HashSet<ProvenanceAnchor>>? knownCallTargets)
    {
        Count(ref remaining, depth);
        var valid = true;
        var descriptor = expression switch
        {
            BoundReferenceInitializationTest test => test.Descriptor,
            BoundReferenceRead read => read.Descriptor,
            _ => null,
        };
        if (descriptor is not null
            && CheckedReferenceTypeContract.IsValidType(descriptor.Type,
                program.CheckedReferenceTypes)
            && program.CheckedReferenceTypes[
                CheckedReferenceTypes.Index(descriptor.Type)]
                .IsInitialization
            && !targets.ContainsKey(descriptor))
        {
            var referenceTargets = knownCallTargets is not null
                && knownCallTargets.TryGetValue(descriptor,
                    out var callTargets)
                    ? callTargets
                    : ReferenceTargetsOfExpression(descriptor,
                        dependencies, initialized, function, program,
                        ref remaining, depth + 1, fieldMasks);
            if (referenceTargets.Count == 0)
            {
                valid = false;
            }
            else if (referenceTargets.Count == 1)
            {
                targets.Add(descriptor, referenceTargets.Single());
            }
            else
            {
                ambiguousTargets.UnionWith(referenceTargets);
            }
        }

        foreach (var nested in expression.NestedExpressions)
        {
            if (!TryCollectInitializationPostconditionTargetsCore(nested,
                dependencies, initialized, fieldMasks, function, program,
                targets, ambiguousTargets, ref remaining, depth + 1,
                knownCallTargets))
            {
                valid = false;
            }
        }
        return valid;
    }

    private static bool CanBeInitializationPostcondition(
        BoundExpression expression, bool result,
        InitializationState initialized,
        IReadOnlyDictionary<BoundExpression, ProvenanceAnchor> targets,
        BoundFunction function, BoundProgram program,
        ref int remaining, int depth)
    {
        Count(ref remaining, depth);
        if (expression is BoundReferenceInitializationTest referenceTest
            && targets.TryGetValue(referenceTest.Descriptor,
                out var referenceTarget))
        {
            return result
                ? ReferenceTargetMayBeLive(referenceTarget, initialized,
                    initialized.PossibleFieldMasks, program)
                : ReferenceTargetMayBeVacant(referenceTarget, initialized,
                    initialized.PossibleFieldMasks, program);
        }
        if (expression is BoundUnary { Operator: TokenKind.Bang } unary)
        {
            return CanBeInitializationPostcondition(unary.Operand,
                !result, initialized, targets, function, program,
                ref remaining, depth + 1);
        }
        if (expression is BoundUnsafeExpression unsafeExpression)
        {
            return CanBeInitializationPostcondition(
                unsafeExpression.Expression, result, initialized, targets,
                function, program, ref remaining, depth + 1);
        }
        if (expression is BoundBinary {
                Operator: TokenKind.AmpersandAmpersand,
            } and)
        {
            if (result)
            {
                return CanBeInitializationPostcondition(and.Left, true,
                        initialized, targets, function, program,
                        ref remaining, depth + 1)
                    && CanBeInitializationPostcondition(and.Right, true,
                        OutcomeInitializationPostcondition(and.Left,
                            initialized, true, targets, function, program,
                            ref remaining, depth + 1),
                        targets, function, program, ref remaining,
                        depth + 1);
            }
            if (CanBeInitializationPostcondition(and.Left, false,
                initialized, targets, function, program, ref remaining,
                depth + 1))
            {
                return true;
            }
            if (!CanBeInitializationPostcondition(and.Left, true,
                initialized, targets, function, program, ref remaining,
                depth + 1))
            {
                return false;
            }
            var leftTrue = OutcomeInitializationPostcondition(and.Left,
                initialized, true, targets, function, program,
                ref remaining, depth + 1);
            return CanBeInitializationPostcondition(and.Right, false,
                leftTrue, targets, function, program, ref remaining,
                depth + 1);
        }
        if (expression is BoundBinary {
                Operator: TokenKind.PipePipe,
            } or)
        {
            if (!result)
            {
                return CanBeInitializationPostcondition(or.Left, false,
                        initialized, targets, function, program,
                        ref remaining, depth + 1)
                    && CanBeInitializationPostcondition(or.Right, false,
                        OutcomeInitializationPostcondition(or.Left,
                            initialized, false, targets, function, program,
                            ref remaining, depth + 1),
                        targets, function, program, ref remaining,
                        depth + 1);
            }
            if (CanBeInitializationPostcondition(or.Left, true,
                initialized, targets, function, program, ref remaining,
                depth + 1))
            {
                return true;
            }
            if (!CanBeInitializationPostcondition(or.Left, false,
                initialized, targets, function, program, ref remaining,
                depth + 1))
            {
                return false;
            }
            var leftFalse = OutcomeInitializationPostcondition(or.Left,
                initialized, false, targets, function, program,
                ref remaining, depth + 1);
            return CanBeInitializationPostcondition(or.Right, true,
                leftFalse, targets, function, program, ref remaining,
                depth + 1);
        }
        if (expression is BoundConditional conditional)
        {
            var trueConditionState
                = OutcomeInitializationPostcondition(conditional.Condition,
                    initialized, true, targets, function, program,
                    ref remaining, depth + 1);
            if (CanBeInitializationPostcondition(conditional.Condition,
                true, initialized, targets, function, program,
                ref remaining, depth + 1)
                && CanBeInitializationPostcondition(conditional.WhenTrue,
                    result, trueConditionState, targets, function, program,
                    ref remaining, depth + 1))
            {
                return true;
            }
            if (!CanBeInitializationPostcondition(conditional.Condition,
                false, initialized, targets, function, program,
                ref remaining, depth + 1))
            {
                return false;
            }
            var falseConditionState
                = OutcomeInitializationPostcondition(conditional.Condition,
                    initialized, false, targets, function, program,
                    ref remaining, depth + 1);
            return CanBeInitializationPostcondition(
                conditional.WhenFalse, result, falseConditionState,
                targets, function, program, ref remaining, depth + 1);
        }

        var readState = CloneOutcomeState(initialized, null);
        SetPostconditionReadTargets(expression, readState, targets,
            function, program, ref remaining, depth + 1);
        return CanBe(expression, result, ref remaining, readState);
    }

    private static InitializationState OutcomeInitializationPostcondition(
        BoundExpression expression, InitializationState initialized,
        bool result,
        IReadOnlyDictionary<BoundExpression, ProvenanceAnchor> targets,
        BoundFunction function, BoundProgram program,
        ref int remaining, int depth)
    {
        Count(ref remaining, depth);
        if (expression is BoundReferenceInitializationTest referenceTest
            && targets.TryGetValue(referenceTest.Descriptor,
                out var referenceTarget))
        {
            var testState = CloneOutcomeState(initialized, null);
            if (referenceTarget.Kind is ProvenanceAnchorKind.IncomingReference
                or ProvenanceAnchorKind.IncomingReferenceContents
                or ProvenanceAnchorKind.IncomingReferencePlace
                or ProvenanceAnchorKind.IncomingReferenceField)
            {
                var possibilities
                    = testState.IncomingReferenceInitializationPossibilities(
                        referenceTarget);
                var selected = (byte)(possibilities
                    & (result ? (byte)2 : (byte)1));
                if (selected != 0)
                {
                    testState.SetIncomingReferenceInitializationPossibilities(
                        referenceTarget, selected);
                }
            }
            else if (referenceTarget.Kind is
                        ProvenanceAnchorKind.ReferencePlace
                    or ProvenanceAnchorKind.NormalBackingPlace
                && referenceTarget.Storage is StorageKey referenceStorage)
            {
                SetReferencePlaceInitializationState(
                    referenceTarget.Identity,
                    referenceStorage.Projection, result, testState,
                    testState.PossibleFieldMasks, function, program,
                    referenceTest.Span);
            }
            else
            {
                throw InvalidEffect(referenceTest.Span,
                    "CheckedReference");
            }
            return testState;
        }
        if (expression is BoundUnary { Operator: TokenKind.Bang } unary)
        {
            return OutcomeInitializationPostcondition(unary.Operand,
                initialized, !result, targets, function, program,
                ref remaining, depth + 1);
        }
        if (expression is BoundUnsafeExpression unsafeExpression)
        {
            return OutcomeInitializationPostcondition(
                unsafeExpression.Expression, initialized, result, targets,
                function, program, ref remaining, depth + 1);
        }
        if (expression is BoundBinary {
                Operator: TokenKind.AmpersandAmpersand,
            } and)
        {
            if (result)
            {
                var leftTrue = OutcomeInitializationPostcondition(and.Left,
                    initialized, true, targets, function, program,
                    ref remaining, depth + 1);
                return OutcomeInitializationPostcondition(and.Right,
                    leftTrue, true, targets, function, program,
                    ref remaining, depth + 1);
            }

            var leftFalsePossible
                = CanBeInitializationPostcondition(and.Left, false,
                    initialized, targets, function, program,
                    ref remaining, depth + 1);
            var rightFalsePossible
                = CanBeInitializationPostcondition(and.Left, true,
                    initialized, targets, function, program,
                    ref remaining, depth + 1)
                && CanBeInitializationPostcondition(and.Right, false,
                    OutcomeInitializationPostcondition(and.Left,
                        initialized, true, targets, function, program,
                        ref remaining, depth + 1),
                    targets, function, program, ref remaining,
                    depth + 1);
            if (leftFalsePossible && !rightFalsePossible)
            {
                return OutcomeInitializationPostcondition(and.Left,
                    initialized, false, targets, function, program,
                    ref remaining, depth + 1);
            }
            if (!leftFalsePossible && rightFalsePossible)
            {
                var leftTrue = OutcomeInitializationPostcondition(and.Left,
                    initialized, true, targets, function, program,
                    ref remaining, depth + 1);
                return OutcomeInitializationPostcondition(and.Right,
                    leftTrue, false, targets, function, program,
                    ref remaining, depth + 1);
            }
            var trueLeft = OutcomeInitializationPostcondition(and.Left,
                initialized, true, targets, function, program,
                ref remaining, depth + 1);
            var falseLeft = OutcomeInitializationPostcondition(and.Left,
                initialized, false, targets, function, program,
                ref remaining, depth + 1);
            var falseRight = OutcomeInitializationPostcondition(and.Right,
                trueLeft, false, targets, function, program,
                ref remaining, depth + 1);
            return Combine(falseLeft, leftFalsePossible, falseRight,
                rightFalsePossible);
        }
        if (expression is BoundBinary {
                Operator: TokenKind.PipePipe,
            } or)
        {
            if (!result)
            {
                var leftFalse = OutcomeInitializationPostcondition(or.Left,
                    initialized, false, targets, function, program,
                    ref remaining, depth + 1);
                return OutcomeInitializationPostcondition(or.Right,
                    leftFalse, false, targets, function, program,
                    ref remaining, depth + 1);
            }

            var leftTruePossible
                = CanBeInitializationPostcondition(or.Left, true,
                    initialized, targets, function, program,
                    ref remaining, depth + 1);
            var rightTruePossible
                = CanBeInitializationPostcondition(or.Left, false,
                    initialized, targets, function, program,
                    ref remaining, depth + 1)
                && CanBeInitializationPostcondition(or.Right, true,
                    OutcomeInitializationPostcondition(or.Left,
                        initialized, false, targets, function, program,
                        ref remaining, depth + 1),
                    targets, function, program, ref remaining,
                    depth + 1);
            if (leftTruePossible && !rightTruePossible)
            {
                return OutcomeInitializationPostcondition(or.Left,
                    initialized, true, targets, function, program,
                    ref remaining, depth + 1);
            }
            if (!leftTruePossible && rightTruePossible)
            {
                var leftFalse = OutcomeInitializationPostcondition(or.Left,
                    initialized, false, targets, function, program,
                    ref remaining, depth + 1);
                return OutcomeInitializationPostcondition(or.Right,
                    leftFalse, true, targets, function, program,
                    ref remaining, depth + 1);
            }
            var trueLeft = OutcomeInitializationPostcondition(or.Left,
                initialized, true, targets, function, program,
                ref remaining, depth + 1);
            var falseLeft = OutcomeInitializationPostcondition(or.Left,
                initialized, false, targets, function, program,
                ref remaining, depth + 1);
            var trueRight = OutcomeInitializationPostcondition(or.Right,
                falseLeft, true, targets, function, program,
                ref remaining, depth + 1);
            return Combine(trueLeft, leftTruePossible, trueRight,
                rightTruePossible);
        }
        if (expression is BoundConditional conditional)
        {
            var whenTrueState = OutcomeInitializationPostcondition(
                conditional.Condition, initialized, true, targets, function,
                program, ref remaining, depth + 1);
            var whenTruePossible
                = CanBeInitializationPostcondition(conditional.Condition,
                    true, initialized, targets, function, program,
                    ref remaining, depth + 1)
                && CanBeInitializationPostcondition(conditional.WhenTrue,
                    result, whenTrueState, targets, function, program,
                    ref remaining, depth + 1);
            var whenFalseState = OutcomeInitializationPostcondition(
                conditional.Condition, initialized, false, targets,
                function, program, ref remaining, depth + 1);
            var whenFalsePossible
                = CanBeInitializationPostcondition(conditional.Condition,
                    false, initialized, targets, function, program,
                    ref remaining, depth + 1)
                && CanBeInitializationPostcondition(
                    conditional.WhenFalse, result, whenFalseState,
                    targets, function, program, ref remaining,
                    depth + 1);
            if (whenTruePossible && !whenFalsePossible)
            {
                return OutcomeInitializationPostcondition(
                    conditional.WhenTrue, whenTrueState, result, targets,
                    function, program, ref remaining, depth + 1);
            }
            if (!whenTruePossible && whenFalsePossible)
            {
                return OutcomeInitializationPostcondition(
                    conditional.WhenFalse, whenFalseState, result,
                    targets, function, program, ref remaining,
                    depth + 1);
            }
            var trueResult = OutcomeInitializationPostcondition(
                conditional.WhenTrue, whenTrueState, result, targets,
                function, program, ref remaining, depth + 1);
            var falseResult = OutcomeInitializationPostcondition(
                conditional.WhenFalse, whenFalseState, result, targets,
                function, program, ref remaining, depth + 1);
            return Combine(trueResult, whenTruePossible, falseResult,
                whenFalsePossible);
        }

        var state = CloneOutcomeState(initialized, null);
        SetPostconditionReadTargets(expression, state, targets,
            function, program, ref remaining, depth + 1);
        return Outcome(expression, state, result, ref remaining);
    }

    private static void SetPostconditionReadTargets(
        BoundExpression expression, InitializationState initialized,
        IReadOnlyDictionary<BoundExpression, ProvenanceAnchor> targets,
        BoundFunction function, BoundProgram program,
        ref int remaining, int depth)
    {
        Count(ref remaining, depth);
        if (expression is BoundReferenceRead referenceRead
            && targets.TryGetValue(referenceRead.Descriptor,
                out var referenceTarget))
        {
            SetInitializationPostconditionTargetInitialized(
                referenceTarget, initialized,
                initialized.PossibleFieldMasks, function, program,
                referenceRead.Span);
        }
        foreach (var nested in expression.NestedExpressions)
        {
            SetPostconditionReadTargets(nested, initialized, targets,
                function, program, ref remaining, depth + 1);
        }
    }

    private static void SetInitializationPostconditionTargetMaybeInitialized(
        ProvenanceAnchor target, InitializationState initialized,
        uint[] fieldMasks, BoundFunction function, BoundProgram program,
        TextSpan span)
    {
        if (target.Kind is ProvenanceAnchorKind.IncomingReference
            or ProvenanceAnchorKind.IncomingReferenceContents
            or ProvenanceAnchorKind.IncomingReferencePlace
            or ProvenanceAnchorKind.IncomingReferenceField)
        {
            var possibilities
                = initialized.IncomingReferenceInitializationPossibilities(
                    target);
            initialized.SetIncomingReferenceInitializationPossibilities(
                target, (byte)(possibilities | 2));
            return;
        }
        if (target.Kind is not (ProvenanceAnchorKind.ReferencePlace
                or ProvenanceAnchorKind.NormalBackingPlace)
            || target.Storage is not StorageKey storage
            || !storage.IsKnown)
        {
            throw InvalidEffect(span, "CheckedReference");
        }

        var liveState = initialized.Clone();
        var liveMasks = (uint[])fieldMasks.Clone();
        SetReferencePlaceInitializationState(target.Identity,
            storage.Projection, live: true, liveState, liveMasks,
            function, program, span);
        initialized.Merge(target.Identity, liveState);
        fieldMasks[target.Identity] &= liveMasks[target.Identity];
    }

    private static void SetInitializationPostconditionTargetInitialized(
        ProvenanceAnchor target, InitializationState initialized,
        uint[] fieldMasks, BoundFunction function, BoundProgram program,
        TextSpan span)
    {
        if (target.Kind is ProvenanceAnchorKind.IncomingReference
            or ProvenanceAnchorKind.IncomingReferenceContents
            or ProvenanceAnchorKind.IncomingReferencePlace
            or ProvenanceAnchorKind.IncomingReferenceField)
        {
            initialized.SetIncomingReferenceInitializationPossibilities(
                target, 2);
            return;
        }
        if (target.Kind is not (ProvenanceAnchorKind.ReferencePlace
                or ProvenanceAnchorKind.NormalBackingPlace)
            || target.Storage is not StorageKey storage
            || !storage.IsKnown)
        {
            throw InvalidEffect(span, "CheckedReference");
        }

        SetReferencePlaceInitializationState(target.Identity,
            storage.Projection, live: true, initialized, fieldMasks,
            function, program, span);
    }

    private static void SetInitializationPostconditionTargetVacant(
        ProvenanceAnchor target, InitializationState initialized,
        uint[] fieldMasks, BoundFunction function, BoundProgram program,
        TextSpan span)
    {
        if (target.Kind is ProvenanceAnchorKind.IncomingReference
            or ProvenanceAnchorKind.IncomingReferenceContents
            or ProvenanceAnchorKind.IncomingReferencePlace
            or ProvenanceAnchorKind.IncomingReferenceField)
        {
            initialized.SetIncomingReferenceInitializationPossibilities(
                target, 1);
            return;
        }
        if (target.Kind is not (ProvenanceAnchorKind.ReferencePlace
                or ProvenanceAnchorKind.NormalBackingPlace)
            || target.Storage is not StorageKey storage
            || !storage.IsKnown)
        {
            throw InvalidEffect(span, "CheckedReference");
        }

        SetReferencePlaceInitializationState(target.Identity,
            storage.Projection, live: false, initialized, fieldMasks,
            function, program, span);
    }

    private static bool VerifyCallExpression(BoundCall call,
        InitializationState initialized, uint[] fieldMasks,
        HashSet<int> declarations, BoundFunction function,
        BoundProgram program, ref int remaining, int depth,
        FailureEdges? failures, bool statementCompound,
        BoundBinary? cleanupCounterStep,
        bool allowUnmaterializedInterfaceDefaults,
        bool discardedResult = false)
    {
        if (call.Function < 0 || call.Function >= program.Functions.Length || call.Arguments.IsDefault)
        {
            throw Invalid();
        }
        if ((!call.ArgumentParameterIndices.IsDefault
                && call.ArgumentParameterIndices.Length != call.Arguments.Length)
            || (!call.ArgumentImplicitReferenceTemporaries.IsDefault
                && call.ArgumentImplicitReferenceTemporaries.Length != call.Arguments.Length)
            || !call.DefaultedArguments.IsDefaultOrEmpty)
        {
            throw Invalid();
        }
        if (call.Arguments.Length > MaximumArguments)
        {
            throw Limit();
        }
        var target = program.Functions[call.Function];
        if (target.PropertyAccessorKind
                == BoundPropertyAccessorKind.Initializer)
        {
            var callerMayInitialize = function.IsClassConstructor
                || (function.PropertyAccessorKind
                        == BoundPropertyAccessorKind.Initializer
                    && function.PropertyName == target.PropertyName);
            var receiverIsCurrentObject
                = !call.Arguments.IsEmpty
                    && (call.ArgumentParameterIndices.IsDefault
                        || call.ParameterIndex(0) == 0)
                    && call.Arguments[0] is (BoundRead {
                        Variable: 0,
                    } or BoundReceiverLoan {
                        Variable: 0,
                    } or BoundMutableReceiverLoan {
                        Variable: 0,
                    });
            if (!callerMayInitialize
                || function.DeclaringStruct != target.DeclaringStruct
                || target.IsStatic || !receiverIsCurrentObject)
            {
                throw InvalidEffect(call.Span, "Initialization");
            }
        }
        if (!IsValidInterfaceCallIdentity(call, function, target, program))
        {
            throw InvalidEffect(call.Span, "InterfaceWitness");
        }
        for (var argumentIndex = 0;
            argumentIndex < call.Arguments.Length; argumentIndex++)
        {
            if (call.Arguments[argumentIndex]
                is not BoundPendingInterfaceDefault pending)
            {
                continue;
            }

            if (!allowUnmaterializedInterfaceDefaults
                || call.InterfaceCallIdentity
                    is not BoundInterfaceCallIdentity interfaceIdentity
                || interfaceIdentity.Requirement != pending.Requirement
                || !BoundInterfaceContract
                    .TryGetInterfaceMemberDefinition(
                        pending.Requirement, program.Interfaces,
                        static _ => true, out var member,
                        allowOpenFormals: true,
                        genericNominalTypeDefinitions:
                            program.GenericNominalTypeDefinitions,
                        sourceGenericTypeDefinitions:
                            program.SourceGenericTypeDefinitions)
                || member is null
                || (uint)pending.ParameterOrdinal
                    >= (uint)member.Parameters.Length
                || call.ParameterIndex(argumentIndex)
                    != pending.ParameterOrdinal + (target.IsStatic ? 0 : 1))
            {
                throw InvalidEffect(pending.Span, "InterfaceWitness");
            }

            var parameter = member.Parameters[pending.ParameterOrdinal];
            if (parameter.Mode != BoundInterfaceParameterMode.Value
                || parameter.Type.Kind
                    != BoundInterfaceTypeKind.Primitive
                || parameter.Type.PrimitiveType != pending.Type
                || (!parameter.HasPendingDefault
                    && parameter.DefaultExpression is null))
            {
                throw InvalidEffect(pending.Span, "InterfaceWitness");
            }
        }
        var requiresMutableInterfaceReceiver
            = IsMutableInterfaceCallReceiver(call, program);
        if (!IsValidGenericMethodInstantiation(call.GenericMethodCall,
                program, function, initialized)
            || !IsGenericMethodOwnerCompatible(
                call.GenericMethodCall, target, program)
            || !AreGenericMethodInstantiationsEqual(
                call.GenericMethodCall,
                target.GenericMethodProofCall
                ?? target.GenericMethodInstantiation)
            || !AreGenericMethodImportCallsEqual(call, target))
        {
            throw InvalidEffect(call.Span, "GenericMethod");
        }
        var copyOriginSummary = initialized.Dependencies is BackingDependencies summaryDependencies
            ? summaryDependencies.CopyOriginSummaries[call.Function]
            : target.CopyOriginSummary;
        if (copyOriginSummary is not null
            && initialized.Dependencies is null)
        {
            throw Invalid(call.Span);
        }
        var copyOriginInputViews = copyOriginSummary is null
            ? null : CopyOriginSummaryInputViews(target, copyOriginSummary);
        var stagedCopyOriginInputs = new Dictionary<int, StagedCopyOriginInput>();
        using var stagedRawUnionSnapshotState
            = new RepeatSnapshotReservationScope(
                initialized.RepeatResources);
        if (initialized.Dependencies is BackingDependencies copyOriginDependencies)
        {
            copyOriginDependencies.ClearCallResultCaches(call);
        }
        initialized.ClearInitializationPostconditionCallResult(call);
        if (target.IsCleanup || target.IsClassConstructor
            || target.StaticConstructorIdentity is not null)
        {
            throw InvalidEffect(call.Span, "Ownership");
        }
        if (target.RequiresUnsafeCaller && !call.IsUnsafeAuthorized)
        {
            throw InvalidEffect(call.Span, "UnsafeCaller");
        }
        if (RequiresNoFailureProof(function)
            && !CanCallWithoutTerrumFailure(function, target)
            && !CanCatchFailureFrom(failures, target))
        {
            throw InvalidNoFailureEffect(function, call.Span);
        }
        if (call.Arguments.Length != target.ParameterCount || call.Type != target.ReturnType)
        {
            throw Invalid();
        }
        if (IsClassOwnershipUnknown(program, call.Type))
        {
            throw InvalidEffect(call.Span, "Ownership");
        }
        if (target.DeclaringStruct is not null && !target.IsStatic && !target.IsConstructor
            && target.Variables[0].IsMutable
            && (int)target.Variables[0].Type is >= 100 and < ManagedClassTypes.First
            && call.Arguments[0] is not (BoundMutableReceiverLoan or BoundMutableFieldLoan))
        {
            throw Invalid();
        }
        if (target.DeclaringStruct is not null && !target.IsStatic && !target.IsConstructor
            && (call.Arguments.IsEmpty || call.ParameterIndex(0) != 0))
        {
            throw Invalid();
        }
        if (target.IsPrivate
            && !CanAccessFunction(function, target, program)
            && call.InterfaceCallIdentity is null)
        {
            throw Invalid();
        }
        var outTargets = new HashSet<int>();
        var initializationReservationTargets
            = new HashSet<ProvenanceAnchor>();
        var initializationOutputTargets
            = new Dictionary<int, HashSet<ProvenanceAnchor>>();
        var directNativeOutputTargets = new HashSet<int>();
        var implicitReferenceTemporaries = new HashSet<int>();
        var argumentParameters = call.ArgumentParameterIndices.IsDefault
            ? null : new bool[call.Arguments.Length];
        var loanRoot = -1;
        var loanOfInitializedField = false;
        var reservedReceiver = -1;
        var stagedDependencyCount = initialized.Dependencies?.Staged.Count ?? 0;
        var argumentsComplete = true;
        InitializationState? nonCompletingArgumentState = null;
        uint[]? nonCompletingArgumentMasks = null;
        void RetireStagedCallResultInputs(InitializationState state)
        {
            for (var argumentIndex = 0;
                argumentIndex < call.Arguments.Length;
                argumentIndex++)
            {
                var argument = call.Arguments[argumentIndex];
                state.RepeatResources.ConsumeWork();
                if (state.Dependencies
                    is BackingDependencies dependencies)
                {
                    dependencies.ClearCallResultCaches(argument);
                }

                if (argument is BoundCall argumentCall)
                {
                    state
                        .ClearInitializationPostconditionCallResult(
                            argumentCall);
                }
            }
        }

        try
        {
            for (var i = 0; i < call.Arguments.Length; i++)
            {
                if (!argumentsComplete)
                {
                    initialized = (nonCompletingArgumentState
                        ?? throw Invalid()).Clone();
                    fieldMasks = (uint[])(nonCompletingArgumentMasks
                        ?? throw Invalid()).Clone();
                    failures = null;
                }
                var argument = call.Arguments[i];
                var parameterIndex = call.ParameterIndex(i);
                if (argumentParameters is not null)
                {
                    if ((uint)parameterIndex >= (uint)call.Arguments.Length
                        || argumentParameters[parameterIndex])
                    {
                        throw Invalid();
                    }
                    argumentParameters[parameterIndex] = true;
                }
                var parameterSlot = parameterIndex + (target.IsConstructor ? 1 : 0);
                if ((uint)parameterSlot >= (uint)target.Variables.Length)
                {
                    throw Invalid();
                }
                var nativeOutputContract = NativeOutputContractForParameter(
                    target, parameterIndex);
                var directNativeOutput = nativeOutputContract is null
                    ? DirectNativeImportContract.OutputForParameter(target, parameterIndex)
                    : null;
                var nativeVTableOutput = NativeVTableCallContract.OutputForParameter(
                    target, parameterIndex);
                var directNativeParameter = DirectNativeImportContract.ParameterForParameter(
                    target, parameterIndex);
                var isDirectNativeStringPointerArgument = directNativeParameter is not null
                    && DirectNativeImportContract.IsStringPointerArgument(
                        argument, directNativeParameter, program);
                var nativeVTableParameter = NativeVTableCallContract.ParameterForParameter(
                    target, parameterIndex);
                var isNativeVTableStringPointerArgument = nativeVTableParameter is not null
                    && DirectNativeImportContract.IsStringPointerArgument(
                        argument, nativeVTableParameter, program);
                var isDirectNativeParameterAddress = argument is BoundNativeStorageAddress
                    directParameterAddress
                    && directNativeParameter is not null
                    && DirectNativeImportContract.MatchesAddress(
                        directParameterAddress, directNativeParameter, function, program);
                var isDirectNativeParameterValue = directNativeParameter is not null
                    && argument is not BoundNativeStorageAddress
                    && DirectNativeImportContract.MatchesNativeParameterArgumentType(
                        argument.Type, target.Variables[parameterSlot].Type,
                        directNativeParameter, program.NativePointerTypes,
                        DirectNativeImportContract.IsNullNativePointerValue(argument));
                var isNativeVTableParameterAddress = argument is BoundNativeStorageAddress
                    nativeVTableParameterAddress
                    && nativeVTableParameter is not null
                    && DirectNativeImportContract.MatchesAddress(
                        nativeVTableParameterAddress, nativeVTableParameter, function, program);
                var isNativeVTableParameterValue = nativeVTableParameter is not null
                    && argument is not BoundNativeStorageAddress
                    && DirectNativeImportContract.MatchesNativeParameterArgumentType(
                        argument.Type, target.Variables[parameterSlot].Type,
                        nativeVTableParameter, program.NativePointerTypes,
                        DirectNativeImportContract.IsNullNativePointerValue(argument));
                var implicitReferenceTemporary = call.ImplicitReferenceTemporary(i);
                if (implicitReferenceTemporary < -1)
                {
                    throw Invalid();
                }
                var implicitReferenceFormal
                    = target.Variables[parameterSlot];
                var implicitReferenceValueType
                    = ImplicitReferenceValueType(
                        implicitReferenceFormal, program);
                var persistedImplicitReference = target
                        .Variables[parameterSlot].IsImplicitRef
                    && CheckedReferenceTypeContract.IsValidType(
                        argument.Type, program.CheckedReferenceTypes)
                    && argument is not BoundPrivatePlaceRead {
                        UseKind: 3,
                    }
                    && IsPrivateImplicitReferenceArgument(
                        argument.Type,
                        target.Variables[parameterSlot], program);
                var sourceArgument = persistedImplicitReference
                    ? new BoundReferenceRead(argument,
                        implicitReferenceValueType,
                        argument.Span)
                    : argument;
                CopyOriginValue? preMoveCopyOriginSnapshot = null;
                Dictionary<StorageProjection, BackingFieldValue>?
                    preMoveBackingSnapshot = null;
                Dictionary<StorageProjection, NativePointerFieldValue>?
                    preMoveNativePointerSnapshot = null;
                Dictionary<StorageProjection, ReferenceFieldValue>?
                    preMoveReferenceSnapshot = null;
                byte[]? preMoveRawUnionInitializedBytes = null;
                SortedDictionary<StorageProjection,
                    InitializationState.RawUnionArrayElementState>?
                    preMoveRawUnionArraySnapshot = null;
                if (argumentsComplete && argument is BoundMove or BoundFieldMove
                    && copyOriginInputViews?.ContainsKey(parameterIndex) == true)
                {
                    if (initialized.Dependencies is not BackingDependencies copyOriginState)
                    {
                        throw Invalid(argument.Span);
                    }
                    var preMoveValue = argument is BoundFieldMove fieldMoveArgument
                        ? fieldMoveArgument.Place : argument;
                    preMoveCopyOriginSnapshot = CopyOriginValueOfExpression(preMoveValue,
                        argument.Type, copyOriginState, function, program,
                        ref remaining, depth + 1);
                    preMoveBackingSnapshot =
                        BackingFieldValueSnapshotOfExpression(preMoveValue,
                            argument.Type, copyOriginState, function, program,
                            ref remaining, depth + 1);
                    preMoveReferenceSnapshot =
                        ReferenceFieldValuesOfExpression(preMoveValue,
                            argument.Type, copyOriginState, initialized,
                            function, program, ref remaining, depth + 1,
                            fieldMasks);
                    if (CarriesNativePointer(argument.Type, program))
                    {
                        preMoveNativePointerSnapshot =
                            NativePointerFieldValueSnapshotOfExpression(preMoveValue,
                                argument.Type, copyOriginState, function, program,
                                ref remaining, depth + 1);
                    }
                    if (CarriesRawUnionPayloadFacts(
                        program, argument.Type))
                    {
                        preMoveRawUnionInitializedBytes
                            = InitializedPayloadBytesOfExpression(
                                preMoveValue, argument.Type, initialized,
                                function, program, ref remaining,
                                depth + 1);
                    }
                    if (CarriesRawUnionArrayFacts(program,
                            argument.Type))
                    {
                        preMoveRawUnionArraySnapshot
                            = RawUnionArrayFactsOfExpression(
                                preMoveValue, initialized, function,
                                program, ref remaining,
                                depth + 1,
                                out var preMoveSnapshotState);
                        stagedRawUnionSnapshotState
                            .Adopt(preMoveSnapshotState);
                    }
                }
                if (target.Variables[parameterSlot].IsImplicitRef)
                {
                    if (persistedImplicitReference)
                    {
                        if (implicitReferenceTemporary >= 0)
                        {
                            throw InvalidEffect(argument.Span,
                                "Ownership");
                        }
                    }
                    else if ((target.IsExternal
                            && !HasPublishedModuleReferenceContract(target))
                        || !IsImplicitReferenceType(
                            implicitReferenceValueType, program)
                        || (implicitReferenceTemporary < 0
                            && !IsSupportedImplicitReferencePlace(argument, function, program)))
                    {
                        throw InvalidEffect(argument.Span, "Ownership");
                    }
                    if (implicitReferenceTemporary >= 0)
                    {
                        var firstLocal = function.ParameterCount + (function.IsConstructor ? 1 : 0);
                        if (implicitReferenceTemporary < firstLocal
                            || implicitReferenceTemporary >= function.Variables.Length
                            || !implicitReferenceTemporaries.Add(implicitReferenceTemporary)
                            || !function.Variables[implicitReferenceTemporary].IsImplicitReferenceTemporary
                            || !function.Variables[implicitReferenceTemporary].IsInitializationLocal
                            || !function.Variables[implicitReferenceTemporary].IsMutable
                            || !declarations.Contains(implicitReferenceTemporary)
                            || function.Variables[implicitReferenceTemporary].Type
                                != implicitReferenceValueType)
                        {
                            throw InvalidEffect(argument.Span, "Ownership");
                        }
                    }
                }
                else if (implicitReferenceTemporary >= 0)
                {
                    throw InvalidEffect(argument.Span, "Ownership");
                }
                if (reservedReceiver >= 0 && InvalidatesReservedOwner(argument, reservedReceiver,
                    ref remaining, depth + 1))
                {
                    throw InvalidEffect(argument.Span, "Ownership");
                }
                if (argument is BoundOutArgument output)
                {
                    CheckBackingInvalidation(output.Variable, initialized, output.Span);
                    if (output.Variable < 0 || output.Variable >= initialized.Length
                        || (output.Variable < function.ParameterCount + (function.IsConstructor ? 1 : 0)
                            && (!function.Variables[output.Variable].IsOut || output.DeclaresVariable))
                        || output.Type != function.Variables[output.Variable].Type
                        || (output.DeclaresVariable && (!declarations.Add(output.Variable) || initialized[output.Variable]
                            || function.Variables[output.Variable].IsInitializationLocal))
                        || (!output.DeclaresVariable && !output.IsInit
                            && !function.Variables[output.Variable].IsMutable)
                        || (output.IsInit && !output.DeclaresVariable && !initialized.IsVacant(output.Variable))
                        || (output.IsInit && !output.DeclaresVariable
                            && !function.Variables[output.Variable].IsMutable
                            && !function.Variables[output.Variable].IsInitializationLocal
                            && initialized.HasRetiredValue(output.Variable))
                        || output.IsInit != target.Variables[parameterSlot].IsInit)
                    {
                        throw Invalid();
                    }
                    if (!outTargets.Add(output.Variable))
                    {
                        throw InvalidEffect(output.Span, "Ownership");
                    }
                    initialized[output.Variable] = false;
                    fieldMasks[output.Variable] = 0;
                    initialized.SetPossibleFieldMask(output.Variable, 0);
                }
                else
                {
                    var isAllowedStorageAddress =
                        argument is BoundNativeStorageAddress matchedDirectParameterAddress
                            && directNativeParameter is not null
                            && DirectNativeImportContract.MatchesAddress(
                                matchedDirectParameterAddress, directNativeParameter, function, program);
                    isAllowedStorageAddress |= isNativeVTableParameterAddress;
                    if (nativeOutputContract is not null)
                    {
                        if (argument is not BoundNativeOutputReservation reservation
                            || !MatchesReservation(reservation, nativeOutputContract,
                                function, program)
                            || !directNativeOutputTargets.Add(reservation.Variable))
                        {
                            throw InvalidEffect(argument.Span, "NativeImport");
                        }
                        VerifyNativeOutputReservation(reservation, nativeOutputContract,
                            initialized, fieldMasks, declarations, function, program,
                            ref remaining, depth + 1, failures);
                    }
                    else if (directNativeOutput is not null)
                    {
                        if (argument is not BoundNativeOutputReservation reservation
                            || !DirectNativeImportContract.MatchesReservation(
                                reservation, directNativeOutput, function, program)
                            || !directNativeOutputTargets.Add(reservation.Variable))
                        {
                            throw InvalidEffect(argument.Span, "NativeImport");
                        }
                        VerifyNativeOutputReservation(reservation, directNativeOutput,
                            initialized, fieldMasks, declarations, function, program,
                            ref remaining, depth + 1, failures);
                    }
                    else if (nativeVTableOutput is not null)
                    {
                        if (argument is not BoundNativeOutputReservation reservation
                            || !DirectNativeImportContract.MatchesReservation(
                                reservation, nativeVTableOutput, function, program)
                            || !directNativeOutputTargets.Add(reservation.Variable))
                        {
                            throw InvalidEffect(argument.Span, "NativeImport");
                        }
                        VerifyNativeOutputReservation(reservation, nativeVTableOutput,
                            initialized, fieldMasks, declarations, function, program,
                            ref remaining, depth + 1, failures);
                    }
                    else if (argument is BoundNativeOutputReservation)
                    {
                        throw InvalidEffect(argument.Span, "NativeImport");
                    }
                    else if (directNativeParameter is not null)
                    {
                        if (argument is BoundNativeStorageAddress address)
                        {
                            if (!DirectNativeImportContract.MatchesAddress(
                                address, directNativeParameter, function, program))
                            {
                                throw InvalidEffect(argument.Span, "NativeImport");
                            }
                            VerifyDirectNativeParameterAddress(address, directNativeParameter,
                                initialized, fieldMasks, declarations, function, program,
                                ref remaining, depth + 1, failures);
                        }
                        else if (!DirectNativeImportContract.MatchesNativeParameterArgumentType(
                                argument.Type, target.Variables[parameterSlot].Type,
                                directNativeParameter,
                                program.NativePointerTypes,
                                DirectNativeImportContract.IsNullNativePointerValue(argument))
                            && !isDirectNativeStringPointerArgument)
                        {
                            throw InvalidEffect(argument.Span, "NativeImport");
                        }
                    }
                    else if (nativeVTableParameter is not null)
                    {
                        if (argument is BoundNativeStorageAddress address)
                        {
                            if (!DirectNativeImportContract.MatchesAddress(
                                address, nativeVTableParameter, function, program))
                            {
                                throw InvalidEffect(argument.Span, "NativeImport");
                            }
                            VerifyDirectNativeParameterAddress(address, nativeVTableParameter,
                                initialized, fieldMasks, declarations, function, program,
                                ref remaining, depth + 1, failures);
                        }
                        else if (!DirectNativeImportContract.MatchesNativeParameterArgumentType(
                                argument.Type, target.Variables[parameterSlot].Type,
                                nativeVTableParameter,
                                program.NativePointerTypes,
                                DirectNativeImportContract.IsNullNativePointerValue(argument))
                            && !isNativeVTableStringPointerArgument)
                        {
                            throw InvalidEffect(argument.Span, "NativeImport");
                        }
                    }
                    else if (argument is BoundNativeStorageAddress && !isAllowedStorageAddress)
                    {
                        throw InvalidEffect(argument.Span, "NativeImport");
                    }
                    else if (target.IsExternal
                        && IsNativeUtfZPointer(target.Variables[parameterSlot].Type)
                        && !HasValidNativeStringArgument(argument,
                            target.Variables[parameterSlot].Type, parameterIndex, target, program))
                    {
                        throw InvalidEffect(argument.Span, "NativeImport");
                    }
                    if (IsNativeUtfZPointer(argument.Type)
                        && argument.Type != target.Variables[parameterSlot].Type)
                    {
                        if (!isDirectNativeStringPointerArgument
                            && !isNativeVTableStringPointerArgument)
                        {
                            throw InvalidEffect(argument.Span, "NativeImport");
                        }
                    }
                    if (argument is BoundMutableReceiverLoan mutableLoan)
                    {
                        CheckBackingInvalidation(mutableLoan.Variable, initialized, mutableLoan.Span);
                        var bufferMutation = target.Intrinsic is BoundIntrinsic.BufferSet
                            or BoundIntrinsic.BufferTryAppend or BoundIntrinsic.BufferClear;
                        var structMutation = target.Intrinsic == BoundIntrinsic.None
                            && target.DeclaringStruct is not null && !target.IsStatic
                            && !target.IsConstructor && target.Variables[0].IsMutable
                            && HasFields(program, mutableLoan.Type)
                            && !ManagedClassTypes.IsClass(mutableLoan.Type);
                        var interfaceReceiverMutation = parameterIndex == 0
                            && call.InterfaceCallIdentity is not null
                            && !target.Variables.IsEmpty
                            && target.Variables[0].IsMutable
                            && requiresMutableInterfaceReceiver;
                        if (parameterIndex != 0
                            || (!bufferMutation && !structMutation
                                && !interfaceReceiverMutation)
                            || mutableLoan.Variable < 0 || mutableLoan.Variable >= initialized.Length
                            || (bufferMutation && mutableLoan.Type != PrimitiveType.OwnedInt32Buffer)
                            || mutableLoan.Type != target.Variables[0].Type
                            || function.Variables[mutableLoan.Variable].Type != mutableLoan.Type
                            || (!function.Variables[
                                    mutableLoan.Variable].IsMutable
                                && !IsWritableGenericMethodTypeArgument(
                                    mutableLoan.Type, program)
                                && !HasGenericWriteRequirement(
                                    mutableLoan.Type, function, program))
                            || !initialized[mutableLoan.Variable])
                        {
                            throw InvalidEffect(mutableLoan.Span, "Ownership");
                        }
                        loanRoot = mutableLoan.Variable;
                    }
                    else if (argument is BoundMutableFieldLoan mutableField)
                    {
                        var bufferMutation = target.Intrinsic is BoundIntrinsic.BufferSet
                            or BoundIntrinsic.BufferTryAppend or BoundIntrinsic.BufferClear;
                        var interfaceReceiverMutation = parameterIndex == 0
                            && call.InterfaceCallIdentity is not null
                            && !target.Variables.IsEmpty
                            && target.Variables[0].IsMutable
                            && requiresMutableInterfaceReceiver;
                        if (parameterIndex != 0 || (target.Intrinsic != BoundIntrinsic.None && !bufferMutation)
                            || (target.DeclaringStruct is null
                                && !interfaceReceiverMutation)
                            || target.IsStatic || target.IsConstructor
                            || (!target.Variables[0].IsMutable
                                && !interfaceReceiverMutation)
                            || mutableField.Place is null
                            || mutableField.Type != target.Variables[0].Type
                            || mutableField.Place.Type != mutableField.Type
                            || (bufferMutation && mutableField.Type != PrimitiveType.OwnedInt32Buffer))
                        {
                            throw InvalidEffect(mutableField.Span, "Ownership");
                        }
                        loanRoot = VerifyMutableFieldPlace(mutableField.Place, initialized,
                            function, program, ref remaining, depth + 1, bufferMutation);
                        CheckBackingInvalidation(loanRoot, initialized, mutableField.Span);
                    }
                    else if (argument is BoundReceiverLoan loan)
                    {
                        var isReceiverLoan = parameterIndex == 0
                            && loan.Type == target.Variables[0].Type
                            && !target.Variables[0].IsMutable;
                        if (!isReceiverLoan
                            || target.DeclaringStruct is null || target.IsStatic || target.IsConstructor
                            || loan.Variable < 0 || loan.Variable >= initialized.Length
                            || !IsUnique(program, loan.Type)
                            || !initialized[loan.Variable]
                            || function.Variables[loan.Variable].Type != loan.Type)
                        {
                            throw InvalidEffect(loan.Span, "Ownership");
                        }
                        loanRoot = loan.Variable;
                    }
                    else if (argument is BoundFieldLoan fieldLoan)
                    {
                        if (parameterIndex != 0 || target.DeclaringStruct is null || target.IsStatic || target.IsConstructor
                            || fieldLoan.Place is null
                            || fieldLoan.Type != target.Variables[0].Type
                            || target.Variables[0].IsMutable
                            || fieldLoan.Place.Type != fieldLoan.Type || !IsUnique(program, fieldLoan.Type))
                        {
                            throw InvalidEffect(fieldLoan.Span, "Ownership");
                        }
                        loanRoot = VerifyUniqueFieldPlace(fieldLoan.Place, initialized, fieldMasks,
                            function, program, ref remaining, depth + 1);
                        loanOfInitializedField = true;
                    }
                    else
                    {
                        if (target.IsExternal
                            && IsNativeUtfZPointer(target.Variables[parameterSlot].Type))
                        {
                            if (!HasValidNativeStringArgument(argument,
                                target.Variables[parameterSlot].Type, parameterIndex, target, program))
                            {
                                throw InvalidEffect(argument.Span, "NativeImport");
                            }
                        }
                        else if (IsNativeUtfZPointer(argument.Type)
                            && argument.Type != target.Variables[parameterSlot].Type
                            && !isDirectNativeStringPointerArgument
                            && !isNativeVTableStringPointerArgument)
                        {
                            throw InvalidEffect(argument.Span, "NativeImport");
                        }
                        if (argument is not (BoundNativeStorageAddress or BoundNativeOutputReservation))
                        {
                            var isClassReceiver = parameterIndex == 0
                                && target.DeclaringStruct is not null
                                && !target.IsStatic && !target.IsConstructor
                                && !target.IsClassConstructor
                                && ManagedClassTypes.IsClass(argument.Type)
                                && target.Variables[0].Type
                                    == argument.Type;
                            if ((IsClassOwnershipUnknown(program,
                                    argument.Type)
                                    && !isClassReceiver)
                                || (IsUnique(program, argument.Type)
                                && argument is not (BoundMove or BoundFieldMove or BoundCall)
                                && argument is not BoundRead {
                                    GenericCopyRefinementOrdinal: >= 0,
                                }))
                            {
                                throw InvalidEffect(argument.Span, "Ownership");
                            }
                            if (!EvaluateExpression(argument, initialized, fieldMasks, declarations,
                                function, program, ref remaining, depth + 1, failures))
                            {
                                argumentsComplete = false;
                                nonCompletingArgumentState
                                    = initialized.Clone(
                                        stagedRawUnionSnapshotState);
                                nonCompletingArgumentMasks = (uint[])fieldMasks.Clone();
                            }
                            else if (directNativeParameter is not null
                                && argument is not BoundNativeStorageAddress
                                && !isDirectNativeStringPointerArgument)
                            {
                                VerifyNativeParameterValueExtent(argument,
                                    directNativeParameter, call.IsUnsafeAuthorized,
                                    initialized, function, program,
                                    ref remaining, depth + 1);
                            }
                            else if (nativeVTableParameter is not null
                                && argument is not BoundNativeStorageAddress
                                && !isNativeVTableStringPointerArgument)
                            {
                                VerifyNativeParameterValueExtent(argument,
                                    nativeVTableParameter, call.IsUnsafeAuthorized,
                                    initialized, function, program,
                                    ref remaining, depth + 1);
                            }
                        }
                    }
                }
                if (loanRoot >= 0 && parameterIndex == 0)
                {
                    reservedReceiver = loanRoot;
                }
                var isSourceImplicitReferenceAdaptation
                    = implicitReferenceFormal.IsImplicitRef
                    && !persistedImplicitReference
                    && argument.Type == implicitReferenceValueType
                    && (implicitReferenceTemporary >= 0
                        || IsSupportedImplicitReferencePlace(
                            argument, function, program));
                if (argument.Type != target.Variables[parameterSlot].Type
                    && !(argument is BoundNativeOutputReservation && nativeOutputContract is not null)
                    && !(argument is BoundNativeOutputReservation && directNativeOutput is not null)
                    && !(argument is BoundNativeOutputReservation && nativeVTableOutput is not null)
                    && !isDirectNativeParameterAddress
                    && !isDirectNativeParameterValue
                    && !isDirectNativeStringPointerArgument
                    && !isNativeVTableParameterAddress
                    && !isNativeVTableParameterValue
                    && !isNativeVTableStringPointerArgument
                    && !persistedImplicitReference
                    && !isSourceImplicitReferenceAdaptation)
                {
                    throw Invalid();
                }
                if ((argument is BoundOutArgument)
                    != target.Variables[parameterSlot].IsOut
                    && directNativeOutput is null && nativeVTableOutput is null)
                {
                    throw Invalid();
                }
                if (implicitReferenceTemporary >= 0)
                {
                    initialized[implicitReferenceTemporary] = true;
                    fieldMasks[implicitReferenceTemporary] = 0;
                    initialized.SetPossibleFieldMask(implicitReferenceTemporary, 0);
                }
                if (argumentsComplete
                    && copyOriginInputViews is not null
                    && copyOriginInputViews.TryGetValue(parameterIndex, out var sourceView))
                {
                    if (initialized.Dependencies is not BackingDependencies copyOriginState)
                    {
                        throw Invalid(argument.Span);
                    }
                    var snapshotEntryValue = sourceView
                            == BoundCopyOriginSourceView.EntryValue
                        || implicitReferenceTemporary >= 0
                        || persistedImplicitReference;
                    var snapshot = snapshotEntryValue
                        ? preMoveCopyOriginSnapshot ?? CopyOriginValueOfExpression(sourceArgument,
                            sourceArgument.Type, copyOriginState, function, program,
                            ref remaining, depth + 1)
                        : null;
                    var backingSnapshot = snapshotEntryValue
                        ? preMoveBackingSnapshot
                            ?? BackingFieldValueSnapshotOfExpression(sourceArgument,
                                sourceArgument.Type, copyOriginState, function, program,
                                ref remaining, depth + 1)
                        : null;
                    var nativePointerSnapshot = snapshotEntryValue
                        && CarriesNativePointer(sourceArgument.Type, program)
                            ? preMoveNativePointerSnapshot
                                ?? NativePointerFieldValueSnapshotOfExpression(
                                    sourceArgument, sourceArgument.Type, copyOriginState,
                                    function, program, ref remaining, depth + 1)
                            : null;
                    var referenceSnapshot = snapshotEntryValue
                        ? preMoveReferenceSnapshot
                            ?? ReferenceFieldValuesOfExpression(sourceArgument,
                                sourceArgument.Type, copyOriginState, initialized,
                                function, program, ref remaining, depth + 1,
                                fieldMasks)
                        : null;
                    var rawUnionInitializedBytes = snapshotEntryValue
                        && CarriesRawUnionPayloadFacts(
                            program, sourceArgument.Type)
                            ? preMoveRawUnionInitializedBytes
                                ?? InitializedPayloadBytesOfExpression(
                                    sourceArgument, sourceArgument.Type, initialized,
                                    function, program,
                                    ref remaining, depth + 1)
                            : null;
                    SortedDictionary<StorageProjection,
                        InitializationState.RawUnionArrayElementState>?
                        rawUnionArraySnapshot = null;
                    RepeatResourceLedger.StateLease? rawUnionArraySnapshotState
                        = null;
                    if (snapshotEntryValue
                        && CarriesRawUnionArrayFacts(
                            program, sourceArgument.Type))
                    {
                        if (preMoveRawUnionArraySnapshot is not null)
                        {
                            rawUnionArraySnapshot
                                = preMoveRawUnionArraySnapshot;
                        }
                        else
                        {
                            rawUnionArraySnapshot
                                = RawUnionArrayFactsOfExpression(
                                    sourceArgument, initialized, function,
                                    program, ref remaining,
                                    depth + 1,
                                    out rawUnionArraySnapshotState);
                        }
                    }
                    if (rawUnionArraySnapshot is not null)
                    {
                        if (argument is BoundCall
                                rawUnionInputCall
                            && initialized.Dependencies
                                is BackingDependencies
                                    rawUnionInputDependencies
                            && rawUnionInputDependencies
                                .TryGetRawUnionArrayCallResult(
                                    rawUnionInputCall,
                                    out var storedRawUnionFacts)
                            && ReferenceEquals(
                                rawUnionArraySnapshot,
                                storedRawUnionFacts))
                        {
                            rawUnionArraySnapshot
                                = BackingDependencies
                                    .CloneRawUnionArrayCallResultSnapshot(
                                        storedRawUnionFacts,
                                        stagedRawUnionSnapshotState);
                            rawUnionInputDependencies
                                .ClearRawUnionArrayCallResult(
                                    rawUnionInputCall);
                        }
                        else
                        {
                            stagedRawUnionSnapshotState.Adopt(
                                rawUnionArraySnapshotState);
                        }
                    }
                    if (!stagedCopyOriginInputs.TryAdd(parameterIndex,
                        new StagedCopyOriginInput(sourceView, sourceArgument, snapshot,
                            backingSnapshot, nativePointerSnapshot,
                            referenceSnapshot, rawUnionInitializedBytes,
                            rawUnionArraySnapshot)))
                    {
                        throw Invalid(argument.Span);
                    }
                }
                if (argumentsComplete
                    && IsInitializationReferenceOutputParameter(
                        target, parameterSlot, program))
                {
                    if (initialized.Dependencies
                        is not BackingDependencies reservationDependencies)
                    {
                        throw InvalidEffect(argument.Span,
                            "CheckedReference");
                    }

                    var outputTargets = ReferenceTargetsOfExpression(
                        argument, reservationDependencies, initialized,
                        function, program, ref remaining, depth + 1,
                        fieldMasks);
                    if (outputTargets.Count == 0)
                    {
                        throw InvalidEffect(argument.Span,
                            "CheckedReference");
                    }
                    initializationOutputTargets.Add(i, outputTargets);
                    var reservedTargets
                        = new HashSet<ProvenanceAnchor>(outputTargets);
                    if (argument is not (BoundReferenceFormation
                        or BoundPrivateReferenceForm {
                            FormationKind: 1,
                        }))
                    {
                        reservedTargets.UnionWith(
                            ReferenceDescriptorPlacesOfExpression(argument,
                                reservationDependencies, initialized,
                                function, program, ref remaining,
                                depth + 1, fieldMasks));
                    }
                    initialized.ReserveInitializationReferenceTargets(
                        reservedTargets, argument.Span);
                    initializationReservationTargets.UnionWith(
                        reservedTargets);
                }
                StageDependencySource(call, parameterIndex, argument, target,
                    initialized, program, ref remaining, depth + 1, fieldMasks);
            }
            if (!argumentsComplete)
            {
                RetireStagedCallResultInputs(initialized);
                initialized.CancelUninvokedNativeOutputReservations();
                return false;
            }
            if (loanRoot >= 0 && !initialized[loanRoot]
                && !(loanOfInitializedField
                    && (initialized.HasPartialValue(loanRoot)
                        || (function.IsConstructor && loanRoot == 0))))
            {
                throw InvalidEffect(call.Span, "Ownership");
            }
            if (directNativeOutputTargets.Overlaps(outTargets))
            {
                throw InvalidEffect(call.Span, "NativeImport");
            }
            VerifyStagedNativeParameterExtents(call, target,
                initialized, program, ref remaining, depth + 1);
            var copyOriginCallResult = CarriesCopyOrigin(call.Type, program)
                && initialized.Dependencies is BackingDependencies
                copyOriginResultDependencies
                ? CreateCopyOriginCallResult(call, target, copyOriginSummary,
                    stagedCopyOriginInputs, copyOriginResultDependencies,
                    function, program, ref remaining, depth + 1)
                : null;
            if (CarriesRawUnionPayloadFacts(program, call.Type)
                && initialized.Dependencies
                    is BackingDependencies rawUnionCallDependencies)
            {
                var rawUnionCallCoverage
                    = RawUnionInitializedPayloadBytesForCall(
                        call, target, copyOriginSummary,
                        stagedCopyOriginInputs,
                        initialized.RawUnionReturnCoverageSummaries,
                        program);
                rawUnionCallDependencies
                    .SetRawUnionCallCoverageResult(call,
                        rawUnionCallCoverage);
            }
            if (CarriesRawUnionArrayFacts(program, call.Type)
                && initialized.Dependencies
                    is BackingDependencies rawUnionArrayDependencies)
            {
                var rawUnionArrayCallFacts
                    = RawUnionArrayFactsForCall(call, target,
                        copyOriginSummary, stagedCopyOriginInputs,
                        initialized, function, program,
                        ref remaining, depth + 1,
                        out var rawUnionArrayCallState);
                try
                {
                    if (rawUnionArrayCallFacts.Count != 0)
                    {
                        rawUnionArrayDependencies
                            .SetRawUnionArrayCallResult(call,
                                rawUnionArrayCallFacts,
                                rawUnionArrayCallState
                                    ?? throw Invalid());
                        rawUnionArrayCallState = null;
                    }
                    else
                    {
                        rawUnionArrayDependencies
                            .ClearRawUnionArrayCallResult(call);
                    }
                }
                finally
                {
                    rawUnionArrayCallState?.Dispose();
                }
            }
            // RawUnionArrayFactsForCall is the final consumer of these snapshots.
            stagedRawUnionSnapshotState.Dispose();
            var backingCallResult =
                initialized.Dependencies is BackingDependencies backingResultDependencies
                ? CreateBackingCallResult(call, target, copyOriginSummary,
                    stagedCopyOriginInputs, backingResultDependencies,
                    function, program, ref remaining, depth + 1)
                : null;
            var nativePointerCallResult =
                initialized.Dependencies is BackingDependencies
                    nativePointerResultDependencies
                ? CreateNativePointerCallResult(call, target,
                    copyOriginSummary, stagedCopyOriginInputs,
                    nativePointerResultDependencies, function, program,
                    ref remaining, depth + 1)
                : null;
            var referenceFieldCallResult =
                initialized.Dependencies is BackingDependencies
                    referenceFieldResultDependencies
                ? CreateReferenceFieldCallResult(call, target,
                    copyOriginSummary, stagedCopyOriginInputs,
                    referenceFieldResultDependencies, initialized,
                    fieldMasks, function, program, ref remaining,
                    depth + 1)
                : null;
            var referenceCallResult =
                CheckedReferenceTypeContract.IsValidType(
                    call.Type, program.CheckedReferenceTypes)
                && initialized.Dependencies is BackingDependencies
                    referenceCallResultDependencies
                ? CreateReferenceCallResult(call, target,
                    referenceCallResultDependencies, initialized,
                    fieldMasks, function, program, ref remaining,
                    depth + 1)
                : null;
            if (referenceFieldCallResult is not null
                && initialized.Dependencies is BackingDependencies
                    referenceFieldCallDependencies)
            {
                referenceFieldCallDependencies.SetReferenceFieldCallResult(
                    call, referenceFieldCallResult);
            }
            ApplyReferenceOwnerStoreCallEffects(call, target, initialized,
                fieldMasks, function, program, ref remaining, depth + 1);
            ApplyCopyOriginCallEffects(call, target, initialized,
                fieldMasks, function, program, ref remaining,
                depth + 1);
            ApplyRawUnionArrayCallEffects(call, target, initialized,
                function, program, ref remaining, depth + 1);
            ApplyBackingCallEffects(call, target, initialized, function,
                program, ref remaining, depth + 1);
            ApplyReferenceBackingCallEffects(call, target, initialized,
                fieldMasks, function, program, ref remaining, depth + 1);
            InvalidateInitializationPostconditionResultsForCall(call,
                target, initialized, fieldMasks, function, program,
                ref remaining, depth + 1);
            ApplyNativePointerCaptureEffects(call, target, initialized, ref remaining);
            InvalidateNativePointerExtentsForCall(
                call, target, initialized, program);
            ApplyNativeOutputCallEffects(call, target, initialized, ref remaining);
            RetireStagedCallResultInputs(initialized);
            if (!ProvidesNoFailureGuarantee(target))
            {
                if (failures is not null)
                {
                    var failureState = initialized.Clone();
                    var failureMasks = (uint[])fieldMasks.Clone();
                    failureState.ReleaseInitializationReferenceTargets(
                        initializationReservationTargets);
                    for (var argumentIndex = 0;
                        argumentIndex < call.Arguments.Length;
                        argumentIndex++)
                    {
                        var parameterSlot = call.ParameterIndex(argumentIndex)
                            + (target.IsConstructor ? 1 : 0);
                        if (!IsInitializationReferenceOutputParameter(
                                target, parameterSlot, program))
                        {
                            continue;
                        }

                        if (!initializationOutputTargets.TryGetValue(
                                argumentIndex, out var outputTargets))
                        {
                            throw Invalid();
                        }
                        ApplyInitializationReferenceOutputTargets(
                            outputTargets, failureState,
                            failureMasks,
                            failureState.Dependencies
                                as BackingDependencies
                                ?? throw InvalidEffect(
                                    call.Arguments[argumentIndex].Span,
                                    "CheckedReference"),
                            call.Arguments[argumentIndex].Span,
                                maybeInitialized: true);
                    }
                    failures.Add(failureState, failureMasks);
                }
            }
            ApplyInitializationPostconditionEffects(call, target,
                initialized, fieldMasks, function, program, failures,
                ref remaining, depth + 1,
                out var correlatedPostconditions);
            var initializationCallFact
                = CreateInitializationPostconditionCallFact(target,
                    correlatedPostconditions, initialized, fieldMasks,
                    function, program, ref remaining, depth + 1);
            if (initializationCallFact is not null && !discardedResult)
            {
                initialized.SetInitializationPostconditionCallFact(call,
                    initializationCallFact);
            }
            else
            {
                initialized.ClearInitializationPostconditionCallFact(call);
            }
            if (initializationCallFact is not null && !discardedResult
                && target.ReturnType == PrimitiveType.Bool
                && !target.DeclarationContractClauses.Any(static clause =>
                    clause.Phase
                        == BoundDeclarationContractPhase.NormalPostcondition)
                && HasInitializationReferenceOutput(target, program))
            {
                initialized.RecordInitializationPostconditionCallFactSnapshot(
                    call, initializationCallFact);
            }
            if (copyOriginCallResult is not null
                && initialized.Dependencies is BackingDependencies resultDependencies)
            {
                resultDependencies.SetCopyOriginCallResult(call, copyOriginCallResult);
            }
            if (backingCallResult is not null
                && initialized.Dependencies is BackingDependencies backingCallDependencies)
            {
                backingCallDependencies.SetBackingCallResult(call, backingCallResult);
            }
            if (nativePointerCallResult is not null
                && initialized.Dependencies is BackingDependencies pointerResultDependencies)
            {
                pointerResultDependencies.SetNativePointerCallResult(call,
                    nativePointerCallResult);
            }
            if (referenceCallResult is not null
                && initialized.Dependencies is BackingDependencies
                    referenceCallDependencies)
            {
                referenceCallDependencies.SetReferenceFieldCallResult(call,
                    new Dictionary<StorageProjection, ReferenceFieldValue> {
                        [StorageProjection.WholeObject] = referenceCallResult,
                    });
            }
            foreach (var output in outTargets)
            {
                if (target.ReturnType == PrimitiveType.Bool)
                {
                    initialized.MarkConditional(output);
                }
                else
                {
                    initialized[output] = true;
                    var outputType = function.Variables[output].Type;
                    initialized.HavocIntegerVariable(output, outputType);
                    if (HasFields(program, outputType))
                    {
                        fieldMasks[output] = FullMask(program, outputType);
                        initialized.SetPossibleFieldMask(output, fieldMasks[output]);
                    }
                }
                SetNormalBackingFactoryObjectIdentity(
                    call, output, function.Variables[output].Type,
                    initialized, succeeds: true);
            }
            if (CallCanMutateIntegerStorage(call, target, program))
            {
                initialized.HavocIntegerValues();
            }
        }
        finally
        {
            initialized.ReleaseInitializationReferenceTargets(
                initializationReservationTargets);
            if (initialized.Dependencies is BackingDependencies dependencies)
            {
                dependencies.Staged.RemoveRange(stagedDependencyCount, dependencies.Staged.Count - stagedDependencyCount);
            }
        }

        if (target.ReturnType != PrimitiveType.Bool || discardedResult)
        {
            var parameterOffset = target.IsConstructor ? 1 : 0;
            foreach (var (argumentIndex, outputTargets)
                in initializationOutputTargets)
            {
                var parameterSlot = call.ParameterIndex(argumentIndex)
                    + parameterOffset;
                if (HasExplicitInitializationOutputPostcondition(target,
                        parameterSlot, ref remaining, depth + 1))
                {
                    continue;
                }

                ApplyInitializationReferenceOutputTargets(outputTargets,
                    initialized, fieldMasks,
                    initialized.Dependencies
                        as BackingDependencies
                        ?? throw InvalidEffect(
                            call.Arguments[argumentIndex].Span,
                            "CheckedReference"),
                    call.Arguments[argumentIndex].Span,
                    maybeInitialized:
                        target.ReturnType == PrimitiveType.Bool);
            }
        }
        if (discardedResult)
        {
            if (initialized.Dependencies
                is BackingDependencies discardedResultDependencies)
            {
                discardedResultDependencies.ClearCallResultCaches(call);
            }
            initialized.ClearInitializationPostconditionCallResult(call);
        }

        initialized.ClearConditionalInitializedTargets();
        return true;
    }

    private static bool CallCanMutateIntegerStorage(BoundCall call,
        BoundFunction target, BoundProgram program)
    {
        if (target.IsExternal || target.DirectNativeImport is not null
            || target.NativeVTableMethod is not null
            || target.Variables.Take(target.ParameterCount).Any(
                static variable => variable.IsOut || variable.IsInit
                    || variable.IsImplicitRef))
        {
            return true;
        }
        foreach (var argument in call.Arguments)
        {
            if (CheckedReferenceTypeContract.IsValidType(argument.Type,
                    program.CheckedReferenceTypes)
                || NativePointerTypeContract.IsValidType(argument.Type,
                    program.NativePointerTypes)
                || argument is BoundNativeStorageAddress
                    or BoundNativePointerAddress)
            {
                return true;
            }
        }
        return false;
    }

    private static bool IsValidStaticInitializationTables(
        BoundProgram program)
    {
        var fields = program.StaticFields;
        var groups = program.StaticInitializationGroups;
        if (fields.IsDefault || groups.IsDefault)
        {
            return false;
        }

        var groupByField = new int[fields.Length];
        Array.Fill(groupByField, -1);
        var usedConstructors = new HashSet<int>();
        var usedInitializerFunctions = new HashSet<int>();
        var usedBackingPropertyGetters = new HashSet<int>();
        for (var groupIndex = 0; groupIndex < groups.Length;
            groupIndex++)
        {
            var group = groups[groupIndex];
            if (group is null || group.Owner is null
                || !IsValidStaticOwner(group.Owner, group.OwnerType, program)
                || group.StaticFieldIndexes.IsDefault
                || group.EagerInitializerFunctionIndexes.IsDefault
                || group.StaticConstructorFunctionIndex < -1
                || group.StaticConstructorFunctionIndex
                    >= program.Functions.Length
                || group.Trigger is not (
                    BoundStaticInitializationTrigger.GroupedStaticFieldAccess
                        or BoundStaticInitializationTrigger.RuntimeStaticMemberAccess))
            {
                return false;
            }

            for (var previousIndex = 0; previousIndex < groupIndex;
                previousIndex++)
            {
                var previous = groups[previousIndex];
                if (previous.OwnerType == group.OwnerType
                    && StaticOwnersEqual(previous.Owner, group.Owner))
                {
                    return false;
                }
            }

            var fieldNames = new HashSet<string>(StringComparer.Ordinal);
            var backingPropertyNames = new HashSet<string>(
                StringComparer.Ordinal);
            var expectedInitializers = ImmutableArray.CreateBuilder<int>();
            var previousSourceInput = -1;
            var previousSourceOffset = -1;
            for (var ordinal = 0;
                ordinal < group.StaticFieldIndexes.Length; ordinal++)
            {
                var fieldIndex = group.StaticFieldIndexes[ordinal];
                if ((uint)fieldIndex >= (uint)fields.Length
                    || groupByField[fieldIndex] != -1)
                {
                    return false;
                }

                var field = fields[fieldIndex];
                if (field is null || field.Owner is null
                    || !IsValidStaticOwner(field.Owner, field.OwnerType,
                        program)
                    || !StaticOwnersEqual(field.Owner, group.Owner)
                    || field.OwnerType != group.OwnerType
                    || field.EagerGroupIndex != groupIndex
                    || string.IsNullOrWhiteSpace(field.Name)
                    || !fieldNames.Add(field.Name)
                    || field.DeclarationOrdinal != (uint)ordinal
                    || field.SourceInputOrdinal < previousSourceInput
                    || (field.SourceInputOrdinal == previousSourceInput
                        && field.SourceOffset <= previousSourceOffset)
                    || field.SourceInputOrdinal < 0
                    || field.SourceInputOrdinal >= program.SourceInputCount
                    || field.SourceOffset < 0
                    || field.SourceOffset != field.Span.Start
                    || (field.IsPrivate && field.IsInternal)
                    || (field.IsFile
                        && (field.IsPrivate || field.IsInternal))
                    || field.FriendTargets.IsDefault
                    || (!field.FriendTargets.IsEmpty
                        && (!field.IsPrivate || field.IsInternal
                            || field.IsFile))
                    || !IsValidStaticFriendTargets(
                        field.FriendTargets, program)
                    || (field.BackingPropertyName is string backingPropertyName
                        ? string.IsNullOrWhiteSpace(backingPropertyName)
                            || field.Name != "$property:"
                                + backingPropertyName
                            || field.IsLazy || field.IsMutable
                            || !backingPropertyNames.Add(
                                backingPropertyName)
                        : field.Name.StartsWith("$property:",
                            StringComparison.Ordinal))
                    || (field.IsLazy
                        && program.LazyInitializationCoreRegistration
                            is null)
                    || !ValidType(field.Type, allowVoid: false, program)
                    || field.InitializerFunctionIndex < -1
                    || field.InitializerFunctionIndex
                        >= program.Functions.Length
                    || (field.InitializerFunctionIndex < 0
                        && (field.IsLazy
                            || group.StaticConstructorFunctionIndex < 0)))
                {
                    return false;
                }

                if (field.BackingPropertyName is string propertyName)
                {
                    var getterIndex = -1;
                    for (var candidateIndex = 0;
                        candidateIndex < program.Functions.Length;
                        candidateIndex++)
                    {
                        var candidate = program.Functions[candidateIndex];
                        if (candidate.PropertyName == propertyName
                            && candidate.DeclaringStruct == group.Owner.Name
                            && candidate.IsStatic)
                        {
                            if (getterIndex >= 0)
                            {
                                return false;
                            }
                            getterIndex = candidateIndex;
                        }
                    }

                    if (getterIndex < 0
                        || !usedBackingPropertyGetters.Add(getterIndex))
                    {
                        return false;
                    }

                    var getter = program.Functions[getterIndex];
                    if (getter.ReturnType != field.Type
                        || getter.ParameterCount != 0
                        || getter.IsPrivate != field.IsPrivate
                        || getter.IsInternal != field.IsInternal
                        || !StaticFriendTargetsEqual(getter.FriendTargets,
                            field.FriendTargets)
                        || getter.Body.Statements.IsDefault
                        || getter.Body.Statements.Length != 1
                        || getter.Body.Statements[0] is not BoundReturn {
                            Value: BoundStaticFieldRead {
                                Field: var backingFieldIndex,
                                Type: var backingFieldType,
                                Authority: BoundStaticFieldAccessAuthority
                                    .EagerGroupCompletion,
                            },
                        }
                        || backingFieldIndex != fieldIndex
                        || backingFieldType != field.Type)
                    {
                        return false;
                    }
                }

                previousSourceInput = field.SourceInputOrdinal;
                previousSourceOffset = field.SourceOffset;
                groupByField[fieldIndex] = groupIndex;
                if (field.InitializerFunctionIndex >= 0)
                {
                    var initializer = program.Functions[
                        field.InitializerFunctionIndex];
                    if (initializer is null
                        || initializer.StaticFieldInitializerIndex
                            != fieldIndex
                        || initializer.SourceInputOrdinal
                            != field.SourceInputOrdinal
                        || initializer.Span != field.Span
                        || initializer.ReturnType != field.Type
                        || initializer.ParameterCount != 0
                        || initializer.IsExternal || !initializer.IsStatic
                        || !initializer.IsPrivate || initializer.IsInternal
                        || initializer.DeclaringStruct != group.Owner.Name
                        || !usedInitializerFunctions.Add(
                            field.InitializerFunctionIndex))
                    {
                        return false;
                    }
                    if (!field.IsLazy)
                    {
                        expectedInitializers.Add(
                            field.InitializerFunctionIndex);
                    }
                }
            }

            if (!group.EagerInitializerFunctionIndexes.SequenceEqual(
                    expectedInitializers))
            {
                return false;
            }

            if (group.StaticConstructorFunctionIndex >= 0)
            {
                var constructor = program.Functions[
                    group.StaticConstructorFunctionIndex];
                if (constructor is null
                    || constructor.StaticConstructorIdentity is not
                        BoundStaticConstructorIdentity identity
                    || identity.OwnerName != group.Owner.Name
                    || program.StaticInitializationCoreRegistration is not
                        StaticInitializationCoreRegistrationSet registration
                    || identity.ModuleIdentity
                        != registration.UsingModuleIdentity
                    || constructor.StaticInitializationTrigger
                        != group.Trigger
                    || !StaticOwnerArgumentsEqual(
                        constructor.StaticConstructorOwnerTypeArguments,
                        group.Owner.TypeArguments)
                    || !usedConstructors.Add(
                        group.StaticConstructorFunctionIndex))
                {
                    return false;
                }
            }
            else if (group.Trigger
                != BoundStaticInitializationTrigger.GroupedStaticFieldAccess)
            {
                return false;
            }
        }

        for (var fieldIndex = 0; fieldIndex < fields.Length; fieldIndex++)
        {
            if (groupByField[fieldIndex] < 0)
            {
                return false;
            }
        }

        for (var functionIndex = 0;
            functionIndex < program.Functions.Length; functionIndex++)
        {
            var function = program.Functions[functionIndex];
            if (function.StaticConstructorIdentity is not null
                && !usedConstructors.Contains(functionIndex))
            {
                return false;
            }
            if (function.StaticFieldInitializerIndex >= 0
                && !usedInitializerFunctions.Contains(functionIndex))
            {
                return false;
            }
        }

        return true;
    }

    private static bool IsValidStaticOwner(BoundStaticOwnerIdentity owner,
        PrimitiveType ownerType, BoundProgram program)
    {
        if (string.IsNullOrWhiteSpace(owner.Name)
            || owner.TypeArguments is null
            || owner.TypeArguments.Any(static argument =>
                string.IsNullOrWhiteSpace(argument.Key))
            || owner.TypeArguments.Any(argument =>
                !ValidType(argument.Value, allowVoid: false, program)))
        {
            return false;
        }

        var isStruct = (int)ownerType >= 100
            && (uint)((int)ownerType - 100)
                < (uint)program.Structures.Length
            && program.Structures[(int)ownerType - 100].Name == owner.Name;
        var isClass = ManagedClassTypes.IsClass(ownerType)
            && (uint)ManagedClassTypes.ClassIndex(ownerType)
                < (uint)program.Classes.Length
            && program.Classes[ManagedClassTypes.ClassIndex(ownerType)].Name
                == owner.Name;
        if (isStruct)
        {
            return IsValidStaticOwnerTypeArguments(owner,
                (int)ownerType - 100, program);
        }
        return isClass && owner.TypeArguments.IsEmpty;
    }

    private static bool IsValidStaticOwnerTypeArguments(
        BoundStaticOwnerIdentity owner, int structureIndex,
        BoundProgram program)
    {
        var structure = program.Structures[structureIndex];
        var definitionIndex = structure.SourceGenericTypeDefinitionIndex;
        if (definitionIndex < 0)
        {
            return owner.TypeArguments.IsEmpty;
        }
        if ((uint)definitionIndex
                >= (uint)program.SourceGenericTypeDefinitions.Length
            || program.SourceGenericTypeInstances.IsDefault)
        {
            return false;
        }

        BoundSourceGenericTypeInstance? instance = null;
        foreach (var candidate in program.SourceGenericTypeInstances)
        {
            if (candidate.StructureIndex != structureIndex)
            {
                continue;
            }
            if (instance is not null)
            {
                return false;
            }
            instance = candidate;
        }
        if (instance is null
            || instance.DefinitionIndex != definitionIndex)
        {
            return false;
        }

        var definition = program.SourceGenericTypeDefinitions[
            definitionIndex];
        var typeFormalOrdinal = 0;
        foreach (var formal in definition.Formals)
        {
            if (formal.Kind != BoundGenericMethodFormalKind.Type)
            {
                continue;
            }
            if (formal.TypeFormalOrdinal != typeFormalOrdinal
                || (uint)typeFormalOrdinal
                    >= (uint)instance.TypeArguments.Length
                || !owner.TypeArguments.TryGetValue(formal.Name,
                    out var actualType)
                || actualType
                    != instance.TypeArguments[typeFormalOrdinal])
            {
                return false;
            }
            typeFormalOrdinal++;
        }

        return typeFormalOrdinal == instance.TypeArguments.Length
            && owner.TypeArguments.Count == typeFormalOrdinal;
    }

    private static bool IsStaticFieldUnsafeAuthorizationValid(
        int fieldIndex, bool isUnsafeAuthorized, bool isUnsafe,
        BoundProgram program)
        => (uint)fieldIndex < (uint)program.StaticFields.Length
            && isUnsafeAuthorized == isUnsafe
            && (!program.StaticFields[fieldIndex].RequiresUnsafeCaller
                || isUnsafe);

    private static bool IsValidOrdinaryParameterDefaults(
        BoundFunction function, BoundProgram program)
    {
        var defaults = function.OrdinaryParameterDefaults;
        if (defaults.IsDefault)
        {
            return false;
        }
        if (!function.HasOrdinaryParameterDefaultSurface)
        {
            return defaults.IsEmpty;
        }

        if (function.SourceDeclarationInputOrdinal < 0
            || function.SourceDeclarationInputOrdinal
                >= program.SourceInputCount
            || function.GenericMethodProofDefinitionOrdinal >= 0
            || function.GenericMethodInstantiation is not null
            || function.ImportedGenericMethod is not null
            || function.Intrinsic != BoundIntrinsic.None)
        {
            return false;
        }

        var receiverCount = function.IsClassConstructor
            || (function.DeclaringStruct is not null
                && !function.IsStatic && !function.IsConstructor) ? 1 : 0;
        var parameterCount = function.ParameterCount - receiverCount;
        if (parameterCount < 0
            || parameterCount
                > function.Variables.Length - receiverCount
            || defaults.Length > parameterCount)
        {
            return false;
        }

        var previousOrdinal = -1;
        foreach (var parameterDefault in defaults)
        {
            if (parameterDefault is null
                || parameterDefault.ParameterOrdinal <= previousOrdinal
                || parameterDefault.ParameterOrdinal >= parameterCount
                || parameterDefault.SourceInputOrdinal < 0
                || parameterDefault.SourceInputOrdinal
                    >= program.SourceInputCount
                || parameterDefault.Span.Start < 0
                || parameterDefault.IsPending
                || (parameterDefault.Value is null)
                    == (parameterDefault.Expression is null))
            {
                return false;
            }

            var variable = function.Variables[
                receiverCount + parameterDefault.ParameterOrdinal];
            if (variable.IsOut || variable.IsInit
                || variable.IsImplicitRef
                || !ValidType(variable.Type, allowVoid: false, program)
                || (parameterDefault.Value is BoundConstant value
                    && (value.Type != variable.Type
                        || !ValidType(value.Type, allowVoid: false,
                            program)))
                || (parameterDefault.Expression is BoundExpression expression
                    && (expression.Type != variable.Type
                        || !ValidType(expression.Type, allowVoid: false,
                            program))))
            {
                return false;
            }

            previousOrdinal = parameterDefault.ParameterOrdinal;
        }

        return BoundTreeTraversal.VisitOrdinaryParameterDefaultExpressions(
            function, static _ => { });
    }

    private static bool IsValidStaticFriendTargets(
        ImmutableArray<BoundFriendTarget> targets,
        BoundProgram program)
    {
        if (targets.IsDefault)
        {
            return false;
        }

        for (var index = 0; index < targets.Length; index++)
        {
            var target = targets[index];
            if (target is null)
            {
                return false;
            }
            if (target.GenericDefinitionIndex < 0)
            {
                if (target.Type == PrimitiveType.Void
                    || !IsLocalFriendType(target.Type, program)
                    || !target.TypeArguments.IsEmpty)
                {
                    return false;
                }
            }
            else if (target.Type != PrimitiveType.Void
                || (uint)target.GenericDefinitionIndex
                    >= (uint)program.SourceGenericTypeDefinitions.Length
                || target.TypeArguments.IsDefault
                || target.TypeArguments.Length
                    != program.SourceGenericTypeDefinitions[
                        target.GenericDefinitionIndex].Formals.Length
                || !target.TypeArguments.Any(
                    static argument => argument is null)
                || target.TypeArguments.Any(argument =>
                    argument is PrimitiveType type
                        && !ValidType(type, allowVoid: false, program)))
            {
                return false;
            }

            for (var previousIndex = 0; previousIndex < index;
                previousIndex++)
            {
                var previous = targets[previousIndex];
                if (previous.GenericDefinitionIndex
                        == target.GenericDefinitionIndex
                    && previous.Type == target.Type
                    && previous.TypeArguments.SequenceEqual(
                        target.TypeArguments))
                {
                    return false;
                }
            }
        }
        return true;
    }

    private static bool StaticFriendTargetsEqual(
        ImmutableArray<BoundFriendTarget> left,
        ImmutableArray<BoundFriendTarget> right)
    {
        if (left.IsDefault || right.IsDefault
            || left.Length != right.Length)
        {
            return false;
        }

        for (var index = 0; index < left.Length; index++)
        {
            if (left[index].Type != right[index].Type
                || left[index].GenericDefinitionIndex
                    != right[index].GenericDefinitionIndex
                || !left[index].TypeArguments.SequenceEqual(
                    right[index].TypeArguments))
            {
                return false;
            }
        }
        return true;
    }

    private static bool IsLocalFriendType(PrimitiveType type,
        BoundProgram program)
        => ((int)type >= 100
                && (uint)((int)type - 100)
                    < (uint)program.Structures.Length)
            || (ManagedClassTypes.IsClass(type)
                && (uint)ManagedClassTypes.ClassIndex(type)
                    < (uint)program.Classes.Length);

    private static bool StaticOwnersEqual(BoundStaticOwnerIdentity left,
        BoundStaticOwnerIdentity right)
        => StringComparer.Ordinal.Equals(left.Name, right.Name)
            && StaticOwnerArgumentsEqual(left.TypeArguments,
                right.TypeArguments);

    private static bool StaticOwnerArgumentsEqual(
        ImmutableDictionary<string, PrimitiveType> left,
        ImmutableDictionary<string, PrimitiveType> right)
        => left is not null && right is not null
            && left.Count == right.Count
            && left.All(pair => right.TryGetValue(pair.Key,
                out var type) && type == pair.Value);

    private static bool IsValidDeclarationContractClauses(
        BoundFunction function, BoundProgram program)
    {
        var clauses = function.DeclarationContractClauses;
        if (clauses.IsDefault)
        {
            return false;
        }
        if (!BoundTreeTraversal.VisitContractExpressions(function,
            static _ => { }))
        {
            return false;
        }
        var bodyContainsReturnValue = false;
        if (!BoundTreeTraversal.VisitExpressions(function.Body,
                expression => bodyContainsReturnValue
                    |= expression is BoundContractReturnValue)
            || bodyContainsReturnValue)
        {
            return false;
        }

        var preconditionOrdinal = 0u;
        var postconditionOrdinal = 0u;
        var hasPostcondition = false;
        foreach (var clause in clauses)
        {
            if (clause is null || clause.Predicate is null
                || clause.Predicate.Type != PrimitiveType.Bool
                || (clause.ExplicitFailureType is PrimitiveType failureType
                    && (!ValidType(failureType, allowVoid: false, program)
                        || !ManagedClassTypes.IsClass(failureType)
                        || ManagedClassTypes.IsOptional(failureType)
                        || ManagedClassTypes.IsWritable(failureType))))
            {
                return false;
            }
            var invalidReturnValue = false;
            var invalidStaticFieldRead = false;
            if (!BoundTreeTraversal.VisitExpressionTree(clause.Predicate,
                    expression => {
                        if (expression is BoundContractReturnValue result
                            && (clause.Phase
                                    != BoundDeclarationContractPhase.NormalPostcondition
                                || result.Type != function.ReturnType
                                || result.Type == PrimitiveType.Void))
                        {
                            invalidReturnValue = true;
                        }
                        if (expression is BoundStaticFieldRead staticFieldRead
                            && ((uint)staticFieldRead.Field
                                    >= (uint)program.StaticFields.Length
                                || staticFieldRead.Type
                                    != program.StaticFields[
                                        staticFieldRead.Field].Type
                                || !CanAccessStaticField(function,
                                    program.StaticFields[staticFieldRead.Field],
                                    program)
                                || (program.StaticFields[
                                        staticFieldRead.Field]
                                        .RequiresUnsafeCaller
                                    && !staticFieldRead.IsUnsafeAuthorized)
                                || !IsStaticFieldReadAuthorized(
                                    staticFieldRead, function, program)))
                        {
                            invalidStaticFieldRead = true;
                        }
                        if (expression is BoundStaticFieldRead preconditionFieldRead
                            && clause.Phase
                                == BoundDeclarationContractPhase.Precondition
                            && function.StaticConstructorIdentity is not null
                            && (uint)preconditionFieldRead.Field
                                < (uint)program.StaticFields.Length
                            && program.StaticFields[
                                preconditionFieldRead.Field]
                                .InitializerFunctionIndex < 0)
                        {
                            invalidStaticFieldRead = true;
                        }
                    })
                || invalidReturnValue || invalidStaticFieldRead)
            {
                return false;
            }

            switch (clause.Phase)
            {
                case BoundDeclarationContractPhase.Precondition:
                    if (hasPostcondition
                        || clause.PhaseLocalOrdinal != preconditionOrdinal++)
                    {
                        return false;
                    }
                    if (clause.ExplicitFailureType is PrimitiveType)
                    {
                        if (clause.SelectedFailureClass is not null)
                        {
                            return false;
                        }
                        continue;
                    }
                    break;
                case BoundDeclarationContractPhase.NormalPostcondition:
                    hasPostcondition = true;
                    if (clause.PhaseLocalOrdinal != postconditionOrdinal++
                        || clause.ExplicitFailureType is not null)
                    {
                        return false;
                    }
                    break;
                default:
                    return false;
            }

            if (clause.SelectedFailureClass is not
                    CoreContractFailureDeclarationIdentity failureIdentity
                || clause.UsingModuleIdentity is not string usingModuleIdentity)
            {
                return false;
            }
            var selection = program.CoreContractFailureIdentitySelections
                .FirstOrDefault(candidate =>
                    candidate.UsingModuleIdentity == usingModuleIdentity);
            if (selection is null
                || (clause.Phase
                        == BoundDeclarationContractPhase.Precondition
                    ? selection.RequirementExceptionClass
                    : selection.PostconditionExceptionClass)
                    != failureIdentity)
            {
                return false;
            }
        }

        return true;
    }

    private static bool IsValidCheckedOutputStatePredicates(
        BoundFunction function, BoundProgram program)
    {
        var predicates = function.CheckedOutputStatePredicates;
        if (predicates.IsDefault)
        {
            return false;
        }
        if (predicates.IsEmpty)
        {
            return true;
        }
        if (function.DirectNativeImport is not null
            || function.NativeVTableMethod is not null)
        {
            return false;
        }

        var expressionsByOrdinal = new Dictionary<uint, BoundExpression>();
        foreach (var predicate in predicates)
        {
            if (predicate is null || predicate.FormalOrdinal < 0
                || predicate.FormalOrdinal >= function.ParameterCount
                || predicate.State is not (0 or 1)
                || predicate.Predicate is null
                || predicate.Predicate.Type != PrimitiveType.Bool
                || !BoundTreeTraversal.VisitExpressionTree(
                    predicate.Predicate, static _ => { }))
            {
                return false;
            }

            var formal = function.Variables[predicate.FormalOrdinal];
            if (!formal.IsInit || formal.IsOut
                || !CheckedReferenceTypes.IsType(formal.Type))
            {
                return false;
            }

            var referenceTypeIndex
                = CheckedReferenceTypes.Index(formal.Type);
            if ((uint)referenceTypeIndex
                >= (uint)program.CheckedReferenceTypes.Length
                || !CheckedReferenceTypeContract.IsValidCompleteType(
                    formal.Type, program.CheckedReferenceTypes))
            {
                return false;
            }

            var referenceType
                = program.CheckedReferenceTypes[referenceTypeIndex];
            if (!referenceType.IsInitialization
                || referenceType.IsOptional
                || referenceType.IsGarbageCollected)
            {
                return false;
            }

            if (expressionsByOrdinal.TryGetValue(
                    predicate.PhaseLocalOrdinal, out var expression))
            {
                if (!Equals(expression, predicate.Predicate))
                {
                    return false;
                }
            }
            else
            {
                expressionsByOrdinal.Add(predicate.PhaseLocalOrdinal,
                    predicate.Predicate);
            }
        }

        var expectedOrdinal = checked((uint)(
            function.CheckedOutputSelectors.IsDefault
                ? 0 : function.CheckedOutputSelectors.Length));
        if (expectedOrdinal == 0
            && !function.HasPrivateCheckedOutputStateMetadata
            && !function.HasStandardCheckedOutputStateMetadata
            && function.ReturnType == PrimitiveType.Bool
            && function.Variables.Take(function.ParameterCount).Any(
                variable => variable.IsInit && !variable.IsOut
                    && CheckedReferenceTypes.IsType(variable.Type)))
        {
            expectedOrdinal = 2;
        }

        foreach (var ordinal in expressionsByOrdinal.Keys.Order())
        {
            if (ordinal != expectedOrdinal++)
            {
                return false;
            }
        }

        return true;
    }

    private static void VerifyOperatorFunction(BoundFunction function, BoundProgram program)
    {
        if (!function.IsStatic || function.IsConstructor || function.IsClassConstructor
            || function.IsCleanup || function.PropertyName is not null || function.Intrinsic != BoundIntrinsic.None
            || function.DeclaringStruct is not string owner
            || !Binder.TryGetStaticOperatorKey(function.Name, owner, out var key)
            || function.ParameterCount != key.Arity || function.Variables.Length < key.Arity
            || !ValidType(function.ReturnType, allowVoid: false, program))
        {
            throw Invalid();
        }
        var ownerIndex = -1;
        for (var index = 0; index < program.Structures.Length; index++)
        {
            if (program.Structures[index].Name == owner)
            {
                ownerIndex = index;
                break;
            }
        }
        if (ownerIndex < 0)
        {
            throw Invalid();
        }
        var ownerType = (PrimitiveType)(100 + ownerIndex);
        for (var index = 0; index < key.Arity; index++)
        {
            var parameter = function.Variables[index];
            if (parameter.Type != ownerType || parameter.IsMutable || parameter.IsOut || parameter.IsInit)
            {
                throw Invalid();
            }
        }
        if (key.Operator is TokenKind.PlusPlus or TokenKind.MinusMinus
            && function.ReturnType != ownerType)
        {
            throw Invalid();
        }
        if (key.Arity == 2)
        {
            var expectedResult = Binder.IsComparisonOperator(key.Operator) ? PrimitiveType.Bool : ownerType;
            if (function.ReturnType != expectedResult)
            {
                throw Invalid();
            }
        }
    }

    private static bool IsNativeUtfZPointer(PrimitiveType type) =>
        type is PrimitiveType.NativeUtf16ZPointer or PrimitiveType.NativeUtf8ZPointer;

    private static bool HasValidNativeStringArgument(BoundExpression argument, PrimitiveType parameterType,
        int parameterIndex, BoundFunction target, BoundProgram program) =>
        argument is BoundConstant { Type: var literalType }
        && literalType == parameterType
        && DirectNativeImportContract.ParameterForParameter(target, parameterIndex)
            is DirectNativeParameter parameter
        && DirectNativeImportContract.IsStringPointerArgument(argument, parameter, program);

    private static bool IsImplicitReferenceScalarType(PrimitiveType type) =>
        type is PrimitiveType.Bool or PrimitiveType.Char8 or PrimitiveType.Char16
            or PrimitiveType.Char32 or PrimitiveType.Rune
            or PrimitiveType.Int8 or PrimitiveType.Int16 or PrimitiveType.Int32
            or PrimitiveType.Int64 or PrimitiveType.UInt8
            or PrimitiveType.UInt16 or PrimitiveType.UInt32
            or PrimitiveType.UInt64 or PrimitiveType.NativeInt
            or PrimitiveType.NativeUInt or PrimitiveType.Float32
            or PrimitiveType.Float64;

    private static bool IsImplicitReferenceType(PrimitiveType type, BoundProgram program) =>
        CheckedReferenceTypeContract.IsImplicitReferenceValueType(
            type, program.Structures, program.CheckedReferenceTypes);

    private static bool IsPrivateImplicitReferenceArgument(
        PrimitiveType argumentType, BoundVariable formal,
        BoundProgram program)
    {
        if (!CheckedReferenceTypeContract.IsValidType(
                argumentType, program.CheckedReferenceTypes))
        {
            return false;
        }

        var reference = program.CheckedReferenceTypes[
            CheckedReferenceTypes.Index(argumentType)];
        if (formal.IsCanonicalImplicitReference)
        {
            return argumentType == formal.Type
                && CheckedReferenceTypeContract.IsCanonicalImplicitReferenceType(
                    formal.Type, program.Structures,
                    program.CheckedReferenceTypes);
        }
        return !reference.IsOptional && !reference.IsGarbageCollected
            && !reference.IsInitialization
            && reference.ReferentType == formal.Type
            && (!formal.IsMutable || reference.IsWritable);
    }

    private static PrimitiveType ImplicitReferenceValueType(
        BoundVariable formal, BoundProgram program)
    {
        if (!formal.IsCanonicalImplicitReference)
        {
            return formal.Type;
        }
        if (!CheckedReferenceTypeContract.IsCanonicalImplicitReferenceType(
                formal.Type, program.Structures,
                program.CheckedReferenceTypes))
        {
            throw InvalidEffect(default, "CheckedReference");
        }
        return program.CheckedReferenceTypes[
            CheckedReferenceTypes.Index(formal.Type)].ReferentType;
    }

    private static bool IsSupportedImplicitReferencePlace(
        BoundExpression argument,
        BoundFunction function,
        BoundProgram program) =>
        argument switch
        {
            BoundRead read => (uint)read.Variable < (uint)function.Variables.Length
                && function.Variables[read.Variable].Type == read.Type
                && IsImplicitReferenceType(read.Type, program),
            BoundFieldRead field => IsSupportedImplicitReferenceFieldPlace(field, function, program),
            BoundBufferRead buffer => (uint)buffer.Buffer < (uint)program.Buffers.Length
                && program.Buffers[buffer.Buffer].ElementType == buffer.Type
                && IsImplicitReferenceType(buffer.Type, program),
            BoundViewRead view => (uint)view.Variable < (uint)function.Variables.Length
                && function.Variables[view.Variable].Type is PrimitiveType.ReadonlyInt32BufferView
                    or PrimitiveType.MutableInt32BufferView
                && IsImplicitReferenceType(view.Type, program),
            _ => false,
        };

    private static bool IsSupportedImplicitReferenceFieldPlace(
        BoundFieldRead field,
        BoundFunction function,
        BoundProgram program)
    {
        if (!IsImplicitReferenceType(field.Type, program)
            || !IsCopyStruct(program, field.Receiver.Type))
        {
            return false;
        }
        return field.Receiver switch
        {
            BoundRead read => (uint)read.Variable < (uint)function.Variables.Length
                && function.Variables[read.Variable].Type == read.Type
                && IsCopyStruct(program, read.Type),
            BoundFieldRead parent => IsSupportedImplicitReferenceFieldPlace(parent, function, program),
            _ => false,
        };
    }

    private static void VerifyIndirectCall(BoundIndirectCall call, BoundFunction caller, BoundProgram program)
    {
        if (!call.IsUnsafeAuthorized || call.Arguments.IsDefault
            || call.Arguments.Length > MaximumArguments
            || !NativeFunctionPointerTypes.IsType(call.Target.Type)
            || !NativeFunctionPointerContract.IsValidType(
                call.Target.Type, program.NativeFunctionPointerSignatures))
        {
            throw InvalidEffect(call.Span, "UnsafeCaller");
        }

        var signature = program.NativeFunctionPointerSignatures[NativeFunctionPointerTypes.Index(call.Target.Type)];
        var outputSelectorOrdinals = signature.OutputStates
            .Select(static outputState => outputState.SelectorOrdinal).ToHashSet();
        if (signature.Selectors.Any(selector =>
                !outputSelectorOrdinals.Contains(selector.PhaseLocalOrdinal))
            || signature.Dependencies.Any(static dependency =>
                dependency.DestinationKind != 2))
        {
            throw InvalidEffect(call.Span, "NativeImport");
        }
        if (call.Type != signature.ReturnType || call.Arguments.Length != signature.ParameterTypes.Length)
        {
            throw Invalid();
        }
        for (var index = 0; index < call.Arguments.Length; index++)
        {
            var argument = call.Arguments[index] ?? throw Invalid();
            var isNativeOutput = signature.OutputStates.Any(outputState =>
                outputState.FormalOrdinal == (uint)index);
            if (isNativeOutput)
            {
                if (!NativeFunctionPointerContract.TryGetNativeOutputContract(
                        signature, index, program.NativePointerTypes, out var output)
                    || output is null
                    || argument is not BoundNativeOutputReservation reservation
                    || !MatchesReservation(reservation, output, caller, program))
                {
                    throw InvalidEffect(call.Span, "NativeImport");
                }
                continue;
            }

            var nativeParameter = signature.NativeParameters.FirstOrDefault(
                parameter => parameter.ParameterIndex == index);
            var validNativeParameterArgument = nativeParameter is not null
                && (argument is BoundNativeStorageAddress address
                    ? DirectNativeImportContract.MatchesAddress(
                        address, nativeParameter, caller, program)
                    : DirectNativeImportContract.MatchesNativeParameterArgumentType(
                        argument.Type, signature.ParameterTypes[index], nativeParameter,
                        program.NativePointerTypes,
                        DirectNativeImportContract.IsNullNativePointerValue(argument))
                        || DirectNativeImportContract.IsStringPointerArgument(
                            argument, nativeParameter, program));
            if ((nativeParameter is null
                    ? argument.Type != signature.ParameterTypes[index]
                    : !validNativeParameterArgument)
                || IsUnique(program, argument.Type))
            {
                throw InvalidEffect(call.Span, "NativeImport");
            }
        }
    }

    private static bool IsSupportedOptionalType(
        PrimitiveType type,
        BoundProgram program) =>
        SourceOptionalTypes.IsSupported(type, program.CheckedReferenceTypes,
            program.Structures, program.Classes, program.EnumDefinitions.Length,
            program.NativeLoweringAgreement, program.NativeFixedArrayTypes);

    private static bool TryGetOptionalPayloadType(
        PrimitiveType type,
        BoundProgram program,
        out PrimitiveType payloadType)
    {
        if (IsSupportedOptionalType(type, program))
        {
            return SourceOptionalTypes.TryGetRequired(
                type, program.CheckedReferenceTypes, out payloadType);
        }
        payloadType = default;
        return false;
    }

    private static void SetOptionalReferencePatternFacts(
        BoundExpression value,
        int variable,
        InitializationState initialized,
        uint[] fieldMasks,
        BoundFunction function,
        BoundProgram program,
        ref int remaining)
    {
        if (!CheckedReferenceTypeContract.IsValidType(
                value.Type, program.CheckedReferenceTypes)
            || !program.CheckedReferenceTypes[
                CheckedReferenceTypes.Index(value.Type)].IsOptional)
        {
            return;
        }
        if (initialized.Dependencies is not BackingDependencies facts)
        {
            throw InvalidEffect(value.Span, "CheckedReference");
        }

        var targets = ReferenceTargetsOfExpression(value, facts, initialized,
            function, program, ref remaining, 0, fieldMasks);
        var obligations = ReferenceObligationsOfExpression(value, facts,
            initialized, function, program, ref remaining, 0, fieldMasks);
        var referenceValue = ReferenceFieldValueOfDescriptorExpression(value,
            facts, initialized, function, program, ref remaining, 0, fieldMasks);
        if (!referenceValue.IsAvailable)
        {
            throw InvalidEffect(value.Span, "CheckedReference");
        }
        facts.SetReferenceTargets(variable, targets);
        facts.SetReferenceObligations(variable, obligations);
        facts.SetReferenceBackingSources(variable, referenceValue.BackingSources);
    }

    private static void CopyOptionalReferencePatternFacts(
        BoundExpression condition,
        InitializationState source,
        InitializationState destination,
        BoundProgram program)
    {
        if (source.Dependencies is not BackingDependencies sourceFacts
            || destination.Dependencies is not BackingDependencies destinationFacts)
        {
            return;
        }

        var pending = new Stack<BoundExpression>();
        pending.Push(condition);
        var remaining = MaximumAnalysisVisits;
        while (pending.TryPop(out var expression))
        {
            if (--remaining < 0 || !expression.HasValidNestedExpressions)
            {
                throw InvalidEffect(condition.Span, "CheckedReference");
            }

            var value = expression switch {
                BoundIsSome pattern => pattern.Value,
                BoundIsVariablePattern pattern => pattern.Value,
                _ => null,
            };
            var variable = expression switch {
                BoundIsSome pattern => pattern.Variable,
                BoundIsVariablePattern pattern => pattern.Variable,
                _ => -1,
            };
            if (value is not null && (uint)variable < (uint)destination.Length
                && destination[variable]
                && CheckedReferenceTypeContract.IsValidType(
                    value.Type, program.CheckedReferenceTypes)
                && program.CheckedReferenceTypes[
                    CheckedReferenceTypes.Index(value.Type)].IsOptional)
            {
                destinationFacts.SetReferenceTargets(
                    variable, sourceFacts.ReferenceTargets[variable]
                        ?? EmptyBackingSources);
                destinationFacts.SetReferenceObligations(
                    variable, sourceFacts.ReferenceObligations[variable]
                        ?? EmptyBackingSources);
                destinationFacts.SetReferenceBackingSources(
                    variable, sourceFacts.ReferenceBackingSources[variable]
                        ?? EmptyBackingSources);
            }

            foreach (var nested in expression.NestedExpressions)
            {
                pending.Push(nested);
            }
        }
    }

    private static bool ValidType(PrimitiveType type, bool allowVoid, BoundProgram program) =>
        type is PrimitiveType.Char8 or PrimitiveType.Char16 or PrimitiveType.Char32 or PrimitiveType.Rune
            or PrimitiveType.Int8 or PrimitiveType.Int16 or PrimitiveType.Int32 or PrimitiveType.UInt8
            or PrimitiveType.UInt16 or PrimitiveType.UInt32 or PrimitiveType.Int64 or PrimitiveType.UInt64
            or PrimitiveType.NativeInt or PrimitiveType.NativeUInt
            or PrimitiveType.Int128 or PrimitiveType.UInt128 or PrimitiveType.Float16 or PrimitiveType.BFloat16
            or PrimitiveType.Float32 or PrimitiveType.Float64 or PrimitiveType.Float128
            or PrimitiveType.Decimal32 or PrimitiveType.Decimal64 or PrimitiveType.Decimal128
            or PrimitiveType.Bool or PrimitiveType.OwnedInt32Buffer or PrimitiveType.TokenSpan
            or PrimitiveType.ManagedNode or PrimitiveType.OptionalManagedNode or PrimitiveType.NativeUtf16ZPointer
            or PrimitiveType.NativeUtf8ZPointer
            or PrimitiveType.NativeStorageAddress
            or PrimitiveType.NativeRawPointer
            || BoundSpanTypeTypes.IsValidType(type, program.SpanTypes)
            || NativeFixedArrayContract.IsCarrier(type)
            || (allowVoid && type == PrimitiveType.Void)
            || ((int)type >= 100 && (int)type - 100 < program.Structures.Length)
            || BoundEnumTypes.IsValidType(type, program.EnumDefinitions)
            || NativePointerTypeContract.IsValidType(type, program.NativePointerTypes)
            || NativeFunctionPointerContract.IsValidType(type, program.NativeFunctionPointerSignatures)
            || BoundGenericNominalTypeContract.IsValidType(type, program)
            || CheckedReferenceTypeContract.IsValidCompleteType(type,
                program.CheckedReferenceTypes)
            || (ManagedClassTypes.IsManaged(type) && (ManagedClassTypes.Readonly(type) is
                PrimitiveType.ManagedNode or PrimitiveType.OptionalManagedNode))
            || ((ManagedClassTypes.IsClass(type) || (ManagedClassTypes.IsOptional(type)
                && type is not (PrimitiveType.OptionalManagedNode or PrimitiveType.OptionalWriteManagedNode)))
                && ManagedClassTypes.ClassIndex(type) < program.Classes.Length
                && (!ManagedClassTypes.IsWritable(type)
                    || program.Classes[ManagedClassTypes.ClassIndex(type)].IsMutable));

    internal static bool IsValidType(PrimitiveType type, bool allowVoid, BoundProgram program) =>
        ValidType(type, allowVoid, program);

    private static bool IsValidSourceGenericTypeTables(BoundProgram program)
    {
        var definitions = program.SourceGenericTypeDefinitions;
        var instances = program.SourceGenericTypeInstances;
        if (definitions.IsDefault || definitions.Length > MaximumAnalysisVisits
            || instances.IsDefault || instances.Length > MaximumAnalysisVisits)
        {
            return false;
        }

        var definitionNames = new HashSet<string>(StringComparer.Ordinal);
        long rowCount = 0;
        for (var definitionIndex = 0; definitionIndex < definitions.Length;
            definitionIndex++)
        {
            var definition = definitions[definitionIndex];
            if (definition is null || definition.DefinitionIndex != definitionIndex
                || definition.Namespace is null || definition.Name is null
                || definition.QualifiedName is null
                || string.IsNullOrWhiteSpace(definition.Name)
                || (definition.Namespace.Length > 0
                    && string.IsNullOrWhiteSpace(definition.Namespace))
                || definition.Formals.IsDefaultOrEmpty
                || definition.Formals.Length > MaximumAnalysisVisits
                || definition.QualifiedName != (definition.Namespace.Length == 0
                    ? definition.Name
                    : definition.Namespace + "." + definition.Name)
                || (definition.TransparentConstantCarrierType
                    is PrimitiveType constantCarrier
                    && (definition.IsUnique
                        || (!PrimitiveTypeFacts.IsIntegerOrWide(
                                constantCarrier)
                            && constantCarrier != PrimitiveType.Bool)))
                || definition.FormalOrder.IsDefault
                || definition.FormalOrder.Length
                    != definition.Formals.Length
                || definition.ConstantFormals.IsDefault
                || !definitionNames.Add(definition.QualifiedName))
            {
                return false;
            }

            var formalNames = new HashSet<string>(StringComparer.Ordinal);
            var typeFormals = ImmutableArray.CreateBuilder<
                BoundGenericMethodFormal>();
            var typeFormalOrdinal = 0;
            var constantFormalOrdinal = 0;
            rowCount += definition.Formals.Length;
            if (rowCount > MaximumAnalysisVisits)
            {
                return false;
            }
            for (var ordinal = 0; ordinal < definition.Formals.Length; ordinal++)
            {
                var formal = definition.Formals[ordinal];
                var formalSlot = definition.FormalOrder[ordinal];
                if (formal is null || formal.Ordinal != ordinal
                    || string.IsNullOrWhiteSpace(formal.Name)
                    || !formalNames.Add(formal.Name)
                    || formalSlot.Ordinal != ordinal
                    || formalSlot.Kind != formal.Kind
                    || formalSlot.TypeFormalOrdinal
                        != formal.TypeFormalOrdinal
                    || formalSlot.ConstantFormalOrdinal
                        != formal.ConstantFormalOrdinal)
                {
                    return false;
                }

                if (formal.Kind == BoundGenericMethodFormalKind.Type)
                {
                    if (formal.TypeFormalOrdinal != typeFormalOrdinal
                        || formal.ConstantFormalOrdinal != -1
                        || formal.OwnershipDomain is < 1 or > 3
                        || formal.NullabilityDomain is < 1 or > 2
                        || formal.ConstantDomain is not null
                        || formal.HasConstantDefault
                        || (formal.HasTypeDefault
                            ? !AreSourceTypeDefaultDependenciesValid(
                                formal.DefaultFormalDependencies,
                                definition.FormalOrder, ordinal)
                                || !AreSourceTypeFormalDependenciesValid(
                                    formal.DefaultTypeFormalDependencies,
                                    definition.FormalOrder, ordinal)
                            : !formal.DefaultFormalDependencies.IsEmpty))
                    {
                        return false;
                    }
                    if (!formal.HasTypeDefault
                        && !formal.DefaultTypeFormalDependencies.IsEmpty)
                    {
                        return false;
                    }

                    typeFormals.Add(new BoundGenericMethodFormal(
                        typeFormalOrdinal, formal.Name, PrimitiveType.Int32,
                        formal.OwnershipDomain,
                        formal.NullabilityDomain, []) {
                        RequiresBlittable = formal.RequiresBlittable,
                    });
                    typeFormalOrdinal++;
                    continue;
                }

                if (formal.Kind != BoundGenericMethodFormalKind.Constant
                    || formal.TypeFormalOrdinal != -1
                    || formal.ConstantFormalOrdinal
                        != constantFormalOrdinal
                    || formal.OwnershipDomain != 0
                    || formal.NullabilityDomain != 0
                    || formal.RequiresBlittable
                    || formal.HasTypeDefault
                    || formal.ConstantDomain is null
                    || (uint)constantFormalOrdinal
                        >= (uint)definition.ConstantFormals.Length)
                {
                    return false;
                }

                var constantFormal
                    = definition.ConstantFormals[constantFormalOrdinal];
                if (constantFormal is null
                    || constantFormal.Ordinal != formal.Ordinal
                    || constantFormal.ConstantOrdinal
                        != constantFormalOrdinal
                    || constantFormal.Name != formal.Name
                    || !Equals(constantFormal.Domain,
                        formal.ConstantDomain)
                    || constantFormal.HasDefault
                        != formal.HasConstantDefault
                    || !constantFormal.DefaultFormalDependencies
                        .SequenceEqual(formal.DefaultFormalDependencies)
                    || !constantFormal.DefaultTypeFormalDependencies
                        .SequenceEqual(
                            formal.DefaultTypeFormalDependencies)
                    || !AreGenericMethodConstantDependenciesValid(
                        constantFormal.DefaultFormalDependencies,
                        definition.FormalOrder, formal.Ordinal)
                    || !AreSourceTypeFormalDependenciesValid(
                        formal.DefaultTypeFormalDependencies,
                        definition.FormalOrder, formal.Ordinal)
                    || (!formal.HasConstantDefault
                        && (!formal.DefaultFormalDependencies.IsEmpty
                            || !formal.DefaultTypeFormalDependencies
                                .IsEmpty)))
                {
                    return false;
                }
                constantFormalOrdinal++;
            }

            if (typeFormalOrdinal + constantFormalOrdinal
                    != definition.Formals.Length
                || constantFormalOrdinal
                    != definition.ConstantFormals.Length)
            {
                return false;
            }
            var precedingConstantFormalCount = 0;
            foreach (var formal in definition.Formals)
            {
                if (formal.Kind == BoundGenericMethodFormalKind.Type)
                {
                    continue;
                }

                var constantFormal = definition.ConstantFormals[
                    precedingConstantFormalCount];
                var precedingConstantFormals =
                    ProjectGenericMethodConstantFormals(
                        [.. definition.ConstantFormals
                            .Take(precedingConstantFormalCount)]);
                if (!IsValidGenericMethodConstantDomain(
                    constantFormal.Domain,
                    typeFormals.ToImmutable(),
                    program, precedingConstantFormals,
                    [.. definition.FormalOrder.Take(formal.Ordinal)],
                    formalOrdinal: -1,
                    definitionOrdinal: definition.DefinitionIndex,
                    formalOwnerKind:
                        BoundGenericTypeFormalOwnerKind.SourceGenericType))
                {
                    return false;
                }
                precedingConstantFormalCount++;
            }
        }

        var mappedStructures = new HashSet<int>();
        foreach (var instance in instances)
        {
            if (instance is null || (uint)instance.StructureIndex
                    >= (uint)program.Structures.Length
                || (uint)instance.DefinitionIndex >= (uint)definitions.Length
                || instance.TypeArguments.IsDefault
                || instance.TypeArguments.Length
                    != definitions[instance.DefinitionIndex].Formals
                        .Count(static formal =>
                            formal.Kind
                                == BoundGenericMethodFormalKind.Type)
                || instance.ConstantArguments.IsDefault
                || instance.ConstantArguments.Length
                    != definitions[instance.DefinitionIndex]
                        .ConstantFormals.Length
                || !mappedStructures.Add(instance.StructureIndex)
                || program.Structures[instance.StructureIndex] is not BoundStruct structure
                || structure.SourceGenericTypeDefinitionIndex
                    != instance.DefinitionIndex)
            {
                return false;
            }
            rowCount += instance.TypeArguments.Length
                + instance.ConstantArguments.Length;
            if (rowCount > MaximumAnalysisVisits)
            {
                return false;
            }
            if (instance.TypeArguments.Any(typeArgument =>
                    !IsValidType(typeArgument, false, program)))
            {
                return false;
            }
            var instanceDefinition = definitions[instance.DefinitionIndex];
            var typeArgumentTerms = ImmutableArray.CreateBuilder<
                BoundGenericMethodTypeTerm>(
                    instance.TypeArguments.Length);
            foreach (var typeArgument in instance.TypeArguments)
            {
                if (!TryGetGenericMethodActualTypeTerm(typeArgument, null,
                    program, 0, out var typeArgumentTerm))
                {
                    return false;
                }
                typeArgumentTerms.Add(typeArgumentTerm);
            }
            var constantArgumentTerms = ImmutableArray.CreateBuilder<
                BoundGenericMethodConstantArgument?>(
                    instance.ConstantArguments.Length);
            foreach (var constantArgument in instance.ConstantArguments)
            {
                constantArgumentTerms.Add(constantArgument);
            }
            var immutableTypeArgumentTerms
                = typeArgumentTerms.MoveToImmutable();
            var immutableConstantArgumentTerms
                = constantArgumentTerms.MoveToImmutable();

            for (var constantOrdinal = 0;
                constantOrdinal < instance.ConstantArguments.Length;
                constantOrdinal++)
            {
                var formal = instanceDefinition.ConstantFormals[
                    constantOrdinal];
                var argument = instance.ConstantArguments[constantOrdinal];
                if (argument is null
                    || argument.Ordinal != formal.Ordinal
                    || argument.ConstantOrdinal != constantOrdinal
                    || !BoundGenericMethodTypeTerms
                        .TrySubstituteSourceGenericTypeFormals(
                        formal.Domain, immutableTypeArgumentTerms,
                        instance.DefinitionIndex,
                        immutableConstantArgumentTerms,
                        out var domain)
                    || !AreGenericMethodTypeTermsEqual(argument.Domain,
                        domain, 0))
                {
                    return false;
                }

                if (argument.Kind
                    == BoundGenericMethodConstantArgumentKind.Value)
                {
                    if (!TryGetGenericMethodConstantValueDomain(domain,
                            null, program, out var domainType,
                            out var carrierType)
                        || argument.DomainType != domainType
                        || argument.CarrierType != carrierType
                        || !argument.Bits.IsCanonicalFor(carrierType)
                        || argument.CallerDefinitionOrdinal != -1
                        || argument.CallerFormalOrdinal != -1
                        || argument.CallerConstantFormalOrdinal != -1
                        || argument.CallerFormalOwnerKind
                            != BoundGenericTypeFormalOwnerKind.GenericMethod)
                    {
                        return false;
                    }
                    continue;
                }

                if (argument.Kind
                        != BoundGenericMethodConstantArgumentKind.Formal
                    || argument.DomainType != PrimitiveType.Void
                    || argument.CarrierType != PrimitiveType.Void
                    || argument.Bits != default
                    || argument.CallerDefinitionOrdinal < 0)
                {
                    return false;
                }

                if (argument.CallerFormalOwnerKind
                    == BoundGenericTypeFormalOwnerKind.SourceGenericType)
                {
                    if (argument.CallerFormalOrdinal != -1
                        || (uint)argument.CallerDefinitionOrdinal
                            >= (uint)program.SourceGenericTypeDefinitions
                                .Length)
                    {
                        return false;
                    }

                    var callerDefinition =
                        program.SourceGenericTypeDefinitions[
                            argument.CallerDefinitionOrdinal];
                    var callerFormal = callerDefinition.ConstantFormals
                        .FirstOrDefault(candidate =>
                            candidate.ConstantOrdinal
                                == argument.CallerConstantFormalOrdinal);
                    if (callerFormal is null
                        || !AreGenericMethodTypeTermsEqual(
                            callerFormal.Domain, domain, 0))
                    {
                        return false;
                    }
                    continue;
                }

                if (argument.CallerFormalOwnerKind
                        != BoundGenericTypeFormalOwnerKind.GenericMethod
                    || (uint)argument.CallerDefinitionOrdinal
                        >= (uint)program.GenericMethodSignatures.Length
                    || program.Functions.All(function =>
                        function.GenericMethodProofDefinitionOrdinal
                            != argument.CallerDefinitionOrdinal))
                {
                    return false;
                }

                var callerSignature = program.GenericMethodSignatures[
                    argument.CallerDefinitionOrdinal];
                var callerMethodFormal = callerSignature.ConstantFormals
                    .FirstOrDefault(candidate =>
                        candidate.Ordinal == argument.CallerFormalOrdinal);
                if (callerMethodFormal is null
                    || callerMethodFormal.ConstantOrdinal
                        != argument.CallerConstantFormalOrdinal
                    || !AreGenericMethodTypeTermsEqual(
                        callerMethodFormal.Domain, domain, 0))
                {
                    return false;
                }
            }
        }

        for (var structureIndex = 0; structureIndex < program.Structures.Length;
            structureIndex++)
        {
            var structure = program.Structures[structureIndex];
            if (structure is null)
            {
                return false;
            }
            var definitionIndex = structure.SourceGenericTypeDefinitionIndex;
            if (definitionIndex < -1
                || definitionIndex >= definitions.Length
                || (definitionIndex >= 0)
                    != mappedStructures.Contains(structureIndex))
            {
                return false;
            }
        }

        return true;
    }

    private static bool AreSourceTypeDefaultDependenciesValid(
        ImmutableArray<int> dependencies,
        ImmutableArray<BoundGenericMethodFormalSlot> formalOrder,
        int formalOrdinal)
    {
        if (dependencies.IsDefault || formalOrder.IsDefault
            || (uint)formalOrdinal >= (uint)formalOrder.Length)
        {
            return false;
        }

        var previous = -1;
        foreach (var dependency in dependencies)
        {
            if (dependency <= previous || dependency >= formalOrdinal
                || (uint)dependency >= (uint)formalOrder.Length
                || formalOrder[dependency].Kind
                    is not (BoundGenericMethodFormalKind.Type
                        or BoundGenericMethodFormalKind.Constant))
            {
                return false;
            }
            previous = dependency;
        }

        return true;
    }

    private static bool AreSourceTypeFormalDependenciesValid(
        ImmutableArray<int> dependencies,
        ImmutableArray<BoundGenericMethodFormalSlot> formalOrder,
        int formalOrdinal)
    {
        if (dependencies.IsDefault)
        {
            return false;
        }

        var typeFormals = formalOrder
            .Where(static formal =>
                formal.Kind == BoundGenericMethodFormalKind.Type)
            .ToArray();
        var previous = -1;
        foreach (var dependency in dependencies)
        {
            if (dependency <= previous
                || (uint)dependency >= (uint)typeFormals.Length
                || typeFormals[dependency].Ordinal >= formalOrdinal)
            {
                return false;
            }
            previous = dependency;
        }

        return true;
    }

    private static bool IsValidInterfaceWitnesses(BoundProgram program)
    {
        var witnesses = program.InterfaceWitnesses;
        if (witnesses.IsDefault
            || witnesses.Length > MaximumAnalysisVisits)
        {
            return false;
        }

        var remainingVisits = MaximumAnalysisVisits;
        for (var index = 0; index < witnesses.Length; index++)
        {
            var witness = witnesses[index];
            if (--remainingVisits < 0
                || witness is null
                || !IsNominalInterfaceImplementingType(
                    witness.ImplementingType, program)
                || witness.SourceInputOrdinal < 0
                || witness.SourceInputOrdinal >= program.SourceInputCount
                || witness.Members.IsDefault
                || witness.AssociatedTypes.IsDefault
                || witness.AssociatedConstants.IsDefault
                || witness.Members.Length
                    + witness.AssociatedTypes.Length
                    + witness.AssociatedConstants.Length
                    > MaximumAnalysisVisits
                || !BoundInterfaceContract.IsValidClosedInterfaceInstance(
                    witness.InterfaceType, program.Interfaces,
                    type => ValidType(type, false, program),
                    program.GenericNominalTypeDefinitions,
                    program.SourceGenericTypeDefinitions)
                || !BoundInterfaceContract.TryGetRequirementIdentities(
                    witness.InterfaceType, program.Interfaces,
                    type => ValidType(type, false, program),
                    out var requirements,
                    genericNominalTypeDefinitions:
                        program.GenericNominalTypeDefinitions,
                    sourceGenericTypeDefinitions:
                        program.SourceGenericTypeDefinitions))
            {
                return false;
            }

            var memberBindings = new HashSet<
                BoundInterfaceMemberIdentity>(
                    BoundInterfaceContract.MemberIdentityComparer);
            var associatedTypeBindings = new HashSet<
                BoundInterfaceMemberIdentity>(
                    BoundInterfaceContract.MemberIdentityComparer);
            var associatedConstantBindings = new HashSet<
                BoundInterfaceMemberIdentity>(
                    BoundInterfaceContract.MemberIdentityComparer);
            for (var previousIndex = 0; previousIndex < index;
                previousIndex++)
            {
                var previous = witnesses[previousIndex];
                remainingVisits--;
                if (remainingVisits < 0)
                {
                    return false;
                }
                if (previous.ImplementingType == witness.ImplementingType
                    && BoundInterfaceContract.AreEquivalent(
                        previous.InterfaceType, witness.InterfaceType))
                {
                    return false;
                }
            }

            foreach (var member in witness.Members)
            {
                remainingVisits--;
                if (remainingVisits < 0
                    || member is null
                    || !BoundInterfaceContract
                        .IsValidInterfaceMemberIdentity(
                            member.Requirement, program.Interfaces,
                            type => ValidType(type, false, program),
                            genericNominalTypeDefinitions:
                                program.GenericNominalTypeDefinitions,
                            sourceGenericTypeDefinitions:
                                program.SourceGenericTypeDefinitions)
                    || member.TargetKind
                        is not (BoundInterfaceWitnessTargetKind
                                .Implementation
                            or BoundInterfaceWitnessTargetKind
                                .ExplicitImplementation
                            or BoundInterfaceWitnessTargetKind.Default))
                {
                    return false;
                }
                if (!memberBindings.Add(member.Requirement))
                {
                    return false;
                }
                if (member.TargetKind is
                    BoundInterfaceWitnessTargetKind.Implementation
                        or BoundInterfaceWitnessTargetKind
                            .ExplicitImplementation)
                {
                    if (member.DefaultTarget is not null
                        || member.PendingGenericMethodName is not null)
                    {
                        return false;
                    }

                    if (member.GenericMethodDefinitionOrdinal >= 0)
                    {
                        if (member.TargetKind
                                != BoundInterfaceWitnessTargetKind
                                    .Implementation
                            || member.FunctionIndex != -1)
                        {
                            return false;
                        }
                        if (!IsValidGenericInterfaceWitnessImplementation(
                                witness, member, program))
                        {
                            return false;
                        }
                    }
                    else if (member.GenericMethodDefinitionOrdinal != -1
                        || (uint)member.FunctionIndex
                            >= (uint)program.Functions.Length
                        || !IsValidInterfaceWitnessImplementation(
                            witness, member, program))
                    {
                        return false;
                    }
                }
                else if (member.FunctionIndex != -1
                    || member.GenericMethodDefinitionOrdinal != -1
                    || member.PendingGenericMethodName is not null
                    || member.DefaultTarget is not
                        BoundInterfaceMemberIdentity defaultTarget
                    || !BoundInterfaceContract.AreEquivalent(
                        member.Requirement, defaultTarget)
                    || !BoundInterfaceContract
                        .IsValidInterfaceMemberIdentity(defaultTarget,
                            program.Interfaces,
                            type => ValidType(type, false, program),
                            genericNominalTypeDefinitions:
                                program.GenericNominalTypeDefinitions,
                            sourceGenericTypeDefinitions:
                                program.SourceGenericTypeDefinitions)
                    || !BoundInterfaceContract
                        .TryGetInterfaceMemberDefinition(defaultTarget,
                            program.Interfaces,
                            type => ValidType(type, false, program),
                            out var defaultMember,
                            genericNominalTypeDefinitions:
                                program.GenericNominalTypeDefinitions,
                            sourceGenericTypeDefinitions:
                                program.SourceGenericTypeDefinitions)
                    || defaultMember is null
                    || !HasInterfaceDefaultBody(defaultMember,
                        defaultTarget))
                {
                    return false;
                }
            }

            foreach (var binding in witness.AssociatedTypes)
            {
                remainingVisits--;
                if (remainingVisits < 0 || binding is null
                    || !BoundInterfaceContract
                        .IsValidInterfaceMemberIdentity(
                            binding.Requirement, program.Interfaces,
                            type => ValidType(type, false, program),
                            genericNominalTypeDefinitions:
                                program.GenericNominalTypeDefinitions,
                            sourceGenericTypeDefinitions:
                                program.SourceGenericTypeDefinitions)
                    || !BoundInterfaceContract.IsValidClosedType(
                        binding.Type, program.Interfaces,
                        type => ValidType(type, false, program),
                        program.GenericNominalTypeDefinitions,
                        program.SourceGenericTypeDefinitions)
                    || !BoundInterfaceContract
                        .TryGetInterfaceMemberDefinition(
                            binding.Requirement, program.Interfaces,
                            type => ValidType(type, false, program),
                            out var associatedType,
                            genericNominalTypeDefinitions:
                                program.GenericNominalTypeDefinitions)
                    || associatedType?.Kind
                        != BoundInterfaceMemberKind.AssociatedType)
                {
                    return false;
                }
                if (!associatedTypeBindings.Add(binding.Requirement))
                {
                    return false;
                }
            }

            foreach (var binding in witness.AssociatedConstants)
            {
                remainingVisits--;
                if (remainingVisits < 0 || binding is null
                    || !BoundInterfaceContract
                        .IsValidInterfaceMemberIdentity(
                            binding.Requirement, program.Interfaces,
                            type => ValidType(type, false, program),
                            genericNominalTypeDefinitions:
                                program.GenericNominalTypeDefinitions,
                            sourceGenericTypeDefinitions:
                                program.SourceGenericTypeDefinitions)
                    || !BoundInterfaceContract.IsValidClosedType(
                        binding.Type, program.Interfaces,
                        type => ValidType(type, false, program),
                        program.GenericNominalTypeDefinitions,
                        program.SourceGenericTypeDefinitions)
                    || !IsValidType(binding.Value.Type, false, program)
                    || !BoundInterfaceContract
                        .TryGetInterfaceMemberDefinition(
                            binding.Requirement, program.Interfaces,
                            type => ValidType(type, false, program),
                            out var associatedConstant,
                            genericNominalTypeDefinitions:
                                program.GenericNominalTypeDefinitions,
                            sourceGenericTypeDefinitions:
                                program.SourceGenericTypeDefinitions)
                    || associatedConstant?.Kind
                        != BoundInterfaceMemberKind.Constant
                    || associatedConstant.AssociatedConstantType
                        is not BoundInterfaceType declaredConstantType
                    || !TryGetInterfacePrimitiveType(
                        declaredConstantType,
                        binding.Requirement.DeclaringInterface
                            .TypeArguments,
                        program, out var expectedConstantType)
                    || !TryGetInterfacePrimitiveType(binding.Type, [],
                        program, out var boundConstantType)
                    || boundConstantType != expectedConstantType
                    || binding.Value.Type != expectedConstantType
                    || !IsValidInterfaceAssociatedConstantValue(
                        binding.Value, program))
                {
                    return false;
                }
                if (!associatedConstantBindings.Add(binding.Requirement))
                {
                    return false;
                }
            }

            foreach (var requirement in requirements)
            {
                remainingVisits--;
                if (remainingVisits < 0
                    || !BoundInterfaceContract
                        .TryGetInterfaceMemberDefinition(requirement,
                            program.Interfaces,
                            type => ValidType(type, false, program),
                            out var requiredMember)
                    || requiredMember is null
                    || !(requiredMember.Kind switch {
                        BoundInterfaceMemberKind.AssociatedType =>
                            associatedTypeBindings.Remove(requirement),
                        BoundInterfaceMemberKind.Constant =>
                            associatedConstantBindings.Remove(requirement),
                        _ => memberBindings.Remove(requirement),
                    }))
                {
                    return false;
                }
            }

            if (memberBindings.Count != 0
                || associatedTypeBindings.Count != 0
                || associatedConstantBindings.Count != 0)
            {
                return false;
            }
        }
        return true;
    }

    private static bool IsValidInterfaceCallIdentity(BoundCall call,
        BoundFunction caller, BoundFunction target, BoundProgram program)
    {
        if (call.InterfaceCallIdentity
            is not BoundInterfaceCallIdentity identity)
        {
            return target.InterfaceRequirement is null;
        }

        if (call.Arguments.IsEmpty)
        {
            return false;
        }
        if (!InterfaceReceiverTypeMatches(call.Arguments[0].Type,
                identity.ImplementingType))
        {
            return false;
        }
        if (!BoundInterfaceContract.IsValidInterfaceMemberIdentity(
                identity.Requirement, program.Interfaces,
                type => ValidType(type, false, program),
                allowOpenFormals: identity.IsConstraintCall,
                genericNominalTypeDefinitions:
                    program.GenericNominalTypeDefinitions,
                sourceGenericTypeDefinitions:
                    program.SourceGenericTypeDefinitions))
        {
            return false;
        }
        ImmutableArray<BoundInterfaceMemberIdentity> requestedRequirements;
        if (identity.IsConstraintCall)
        {
            if (!BoundInterfaceContract.AreEquivalent(
                    identity.WitnessInterface,
                    identity.RequestedInterface)
                || !BoundInterfaceContract.TryGetRequirementIdentities(
                    identity.RequestedInterface, program.Interfaces,
                    type => ValidType(type, false, program),
                    out requestedRequirements, allowOpenFormals: true,
                    genericNominalTypeDefinitions:
                        program.GenericNominalTypeDefinitions,
                    sourceGenericTypeDefinitions:
                        program.SourceGenericTypeDefinitions))
            {
                return false;
            }
        }
        else if (!BoundInterfaceContract.IsValidClosedInterfaceInstance(
                     identity.RequestedInterface, program.Interfaces,
                     type => ValidType(type, false, program),
                     program.GenericNominalTypeDefinitions,
                     program.SourceGenericTypeDefinitions)
            || !BoundInterfaceContract.IsValidClosedInterfaceInstance(
                identity.WitnessInterface, program.Interfaces,
                type => ValidType(type, false, program),
                program.GenericNominalTypeDefinitions,
                program.SourceGenericTypeDefinitions)
            || !BoundInterfaceContract.TryGetRequirementIdentities(
                identity.RequestedInterface, program.Interfaces,
                type => ValidType(type, false, program),
                out requestedRequirements,
                genericNominalTypeDefinitions:
                    program.GenericNominalTypeDefinitions,
                sourceGenericTypeDefinitions:
                    program.SourceGenericTypeDefinitions))
        {
            return false;
        }
        if (!requestedRequirements.Any(requirement =>
                BoundInterfaceContract.AreEquivalent(
                    requirement, identity.Requirement)))
        {
            return false;
        }

        if (identity.IsConstraintCall)
        {
            if (target.InterfaceRequirement is not
                    BoundInterfaceMemberIdentity targetRequirement
                || !BoundInterfaceContract.AreEquivalent(
                    targetRequirement, identity.Requirement)
                || !BoundInterfaceContract.AreEquivalent(
                    identity.WitnessInterface,
                    identity.RequestedInterface)
                || !target.IsExternal || !target.IsPrivate
                || target.IsStatic || target.DeclaringStruct is not null
                || target.GenericMethodProofCall is not null
                || caller.GenericMethodProofDefinitionOrdinal < 0
                || (uint)caller.GenericMethodProofDefinitionOrdinal
                    >= (uint)program.GenericMethodSignatures.Length
                || caller.GenericMethodProofTypeParameters.Length
                    != program.GenericMethodSignatures[
                        caller.GenericMethodProofDefinitionOrdinal]
                        .Formals.Length)
            {
                return false;
            }

            if (!BoundInterfaceContract.TryGetInterfaceMemberDefinition(
                    identity.Requirement, program.Interfaces,
                    type => ValidType(type, false, program),
                    out var requiredMember, allowOpenFormals: true,
                    genericNominalTypeDefinitions:
                        program.GenericNominalTypeDefinitions,
                    sourceGenericTypeDefinitions:
                        program.SourceGenericTypeDefinitions)
                || requiredMember is null)
            {
                return false;
            }
            var requiredAccessor
                = requiredMember.Kind is (BoundInterfaceMemberKind.Property
                    or BoundInterfaceMemberKind.Indexer)
                    && (uint)identity.Requirement.AccessorOrdinal
                        < (uint)requiredMember.Accessors.Length
                    ? requiredMember.Accessors[
                        identity.Requirement.AccessorOrdinal] : null;
            var isCallable = requiredMember.Kind
                == BoundInterfaceMemberKind.Callable;
            var isPropertyGetter = requiredAccessor?.Kind
                == BoundInterfaceAccessorKind.Get;
            var isIndexerSetter = requiredMember.Kind
                    == BoundInterfaceMemberKind.Indexer
                && requiredAccessor?.Kind
                    == BoundInterfaceAccessorKind.Set;
            var isAccessorCall = isPropertyGetter || isIndexerSetter;
            var receiverRequiresMutable = requiredAccessor?.IsMutable
                ?? requiredMember.RequiresMutableReceiver;
            var requiresUnsafeCaller = requiredAccessor?.RequiresUnsafeCaller
                ?? requiredMember.RequiresUnsafeCaller;
            var doesNotReturn = requiredAccessor?.DoesNotReturn
                ?? requiredMember.DoesNotReturn;
            if ((!isCallable && !isAccessorCall)
                || requiredMember.IsStatic
                || requiredMember.IsAsync
                || requiredMember.NativeCallableConvention is not null
                || !requiredMember.TypeParameters.IsEmpty
                || !requiredMember.Constraints.IsEmpty
                || !requiredMember.Attributes.IsEmpty
                || !requiredMember.ContractTokens.IsEmpty
                || !requiredMember.Dependencies.IsEmpty
                || requiredMember.Parameters.Any(static parameter =>
                    parameter.Mode != BoundInterfaceParameterMode.Value
                    || !parameter.Attributes.IsEmpty
                    || !parameter.AttributeTokens.IsEmpty)
                || (isAccessorCall
                    && (requiredMember.DoesNotReturn
                        || (requiredMember.Kind
                                == BoundInterfaceMemberKind.Property
                            && !requiredMember.Parameters.IsEmpty)
                        || requiredAccessor!.HasBody
                        || !requiredAccessor.Attributes.IsEmpty
                        || !requiredAccessor.AttributeTokens.IsEmpty
                        || !requiredAccessor.ContractTokens.IsEmpty
                        || !requiredAccessor.Dependencies.IsEmpty))
                || requiredMember.ResultType
                    is not BoundInterfaceType requiredResult
                || target.ParameterCount
                    != requiredMember.Parameters.Length + 1
                        + (isIndexerSetter ? 1 : 0)
                || target.Variables.Length != target.ParameterCount
                || target.Variables[0].Type
                    != identity.ImplementingType
                || target.Variables[0].IsMutable
                    != receiverRequiresMutable
                || !TryGetInterfaceProofPrimitiveType(requiredResult,
                    identity.Requirement.DeclaringInterface.TypeArguments,
                    caller, program, out var expectedResult)
                || target.ReturnType != (isIndexerSetter
                    ? PrimitiveType.Void : expectedResult)
                || target.RequiresUnsafeCaller != requiresUnsafeCaller
                || target.DoesNotReturn != doesNotReturn)
            {
                return false;
            }
            for (var ordinal = 0;
                ordinal < requiredMember.Parameters.Length; ordinal++)
            {
                if (!TryGetInterfaceProofPrimitiveType(
                        requiredMember.Parameters[ordinal].Type,
                        identity.Requirement.DeclaringInterface
                            .TypeArguments,
                        caller, program, out var expectedType)
                    || target.Variables[ordinal + 1].Type
                        != expectedType
                    || target.Variables[ordinal + 1].IsMutable)
                {
                    return false;
                }
            }
            if (isIndexerSetter)
            {
                var valueParameter = target.Variables[
                    requiredMember.Parameters.Length + 1];
                if (valueParameter.Type != expectedResult
                    || valueParameter.IsMutable || valueParameter.IsOut
                    || valueParameter.IsImplicitRef
                    || valueParameter.IsCanonicalImplicitReference)
                {
                    return false;
                }
            }

            var receiverFormalOrdinal = -1;
            for (var ordinal = 0;
                ordinal < caller.GenericMethodProofTypeParameters.Length;
                ordinal++)
            {
                if (caller.GenericMethodProofTypeParameters[ordinal]
                    != identity.ImplementingType)
                {
                    continue;
                }
                if (receiverFormalOrdinal >= 0)
                {
                    return false;
                }
                receiverFormalOrdinal = ordinal;
            }

            if (receiverFormalOrdinal < 0)
            {
                return false;
            }

            var receiverFormal = program.GenericMethodSignatures[
                caller.GenericMethodProofDefinitionOrdinal]
                .Formals[receiverFormalOrdinal];
            return (!receiverRequiresMutable
                    || (receiverFormal.RequiresWritable
                        && HasWritableInterfaceCallReceiver(
                            call.Arguments[0],
                            identity.ImplementingType, caller, program)))
                && receiverFormal.InterfaceConstraints.Any(constraint =>
                    BoundInterfaceContract.IsInInheritanceClosure(
                        constraint, identity.RequestedInterface,
                        program.Interfaces));
        }

        if (target.InterfaceRequirement is not null
            || target.IsStatic
            || !IsNominalInterfaceImplementingType(
                identity.ImplementingType, program)
            || !BoundInterfaceContract.IsInInheritanceClosure(
                identity.WitnessInterface, identity.RequestedInterface,
                program.Interfaces))
        {
            return false;
        }

        var witness = program.InterfaceWitnesses.SingleOrDefault(candidate =>
            candidate.ImplementingType == identity.ImplementingType
            && BoundInterfaceContract.AreEquivalent(
                candidate.InterfaceType, identity.WitnessInterface));
        if (witness is null)
        {
            return false;
        }

        var binding = witness.Members.SingleOrDefault(candidate =>
            BoundInterfaceContract.AreEquivalent(
                candidate.Requirement, identity.Requirement));
        var bindingSelectsCallTarget = binding is not null
            && (binding.GenericMethodDefinitionOrdinal >= 0
                ? binding.FunctionIndex == -1
                    && call.GenericMethodCall?.DefinitionOrdinal
                        == binding.GenericMethodDefinitionOrdinal
                    && target.GenericMethodInstantiation?.DefinitionOrdinal
                        == binding.GenericMethodDefinitionOrdinal
                : binding.GenericMethodDefinitionOrdinal == -1
                    && binding.FunctionIndex == call.Function);
        if (binding is null
            || binding.TargetKind is not (
                BoundInterfaceWitnessTargetKind.Implementation
                or BoundInterfaceWitnessTargetKind.ExplicitImplementation)
            || !bindingSelectsCallTarget
            || !BoundInterfaceContract.TryGetInterfaceMemberDefinition(
                identity.Requirement, program.Interfaces,
                type => ValidType(type, false, program),
                out var requirement,
                genericNominalTypeDefinitions:
                    program.GenericNominalTypeDefinitions,
                sourceGenericTypeDefinitions:
                    program.SourceGenericTypeDefinitions)
            || requirement is null || requirement.IsStatic)
        {
            return false;
        }
        var requiresMutableReceiver = requirement.RequiresMutableReceiver;
        if (requirement.Kind is BoundInterfaceMemberKind.Property
                or BoundInterfaceMemberKind.Indexer)
        {
            if ((uint)identity.Requirement.AccessorOrdinal
                >= (uint)requirement.Accessors.Length)
            {
                return false;
            }
            requiresMutableReceiver = requirement.Accessors[
                identity.Requirement.AccessorOrdinal].IsMutable;
        }

        return !requiresMutableReceiver
            || HasWritableInterfaceCallReceiver(call.Arguments[0],
                identity.ImplementingType, caller, program);
    }

    private static bool IsMutableInterfaceCallReceiver(BoundCall call,
        BoundProgram program)
    {
        if (call.InterfaceCallIdentity
            is not BoundInterfaceCallIdentity identity
            || !BoundInterfaceContract.TryGetInterfaceMemberDefinition(
                identity.Requirement, program.Interfaces,
                type => ValidType(type, false, program),
                out var member,
                allowOpenFormals: identity.IsConstraintCall,
                genericNominalTypeDefinitions:
                    program.GenericNominalTypeDefinitions,
                sourceGenericTypeDefinitions:
                    program.SourceGenericTypeDefinitions)
            || member is null)
        {
            return false;
        }

        if (member.Kind is BoundInterfaceMemberKind.Property
            or BoundInterfaceMemberKind.Indexer)
        {
            return (uint)identity.Requirement.AccessorOrdinal
                    < (uint)member.Accessors.Length
                && member.Accessors[
                    identity.Requirement.AccessorOrdinal].IsMutable;
        }

        return member.Kind == BoundInterfaceMemberKind.Callable
            && member.RequiresMutableReceiver;
    }

    private static bool HasInterfaceDefaultBody(
        BoundInterfaceMemberDefinition member,
        BoundInterfaceMemberIdentity identity)
    {
        if (member.Kind is BoundInterfaceMemberKind.Callable
            or BoundInterfaceMemberKind.Operator)
        {
            return member.HasBody;
        }
        return member.Kind is BoundInterfaceMemberKind.Property
                or BoundInterfaceMemberKind.Indexer
            && (uint)identity.AccessorOrdinal
                < (uint)member.Accessors.Length
            && member.Accessors[identity.AccessorOrdinal].HasBody;
    }

    private static bool IsNominalInterfaceImplementingType(
        PrimitiveType type, BoundProgram program)
    {
        if (ManagedClassTypes.IsClass(type))
        {
            return (uint)ManagedClassTypes.ClassIndex(type)
                < (uint)program.Classes.Length;
        }
        var structureIndex = (int)type - 100;
        return structureIndex >= 0
            && (uint)structureIndex < (uint)program.Structures.Length;
    }

    private static bool TryGetInterfaceMethodReceiverMode(
        BoundVariable receiver, PrimitiveType implementingType,
        out bool requiresMutableReceiver)
    {
        requiresMutableReceiver = false;
        if (ManagedClassTypes.IsClass(implementingType))
        {
            if (!ManagedClassTypes.IsClass(receiver.Type)
                || ManagedClassTypes.IsOptional(receiver.Type)
                || ManagedClassTypes.Readonly(receiver.Type)
                    != implementingType
                || receiver.IsMutable)
            {
                return false;
            }

            requiresMutableReceiver
                = ManagedClassTypes.IsWritable(receiver.Type);
            return true;
        }

        if (receiver.Type != implementingType)
        {
            return false;
        }

        requiresMutableReceiver = receiver.IsMutable;
        return true;
    }

    private static bool InterfaceReceiverTypeMatches(
        PrimitiveType receiverType, PrimitiveType implementingType)
    {
        if (ManagedClassTypes.IsClass(implementingType))
        {
            return ManagedClassTypes.IsClass(receiverType)
                && !ManagedClassTypes.IsOptional(receiverType)
                && ManagedClassTypes.Readonly(receiverType)
                    == implementingType;
        }

        return receiverType == implementingType;
    }

    private static bool HasWritableInterfaceCallReceiver(
        BoundExpression receiver, PrimitiveType implementingType,
        BoundFunction caller, BoundProgram program)
    {
        for (var depth = 0;
             receiver is BoundReadonlyProjection projection;
             depth++)
        {
            if (depth >= MaximumDepth)
            {
                return false;
            }
            receiver = projection.Value;
        }
        if (!InterfaceReceiverTypeMatches(receiver.Type,
                implementingType))
        {
            return false;
        }
        if (ManagedClassTypes.IsClass(implementingType))
        {
            if (ManagedClassTypes.IsWritable(receiver.Type))
            {
                return true;
            }
            if (receiver is BoundRead read
                && (uint)read.Variable < (uint)caller.Variables.Length)
            {
                var sourceType = caller.Variables[read.Variable].Type;
                return ManagedClassTypes.IsClass(sourceType)
                    && !ManagedClassTypes.IsOptional(sourceType)
                    && ManagedClassTypes.IsWritable(sourceType)
                    && ManagedClassTypes.Readonly(sourceType)
                        == implementingType;
            }
            return receiver is BoundFieldRead field
                && ManagedClassTypes.IsWritable(field.Type);
        }

        return receiver switch {
            BoundMutableReceiverLoan mutable =>
                IsMutableInterfaceReceiverVariable(mutable.Variable,
                    mutable.Type, implementingType, caller, program),
            BoundReceiverLoan loan =>
                IsMutableInterfaceReceiverVariable(loan.Variable,
                    loan.Type, implementingType, caller, program),
            BoundRead read =>
                IsMutableInterfaceReceiverVariable(read.Variable,
                    read.Type, implementingType, caller, program),
            BoundMutableFieldLoan field =>
                HasWritableInterfaceStructFieldPlace(field.Place,
                    implementingType, caller, program),
            BoundFieldLoan field =>
                HasWritableInterfaceStructFieldPlace(field.Place,
                    implementingType, caller, program),
            BoundFieldRead field =>
                HasWritableInterfaceStructFieldPlace(field,
                    implementingType, caller, program),
            _ => false,
        };
    }

    private static bool IsMutableInterfaceReceiverVariable(int variable,
        PrimitiveType receiverType, PrimitiveType implementingType,
        BoundFunction caller, BoundProgram program) =>
        receiverType == implementingType
            && (uint)variable < (uint)caller.Variables.Length
            && caller.Variables[variable].Type == implementingType
            && (caller.Variables[variable].IsMutable
                || HasGenericWriteRequirement(implementingType, caller,
                    program));

    private static bool HasGenericWriteRequirement(PrimitiveType type,
        BoundFunction caller, BoundProgram program)
    {
        var definitionOrdinal
            = caller.GenericMethodProofDefinitionOrdinal;
        if ((uint)definitionOrdinal
                >= (uint)program.GenericMethodSignatures.Length
            || caller.GenericMethodProofTypeParameters.IsDefault
            || caller.GenericMethodProofTypeParameters.Length
                != program.GenericMethodSignatures[definitionOrdinal]
                    .Formals.Length)
        {
            return false;
        }

        for (var ordinal = 0;
            ordinal < caller.GenericMethodProofTypeParameters.Length;
            ordinal++)
        {
            if (caller.GenericMethodProofTypeParameters[ordinal] == type
                && program.GenericMethodSignatures[definitionOrdinal]
                    .Formals[ordinal].RequiresWritable)
            {
                return true;
            }
        }

        return false;
    }

    private static bool HasWritableInterfaceStructFieldPlace(
        BoundFieldRead place, PrimitiveType expectedType,
        BoundFunction caller, BoundProgram program)
    {
        if (place is null || place.Type != expectedType)
        {
            return false;
        }
        BoundExpression current = place;
        for (var depth = 0; depth < MaximumDepth; depth++)
        {
            if (current is not BoundFieldRead field)
            {
                return current is BoundRead root
                    && (uint)root.Variable < (uint)caller.Variables.Length
                    && root.Type == caller.Variables[root.Variable].Type
                    && caller.Variables[root.Variable].IsMutable;
            }
            if (field.Receiver is null
                || !HasFields(program, field.Receiver.Type)
                || ManagedClassTypes.IsClass(field.Receiver.Type))
            {
                return false;
            }
            var owner = (int)field.Receiver.Type - 100;
            if ((uint)owner >= (uint)program.Structures.Length
                || (uint)field.Field
                    >= (uint)program.Structures[owner].Fields.Length)
            {
                return false;
            }
            var declaration = program.Structures[owner].Fields[field.Field];
            if (!declaration.IsMutable || declaration.Type != field.Type)
            {
                return false;
            }
            current = field.Receiver;
        }
        return false;
    }

    private static bool IsValidGenericInterfaceWitnessImplementation(
        BoundInterfaceWitness witness,
        BoundInterfaceWitnessMember binding,
        BoundProgram program)
    {
        var definitionOrdinal
            = binding.GenericMethodDefinitionOrdinal;
        if ((uint)definitionOrdinal
                >= (uint)program.GenericMethodDefinitions.Length
            || (uint)definitionOrdinal
                >= (uint)program.GenericMethodSignatures.Length
            || !BoundInterfaceContract.TryGetInterfaceMemberDefinition(
                binding.Requirement, program.Interfaces,
                type => ValidType(type, false, program),
                out var requirement,
                genericNominalTypeDefinitions:
                    program.GenericNominalTypeDefinitions,
                sourceGenericTypeDefinitions:
                    program.SourceGenericTypeDefinitions)
            || requirement is null
            || requirement.Kind != BoundInterfaceMemberKind.Callable
            || requirement.IsStatic
            || requirement.IsAsync
            || requirement.NativeCallableConvention is not null
            || requirement.TypeParameters.IsDefault
            || requirement.TypeParameters.IsEmpty
            || requirement.Constraints.IsDefault
            || requirement.Constraints.Any(constraint =>
                constraint.FormalScope
                    != BoundInterfaceTypeParameterScope.Member
                || constraint.Kind != BoundInterfaceConstraintKind.Type
                || constraint.Type is null
                || (uint)constraint.FormalOrdinal
                    >= (uint)requirement.TypeParameters.Length)
            || requirement.Attributes.IsDefault
            || requirement.AttributeTokens.IsDefault
            || requirement.Attributes.Any(static attribute =>
                !StringComparer.Ordinal.Equals(attribute,
                    "DoesNotReturn"))
            || requirement.AttributeTokens.Length
                != requirement.Attributes.Length
            || requirement.DoesNotReturn
                != requirement.Attributes.Any(static attribute =>
                    StringComparer.Ordinal.Equals(attribute,
                        "DoesNotReturn"))
            || !requirement.ContractTokens.IsEmpty
            || !requirement.Dependencies.IsEmpty)
        {
            return false;
        }

        var definition
            = program.GenericMethodDefinitions[definitionOrdinal];
        var signature
            = program.GenericMethodSignatures[definitionOrdinal];
        if (definition.ProofProgram is not BoundProgram proofProgram
            || proofProgram.GenericMethodSignatures.IsDefault
            || (uint)definitionOrdinal
                >= (uint)proofProgram.GenericMethodSignatures.Length)
        {
            return false;
        }
        var methodSeparator = definition.Name.LastIndexOf('.');
        var implementationMemberName = definition.Name[
            (methodSeparator + 1)..];
        if (definition.DefinitionOrdinal != definitionOrdinal
            || !StringComparer.Ordinal.Equals(signature.Name,
                definition.Name)
            || !StringComparer.Ordinal.Equals(implementationMemberName,
                requirement.Name)
            || definition.Owner is not BoundGenericMethodOwner owner
            || owner.ClosedType != witness.ImplementingType
            || owner.SourceGenericTypeDefinitionIndex != -1
            || !owner.TypeArguments.IsEmpty
            || !owner.ConstantArguments.IsEmpty
            || definition.IsStatic
            || (definition.IsMutable
                && !requirement.RequiresMutableReceiver)
            || definition.Formals.Length
                != requirement.TypeParameters.Length
            || !definition.ConstantFormals.IsEmpty
            || definition.FormalOrder.Length
                != requirement.TypeParameters.Length
            || signature.DefinitionOrdinal != definitionOrdinal
            || signature.Owner is not BoundGenericMethodOwner signatureOwner
            || signatureOwner.ClosedType != witness.ImplementingType
            || signatureOwner.SourceGenericTypeDefinitionIndex != -1
            || !signatureOwner.TypeArguments.IsEmpty
            || !signatureOwner.ConstantArguments.IsEmpty
            || signature.IsStatic
            || (signature.IsMutable
                && !requirement.RequiresMutableReceiver)
            || definition.IsMutable != signature.IsMutable
            || signature.Formals.Length
                != requirement.TypeParameters.Length
            || !signature.ConstantFormals.IsEmpty
            || signature.FormalOrder.Length
                != requirement.TypeParameters.Length
            || definition.FunctionIndex < 0
            || (uint)definition.FunctionIndex
                >= (uint)proofProgram.Functions.Length)
        {
            return false;
        }

        bool InterfaceConstraintsMatch(int ordinal,
            ImmutableArray<BoundInterfaceType> implementationConstraints)
        {
            var requiredConstraints = requirement.Constraints.Where(
                constraint => constraint.FormalScope
                    == BoundInterfaceTypeParameterScope.Member
                    && constraint.FormalOrdinal == ordinal).ToArray();
            if (requiredConstraints.Length
                    != implementationConstraints.Length
                || implementationConstraints.IsDefault)
            {
                return false;
            }

            var unmatched = implementationConstraints.ToList();
            foreach (var constraint in requiredConstraints)
            {
                if (constraint.Kind != BoundInterfaceConstraintKind.Type
                    || constraint.Type is not BoundInterfaceType requiredType)
                {
                    return false;
                }

                var substituted = BoundInterfaceContract
                    .SubstituteTypeParameters(requiredType,
                        binding.Requirement.DeclaringInterface.TypeArguments);
                var matchIndex = unmatched.FindIndex(candidate =>
                    BoundInterfaceContract.AreEquivalent(substituted,
                        candidate));
                if (matchIndex < 0)
                {
                    return false;
                }
                unmatched.RemoveAt(matchIndex);
            }

            return unmatched.Count == 0;
        }

        for (var ordinal = 0;
            ordinal < requirement.TypeParameters.Length; ordinal++)
        {
            var requiredFormal = requirement.TypeParameters[ordinal];
            var definitionFormal = definition.Formals[ordinal];
            var signatureFormal = signature.Formals[ordinal];
            var definitionSlot = definition.FormalOrder[ordinal];
            var signatureSlot = signature.FormalOrder[ordinal];
            if (requiredFormal.Ordinal != ordinal
                || requiredFormal.Kind != BoundInterfaceFormalKind.Type
                || requiredFormal.IsSelf
                || !requiredFormal.Attributes.IsEmpty
                || !requiredFormal.AttributeTokens.IsEmpty
                || requiredFormal.ConstantType is not null
                || requiredFormal.TypeDefault is not null
                || requiredFormal.ConstantDefault is not null
                || definitionFormal.Ordinal != ordinal
                || definitionFormal.OwnershipDomain != 1
                || definitionFormal.NullabilityDomain != 1
                || !definitionFormal.Requirements.IsEmpty
                || definitionFormal.TypeDefault is not null
                || definitionFormal.RequiresBlittable
                || definitionFormal.RequiresWritable
                || !InterfaceConstraintsMatch(ordinal,
                    definitionFormal.InterfaceConstraints)
                || signatureFormal.Ordinal != ordinal
                || signatureFormal.OwnershipDomain != 1
                || signatureFormal.NullabilityDomain != 1
                || !signatureFormal.Requirements.IsEmpty
                || signatureFormal.HasTypeDefault
                || signatureFormal.RequiresBlittable
                || signatureFormal.RequiresWritable
                || !InterfaceConstraintsMatch(ordinal,
                    signatureFormal.InterfaceConstraints)
                || !signatureFormal.DefaultTypeParameterDependencies.IsEmpty
                || definitionSlot.Ordinal != ordinal
                || definitionSlot.Kind != BoundGenericMethodFormalKind.Type
                || definitionSlot.TypeFormalOrdinal != ordinal
                || definitionSlot.ConstantFormalOrdinal != -1
                || signatureSlot.Ordinal != ordinal
                || signatureSlot.Kind != BoundGenericMethodFormalKind.Type
                || signatureSlot.TypeFormalOrdinal != ordinal
                || signatureSlot.ConstantFormalOrdinal != -1)
            {
                return false;
            }
        }

        var function = proofProgram.Functions[
            definition.FunctionIndex];
        if (function.GenericMethodProofDefinitionOrdinal
                != definitionOrdinal
            || function.GenericMethodProofTypeParameters.Length
                != proofProgram.GenericMethodSignatures[
                    definitionOrdinal].Formals.Length)
        {
            return false;
        }
        if (function.IsExternal || function.IsStatic
            || function.ParameterCount
                != requirement.Parameters.Length + 1
            || function.Variables.Length < function.ParameterCount)
        {
            return false;
        }
        if (!function.DependencyContracts.IsEmpty
            || !function.DeclarationContractClauses.IsEmpty
            || (function.RequiresUnsafeCaller
                && !requirement.RequiresUnsafeCaller)
            || (requirement.DoesNotReturn && !function.DoesNotReturn))
        {
            return false;
        }
        if (requirement.ResultType is not BoundInterfaceType resultType
            || !TryGetInterfaceProofPrimitiveType(resultType,
                binding.Requirement.DeclaringInterface.TypeArguments,
                function, proofProgram, out var expectedResult))
        {
            return false;
        }
        if (function.ReturnType != expectedResult)
        {
            return false;
        }
        if (!TryGetInterfaceMethodReceiverMode(function.Variables[0],
                witness.ImplementingType, out var functionRequiresMutable)
            || functionRequiresMutable != definition.IsMutable)
        {
            return false;
        }

        for (var ordinal = 0; ordinal < requirement.Parameters.Length;
            ordinal++)
        {
            var requiredParameter = requirement.Parameters[ordinal];
            var actualParameter = function.Variables[ordinal + 1];
            if (!requiredParameter.Attributes.IsEmpty
                || !requiredParameter.AttributeTokens.IsEmpty
                || !TryGetInterfaceProofPrimitiveType(
                    requiredParameter.Type,
                    binding.Requirement.DeclaringInterface.TypeArguments,
                    function, proofProgram, out var expectedType)
                || actualParameter.Type != expectedType
                || !InterfaceWitnessParameterModeMatches(actualParameter,
                    requiredParameter.Mode))
            {
                return false;
            }
        }

        return true;
    }

    private static bool IsValidInterfaceWitnessImplementation(
        BoundInterfaceWitness witness,
        BoundInterfaceWitnessMember binding,
        BoundProgram program)
    {
        if (!BoundInterfaceContract.TryGetInterfaceMemberDefinition(
                binding.Requirement, program.Interfaces,
                type => ValidType(type, false, program),
                out var requirement,
                genericNominalTypeDefinitions:
                    program.GenericNominalTypeDefinitions,
                sourceGenericTypeDefinitions:
                    program.SourceGenericTypeDefinitions)
            || requirement is null
            || requirement.IsAsync
            || requirement.NativeCallableConvention is not null
            || (uint)binding.FunctionIndex >= (uint)program.Functions.Length)
        {
            return false;
        }

        BoundInterfaceAccessor? accessor = null;
        var isPropertyMember = requirement.Kind
            is BoundInterfaceMemberKind.Property
                or BoundInterfaceMemberKind.Indexer;
        if (isPropertyMember)
        {
            if ((uint)binding.Requirement.AccessorOrdinal
                    >= (uint)requirement.Accessors.Length)
            {
                return false;
            }
            accessor = requirement.Accessors[
                binding.Requirement.AccessorOrdinal];
            if (accessor.Kind != BoundInterfaceAccessorKind.Get
                && (requirement.Kind
                        != BoundInterfaceMemberKind.Indexer
                    || accessor.Kind != BoundInterfaceAccessorKind.Set))
            {
                return false;
            }
        }
        else if (requirement.Kind != BoundInterfaceMemberKind.Callable
            || !requirement.Accessors.IsEmpty)
        {
            return false;
        }
        var isPropertyGetter = accessor?.Kind
            == BoundInterfaceAccessorKind.Get;
        var isIndexerSetter = requirement.Kind
                == BoundInterfaceMemberKind.Indexer
            && accessor?.Kind == BoundInterfaceAccessorKind.Set;

        if (!requirement.TypeParameters.IsEmpty
            || !requirement.Constraints.IsEmpty
            || !requirement.Attributes.IsEmpty
            || !requirement.ContractTokens.IsEmpty
            || !requirement.Dependencies.IsEmpty
            || (accessor is not null
                && (!accessor.Attributes.IsEmpty
                    || !accessor.ContractTokens.IsEmpty
                    || !accessor.Dependencies.IsEmpty))
            || requirement.ResultType is not BoundInterfaceType resultType)
        {
            return false;
        }

        var function = program.Functions[binding.FunctionIndex];
        var ownerName = ManagedClassTypes.IsClass(witness.ImplementingType)
            ? program.Classes[ManagedClassTypes.ClassIndex(
                witness.ImplementingType)].Name
            : program.Structures[(int)witness.ImplementingType - 100].Name;
        var receiverCount = requirement.IsStatic ? 0 : 1;
        var isExplicit = binding.TargetKind
            == BoundInterfaceWitnessTargetKind.ExplicitImplementation;
        var functionName = isIndexerSetter
            ? ownerName + ".#set:" + requirement.Name
            : isPropertyGetter
                ? ownerName + ".#get:" + requirement.Name
            : ownerName + "." + requirement.Name;
        var requiresUnsafeCaller = accessor?.RequiresUnsafeCaller
            ?? requirement.RequiresUnsafeCaller;
        var targetAccessibility = accessor?.Accessibility
            ?? requirement.Accessibility;
        var doesNotReturn = accessor?.DoesNotReturn
            ?? requirement.DoesNotReturn;
        var requiresMutableReceiver = accessor?.IsMutable
            ?? requirement.RequiresMutableReceiver;
        if (function is null || function.IsExternal)
        {
            return false;
        }
        if (function.IsPrivate != isExplicit)
        {
            return false;
        }
        if (!isExplicit
            && targetAccessibility == BoundInterfaceAccessibility.Public
            && function.IsInternal)
        {
            return false;
        }
        if (isExplicit
            ? function.ExplicitInterfaceOwner is not
                    BoundInterfaceType explicitOwner
                || !BoundInterfaceContract.AreEquivalent(explicitOwner,
                    binding.Requirement.DeclaringInterface)
            : function.ExplicitInterfaceOwner is not null)
        {
            return false;
        }
        if (isExplicit && requirement.Kind
            == BoundInterfaceMemberKind.Property)
        {
            return false;
        }
        if (function.IsConstructor || function.IsCleanup
            || function.IsOperator
            || (!isExplicit
                && !StringComparer.Ordinal.Equals(function.Name,
                    functionName)
                && !function.Name.EndsWith("." + functionName,
                    StringComparison.Ordinal)))
        {
            return false;
        }
        if (function.DeclaringStruct != ownerName)
        {
            return false;
        }
        if (function.IsStatic != requirement.IsStatic
            || function.ParameterCount
                != requirement.Parameters.Length + receiverCount
                    + (isIndexerSetter ? 1 : 0)
            || function.Variables.Length < function.ParameterCount)
        {
            return false;
        }
        if (function.DependencyContracts.IsDefault
            || !function.DependencyContracts.IsEmpty
            || function.DeclarationContractClauses.IsDefault
            || !function.DeclarationContractClauses.IsEmpty
            || (function.RequiresUnsafeCaller
                && !requiresUnsafeCaller)
            || (doesNotReturn && !function.DoesNotReturn))
        {
            return false;
        }
        var expectedResult = PrimitiveType.Void;
        if (resultType.Kind == BoundInterfaceTypeKind.Primitive
            && resultType.PrimitiveType == PrimitiveType.Void
            && !resultType.IsWritable && !resultType.IsOptional
            && !resultType.IsGarbageCollected
            && !resultType.IsInitialization)
        {
            expectedResult = PrimitiveType.Void;
        }
        else if (!TryGetInterfacePrimitiveType(resultType,
                    binding.Requirement.DeclaringInterface.TypeArguments,
                    program, out expectedResult))
        {
            return false;
        }
        if (function.ReturnType != (isIndexerSetter
                ? PrimitiveType.Void : expectedResult))
        {
            return false;
        }
        if ((isPropertyGetter || isIndexerSetter)
            && function.PropertyName != requirement.Name)
        {
            return false;
        }

        for (var ordinal = 0; ordinal < requirement.Parameters.Length;
            ordinal++)
        {
            var requiredParameter = requirement.Parameters[ordinal];
            var actualParameter = function.Variables[
                ordinal + receiverCount];
            if (!requiredParameter.Attributes.IsEmpty
                || !requiredParameter.AttributeTokens.IsEmpty
                || !TryGetInterfacePrimitiveType(requiredParameter.Type,
                    binding.Requirement.DeclaringInterface.TypeArguments,
                    program, out var expectedType)
                || actualParameter.Type != expectedType
                || !InterfaceWitnessParameterModeMatches(actualParameter,
                    requiredParameter.Mode))
            {
                return false;
            }
        }
        if (isIndexerSetter)
        {
            var valueParameter = function.Variables[
                requirement.Parameters.Length + receiverCount];
            if (valueParameter.Type != expectedResult
                || valueParameter.IsOut
                || valueParameter.IsImplicitRef
                || valueParameter.IsCanonicalImplicitReference)
            {
                return false;
            }
        }
        if (receiverCount == 0)
        {
            return true;
        }
        if (!TryGetInterfaceMethodReceiverMode(function.Variables[0],
                witness.ImplementingType,
                out var implementationRequiresMutable))
        {
            return false;
        }
        if (implementationRequiresMutable && !requiresMutableReceiver)
        {
            return false;
        }
        return true;
    }

    private static bool TryGetInterfacePrimitiveType(
        BoundInterfaceType type,
        ImmutableArray<BoundInterfaceTypeArgument> typeArguments,
        BoundProgram program, out PrimitiveType primitiveType)
    {
        var substituted = BoundInterfaceContract.SubstituteTypeParameters(
            type, typeArguments);
        if (substituted.Kind == BoundInterfaceTypeKind.Primitive
            && !substituted.IsWritable && !substituted.IsOptional
            && !substituted.IsGarbageCollected
            && !substituted.IsInitialization)
        {
            primitiveType = substituted.PrimitiveType;
            return IsValidType(primitiveType, false, program);
        }
        if (substituted.Kind == BoundInterfaceTypeKind.CheckedReference
            && substituted.TypeArguments is [
                { Kind: BoundInterfaceTypeArgumentKind.Type,
                    Type: BoundInterfaceType referent },
            ]
            && TryGetInterfacePrimitiveType(referent, [], program,
                out var referentType))
        {
            var definition = new CheckedReferenceTypeDefinition(
                referentType, substituted.IsWritable,
                substituted.IsGarbageCollected,
                substituted.IsInitialization,
                substituted.IsOptional);
            var index = program.CheckedReferenceTypes.IndexOf(definition);
            if (index >= 0)
            {
                primitiveType = CheckedReferenceTypes.Type(index);
                return true;
            }
        }

        primitiveType = default;
        return false;
    }

    private static bool TryGetInterfaceProofPrimitiveType(
        BoundInterfaceType type,
        ImmutableArray<BoundInterfaceTypeArgument> typeArguments,
        BoundFunction caller, BoundProgram program,
        out PrimitiveType primitiveType)
    {
        var substituted = BoundInterfaceContract.SubstituteTypeParameters(
            type, typeArguments);
        if (substituted.Kind == BoundInterfaceTypeKind.TypeParameter
            && substituted.TypeParameterScope
                == BoundInterfaceTypeParameterScope.Member
            && caller.GenericMethodProofDefinitionOrdinal
                is int proofDefinitionOrdinal
                and >= 0
            && (uint)proofDefinitionOrdinal
                < (uint)program.GenericMethodSignatures.Length
            && caller.GenericMethodProofTypeParameters.Length
                == program.GenericMethodSignatures[proofDefinitionOrdinal]
                    .Formals.Length)
        {
            var formalSlot = program.GenericMethodSignatures[
                    proofDefinitionOrdinal]
                .FormalOrder.FirstOrDefault(slot =>
                    slot.Ordinal == substituted.TypeParameterOrdinal
                    && slot.Kind == BoundGenericMethodFormalKind.Type);
            if (formalSlot is not null
                && (uint)formalSlot.TypeFormalOrdinal
                    < (uint)caller.GenericMethodProofTypeParameters.Length)
            {
                primitiveType = caller.GenericMethodProofTypeParameters[
                    formalSlot.TypeFormalOrdinal];
                return IsValidType(primitiveType, false, program);
            }
        }
        if (substituted.Kind == BoundInterfaceTypeKind.Primitive
            && !substituted.IsWritable && !substituted.IsOptional
            && !substituted.IsGarbageCollected
            && !substituted.IsInitialization)
        {
            primitiveType = substituted.PrimitiveType;
            return IsValidType(primitiveType, false, program);
        }
        if (substituted.Kind == BoundInterfaceTypeKind.CheckedReference
            && substituted.TypeArguments is [
                { Kind: BoundInterfaceTypeArgumentKind.Type,
                    Type: BoundInterfaceType referent },
            ]
            && TryGetInterfaceProofPrimitiveType(referent, [],
                caller, program, out var referentType))
        {
            var definition = new CheckedReferenceTypeDefinition(
                referentType, substituted.IsWritable,
                substituted.IsGarbageCollected,
                substituted.IsInitialization,
                substituted.IsOptional);
            var index = program.CheckedReferenceTypes.IndexOf(definition);
            if (index >= 0)
            {
                primitiveType = CheckedReferenceTypes.Type(index);
                return true;
            }
        }

        primitiveType = default;
        return false;
    }

    private static bool InterfaceWitnessParameterModeMatches(
        BoundVariable implementation,
        BoundInterfaceParameterMode requirement) =>
        requirement switch {
            BoundInterfaceParameterMode.Value =>
                !implementation.IsOut && !implementation.IsInit
                    && !implementation.IsImplicitRef,
            BoundInterfaceParameterMode.Out => implementation.IsOut
                && !implementation.IsInit && !implementation.IsImplicitRef,
            BoundInterfaceParameterMode.Init => implementation.IsInit
                && !implementation.IsOut && !implementation.IsImplicitRef,
            BoundInterfaceParameterMode.ImplicitRef =>
                implementation.IsImplicitRef && !implementation.IsOut
                    && !implementation.IsInit,
            _ => false,
        };

    private static bool IsValidInterfaceAssociatedConstantValue(
        BoundConstant value, BoundProgram program)
    {
        var type = value.Type;
        if (!IsValidType(type, false, program)
            || (type != PrimitiveType.Bool
                && !PrimitiveTypeFacts.IsIntegerOrWide(type)
                && !PrimitiveTypeFacts.IsFloating(type)
                && !BoundEnumTypes.IsType(type)))
        {
            return false;
        }

        var carrierType = BoundEnumTypes.IsType(type)
            ? program.EnumDefinitions[BoundEnumTypes.Index(type)]
                .UnderlyingType
            : type;
        return (PrimitiveTypeFacts.IsIntegerOrWide(carrierType)
            || PrimitiveTypeFacts.IsFloating(carrierType)
            || carrierType == PrimitiveType.Bool)
            && value.Bits.IsCanonicalFor(carrierType);
    }

    private static bool AreInterfaceParameterDefaultsValid(
        BoundProgram program, bool allowUnmaterializedDefaults)
    {
        foreach (var member in program.Interfaces.SelectMany(
            static definition => definition.Members))
        {
            foreach (var parameter in member.Parameters)
            {
                if (parameter.HasPendingDefault)
                {
                    if (!allowUnmaterializedDefaults
                        || parameter.Mode
                            != BoundInterfaceParameterMode.Value
                        || parameter.Type.Kind
                            != BoundInterfaceTypeKind.Primitive
                        || parameter.DefaultSyntaxSpan.Length <= 0
                        || parameter.DefaultValue is not null
                        || parameter.DefaultExpression is not null
                        || parameter.DefaultExpressionSourceInputOrdinal != -1)
                    {
                        return false;
                    }
                    continue;
                }

                if (parameter.DefaultExpression is not null
                    || parameter.DefaultExpressionSourceInputOrdinal != -1)
                {
                    if (!allowUnmaterializedDefaults
                        || parameter.DefaultExpression
                            is not BoundExpression expression
                        || parameter.Mode
                            != BoundInterfaceParameterMode.Value
                        || parameter.Type.Kind
                            != BoundInterfaceTypeKind.Primitive
                        || expression.Type
                            != parameter.Type.PrimitiveType
                        || (uint)parameter
                            .DefaultExpressionSourceInputOrdinal
                            >= (uint)program.SourceInputCount)
                    {
                        return false;
                    }
                    continue;
                }
                if (parameter.DefaultValue is not BoundConstant value)
                {
                    continue;
                }
                if (parameter.Mode != BoundInterfaceParameterMode.Value
                    || parameter.Type.Kind
                        != BoundInterfaceTypeKind.Primitive
                    || value.Type != parameter.Type.PrimitiveType
                    || !IsValidInterfaceParameterDefaultValue(value,
                        program))
                {
                    return false;
                }
            }
        }

        return true;
    }

    private static bool IsValidInterfaceParameterDefaultValue(
        BoundConstant value, BoundProgram program)
    {
        var type = value.Type;
        var isEnum = BoundEnumTypes.IsType(type);
        if (type is not (PrimitiveType.Bool or PrimitiveType.Char8
                or PrimitiveType.Char16 or PrimitiveType.Char32
                or PrimitiveType.Rune or PrimitiveType.Int8
                or PrimitiveType.Int16 or PrimitiveType.Int32
                or PrimitiveType.Int64 or PrimitiveType.UInt8
                or PrimitiveType.UInt16 or PrimitiveType.UInt32
                or PrimitiveType.UInt64 or PrimitiveType.Int128
                or PrimitiveType.UInt128 or PrimitiveType.Float16
                or PrimitiveType.BFloat16 or PrimitiveType.Float32
                or PrimitiveType.Float64 or PrimitiveType.Float128
                or PrimitiveType.Decimal32 or PrimitiveType.Decimal64
                or PrimitiveType.Decimal128)
            && (!isEnum
                || !BoundEnumTypes.IsValidType(type,
                    program.EnumDefinitions.Length)))
        {
            return false;
        }

        var carrierType = isEnum
            ? program.EnumDefinitions[BoundEnumTypes.Index(type)]
                .UnderlyingType
            : type;
        return value.RepresentationType == carrierType
            && value.Bits.IsCanonicalFor(carrierType);
    }

    private static bool TryProjectGenericMethodInterfaceFormals(
        BoundGenericMethodSignature signature,
        BoundProgram program,
        out ImmutableArray<BoundInterfaceFormal> formals)
    {
        formals = [];
        if (signature.Formals.IsDefault
            || signature.ConstantFormals.IsDefault
            || signature.FormalOrder.IsDefault
            || !IsValidGenericMethodFormalOrder(signature.FormalOrder,
                signature.Formals.Length,
                signature.ConstantFormals.Length))
        {
            return false;
        }

        var result = ImmutableArray.CreateBuilder<BoundInterfaceFormal>(
            signature.FormalOrder.Length);
        foreach (var slot in signature.FormalOrder)
        {
            if (slot.Kind == BoundGenericMethodFormalKind.Type)
            {
                if ((uint)slot.TypeFormalOrdinal
                    >= (uint)signature.Formals.Length)
                {
                    return false;
                }
                var formal = signature.Formals[slot.TypeFormalOrdinal];
                result.Add(new BoundInterfaceFormal(slot.Ordinal,
                    formal.Name, BoundInterfaceFormalKind.Type, false,
                    [], [], null, null, null)
                {
                    RequiresWritable = formal.RequiresWritable,
                });
                continue;
            }

            if (slot.Kind != BoundGenericMethodFormalKind.Constant
                || (uint)slot.ConstantFormalOrdinal
                    >= (uint)signature.ConstantFormals.Length)
            {
                return false;
            }
            var constantFormal = signature.ConstantFormals[
                slot.ConstantFormalOrdinal];
            var constantType = TryGetGenericMethodInterfaceConstantDomain(
                constantFormal.Domain, signature, program);
            result.Add(new BoundInterfaceFormal(slot.Ordinal,
                constantFormal.Name, BoundInterfaceFormalKind.Constant,
                false, [], [], constantType, null, null));
        }
        formals = result.MoveToImmutable();
        return true;
    }

    private static BoundInterfaceType?
        TryGetGenericMethodInterfaceConstantDomain(
            BoundGenericMethodTypeTerm? domain,
            BoundGenericMethodSignature signature,
            BoundProgram program)
    {
        if (domain is null
            || !TryCreateInterfaceTypeFromGenericMethodTerm(domain,
               signature, program, isConstantDomain: true,
               out var interfaceType))
        {
            return null;
        }

        return interfaceType;
    }

    private static bool TryCreateInterfaceTypeFromGenericMethodTerm(
        BoundGenericMethodTypeTerm term,
        BoundGenericMethodSignature signature,
        BoundProgram program, bool isConstantDomain,
        out BoundInterfaceType interfaceType, int depth = 0)
    {
        interfaceType = null!;
        if (depth > MaximumDepth || term.TypeArguments.IsDefault
            || term.ConstantArguments.IsDefault)
        {
            return false;
        }

        if (term.Kind == BoundGenericMethodTypeTermKind.Concrete)
        {
            if (term.ConcreteType == PrimitiveType.Void)
            {
               return false;
            }
            interfaceType = new BoundInterfaceType(
               BoundInterfaceTypeKind.Primitive, term.ConcreteType, null,
               -1, [], false, false, false, false);
            return true;
        }

        if (term.Kind == BoundGenericMethodTypeTermKind.Formal)
        {
            var typeSlot = signature.FormalOrder.FirstOrDefault(slot =>
               slot.Kind == BoundGenericMethodFormalKind.Type
               && slot.TypeFormalOrdinal == term.FormalOrdinal);
            if (typeSlot is null)
            {
               return false;
            }
            interfaceType = new BoundInterfaceType(
               BoundInterfaceTypeKind.TypeParameter,
               PrimitiveType.Void, null, typeSlot.Ordinal, [],
               term.IsWritable, term.IsOptional,
               term.IsGarbageCollected, term.IsInitialization) {
               TypeParameterScope =
                   BoundInterfaceTypeParameterScope.Member,
            };
            return !term.IsGarbageCollected
               && !term.IsInitialization;
        }

        if (term.Kind == BoundGenericMethodTypeTermKind.SourceGeneric)
        {
            return TryCreateInterfaceTypeFromSourceGenericMethodTerm(
                term, signature, program, isConstantDomain, out interfaceType,
                depth);
        }

        if (term.Kind
               != BoundGenericMethodTypeTermKind.ImportedGeneric
            || term.NominalTypeIdentity
               is not BoundGenericNominalTypeIdentity identity
            || term.ConstantArguments.IsDefault)
        {
            return false;
        }

        BoundGenericNominalTypeDefinition? definition = null;
        foreach (var candidate in program.GenericNominalTypeDefinitions)
        {
            if (candidate.Identity != identity)
            {
               continue;
            }
            if (definition is not null)
            {
               return false;
            }
            definition = candidate;
        }
        if (definition is null
            || definition.Formals.IsDefaultOrEmpty
            || definition.Formals.Count(static formal =>
                formal.Kind == BoundGenericArgumentKind.Type)
                != term.TypeArguments.Length
            || definition.Formals.Count(static formal =>
                formal.Kind == BoundGenericArgumentKind.Constant)
                != term.ConstantArguments.Length
            || (isConstantDomain
               && definition.TransparentConstantCarrierType is null)
            || (isConstantDomain
               && (term.IsWritable || term.IsOptional
                   || term.IsGarbageCollected
                   || term.IsInitialization)))
        {
            return false;
        }

        var typeArguments = ImmutableArray.CreateBuilder<
            BoundInterfaceTypeArgument>(definition.Formals.Length);
        var typeArgumentOrdinal = 0;
        var constantArgumentOrdinal = 0;
        foreach (var formal in definition.Formals)
        {
            if (formal.Constraints.IsDefault
               || !formal.Constraints.IsEmpty)
            {
               return false;
            }

            if (formal.Kind == BoundGenericArgumentKind.Type)
            {
               if ((uint)typeArgumentOrdinal
                       >= (uint)term.TypeArguments.Length
                   || !TryCreateInterfaceTypeFromGenericMethodTerm(
                       term.TypeArguments[typeArgumentOrdinal++],
                       signature, program, isConstantDomain: false,
                       out var interfaceTypeArgument, depth + 1))
               {
                   return false;
               }

               typeArguments.Add(
                   BoundInterfaceTypeArgument.ForType(
                       interfaceTypeArgument));
               continue;
            }

            if (formal.Kind != BoundGenericArgumentKind.Constant
               || formal.ConstantDomainType is not PrimitiveType domainType
               || formal.ConstantCarrierType is not
                   PrimitiveType carrierType
               || (PrimitiveTypeFacts.IsIntegerOrWide(carrierType)
                   == false
                   && carrierType != PrimitiveType.Bool
                   && !BoundEnumTypes.IsType(domainType))
               || (formal.ConstantDomainTypeTerm is not null
                   && (formal.ConstantDomainTypeTerm.Kind
                           != BoundGenericMethodTypeTermKind.Concrete
                       || formal.ConstantDomainTypeTerm.ConcreteType
                           != domainType))
               || (uint)constantArgumentOrdinal
                   >= (uint)term.ConstantArguments.Length)
            {
               return false;
            }

            var constantType = new BoundInterfaceType(
               BoundInterfaceTypeKind.Primitive, domainType, null, -1,
               [], false, false, false, false);
            var constantArgument = term.ConstantArguments[
               constantArgumentOrdinal++];
            if (constantArgument.Kind
                   == BoundGenericMethodTypeConstantArgumentKind.Value
               && (constantArgument.DomainType != domainType
                   || constantArgument.CarrierType != carrierType))
            {
               return false;
            }
            if (!TryCreateInterfaceConstantArgumentFromGenericMethodTerm(
               constantArgument, constantType, signature, program,
               out var interfaceConstantArgument, depth + 1))
            {
               return false;
            }

            typeArguments.Add(interfaceConstantArgument);
        }

        if (typeArgumentOrdinal != term.TypeArguments.Length
            || constantArgumentOrdinal != term.ConstantArguments.Length)
        {
            return false;
        }

        interfaceType = new BoundInterfaceType(
            BoundInterfaceTypeKind.GenericNominal,
            PrimitiveType.Void, definition.Namespace + "." + definition.Name,
            -1, typeArguments.MoveToImmutable(), term.IsWritable,
            term.IsOptional, term.IsGarbageCollected,
            term.IsInitialization) {
            GenericNominalTypeIdentity = identity,
            IsGenericNominalConstantDomain = isConstantDomain,
        };
        return true;
    }

    private static bool TryCreateInterfaceTypeFromSourceGenericMethodTerm(
        BoundGenericMethodTypeTerm term,
        BoundGenericMethodSignature signature,
        BoundProgram program,
        bool isConstantDomain,
        out BoundInterfaceType interfaceType,
        int depth)
    {
        interfaceType = null!;
        if ((uint)term.SourceGenericTypeDefinitionIndex
                >= (uint)program.SourceGenericTypeDefinitions.Length
            || (isConstantDomain
                && (term.IsWritable || term.IsOptional
                    || term.IsGarbageCollected
                    || term.IsInitialization)))
        {
            return false;
        }

        var sourceDefinition = program.SourceGenericTypeDefinitions[
            term.SourceGenericTypeDefinitionIndex];
        if (sourceDefinition is null
            || sourceDefinition.DefinitionIndex
                != term.SourceGenericTypeDefinitionIndex
            || sourceDefinition.Formals.IsDefaultOrEmpty
            || sourceDefinition.FormalOrder.IsDefault
            || sourceDefinition.Formals.Length
                != sourceDefinition.FormalOrder.Length
            || (isConstantDomain
                && sourceDefinition.TransparentConstantCarrierType
                    is null)
            || sourceDefinition.Formals.Count(static formal =>
                formal.Kind == BoundGenericMethodFormalKind.Type)
                != term.TypeArguments.Length
            || sourceDefinition.Formals.Count(static formal =>
                formal.Kind == BoundGenericMethodFormalKind.Constant)
                != term.ConstantArguments.Length
            || sourceDefinition.ConstantFormals.IsDefault
            || sourceDefinition.ConstantFormals.Length
                != term.ConstantArguments.Length)
        {
            return false;
        }

        var arguments = ImmutableArray.CreateBuilder<
            BoundInterfaceTypeArgument>(sourceDefinition.Formals.Length);
        foreach (var formal in sourceDefinition.Formals)
        {
            if ((uint)formal.Ordinal
                    >= (uint)sourceDefinition.FormalOrder.Length
                || sourceDefinition.FormalOrder[formal.Ordinal]
                    is not BoundGenericMethodFormalSlot slot
                || slot.Ordinal != formal.Ordinal)
            {
                return false;
            }

            if (formal.Kind == BoundGenericMethodFormalKind.Type)
            {
                if (formal.RequiresBlittable
                    || formal.OwnershipDomain != 1
                    || formal.NullabilityDomain != 1
                    || (uint)formal.TypeFormalOrdinal
                        >= (uint)term.TypeArguments.Length
                    || slot.TypeFormalOrdinal != formal.TypeFormalOrdinal
                    || slot.ConstantFormalOrdinal != -1
                    || !TryCreateInterfaceTypeFromGenericMethodTerm(
                        term.TypeArguments[formal.TypeFormalOrdinal],
                        signature, program, isConstantDomain: false,
                        out var typeArgument, depth + 1))
                {
                    return false;
                }

                arguments.Add(
                    BoundInterfaceTypeArgument.ForType(typeArgument));
                continue;
            }

            if (formal.Kind != BoundGenericMethodFormalKind.Constant
                || (uint)formal.ConstantFormalOrdinal
                    >= (uint)term.ConstantArguments.Length
                || slot.ConstantFormalOrdinal
                    != formal.ConstantFormalOrdinal
                || slot.TypeFormalOrdinal != -1
                || !TryGetSourceGenericConstantDomain(formal,
                    term.TypeArguments, term.ConstantArguments,
                    sourceDefinition.DefinitionIndex, signature, program,
                    depth + 1, out var constantDomain)
                || !TryCreateInterfaceConstantArgumentFromGenericMethodTerm(
                    term.ConstantArguments[formal.ConstantFormalOrdinal],
                    constantDomain, signature, program,
                    out var constantArgument, depth + 1))
            {
                return false;
            }

            arguments.Add(constantArgument);
        }

        interfaceType = new BoundInterfaceType(
            BoundInterfaceTypeKind.GenericNominal,
            PrimitiveType.Void, sourceDefinition.QualifiedName, -1,
            arguments.MoveToImmutable(), term.IsWritable, term.IsOptional,
            term.IsGarbageCollected, term.IsInitialization) {
            SourceGenericTypeDefinitionIndex =
                sourceDefinition.DefinitionIndex,
            IsGenericNominalConstantDomain = isConstantDomain,
        };
        return true;
    }

    private static bool TryGetSourceGenericConstantDomain(
        BoundSourceGenericTypeFormal formal,
        ImmutableArray<BoundGenericMethodTypeTerm> typeArguments,
        ImmutableArray<BoundGenericMethodTypeConstantArgument>
            constantArguments,
        int sourceGenericTypeDefinitionIndex,
        BoundGenericMethodSignature signature,
        BoundProgram program,
        int depth,
        out BoundInterfaceType domain)
    {
        domain = null!;
        if (depth > MaximumDepth
            || formal.ConstantDomain is not
                BoundGenericMethodTypeTerm constantDomain
            || !BoundGenericMethodTypeTerms
                .TrySubstituteSourceGenericTypeFormals(constantDomain,
                typeArguments, sourceGenericTypeDefinitionIndex,
                constantArguments,
                out var substitutedConstantDomain)
            || !BoundGenericMethodTypeTerms
                .TryGetConstantFormalDependencies(
                    substitutedConstantDomain,
                    out _)
            || !TryCreateInterfaceTypeFromGenericMethodTerm(
                substitutedConstantDomain, signature, program,
                isConstantDomain: true, out domain, depth + 1))
        {
            return false;
        }

        return true;
    }

    private static bool
        TryCreateInterfaceConstantArgumentFromGenericMethodTerm(
            BoundGenericMethodTypeConstantArgument argument,
            BoundInterfaceType expectedDomain,
            BoundGenericMethodSignature signature,
            BoundProgram program,
            out BoundInterfaceTypeArgument boundArgument,
            int depth)
    {
        boundArgument = null!;
        if (depth > MaximumDepth)
        {
            return false;
        }

        if (argument.Kind
            == BoundGenericMethodTypeConstantArgumentKind.Value)
        {
            if (expectedDomain.Kind != BoundInterfaceTypeKind.Primitive
                || argument.DomainType != expectedDomain.PrimitiveType
                || !argument.Bits.IsCanonicalFor(argument.CarrierType))
            {
                return false;
            }

            var value = argument.DomainType == argument.CarrierType
                ? new BoundConstant(argument.Bits, argument.DomainType,
                    default)
                : new BoundConstant(argument.Bits, argument.DomainType,
                    argument.CarrierType, default);
            boundArgument = BoundInterfaceTypeArgument.ForConstant(
                expectedDomain, value);
            return true;
        }

        if (argument.Kind
                != BoundGenericMethodTypeConstantArgumentKind.Formal
            || argument.FormalOwnerKind
                != BoundGenericTypeFormalOwnerKind.GenericMethod
            || argument.FormalDefinitionOrdinal != signature.DefinitionOrdinal
            || (uint)argument.FormalOrdinal
                >= (uint)signature.ConstantFormals.Length
            || !TryCreateInterfaceTypeFromGenericMethodTerm(
                signature.ConstantFormals[argument.FormalOrdinal].Domain,
                signature, program, isConstantDomain: true,
                out var actualDomain, depth + 1)
            || !BoundInterfaceContract.AreEquivalent(expectedDomain,
                actualDomain))
        {
            return false;
        }

        var formalSlot = signature.FormalOrder.FirstOrDefault(slot =>
            slot.Kind == BoundGenericMethodFormalKind.Constant
            && slot.ConstantFormalOrdinal == argument.FormalOrdinal);
        if (formalSlot is null)
        {
            return false;
        }

        boundArgument = BoundInterfaceTypeArgument.ForConstantParameter(
            expectedDomain, BoundInterfaceTypeParameterScope.Member,
            formalSlot.Ordinal);
        return true;
    }

    private static bool IsValidGenericMethodDefinitions(BoundProgram program,
        out int invalidDefinitionIndex)
    {
        var definitions = program.GenericMethodDefinitions;
        var signatures = program.GenericMethodSignatures;
        if (definitions.IsDefault || definitions.Length > 32
            || !IsValidGenericMethodSignatures(signatures, program)
            || (!definitions.IsEmpty
                && definitions.Length != signatures.Length))
        {
            invalidDefinitionIndex = -1;
            return false;
        }

        long work = 0;
        for (var definitionIndex = 0; definitionIndex < definitions.Length;
            definitionIndex++)
        {
            var definition = definitions[definitionIndex];
            var signature = signatures[definitionIndex];
            if (definition is not null && signature is not null
                && !AreGenericMethodOwnersEquivalent(definition.Owner,
                    signature.Owner, program, program))
            {
                invalidDefinitionIndex = definitionIndex;
                return false;
            }
            if (definition is null || signature is null
                || definition.DefinitionOrdinal != definitionIndex
                || definition.Name != signature.Name
                || definition.IsPublic != signature.IsPublic
                || definition.RequiresUnsafeCaller
                    != signature.RequiresUnsafeCaller
                || definition.IsStatic != signature.IsStatic
                || definition.IsMutable != signature.IsMutable
                || (definition.Owner is null
                    && (signature.Owner is not null
                        || !definition.IsStatic
                        || definition.IsMutable))
                || !AreGenericMethodOwnersEquivalent(definition.Owner,
                    signature.Owner, program, program)
                || definition.SourceInputOrdinal < 0
                || definition.SourceInputOrdinal >= program.SourceInputCount
                || definition.Formals.IsDefault
                || definition.ConstantFormals.IsDefault
                || definition.FormalOrder.IsDefault
                || definition.RuntimeParameterCount is < 0 or > 8
                || definition.Formals.Length
                    + definition.ConstantFormals.Length is < 1 or > 8
                || definition.Formals.Length != signature.Formals.Length
                || definition.ConstantFormals.Length
                    != signature.ConstantFormals.Length
                || !definition.FormalOrder.SequenceEqual(
                    signature.FormalOrder)
                || !IsValidGenericMethodFormalOrder(
                    definition.FormalOrder, definition.Formals.Length,
                    definition.ConstantFormals.Length)
                || definition.FunctionIndex < 0
                || definition.ProofProgram is not BoundProgram proofProgram
                || proofProgram.EntryPoint != -1
                || proofProgram.GenericMethodDefinitions.IsDefault
                || !proofProgram.GenericMethodDefinitions.IsEmpty
                || proofProgram.GenericMethodSignatures.IsDefault
                || (uint)definition.DefinitionOrdinal
                    >= (uint)proofProgram.GenericMethodSignatures.Length
                || proofProgram.RuntimePolicy != program.RuntimePolicy
                || (definition.Formals.Any(static formal =>
                        formal?.RequiresBlittable == true)
                    && !ReferenceEquals(proofProgram.LayoutCoreRegistration,
                        program.LayoutCoreRegistration))
                || proofProgram.Functions.IsDefault
                || proofProgram.Structures.IsDefault
                || (uint)definition.FunctionIndex
                    >= (uint)proofProgram.Functions.Length)
            {
                invalidDefinitionIndex = definitionIndex;
                return false;
            }
            if (!AreGenericMethodSignaturesEqual(signatures,
                    proofProgram.GenericMethodSignatures, program,
                    proofProgram))
            {
                invalidDefinitionIndex = definitionIndex;
                return false;
            }
            if (!AreGenericMethodOperatorProtocolsEqual(
                    program.GenericMethodOperatorProtocols,
                    proofProgram.GenericMethodOperatorProtocols))
            {
                invalidDefinitionIndex = definitionIndex;
                return false;
            }

            var proofFunction = proofProgram.Functions[
                definition.FunctionIndex];
            if (proofFunction is null
                || definition.RequiresUnsafeCaller
                    != proofFunction.RequiresUnsafeCaller
                || proofFunction.IsStatic != definition.IsStatic
                || proofFunction.DeclaringStruct
                    != GenericMethodOwnerName(signature.Owner,
                        proofProgram)
                || proofFunction.IsExternal
                || proofFunction.Span != definition.Span)
            {
                invalidDefinitionIndex = definitionIndex;
                return false;
            }
            if (!IsValidGenericMethodProofReceiver(proofFunction,
                signature, proofProgram))
            {
                invalidDefinitionIndex = definitionIndex;
                return false;
            }
            if (!IsValidGenericMethodOwnerConstantProofVariables(
                definition,
                proofProgram.GenericMethodSignatures[definitionIndex].Owner,
                proofFunction, proofProgram))
            {
                invalidDefinitionIndex = definitionIndex;
                return false;
            }

            var formalNames = new HashSet<string>(StringComparer.Ordinal);
            var formalTypes = new HashSet<PrimitiveType>();
            work += definition.Formals.Length
                + definition.ConstantFormals.Length;
            if (work > MaximumAnalysisVisits)
            {
                invalidDefinitionIndex = definitionIndex;
                return false;
            }
            for (var ordinal = 0; ordinal < definition.Formals.Length;
                ordinal++)
            {
                var formal = definition.Formals[ordinal];
                var formalSignature = signature.Formals[ordinal];
                if (formal is null
                    || formalSignature is null
                    || formal.Ordinal != formalSignature.Ordinal
                    || formal.Name != formalSignature.Name
                    || formal.OwnershipDomain
                        != formalSignature.OwnershipDomain
                    || formal.NullabilityDomain
                        != formalSignature.NullabilityDomain
                    || formal.RequiresBlittable
                        != formalSignature.RequiresBlittable
                    || formal.RequiresWritable
                        != formalSignature.RequiresWritable
                    || formal.InterfaceConstraints.IsDefault
                    || !formal.InterfaceConstraints.SequenceEqual(
                        formalSignature.InterfaceConstraints)
                    || (formal.TypeDefault is not null)
                        != formalSignature.HasTypeDefault
                    || (formal.TypeDefault is BoundGenericMethodTypeDefault
                            typeDefault
                        && (typeDefault.FormalDependencies.IsDefault
                            || !typeDefault.FormalDependencies.SequenceEqual(
                                formalSignature
                                    .DefaultTypeParameterDependencies)
                            || !IsValidGenericMethodTypeDefault(program,
                                typeDefault, definition.Formals,
                                definition.ConstantFormals,
                                definition.FormalOrder, ordinal,
                                definition.DefinitionOrdinal)
                            || typeDefault.FormalDependencies.Any(
                                dependency => dependency < 0
                                    || dependency >= ordinal)))
                    || !formal.Requirements.SequenceEqual(
                        formalSignature.Requirements))
                {
                    invalidDefinitionIndex = definitionIndex;
                    return false;
                }
                var placeholder = (int)formal.PlaceholderType - 100;
                if (formal.Ordinal != ordinal
                    || string.IsNullOrWhiteSpace(formal.Name)
                    || !formalNames.Add(formal.Name)
                    || formal.OwnershipDomain is not (1 or 2 or 3)
                    || formal.NullabilityDomain is not (1 or 2)
                    || placeholder < 0
                    || (uint)placeholder
                        >= (uint)proofProgram.Structures.Length
                    || !formalTypes.Add(formal.PlaceholderType)
                    || formal.Requirements.IsDefault)
                {
                    invalidDefinitionIndex = definitionIndex;
                    return false;
                }
                var placeholderStructure = proofProgram.Structures[
                    placeholder];
                if (placeholderStructure is null
                    || !placeholderStructure.IsInternal
                    || placeholderStructure.IsUnique
                        != (formal.OwnershipDomain is 2 or 3))
                {
                    invalidDefinitionIndex = definitionIndex;
                    return false;
                }

                var requirementKeys = new HashSet<(TokenKind, int)>();
                foreach (var requirement in formal.Requirements)
                {
                    work++;
                    if (work > MaximumAnalysisVisits
                        || requirement is null
                        || string.IsNullOrWhiteSpace(requirement.Protocol)
                        || requirement.Arity is < 1 or > 2
                        || requirement.ProtocolOrdinal < 0
                        || requirement.ProtocolOrdinal
                            >= program.GenericMethodOperatorProtocols.Length
                        || !requirementKeys.Add((requirement.Operator,
                            requirement.Arity))
                        || !GenericMethodRequirementMatchesProtocol(
                            requirement,
                            program.GenericMethodOperatorProtocols[
                                requirement.ProtocolOrdinal])
                        || (requirement.FixedResult is PrimitiveType
                            fixedResult
                            && !IsValidType(fixedResult, false,
                                proofProgram))
                        || (requirement.FixedResult is null
                            ? (uint)requirement.ResultTypeParameterIndex
                                >= (uint)definition.Formals.Length
                            : requirement.ResultTypeParameterIndex != -1))
                    {
                        invalidDefinitionIndex = definitionIndex;
                        return false;
                    }
                }
            }

            var defaultFunctionIndices = new HashSet<int>();
            for (var constantOrdinal = 0;
                constantOrdinal < definition.ConstantFormals.Length;
                constantOrdinal++)
            {
                var constantFormal =
                    definition.ConstantFormals[constantOrdinal];
                var constantFormalSignature =
                    signature.ConstantFormals[constantOrdinal];
                if (constantFormal is null
                    || constantFormalSignature is null
                    || constantFormal.ConstantOrdinal != constantOrdinal
                    || constantFormal.Ordinal
                        != constantFormalSignature.Ordinal
                    || constantFormal.ConstantOrdinal
                        != constantFormalSignature.ConstantOrdinal
                    || constantFormal.Name != constantFormalSignature.Name
                    || constantFormal.Domain is null
                    || !constantFormal.Domain.Equals(
                        constantFormalSignature.Domain)
                    || constantFormal.ProofParameterIndex
                        != definition.RuntimeParameterCount
                            + constantOrdinal
                    || (uint)constantFormal.ProofParameterIndex
                        >= (uint)proofFunction.Variables.Length
                    || !formalNames.Add(constantFormal.Name)
                    || !IsValidGenericMethodConstantDomain(
                        constantFormal.Domain, definition.Formals,
                        program, definition.ConstantFormals,
                        definition.FormalOrder, constantFormal.Ordinal,
                        definition.DefinitionOrdinal)
                    || !IsValidType(constantFormal.PlaceholderType, false,
                        proofProgram)
                    || !IsGenericMethodConstantProofType(
                        constantFormal.Domain,
                        constantFormal.PlaceholderType, program,
                        proofProgram, proofFunction)
                    || !IsValidGenericMethodConstantFormalOrdinal(
                        definition.FormalOrder, constantFormal.Ordinal,
                        BoundGenericMethodFormalKind.Constant,
                        constantOrdinal)
                    || (constantFormal.Default is null
                        ? constantFormalSignature.HasDefault
                            || !constantFormalSignature
                                .DefaultFormalDependencies.IsEmpty
                        : !constantFormalSignature.HasDefault
                            || constantFormal.Default.FormalDependencies.IsDefault
                            || !constantFormal.Default.FormalDependencies
                                .SequenceEqual(constantFormalSignature
                                    .DefaultFormalDependencies)
                            || !AreGenericMethodConstantDependenciesValid(
                                constantFormal.Default.FormalDependencies,
                                definition.FormalOrder,
                                constantFormal.Ordinal)
                            || (uint)constantFormal.Default.ProofFunctionIndex
                                >= (uint)proofProgram.Functions.Length
                            || !defaultFunctionIndices.Add(
                                constantFormal.Default.ProofFunctionIndex)))
                {
                    invalidDefinitionIndex = definitionIndex;
                    return false;
                }

                var proofVariable = proofFunction.Variables[
                    constantFormal.ProofParameterIndex];
                if (proofVariable is null
                    || proofVariable.Name != constantFormal.Name
                    || proofVariable.Type
                        != constantFormal.PlaceholderType
                    || proofVariable.IsMutable
                    || proofVariable.IsOut || proofVariable.IsInit)
                {
                    invalidDefinitionIndex = definitionIndex;
                    return false;
                }

                if (constantFormal.Default
                    is BoundGenericMethodConstantDefault
                        constantDefault)
                {
                    var defaultFunction = proofProgram.Functions[
                        constantDefault.ProofFunctionIndex];
                    if (defaultFunction is null
                        || defaultFunction.IsExternal
                        || defaultFunction.ReturnType
                            != constantFormal.PlaceholderType
                        || defaultFunction.ParameterCount
                            != constantDefault.FormalDependencies.Length
                        || defaultFunction.Variables.Length
                            != constantDefault.FormalDependencies.Length
                        || defaultFunction
                                .GenericMethodProofDefinitionOrdinal
                            != definitionIndex
                        || !defaultFunction.GenericMethodProofTypeParameters
                            .SequenceEqual(
                                proofFunction.GenericMethodProofTypeParameters)
                        || defaultFunction
                                .GenericMethodConstantDefaultFormalOrdinal
                            != constantFormal.Ordinal
                        || !defaultFunction
                            .GenericMethodConstantDefaultDependencies
                            .SequenceEqual(
                                constantDefault.FormalDependencies))
                    {
                        invalidDefinitionIndex = definitionIndex;
                        return false;
                    }

                    for (var dependencyIndex = 0;
                        dependencyIndex
                            < constantDefault.FormalDependencies.Length;
                        dependencyIndex++)
                    {
                        var dependencyOrdinal =
                            constantDefault.FormalDependencies[
                                dependencyIndex];
                        var dependencyFormal =
                            definition.ConstantFormals.FirstOrDefault(
                                candidate => candidate.Ordinal
                                    == dependencyOrdinal);
                        var variable = defaultFunction.Variables[
                            dependencyIndex];
                        if (dependencyFormal is null || variable is null
                            || variable.Name != dependencyFormal.Name
                            || variable.Type
                                != dependencyFormal.PlaceholderType
                            || variable.IsMutable
                            || variable.IsOut || variable.IsInit)
                        {
                            invalidDefinitionIndex = definitionIndex;
                            return false;
                        }
                    }
                }
            }

            for (var proofFunctionIndex = 0;
                proofFunctionIndex < proofProgram.Functions.Length;
                proofFunctionIndex++)
            {
                var function = proofProgram.Functions[proofFunctionIndex];
                if (function is null
                    || (function.GenericMethodConstantDefaultFormalOrdinal
                        >= 0)
                        != defaultFunctionIndices.Contains(
                            proofFunctionIndex))
                {
                    invalidDefinitionIndex = definitionIndex;
                    return false;
                }
            }

            if (!IsValidGenericMethodOrdinaryParameterDefaults(
                    program, definition, proofFunction, proofProgram,
                    ref work))
            {
                invalidDefinitionIndex = definitionIndex;
                return false;
            }
        }

        if (!BoundTreeTraversal.VisitGenericMethodFunctions(program,
            static _ => { }))
        {
            invalidDefinitionIndex = definitions.IsEmpty ? -1 : 0;
            return false;
        }

        invalidDefinitionIndex = -1;
        return true;
    }

    private static bool IsValidGenericMethodOwnerConstantProofVariables(
        BoundGenericMethodDefinition definition,
        BoundGenericMethodOwner? owner, BoundFunction proofFunction,
        BoundProgram proofProgram)
    {
        var variableIndex = definition.RuntimeParameterCount
            + definition.ConstantFormals.Length;
        if (owner is null)
        {
            return proofFunction.ParameterCount == variableIndex;
        }

        if (owner.SourceGenericTypeDefinitionIndex < 0)
        {
            return owner.ConstantArguments.IsDefaultOrEmpty
                && proofFunction.ParameterCount == variableIndex;
        }

        if ((uint)owner.SourceGenericTypeDefinitionIndex
            >= (uint)proofProgram.SourceGenericTypeDefinitions.Length)
        {
            return false;
        }

        var ownerDefinition = proofProgram.SourceGenericTypeDefinitions[
            owner.SourceGenericTypeDefinitionIndex];
        var ownerConstantArguments = owner.ConstantArguments.IsDefault
            ? ImmutableArray<BoundGenericMethodConstantArgument>.Empty
            : owner.ConstantArguments;
        if (ownerDefinition.Formals.IsDefault
            || ownerDefinition.ConstantFormals.IsDefault
            || ownerConstantArguments.Length
            != ownerDefinition.ConstantFormals.Length)
        {
            return false;
        }

        var ownerTypeFormalCount = ownerDefinition.Formals.Count(
            static formal =>
                formal.Kind == BoundGenericMethodFormalKind.Type);
        var ownerTypeArguments = owner.TypeArguments.IsDefault
            ? ImmutableArray<PrimitiveType>.Empty : owner.TypeArguments;
        if (ownerTypeFormalCount != ownerTypeArguments.Length)
        {
            return false;
        }

        var ownerTypeTerms = ImmutableArray.CreateBuilder<
            BoundGenericMethodTypeTerm>(ownerTypeArguments.Length);
        foreach (var ownerTypeArgument in ownerTypeArguments)
        {
            if (!TryGetGenericMethodActualTypeTerm(ownerTypeArgument,
                proofFunction, proofProgram, 0, out var ownerTypeTerm))
            {
                return false;
            }
            ownerTypeTerms.Add(ownerTypeTerm);
        }
        var ownerConstantArgumentTerms = ownerConstantArguments
            .Select(static actual =>
                (BoundGenericMethodConstantArgument?)actual)
            .ToImmutableArray();
        var checkedOwnerTypeTerms = ownerTypeTerms.MoveToImmutable();

        for (var ordinal = 0;
            ordinal < ownerDefinition.ConstantFormals.Length; ordinal++)
        {
            var ownerFormal = ownerDefinition.ConstantFormals[ordinal];
            var actual = ownerConstantArguments[ordinal];
            if (ownerFormal.ConstantOrdinal != ordinal
                || !BoundGenericMethodTypeTerms
                    .TrySubstituteSourceGenericTypeFormals(
                        ownerFormal.Domain, checkedOwnerTypeTerms,
                        owner.SourceGenericTypeDefinitionIndex,
                        ownerConstantArgumentTerms,
                        out var expectedDomain)
                || !AreGenericMethodTypeTermsEqual(expectedDomain,
                    actual.Domain, 0))
            {
                return false;
            }

            if (actual.Kind
                == BoundGenericMethodConstantArgumentKind.Value)
            {
                if (actual.CallerDefinitionOrdinal != -1
                    || actual.CallerFormalOrdinal != -1
                    || actual.CallerConstantFormalOrdinal != -1
                    || actual.CallerFormalOwnerKind
                        != BoundGenericTypeFormalOwnerKind.GenericMethod
                    || actual.DomainType == PrimitiveType.Void
                    || actual.CarrierType == PrimitiveType.Void
                    || !actual.Bits.IsCanonicalFor(actual.CarrierType)
                    || !TryGetGenericMethodConstantValueDomain(
                        expectedDomain, proofFunction, proofProgram,
                        out var domainType, out var carrierType)
                    || actual.DomainType != domainType
                    || actual.CarrierType != carrierType)
                {
                    return false;
                }
                continue;
            }

            if (actual.Kind
                    != BoundGenericMethodConstantArgumentKind.Formal
                || !IsValidGenericMethodConstantFormalIdentity(actual,
                    proofProgram)
                || !AreGenericMethodTypeTermsEqual(actual.Domain,
                    expectedDomain, 0))
            {
                return false;
            }

            if (definition.ConstantFormals.Any(formal =>
                formal.Name == ownerFormal.Name))
            {
                continue;
            }

            if (!TryGetGenericMethodConstantValueDomain(expectedDomain,
                    proofFunction, proofProgram, out var formalType, out _)
                || (uint)variableIndex >= (uint)proofFunction.Variables.Length)
            {
                return false;
            }

            var proofVariable = proofFunction.Variables[variableIndex++];
            if (proofVariable is null
                || proofVariable.Name != ownerFormal.Name
                || proofVariable.Type != formalType
                || proofVariable.IsMutable
                || proofVariable.IsOut || proofVariable.IsInit)
            {
                return false;
            }
        }

        return proofFunction.ParameterCount == variableIndex;
    }

    private static bool TryGetGenericMethodOwnerProofConstantFormalCount(
        BoundGenericMethodOwner? owner,
        ImmutableArray<BoundGenericMethodConstantFormalSignature>
            methodConstantFormals,
        BoundProgram program, out int count)
    {
        count = 0;
        if (owner is null)
        {
            return true;
        }

        if (owner.SourceGenericTypeDefinitionIndex < 0)
        {
            return owner.ConstantArguments.IsDefaultOrEmpty;
        }

        if ((uint)owner.SourceGenericTypeDefinitionIndex
                >= (uint)program.SourceGenericTypeDefinitions.Length)
        {
            return false;
        }

        var ownerDefinition = program.SourceGenericTypeDefinitions[
            owner.SourceGenericTypeDefinitionIndex];
        if (ownerDefinition.ConstantFormals.IsDefault)
        {
            return false;
        }
        var ownerConstantArguments = owner.ConstantArguments.IsDefault
            ? ImmutableArray<BoundGenericMethodConstantArgument>.Empty
            : owner.ConstantArguments;
        if (ownerConstantArguments.Length
            != ownerDefinition.ConstantFormals.Length)
        {
            return false;
        }

        foreach (var ownerFormal in ownerDefinition.ConstantFormals)
        {
            if ((uint)ownerFormal.ConstantOrdinal
                >= (uint)ownerConstantArguments.Length)
            {
                return false;
            }
            var actual = ownerConstantArguments[
                ownerFormal.ConstantOrdinal];
            if (actual.Kind
                == BoundGenericMethodConstantArgumentKind.Value)
            {
                continue;
            }

            if (actual.Kind
                    != BoundGenericMethodConstantArgumentKind.Formal
                || !IsValidGenericMethodConstantFormalIdentity(actual,
                    program))
            {
                return false;
            }

            if (!methodConstantFormals.Any(methodFormal =>
                methodFormal.Name == ownerFormal.Name))
            {
                count++;
            }
        }

        return true;
    }

    internal static bool IsValidGenericMethodConstantFormalIdentity(
        BoundGenericMethodConstantArgument argument, BoundProgram program)
    {
        if (argument.CallerDefinitionOrdinal < 0
            || argument.CallerConstantFormalOrdinal < 0)
        {
            return false;
        }

        if (argument.CallerFormalOwnerKind
            == BoundGenericTypeFormalOwnerKind.GenericMethod)
        {
            if (argument.CallerFormalOrdinal < 0
                || (uint)argument.CallerDefinitionOrdinal
                    >= (uint)program.GenericMethodSignatures.Length)
            {
                return false;
            }

            var signature = program.GenericMethodSignatures[
                argument.CallerDefinitionOrdinal];
            var formal = signature.ConstantFormals.FirstOrDefault(
                candidate => candidate.Ordinal
                    == argument.CallerFormalOrdinal);
            return formal is not null
                && formal.ConstantOrdinal
                    == argument.CallerConstantFormalOrdinal;
        }

        if (argument.CallerFormalOwnerKind
                != BoundGenericTypeFormalOwnerKind.SourceGenericType
            || argument.CallerFormalOrdinal != -1
            || (uint)argument.CallerDefinitionOrdinal
                >= (uint)program.SourceGenericTypeDefinitions.Length)
        {
            return false;
        }

        return program.SourceGenericTypeDefinitions[
                argument.CallerDefinitionOrdinal].ConstantFormals.Any(
                    formal => formal.ConstantOrdinal
                        == argument.CallerConstantFormalOrdinal);
    }

    private static bool IsValidGenericMethodOrdinaryParameterDefaults(
        BoundProgram program, BoundGenericMethodDefinition definition,
        BoundFunction proofFunction, BoundProgram proofProgram,
        ref long work)
    {
        var receiverCount = definition.Owner is not null
                && !definition.IsStatic
            ? 1 : 0;
        var ordinaryParameterCount = definition.RuntimeParameterCount
            - receiverCount;
        var defaults = definition.OrdinaryParameterDefaults;
        if (ordinaryParameterCount < 0 || defaults.IsDefault
            || defaults.Length != ordinaryParameterCount)
        {
            return false;
        }

        work += defaults.Length;
        if (work > MaximumAnalysisVisits)
        {
            return false;
        }

        for (var parameterIndex = 0;
            parameterIndex < defaults.Length; parameterIndex++)
        {
            var parameterDefault = defaults[parameterIndex];
            if (parameterDefault is null)
            {
                continue;
            }

            var variableIndex = receiverCount + parameterIndex;
            if ((uint)variableIndex >= (uint)proofFunction.Variables.Length
                || parameterDefault.ParameterIndex != parameterIndex
                || string.IsNullOrWhiteSpace(parameterDefault.ParameterName)
                || parameterDefault.ParameterName
                    != proofFunction.Variables[variableIndex].Name
                || parameterDefault.ParameterType
                    != proofFunction.Variables[variableIndex].Type
                || !IsValidType(parameterDefault.ParameterType, false,
                    proofProgram)
                || parameterDefault.Value is not BoundExpression value
                || value.Type != parameterDefault.ParameterType
                || parameterDefault.FormalDependencies.IsDefault)
            {
                return false;
            }

            var previousOwnerDependency = -1;
            var previousMethodDependency = -1;
            var sawMethodDependency = false;
            foreach (var dependency in parameterDefault.FormalDependencies)
            {
                work++;
                if (work > MaximumAnalysisVisits || dependency is null
                    || dependency.Domain is null)
                {
                    return false;
                }

                if (dependency.OwnerKind
                    == BoundGenericTypeFormalOwnerKind.SourceGenericType)
                {
                    if (sawMethodDependency
                        || definition.Owner is not BoundGenericMethodOwner
                            owner
                        || owner.SourceGenericTypeDefinitionIndex
                            != dependency.DefinitionOrdinal
                        || (uint)dependency.DefinitionOrdinal
                            >= (uint)program.SourceGenericTypeDefinitions.Length
                        || owner.ConstantArguments.IsDefault
                        || (uint)dependency.ConstantFormalOrdinal
                            >= (uint)owner.ConstantArguments.Length
                        || dependency.ConstantFormalOrdinal
                            <= previousOwnerDependency)
                    {
                        return false;
                    }

                    var ownerArgument = owner.ConstantArguments[
                        dependency.ConstantFormalOrdinal];
                    var ownerDefinition = program.SourceGenericTypeDefinitions[
                        dependency.DefinitionOrdinal];
                    if (ownerDefinition.ConstantFormals.IsDefault)
                    {
                        return false;
                    }
                    var ownerFormal = ownerDefinition.ConstantFormals
                        .FirstOrDefault(formal => formal.ConstantOrdinal
                            == dependency.ConstantFormalOrdinal);
                    if (ownerFormal is null
                        || ownerFormal.ConstantOrdinal
                            != dependency.ConstantFormalOrdinal
                        || ownerArgument is null
                        || ownerArgument.ConstantOrdinal
                            != dependency.ConstantFormalOrdinal
                        || (ownerArgument.Kind
                                != BoundGenericMethodConstantArgumentKind.Value
                            && ownerArgument.Kind
                                != BoundGenericMethodConstantArgumentKind.Formal)
                        || !AreGenericMethodConstantDomainTermsEquivalent(
                            dependency.Domain, ownerArgument.Domain,
                            program, proofProgram))
                    {
                        return false;
                    }
                    previousOwnerDependency
                        = dependency.ConstantFormalOrdinal;
                    continue;
                }

                if (dependency.OwnerKind
                        != BoundGenericTypeFormalOwnerKind.GenericMethod
                    || dependency.DefinitionOrdinal
                        != definition.DefinitionOrdinal
                    || (uint)dependency.ConstantFormalOrdinal
                        >= (uint)definition.ConstantFormals.Length
                    || dependency.ConstantFormalOrdinal
                        <= previousMethodDependency)
                {
                    return false;
                }

                var methodFormal = definition.ConstantFormals.FirstOrDefault(
                    formal => formal.ConstantOrdinal
                        == dependency.ConstantFormalOrdinal);
                if (methodFormal is null
                    || !AreGenericMethodConstantDomainTermsEquivalent(
                        dependency.Domain, methodFormal.Domain, program,
                        proofProgram))
                {
                    return false;
                }
                previousMethodDependency
                    = dependency.ConstantFormalOrdinal;
                sawMethodDependency = true;
            }

            var usedDependencies = new bool[
                parameterDefault.FormalDependencies.Length];
            long expressionVisits = 0;
            var validExpression = value.HasValidNestedExpressions;
            if (validExpression)
            {
                var traversalValid
                    = BoundTreeTraversal.VisitExpressionTree(value,
                        expression =>
                        {
                            expressionVisits++;
                            if (expressionVisits > MaximumAnalysisVisits
                                || !IsValidType(expression.Type, false,
                                    proofProgram))
                            {
                                validExpression = false;
                                return;
                            }

                            if (expression is not BoundRead read)
                            {
                                return;
                            }

                            if ((uint)read.Variable
                                >= (uint)parameterDefault
                                    .FormalDependencies.Length)
                            {
                                validExpression = false;
                                return;
                            }

                            var dependency
                                = parameterDefault.FormalDependencies[
                                    read.Variable];
                            var validReadType = false;
                            if (dependency.OwnerKind
                                == BoundGenericTypeFormalOwnerKind
                                    .GenericMethod)
                            {
                                var methodFormal
                                    = definition.ConstantFormals
                                        .FirstOrDefault(formal =>
                                            formal.ConstantOrdinal
                                                == dependency
                                                    .ConstantFormalOrdinal);
                                validReadType = methodFormal is not null
                                    && methodFormal.PlaceholderType
                                        == read.Type;
                            }
                            else if (dependency.OwnerKind
                                == BoundGenericTypeFormalOwnerKind
                                    .SourceGenericType)
                            {
                                validReadType
                                    = TryGetGenericMethodActualTypeTerm(
                                        read.Type, proofFunction,
                                        proofProgram, 0,
                                        out var readTypeTerm)
                                    && AreGenericMethodConstantDomainTermsEquivalent(
                                        dependency.Domain, readTypeTerm,
                                        program, proofProgram);
                            }
                            if (!validReadType)
                            {
                                validExpression = false;
                                return;
                            }
                            usedDependencies[read.Variable] = true;
                        });
                validExpression &= traversalValid;
            }
            work += expressionVisits;
            if (!validExpression
                || work > MaximumAnalysisVisits
                || usedDependencies.Any(static used => !used))
            {
                return false;
            }
        }

        return true;
    }

    private static bool IsValidGenericMethodTypeDefault(
        BoundProgram program, BoundGenericMethodTypeDefault typeDefault,
        ImmutableArray<BoundGenericMethodFormal> formals,
        ImmutableArray<BoundGenericMethodConstantFormal> constantFormals,
        ImmutableArray<BoundGenericMethodFormalSlot> formalOrder,
        int formalOrdinal, int definitionOrdinal,
        BoundGenericTypeFormalOwnerKind formalOwnerKind
            = BoundGenericTypeFormalOwnerKind.GenericMethod)
    {
        var formalOrderOrdinal = formalOrder.IsDefault
            ? -1
            : formalOrder.FirstOrDefault(slot =>
                slot.Kind == BoundGenericMethodFormalKind.Type
                && slot.TypeFormalOrdinal == formalOrdinal)?.Ordinal ?? -1;
        if (typeDefault is null
            || formals.IsDefault
            || (uint)formalOrdinal >= (uint)formals.Length
            || constantFormals.IsDefault
            || formalOrder.IsDefault
            || formalOrderOrdinal < 0
            || !IsGenericMethodTypeTermInOwnershipDomain(
                typeDefault.Term, formals[formalOrdinal].OwnershipDomain,
                formals, program, 0)
            || (formals[formalOrdinal].NullabilityDomain == 1
                && IsNullableGenericMethodTypeTerm(typeDefault.Term,
                    formals, program))
            || (formals[formalOrdinal].RequiresBlittable
                && !IsValidGenericMethodBlittableTypeTerm(
                    typeDefault.Term, formals, program, 0))
            || (formals[formalOrdinal].RequiresWritable
                && !IsWritableGenericMethodTypeTerm(
                    typeDefault.Term, formals, program))
            || (formals[formalOrdinal].RequiresWritable
                && !IsWritableGenericMethodTypeTerm(
                    typeDefault.Term, formals, program))
            || typeDefault.FormalDependencies.IsDefault
            || !AreOrderedEarlierFormalDependencies(
                typeDefault.FormalDependencies, formalOrdinal))
        {
            return false;
        }

        if (typeDefault.ConstantFormalDependencies.IsDefault
            || !BoundGenericMethodTypeTerms
                .TryGetConstantFormalDependencies(typeDefault.Term,
                    out var actualConstantDependencies)
            || !actualConstantDependencies.SequenceEqual(
                typeDefault.ConstantFormalDependencies))
        {
            return false;
        }
        foreach (var dependency in typeDefault.ConstantFormalDependencies)
        {
            if ((uint)dependency >= (uint)constantFormals.Length)
            {
                return false;
            }
            var dependencySlot = formalOrder.FirstOrDefault(slot =>
                slot.Kind == BoundGenericMethodFormalKind.Constant
                && slot.ConstantFormalOrdinal == dependency);
            if (dependencySlot is null
                || dependencySlot.Ordinal >= formalOrderOrdinal)
            {
                return false;
            }
        }

        var dependencies = new SortedSet<int>();
        var constantDependencies = new SortedSet<int>();
        var remaining = MaximumAnalysisVisits;
        if (!Visit(typeDefault.Term, 0)
            || !dependencies.SetEquals(typeDefault.FormalDependencies)
            || !constantDependencies.SetEquals(
                typeDefault.ConstantFormalDependencies))
        {
            return false;
        }

        return true;

        bool Visit(BoundGenericMethodTypeTerm? term, int depth)
        {
            if (term is null || depth > MaximumDepth || --remaining < 0
                || term.TypeArguments.IsDefault
                || term.ConstantArguments.IsDefault
                || (term.Kind
                        != BoundGenericMethodTypeTermKind.NativeFixedArray
                    && term.ElementCount != 0)
                || (term.Kind
                        != BoundGenericMethodTypeTermKind.NativeFunctionPointer
                    && (term.CallingConvention
                            != NativeCallingConvention.Native
                        || term.ParameterCount != 0))
                || (term.Kind != BoundGenericMethodTypeTermKind.Span
                    && term.IsElementWritable)
                || (term.Kind != BoundGenericMethodTypeTermKind.Concrete
                    && term.AllowsVoid))
            {
                return false;
            }

            switch (term.Kind)
            {
                case BoundGenericMethodTypeTermKind.Concrete:
                    return term.FormalOrdinal == -1
                        && term.SourceGenericTypeDefinitionIndex == -1
                        && term.NominalTypeIdentity is null
                        && term.TypeArguments.IsEmpty
                        && !term.IsWritable
                        && !term.IsGarbageCollected
                        && !term.IsInitialization
                        && !term.IsOptional
                        && (term.AllowsVoid
                            ? term.ConcreteType == PrimitiveType.Void
                            : IsValidType(term.ConcreteType, false, program));
                case BoundGenericMethodTypeTermKind.Formal:
                    if (term.FormalOrdinal < 0
                        || term.FormalOrdinal >= formalOrdinal
                        || term.SourceGenericTypeDefinitionIndex != -1
                        || term.NominalTypeIdentity is not null
                        || !term.TypeArguments.IsEmpty
                        || term.IsGarbageCollected
                        || term.IsInitialization
                        || term.IsOptional
                        || term.IsWritable
                        || term.ConcreteType != PrimitiveType.Void)
                    {
                        return false;
                    }

                    _ = dependencies.Add(term.FormalOrdinal);
                    return true;
                case BoundGenericMethodTypeTermKind.CheckedReference:
                    return term.FormalOrdinal == -1
                        && term.SourceGenericTypeDefinitionIndex == -1
                        && term.NominalTypeIdentity is null
                        && term.ConcreteType == PrimitiveType.Void
                        && term.TypeArguments.Length == 1
                        && !(term.IsGarbageCollected
                            && term.IsInitialization)
                        && Visit(term.TypeArguments[0], depth + 1);
                case BoundGenericMethodTypeTermKind.SourceGeneric:
                    if (term.FormalOrdinal != -1
                        || term.ConcreteType != PrimitiveType.Void
                        || term.IsWritable
                        || term.IsGarbageCollected
                        || term.IsInitialization
                        || term.IsOptional
                        || term.NominalTypeIdentity is not null
                        || (uint)term.SourceGenericTypeDefinitionIndex
                            >= (uint)program.SourceGenericTypeDefinitions
                                .Length)
                    {
                        return false;
                    }

                    var definition =
                        program.SourceGenericTypeDefinitions[
                            term.SourceGenericTypeDefinitionIndex];
                    if (definition is null
                        || definition.Formals.IsDefault
                        || definition.FormalOrder.IsDefault
                        || definition.FormalOrder.Length
                            != definition.Formals.Length
                        || definition.ConstantFormals.IsDefault
                        || definition.Formals.Count(static formal =>
                            formal.Kind
                                == BoundGenericMethodFormalKind.Type)
                            != term.TypeArguments.Length
                        || definition.ConstantFormals.Length
                            != term.ConstantArguments.Length)
                    {
                        return false;
                    }

                    var sourceTypeArgumentOrdinal = 0;
                    var sourceConstantArgumentOrdinal = 0;
                    foreach (var slot in definition.FormalOrder)
                    {
                        if ((uint)slot.Ordinal
                            >= (uint)definition.Formals.Length)
                        {
                            return false;
                        }

                        var formal = definition.Formals[slot.Ordinal];
                        if (formal is null
                            || formal.Ordinal != slot.Ordinal
                            || formal.Kind != slot.Kind)
                        {
                            return false;
                        }

                        if (slot.Kind
                            == BoundGenericMethodFormalKind.Constant)
                        {
                            if ((uint)slot.ConstantFormalOrdinal
                                    >= (uint)definition.ConstantFormals.Length
                                || (uint)sourceConstantArgumentOrdinal
                                    >= (uint)term.ConstantArguments.Length)
                            {
                                return false;
                            }

                            var constantFormal = definition.ConstantFormals[
                                slot.ConstantFormalOrdinal];
                            var constantArgument = term.ConstantArguments[
                                sourceConstantArgumentOrdinal++];
                            if (constantFormal is null
                                || constantFormal.Ordinal != formal.Ordinal
                                || constantFormal.ConstantOrdinal
                                    != slot.ConstantFormalOrdinal
                                || !BoundGenericMethodTypeTerms
                                    .TrySubstituteSourceGenericTypeFormals(
                                        constantFormal.Domain,
                                        term.TypeArguments,
                                        definition.DefinitionIndex,
                                        term.ConstantArguments,
                                        out var domainTerm)
                                || !BoundGenericMethodTypeTerms
                                    .TryGetConstantFormalDependencies(
                                        domainTerm, out _)
                                || !IsValidGenericMethodConstantDomain(
                                    domainTerm, formals, program,
                                    constantFormals, formalOrder,
                                    formalOrderOrdinal,
                                    definitionOrdinal,
                                    formalOwnerKind))
                            {
                                return false;
                            }

                            if (constantArgument.Kind
                                == BoundGenericMethodTypeConstantArgumentKind.Value)
                            {
                                if (!TryGetGenericMethodConstantValueDomain(
                                        domainTerm, null, program,
                                        out var domainType,
                                        out var carrierType)
                                    || constantArgument.DomainType
                                        != domainType
                                    || constantArgument.CarrierType
                                        != carrierType
                                    || !constantArgument.Bits
                                        .IsCanonicalFor(carrierType))
                                {
                                    return false;
                                }
                            }
                            else if (constantArgument.Kind
                                    == BoundGenericMethodTypeConstantArgumentKind.Formal
                                && constantArgument.FormalOwnerKind
                                    == formalOwnerKind
                                && constantArgument.FormalDefinitionOrdinal
                                    == definitionOrdinal
                                && (uint)constantArgument.FormalOrdinal
                                    < (uint)constantFormals.Length
                                && AreGenericMethodTypeTermsEqual(
                                    constantFormals[
                                        constantArgument.FormalOrdinal]
                                        .Domain, domainTerm, 0))
                            {
                                _ = constantDependencies.Add(
                                    constantArgument.FormalOrdinal);
                            }
                            else
                            {
                                return false;
                            }

                            continue;
                        }

                        if (slot.Kind != BoundGenericMethodFormalKind.Type
                            || (uint)slot.TypeFormalOrdinal
                                >= (uint)term.TypeArguments.Length)
                        {
                            return false;
                        }

                        var argument = term.TypeArguments[
                            sourceTypeArgumentOrdinal++];
                        var argumentDomain =
                            GetGenericMethodTypeTermOwnershipDomain(
                                argument, formals, program, depth + 1);
                        if (formal.OwnershipDomain is not (1 or 2 or 3)
                            || formal.NullabilityDomain is not (1 or 2)
                            || argumentDomain is not (1 or 2 or 3)
                            || (formal.OwnershipDomain == 1
                                && argumentDomain != 1)
                            || (formal.OwnershipDomain == 2
                                && argumentDomain != 2)
                            || (formal.NullabilityDomain == 1
                                && IsNullableGenericMethodTypeTerm(
                                    argument, formals, program))
                            || (formal.RequiresBlittable
                                && !IsValidGenericMethodBlittableTypeTerm(
                                    argument, formals, program, depth + 1))
                            || !Visit(argument, depth + 1))
                        {
                            return false;
                        }
                    }

                    return sourceTypeArgumentOrdinal
                            == term.TypeArguments.Length
                        && sourceConstantArgumentOrdinal
                            == term.ConstantArguments.Length;
                case BoundGenericMethodTypeTermKind.ImportedGeneric:
                    if (term.FormalOrdinal != -1
                        || term.SourceGenericTypeDefinitionIndex != -1
                        || term.ConcreteType != PrimitiveType.Void
                        || term.IsWritable
                        || term.IsGarbageCollected
                        || term.IsInitialization
                        || term.IsOptional
                        || term.NominalTypeIdentity
                            is not BoundGenericNominalTypeIdentity identity
                        || !identity.IsValid
                        || program.GenericNominalTypeDefinitions.IsDefault)
                    {
                        return false;
                    }

                    BoundGenericNominalTypeDefinition? nominalDefinition = null;
                    foreach (var candidate
                        in program.GenericNominalTypeDefinitions)
                    {
                        if (candidate?.Identity != identity)
                        {
                            continue;
                        }
                        if (nominalDefinition is not null)
                        {
                            return false;
                        }
                        nominalDefinition = candidate;
                    }
                    if (nominalDefinition is null
                        || (nominalDefinition.NominalKind != 2
                            && !(nominalDefinition.NominalKind == 1
                                && nominalDefinition
                                    .TransparentConstantCarrierType
                                    is not null))
                        || nominalDefinition.Formals.IsDefault
                        || nominalDefinition.Formals.Length
                            != term.TypeArguments.Length
                                + term.ConstantArguments.Length)
                    {
                        return false;
                    }

                    var typeArgumentOrdinal = 0;
                    var constantArgumentOrdinal = 0;
                    for (var index = 0;
                        index < nominalDefinition.Formals.Length; index++)
                    {
                        var formal = nominalDefinition.Formals[index];
                        if (formal is null
                            || formal.OwnerDefinitionId
                                != identity.DefinitionId
                            || formal.Ordinal != (uint)index
                            || formal.Constraints.IsDefault
                            || !formal.Constraints.IsEmpty)
                        {
                            return false;
                        }

                        if (formal.Kind == BoundGenericArgumentKind.Type)
                        {
                            if ((uint)typeArgumentOrdinal
                                >= (uint)term.TypeArguments.Length)
                            {
                                return false;
                            }
                            var argument = term.TypeArguments[
                                typeArgumentOrdinal++];
                            var argumentDomain =
                                GetGenericMethodTypeTermOwnershipDomain(
                                    argument, formals, program, depth + 1);
                            if (formal.OwnershipDomain
                                    is not (1 or 2 or 3)
                                || formal.NullabilityDomain is not (1 or 2)
                                || argumentDomain is not (1 or 2 or 3)
                                || (formal.OwnershipDomain == 1
                                    && argumentDomain != 1)
                                || (formal.OwnershipDomain == 2
                                    && argumentDomain != 2)
                                || (formal.NullabilityDomain == 1
                                    && IsNullableGenericMethodTypeTerm(
                                        argument, formals, program))
                                || !Visit(argument, depth + 1))
                            {
                                return false;
                            }
                            continue;
                        }

                        if (formal.Kind
                                != BoundGenericArgumentKind.Constant
                            || (uint)constantArgumentOrdinal
                                >= (uint)term.ConstantArguments.Length
                            || formal.ConstantDomainType
                                is not PrimitiveType constantDomain
                                || formal.ConstantCarrierType
                                    is not PrimitiveType constantCarrier
                                || !IsValidType(constantDomain, false, program))
                        {
                            return false;
                        }

                        var constantArgument = term.ConstantArguments[
                            constantArgumentOrdinal++];
                        if (constantArgument.Kind
                            == BoundGenericMethodTypeConstantArgumentKind.Value)
                        {
                            if (constantArgument.DomainType
                                    != constantDomain
                                || constantArgument.CarrierType
                                    != constantCarrier
                                || !(PrimitiveTypeFacts
                                        .IsIntegerOrWide(
                                            constantArgument.CarrierType)
                                    || constantArgument.CarrierType
                                        == PrimitiveType.Bool)
                                || !constantArgument.Bits.IsCanonicalFor(
                                    constantArgument.CarrierType))
                            {
                                return false;
                            }
                            continue;
                        }

                        if (constantArgument.Kind
                                != BoundGenericMethodTypeConstantArgumentKind.Formal
                            || constantArgument.FormalOwnerKind
                                != formalOwnerKind
                            || constantArgument.FormalDefinitionOrdinal
                                != definitionOrdinal
                            || (uint)constantArgument.FormalOrdinal
                                >= (uint)constantFormals.Length
                            || constantFormals[
                                constantArgument.FormalOrdinal].Domain
                                is not {
                                    Kind:
                                        BoundGenericMethodTypeTermKind.Concrete,
                                    ConcreteType: var formalDomain,
                                }
                            || formalDomain != constantDomain)
                        {
                            return false;
                        }
                        _ = constantDependencies.Add(
                            constantArgument.FormalOrdinal);
                    }
                    return typeArgumentOrdinal
                            == term.TypeArguments.Length
                        && constantArgumentOrdinal
                            == term.ConstantArguments.Length;
                case BoundGenericMethodTypeTermKind.NativePointer:
                    return term.FormalOrdinal == -1
                        && term.SourceGenericTypeDefinitionIndex == -1
                        && term.ConcreteType == PrimitiveType.Void
                        && !term.IsGarbageCollected
                        && !term.IsInitialization
                        && !term.IsOptional
                        && term.NominalTypeIdentity is null
                        && term.TypeArguments.Length == 1
                        && IsValidGenericMethodNativePointeeTerm(
                            term.TypeArguments[0], formals, program, 0)
                        && Visit(term.TypeArguments[0], depth + 1);
                case BoundGenericMethodTypeTermKind.NativeFixedArray:
                    return term.FormalOrdinal == -1
                        && term.SourceGenericTypeDefinitionIndex == -1
                        && term.ConcreteType == PrimitiveType.Void
                        && !term.IsWritable
                        && !term.IsGarbageCollected
                        && !term.IsInitialization
                        && !term.IsOptional
                        && term.NominalTypeIdentity is null
                        && term.TypeArguments.Length == 1
                        && IsValidGenericMethodFixedArrayElementTerm(
                            term.TypeArguments[0], formals, program, 0)
                        && Visit(term.TypeArguments[0], depth + 1);
                case BoundGenericMethodTypeTermKind.Span:
                    return term.FormalOrdinal == -1
                        && term.SourceGenericTypeDefinitionIndex == -1
                        && term.ConcreteType == PrimitiveType.Void
                        && !term.IsGarbageCollected
                        && !term.IsOptional
                        && term.NominalTypeIdentity is null
                        && term.TypeArguments.Length == 1
                        && !(term.TypeArguments[0].Kind
                                == BoundGenericMethodTypeTermKind.Concrete
                            && (term.TypeArguments[0].ConcreteType
                                    == PrimitiveType.Void
                                || term.TypeArguments[0].AllowsVoid))
                        && (!term.IsElementWritable
                            || (term.TypeArguments[0].Kind
                                    == BoundGenericMethodTypeTermKind.Formal
                                && (uint)term.TypeArguments[0].FormalOrdinal
                                    < (uint)formals.Length
                                && formals[term.TypeArguments[0]
                                    .FormalOrdinal].RequiresWritable))
                        && Visit(term.TypeArguments[0], depth + 1);
                case BoundGenericMethodTypeTermKind.NativeFunctionPointer:
                    if (!IsValidGenericMethodFunctionPointerSignatureTerm(
                        term, formals, program, 0))
                    {
                        return false;
                    }
                    foreach (var argument in term.TypeArguments)
                    {
                        if (!Visit(argument, depth + 1))
                        {
                            return false;
                        }
                    }
                    return true;
                case BoundGenericMethodTypeTermKind.OptionalValue:
                    return term.FormalOrdinal == -1
                        && term.SourceGenericTypeDefinitionIndex == -1
                        && term.NominalTypeIdentity is null
                        && term.ConcreteType == PrimitiveType.Void
                        && !term.IsWritable
                        && !term.IsGarbageCollected
                        && !term.IsInitialization
                        && !term.IsOptional
                        && term.TypeArguments.Length == 1
                        && Visit(term.TypeArguments[0], depth + 1);
                default:
                    return false;
            }
        }
    }

    private static bool IsNullableGenericMethodTypeTerm(
        BoundGenericMethodTypeTerm term,
        ImmutableArray<BoundGenericMethodFormal> formals,
        BoundProgram program) =>
        term.Kind switch {
            BoundGenericMethodTypeTermKind.Concrete =>
                IsSupportedOptionalType(term.ConcreteType, program),
            BoundGenericMethodTypeTermKind.Formal =>
                term.IsOptional
                || ((uint)term.FormalOrdinal < (uint)formals.Length
                    && formals[term.FormalOrdinal].NullabilityDomain == 2),
            BoundGenericMethodTypeTermKind.CheckedReference =>
                term.IsOptional,
            BoundGenericMethodTypeTermKind.OptionalValue => true,
            BoundGenericMethodTypeTermKind.Span => false,
            BoundGenericMethodTypeTermKind.SourceGeneric
                or BoundGenericMethodTypeTermKind.ImportedGeneric
                or BoundGenericMethodTypeTermKind.NativePointer
                or BoundGenericMethodTypeTermKind.NativeFixedArray
                or BoundGenericMethodTypeTermKind.NativeFunctionPointer =>
                term.IsOptional,
            _ => true,
        };

    private static bool IsGenericMethodTypeTermInOwnershipDomain(
        BoundGenericMethodTypeTerm term, byte targetDomain,
        ImmutableArray<BoundGenericMethodFormal> formals,
        BoundProgram program, int depth)
    {
        var sourceDomain = GetGenericMethodTypeTermOwnershipDomain(
            term, formals, program, depth);
        return sourceDomain is byte domain
            && (targetDomain switch {
                1 => domain == 1,
                2 => domain == 2,
                3 => domain is 1 or 2 or 3,
                _ => false,
            });
    }

    internal static bool IsGenericNominalTypeArgumentTermAdmitted(
        BoundGenericMethodTypeTerm term,
        ImmutableArray<BoundGenericMethodFormal> formals,
        byte ownershipDomain, byte nullabilityDomain,
        BoundProgram program)
    {
        return !formals.IsDefault
            && IsGenericMethodTypeTermInOwnershipDomain(term,
                ownershipDomain, formals, program, 0)
            && (nullabilityDomain != 1
                || !IsNullableGenericMethodTypeTerm(term, formals, program));
    }

    private static byte? GetGenericMethodTypeTermOwnershipDomain(
        BoundGenericMethodTypeTerm term,
        ImmutableArray<BoundGenericMethodFormal> formals,
        BoundProgram program, int depth)
    {
        if (depth > MaximumDepth)
        {
            return null;
        }

        switch (term.Kind)
        {
            case BoundGenericMethodTypeTermKind.Concrete:
                if (IsUniqueGenericMethodTypeArgument(
                    term.ConcreteType, program))
                {
                    return 2;
                }
                return IsCopyGenericMethodTypeArgument(
                        term.ConcreteType, program)
                    || BoundEnumTypes.IsValidType(term.ConcreteType,
                        program.EnumDefinitions.Length)
                    ? (byte)1 : null;
            case BoundGenericMethodTypeTermKind.Formal:
                return (uint)term.FormalOrdinal < (uint)formals.Length
                    ? formals[term.FormalOrdinal].OwnershipDomain : null;
            case BoundGenericMethodTypeTermKind.CheckedReference:
                return !term.IsInitialization
                    && term.TypeArguments.Length == 1 ? (byte)1 : null;
            case BoundGenericMethodTypeTermKind.OptionalValue:
                return term.TypeArguments.Length == 1
                    ? GetGenericMethodTypeTermOwnershipDomain(
                        term.TypeArguments[0], formals, program,
                        depth + 1)
                    : null;
            case BoundGenericMethodTypeTermKind.Span:
                return !term.IsInitialization
                    && term.TypeArguments.Length == 1 ? (byte)1 : null;
            case BoundGenericMethodTypeTermKind.SourceGeneric:
                if ((uint)term.SourceGenericTypeDefinitionIndex
                    >= (uint)program.SourceGenericTypeDefinitions.Length)
                {
                    return null;
                }
                var sourceDefinition =
                    program.SourceGenericTypeDefinitions[
                        term.SourceGenericTypeDefinitionIndex];
                if (sourceDefinition is null
                    || sourceDefinition.Formals.IsDefault
                    || sourceDefinition.FormalOrder.IsDefault
                    || sourceDefinition.FormalOrder.Length
                        != sourceDefinition.Formals.Length
                    || sourceDefinition.Formals.Count(static formal =>
                        formal.Kind == BoundGenericMethodFormalKind.Type)
                        != term.TypeArguments.Length
                    || sourceDefinition.ConstantFormals.IsDefault
                    || sourceDefinition.ConstantFormals.Length
                        != term.ConstantArguments.Length)
                {
                    return null;
                }
                if (sourceDefinition.IsUnique)
                {
                    return 2;
                }

                var mayBeUnique = false;
                var typeArgumentOrdinal = 0;
                foreach (var slot in sourceDefinition.FormalOrder)
                {
                    if (slot.Kind
                        != BoundGenericMethodFormalKind.Type)
                    {
                        continue;
                    }
                    if ((uint)slot.Ordinal
                            >= (uint)sourceDefinition.Formals.Length
                        || (uint)slot.TypeFormalOrdinal
                            >= (uint)term.TypeArguments.Length)
                    {
                        return null;
                    }

                    var sourceFormal =
                        sourceDefinition.Formals[slot.Ordinal];
                    var argument = term.TypeArguments[
                        typeArgumentOrdinal++];
                    var argumentDomain =
                        GetGenericMethodTypeTermOwnershipDomain(
                            argument, formals, program, depth + 1);
                    if (sourceFormal is null
                        || argumentDomain is not (1 or 2 or 3)
                        || (sourceFormal.OwnershipDomain == 1
                            && argumentDomain != 1)
                        || (sourceFormal.OwnershipDomain == 2
                            && argumentDomain != 2)
                        || (sourceFormal.NullabilityDomain == 1
                            && IsNullableGenericMethodTypeTerm(
                                argument, formals, program))
                        || (sourceFormal.RequiresBlittable
                            && !IsValidGenericMethodBlittableTypeTerm(
                                argument, formals, program, depth + 1)))
                    {
                        return null;
                    }
                    mayBeUnique |= argumentDomain != 1;
                }
                if (typeArgumentOrdinal != term.TypeArguments.Length)
                {
                    return null;
                }
                return mayBeUnique ? (byte)3 : (byte)1;
            case BoundGenericMethodTypeTermKind.ImportedGeneric:
                if (term.NominalTypeIdentity
                    is not BoundGenericNominalTypeIdentity identity
                    || !identity.IsValid)
                {
                    return null;
                }
                var importedDefinition =
                    program.GenericNominalTypeDefinitions.FirstOrDefault(
                        candidate => candidate.Identity == identity);
                if (importedDefinition is null)
                {
                    return null;
                }
                if (importedDefinition.NominalKind == 1
                    && importedDefinition.TransparentConstantCarrierType
                        is not null)
                {
                    return 1;
                }
                if (importedDefinition.NominalKind != 2)
                {
                    return null;
                }
                return program.CoreTaskType?.Definition == identity
                    ? (byte)2 : null;
            case BoundGenericMethodTypeTermKind.NativePointer:
            case BoundGenericMethodTypeTermKind.NativeFixedArray:
            case BoundGenericMethodTypeTermKind.NativeFunctionPointer:
                return 1;
            default:
                return null;
        }
    }

    private static bool IsWritableGenericMethodTypeTerm(
        BoundGenericMethodTypeTerm term,
        ImmutableArray<BoundGenericMethodFormal> formals,
        BoundProgram program) =>
        term.Kind switch {
            BoundGenericMethodTypeTermKind.Concrete =>
                IsWritableGenericMethodTypeArgument(
                    term.ConcreteType, program),
            BoundGenericMethodTypeTermKind.Formal =>
                (uint)term.FormalOrdinal < (uint)formals.Length
                && formals[term.FormalOrdinal].RequiresWritable,
            BoundGenericMethodTypeTermKind.CheckedReference =>
                term.IsWritable,
            BoundGenericMethodTypeTermKind.OptionalValue =>
                term.TypeArguments.Length == 1
                && IsWritableGenericMethodTypeTerm(
                    term.TypeArguments[0], formals, program),
            BoundGenericMethodTypeTermKind.NativePointer =>
                term.IsWritable,
            BoundGenericMethodTypeTermKind.Span =>
                term.IsWritable,
            _ => false,
        };

    private static bool IsValidGenericMethodNativePointeeTerm(
        BoundGenericMethodTypeTerm term,
        ImmutableArray<BoundGenericMethodFormal> formals,
        BoundProgram program, int depth)
    {
        if (depth > MaximumDepth)
        {
            return false;
        }

        return term.Kind switch {
            BoundGenericMethodTypeTermKind.Concrete =>
                IsValidType(term.ConcreteType, false, program)
                && NativePointerTypeContract.IsSourcePointee(
                    term.ConcreteType, program.Structures,
                    program.CheckedReferenceTypes,
                    program.NativeLoweringAgreement,
                    program.NativeFixedArrayTypes),
            BoundGenericMethodTypeTermKind.Formal =>
                (uint)term.FormalOrdinal < (uint)formals.Length
                && formals[term.FormalOrdinal].RequiresBlittable
                && !term.IsGarbageCollected
                && !term.IsInitialization
                && !term.IsOptional,
            BoundGenericMethodTypeTermKind.NativePointer =>
                term.TypeArguments.Length == 1
                && !term.IsGarbageCollected
                && !term.IsInitialization
                && !term.IsOptional
                && IsValidGenericMethodNativePointeeTerm(
                    term.TypeArguments[0], formals, program, depth + 1),
            BoundGenericMethodTypeTermKind.NativeFunctionPointer =>
                IsValidGenericMethodFunctionPointerSignatureTerm(
                    term, formals, program, depth + 1),
            _ => false,
        };
    }

    private static bool IsValidGenericMethodFunctionPointerSignatureTerm(
        BoundGenericMethodTypeTerm term,
        ImmutableArray<BoundGenericMethodFormal> formals,
        BoundProgram program, int depth)
    {
        if (depth > MaximumDepth
            || term.Kind
                != BoundGenericMethodTypeTermKind.NativeFunctionPointer
            || term.FormalOrdinal != -1
            || term.SourceGenericTypeDefinitionIndex != -1
            || term.ConcreteType != PrimitiveType.Void
            || term.IsWritable
            || term.IsGarbageCollected
            || term.IsInitialization
            || term.IsOptional
            || term.NominalTypeIdentity is not null
            || term.ElementCount != 0
            || term.AllowsVoid
            || term.ParameterCount < 0
            || term.ParameterCount >= MaximumAnalysisVisits
            || term.TypeArguments.Length != term.ParameterCount + 1
            || !NativeFunctionPointerContract.IsKnownConvention(
                term.CallingConvention))
        {
            return false;
        }

        for (var index = 0; index < term.ParameterCount; index++)
        {
            if (!IsValidGenericMethodFunctionPointerValueTerm(
                term.TypeArguments[index], formals, program,
                allowVoid: false, depth + 1))
            {
                return false;
            }
        }

        return IsValidGenericMethodFunctionPointerValueTerm(
            term.TypeArguments[^1], formals, program, allowVoid: true,
            depth + 1);
    }

    private static bool IsValidGenericMethodFunctionPointerValueTerm(
        BoundGenericMethodTypeTerm term,
        ImmutableArray<BoundGenericMethodFormal> formals,
        BoundProgram program, bool allowVoid, int depth)
    {
        if (depth > MaximumDepth)
        {
            return false;
        }

        switch (term.Kind)
        {
            case BoundGenericMethodTypeTermKind.Concrete:
                if (term.FormalOrdinal != -1
                    || term.SourceGenericTypeDefinitionIndex != -1
                    || term.NominalTypeIdentity is not null
                    || !term.TypeArguments.IsEmpty
                    || term.IsWritable
                    || term.IsGarbageCollected
                    || term.IsInitialization
                    || term.IsOptional
                    || term.CallingConvention
                        != NativeCallingConvention.Native
                    || term.ParameterCount != 0
                    || term.ElementCount != 0)
                {
                    return false;
                }

                if (term.AllowsVoid)
                {
                    return allowVoid
                        && term.ConcreteType == PrimitiveType.Void;
                }

                return IsValidType(term.ConcreteType, false, program)
                    && (PrimitiveTypeFacts.ScalarWidth(
                            term.ConcreteType, program.EnumDefinitions) > 0
                        || term.ConcreteType
                            == PrimitiveType.NativeRawPointer
                        || NativePointerTypes.IsType(term.ConcreteType)
                        || NativeFunctionPointerTypes.IsType(
                            term.ConcreteType)
                        || BoundEnumTypes.IsType(term.ConcreteType));
            case BoundGenericMethodTypeTermKind.Formal:
                return false;
            case BoundGenericMethodTypeTermKind.NativePointer:
                return IsValidGenericMethodNativePointeeTerm(term,
                    formals, program, depth + 1);
            case BoundGenericMethodTypeTermKind.NativeFunctionPointer:
                return IsValidGenericMethodFunctionPointerSignatureTerm(
                    term, formals, program, depth + 1);
            default:
                return false;
        }
    }

    private static bool IsValidGenericMethodBlittableTypeTerm(
        BoundGenericMethodTypeTerm term,
        ImmutableArray<BoundGenericMethodFormal> formals,
        BoundProgram program, int depth)
    {
        if (depth > MaximumDepth)
        {
            return false;
        }

        return term.Kind switch {
            BoundGenericMethodTypeTermKind.Concrete =>
                IsValidType(term.ConcreteType, false, program)
                && IsBlittableGenericMethodArgument(term.ConcreteType,
                    program),
            BoundGenericMethodTypeTermKind.Formal =>
                (uint)term.FormalOrdinal < (uint)formals.Length
                && formals[term.FormalOrdinal].RequiresBlittable
                && !term.IsGarbageCollected
                && !term.IsInitialization
                && !term.IsOptional,
            BoundGenericMethodTypeTermKind.NativePointer =>
                !term.IsGarbageCollected
                && !term.IsInitialization
                && !term.IsOptional
                && term.TypeArguments.Length == 1
                && IsValidGenericMethodNativePointeeTerm(
                    term.TypeArguments[0], formals, program, depth + 1),
            BoundGenericMethodTypeTermKind.NativeFixedArray =>
                !term.IsWritable
                && !term.IsGarbageCollected
                && !term.IsInitialization
                && !term.IsOptional
                && term.TypeArguments.Length == 1
                && IsValidGenericMethodFixedArrayElementTerm(
                    term.TypeArguments[0], formals, program, depth + 1),
            BoundGenericMethodTypeTermKind.NativeFunctionPointer =>
                IsValidGenericMethodFunctionPointerSignatureTerm(
                    term, formals, program, depth + 1),
            _ => false,
        };
    }

    private static bool IsValidGenericMethodFixedArrayElementTerm(
        BoundGenericMethodTypeTerm term,
        ImmutableArray<BoundGenericMethodFormal> formals,
        BoundProgram program, int depth)
    {
        if (depth > MaximumDepth)
        {
            return false;
        }

        return term.Kind switch {
            BoundGenericMethodTypeTermKind.Concrete =>
                IsValidType(term.ConcreteType, false, program)
                && !IsUniqueGenericMethodTypeArgument(
                    term.ConcreteType, program)
                && IsCopyGenericMethodTypeArgument(
                    term.ConcreteType, program)
                && IsBlittableGenericMethodArgument(
                    term.ConcreteType, program),
            BoundGenericMethodTypeTermKind.Formal =>
                (uint)term.FormalOrdinal < (uint)formals.Length
                && formals[term.FormalOrdinal].OwnershipDomain == 1
                && formals[term.FormalOrdinal].RequiresBlittable
                && !term.IsGarbageCollected
                && !term.IsInitialization
                && !term.IsOptional,
            BoundGenericMethodTypeTermKind.NativePointer =>
                IsValidGenericMethodBlittableTypeTerm(
                    term, formals, program, depth + 1),
            BoundGenericMethodTypeTermKind.NativeFunctionPointer =>
                IsValidGenericMethodFunctionPointerSignatureTerm(
                    term, formals, program, depth + 1),
            BoundGenericMethodTypeTermKind.NativeFixedArray =>
                term.TypeArguments.Length == 1
                && IsValidGenericMethodFixedArrayElementTerm(
                    term.TypeArguments[0], formals, program, depth + 1),
            _ => false,
        };
    }

    private static bool IsBlittableGenericMethodArgument(
        PrimitiveType type, BoundProgram program)
    {
        if (PrimitiveTypeFacts.ScalarWidth(type,
                program.EnumDefinitions) > 0
            || type == PrimitiveType.NativeRawPointer)
        {
            return true;
        }
        if (NativePointerTypes.IsType(type))
        {
            return NativePointerTypeContract.IsValidType(type,
                program.NativePointerTypes);
        }
        if (NativeFunctionPointerTypes.IsType(type))
        {
            return NativeFunctionPointerContract.IsValidType(type,
                program.NativeFunctionPointerSignatures);
        }
        if (BoundEnumTypes.IsType(type))
        {
            var index = BoundEnumTypes.Index(type);
            return (uint)index < (uint)program.EnumDefinitions.Length
                && program.EnumDefinitions[index]
                    .BlittableTargetRequirement
                    == FixedLayoutStorage.WindowsX64TargetRequirement;
        }
        if (NativeFixedArrayTypes.IsType(type))
        {
            return NativeFixedArrayContract.IsRootlessCopyFieldType(
                type, program.Structures, program.NativeFixedArrayTypes,
                program.CheckedReferenceTypes);
        }

        var structureIndex = (int)type - 100;
        return (uint)structureIndex < (uint)program.Structures.Length
            && program.Structures[structureIndex]
                .BlittableTargetRequirement
                == FixedLayoutStorage.WindowsX64TargetRequirement
            && !program.Structures[structureIndex].IsUnique;
    }

    private static bool IsValidGenericMethodSignatures(
        ImmutableArray<BoundGenericMethodSignature> signatures,
        BoundProgram program)
    {
        if (signatures.IsDefault || signatures.Length > 32
            || !IsValidGenericMethodOperatorProtocols(
                program.GenericMethodOperatorProtocols, program))
        {
            return false;
        }

        var names = new HashSet<string>(StringComparer.Ordinal);
        long work = 0;
        for (var definitionIndex = 0; definitionIndex < signatures.Length;
            definitionIndex++)
        {
            var signature = signatures[definitionIndex];
            if (signature is null
                || signature.DefinitionOrdinal != definitionIndex
                || string.IsNullOrWhiteSpace(signature.Name)
                || !names.Add(signature.Name)
                || !IsValidGenericMethodOwner(signature.Owner,
                    program)
                || (signature.Owner is null
                    && (!signature.IsStatic || signature.IsMutable))
                || (signature.IsStatic && signature.IsMutable)
                || signature.Formals.IsDefault
                || signature.ConstantFormals.IsDefault
                || signature.FormalOrder.IsDefault
                || signature.Formals.Length
                    + signature.ConstantFormals.Length is < 1 or > 8
                || !IsValidGenericMethodFormalOrder(
                    signature.FormalOrder, signature.Formals.Length,
                    signature.ConstantFormals.Length))
            {
                return false;
            }

            if (!TryProjectGenericMethodInterfaceFormals(signature, program,
                    out var interfaceMethodFormals))
            {
                return false;
            }
            var formalNames = new HashSet<string>(StringComparer.Ordinal);
            for (var ordinal = 0; ordinal < signature.Formals.Length;
                ordinal++)
            {
                var formal = signature.Formals[ordinal];
                if (formal is null || formal.Ordinal != ordinal
                    || string.IsNullOrWhiteSpace(formal.Name)
                    || !formalNames.Add(formal.Name)
                    || formal.OwnershipDomain is not (1 or 2 or 3)
                    || formal.NullabilityDomain is not (1 or 2)
                    || formal.Requirements.IsDefault
                    || formal.InterfaceConstraints.IsDefault
                    || formal.InterfaceConstraints.Length
                        > MaximumArguments
                    || (formal.RequiresBlittable
                        && program.LayoutCoreRegistration is null)
                    || (formal.HasTypeDefault
                        ? formal.DefaultTypeParameterDependencies.IsDefault
                            || !AreOrderedEarlierFormalDependencies(
                                formal.DefaultTypeParameterDependencies,
                                ordinal)
                        : !formal.DefaultTypeParameterDependencies.IsEmpty))
                {
                    return false;
                }

                var requirementKeys = new HashSet<(TokenKind, int)>();
                foreach (var requirement in formal.Requirements)
                {
                    work++;
                    if (work > MaximumAnalysisVisits
                        || requirement is null
                        || string.IsNullOrWhiteSpace(requirement.Protocol)
                        || requirement.Arity is < 1 or > 2
                        || requirement.ProtocolOrdinal < 0
                        || requirement.ProtocolOrdinal
                            >= program.GenericMethodOperatorProtocols.Length
                        || !requirementKeys.Add((requirement.Operator,
                            requirement.Arity))
                        || !GenericMethodRequirementMatchesProtocol(
                            requirement,
                            program.GenericMethodOperatorProtocols[
                                requirement.ProtocolOrdinal])
                        || (requirement.FixedResult is PrimitiveType
                            fixedResult
                            && !IsValidType(fixedResult, false, program))
                        || (requirement.FixedResult is null
                            ? (uint)requirement.ResultTypeParameterIndex
                                >= (uint)signature.Formals.Length
                            : requirement.ResultTypeParameterIndex != -1))
                    {
                        return false;
                    }
                }

                work += formal.InterfaceConstraints.Length;
                if (work > MaximumAnalysisVisits
                    || !BoundInterfaceContract
                        .IsValidGenericMethodConstraintTypes(
                            formal.InterfaceConstraints,
                            program.Interfaces,
                            type => ValidType(type, false, program),
                            signature.Owner?.TypeArguments.Length ?? 0,
                            interfaceMethodFormals,
                            program.GenericNominalTypeDefinitions,
                            program.SourceGenericTypeDefinitions))
                {
                    return false;
                }
            }

            var typeFormalProjection =
                ProjectGenericMethodTypeFormals(signature.Formals);
            var constantFormalProjection =
                ProjectGenericMethodConstantFormals(
                    signature.ConstantFormals);
            for (var constantOrdinal = 0;
                constantOrdinal < signature.ConstantFormals.Length;
                constantOrdinal++)
            {
                work++;
                var formal = signature.ConstantFormals[constantOrdinal];
                if (work > MaximumAnalysisVisits
                    || formal is null
                    || formal.ConstantOrdinal != constantOrdinal
                    || formal.Ordinal < 0
                    || formal.Ordinal >= signature.FormalOrder.Length
                    || string.IsNullOrWhiteSpace(formal.Name)
                    || !formalNames.Add(formal.Name)
                    || formal.Domain is null
                    || !IsValidGenericMethodConstantDomain(
                        formal.Domain, typeFormalProjection, program,
                        constantFormalProjection, signature.FormalOrder,
                        formal.Ordinal, signature.DefinitionOrdinal)
                    || !IsValidGenericMethodConstantFormalOrdinal(
                        signature.FormalOrder, formal.Ordinal,
                        BoundGenericMethodFormalKind.Constant,
                        constantOrdinal)
                    || formal.DefaultFormalDependencies.IsDefault
                    || (formal.HasDefault
                        ? !AreGenericMethodConstantDependenciesValid(
                            formal.DefaultFormalDependencies,
                            signature.FormalOrder, formal.Ordinal)
                        : !formal.DefaultFormalDependencies.IsEmpty))
                {
                    return false;
                }
            }
        }

        return true;
    }

    private static bool IsValidGenericMethodOperatorProtocols(
        ImmutableArray<BoundGenericMethodOperatorProtocol> protocols,
        BoundProgram program)
    {
        if (protocols.IsDefault || protocols.Length > 256)
        {
            return false;
        }

        var names = new HashSet<string>(StringComparer.Ordinal);
        for (var index = 0; index < protocols.Length; index++)
        {
            var protocol = protocols[index];
            if (protocol is null || protocol.DefinitionOrdinal != index
                || string.IsNullOrWhiteSpace(protocol.Name)
                || !names.Add(protocol.Name)
                || protocol.SourceInputOrdinal < 0
                || protocol.SourceInputOrdinal >= program.SourceInputCount
                || protocol.Span.Start < 0 || protocol.Span.Length < 0
                || protocol.Arity is < 1 or > 2
                || !IsGenericMethodOperatorArity(protocol.Operator,
                    protocol.Arity))
            {
                return false;
            }
        }
        return true;
    }

    private static bool GenericMethodRequirementMatchesProtocol(
        BoundGenericMethodOperatorRequirement requirement,
        BoundGenericMethodOperatorProtocol protocol) =>
        protocol.DefinitionOrdinal == requirement.ProtocolOrdinal
        && protocol.Name == requirement.Protocol
        && protocol.Operator == requirement.Operator
        && protocol.Arity == requirement.Arity;

    private static bool IsValidGenericMethodFormalOrder(
        ImmutableArray<BoundGenericMethodFormalSlot> formalOrder,
        int typeFormalCount, int constantFormalCount)
    {
        if (formalOrder.IsDefault || typeFormalCount < 0
            || constantFormalCount < 0
            || formalOrder.Length
                != typeFormalCount + constantFormalCount)
        {
            return false;
        }

        var typeOrdinal = 0;
        var constantOrdinal = 0;
        for (var ordinal = 0; ordinal < formalOrder.Length; ordinal++)
        {
            var formal = formalOrder[ordinal];
            if (formal is null || formal.Ordinal != ordinal)
            {
                return false;
            }

            if (formal.Kind == BoundGenericMethodFormalKind.Type)
            {
                if (formal.TypeFormalOrdinal != typeOrdinal++
                    || formal.ConstantFormalOrdinal != -1)
                {
                    return false;
                }
            }
            else if (formal.Kind == BoundGenericMethodFormalKind.Constant)
            {
                if (formal.TypeFormalOrdinal != -1
                    || formal.ConstantFormalOrdinal
                        != constantOrdinal++)
                {
                    return false;
                }
            }
            else
            {
                return false;
            }
        }

        return typeOrdinal == typeFormalCount
            && constantOrdinal == constantFormalCount;
    }

    private static bool IsValidGenericMethodConstantFormalOrdinal(
        ImmutableArray<BoundGenericMethodFormalSlot> formalOrder,
        int ordinal, BoundGenericMethodFormalKind expectedKind,
        int expectedKindOrdinal) =>
        !formalOrder.IsDefault
        && (uint)ordinal < (uint)formalOrder.Length
        && formalOrder[ordinal] is BoundGenericMethodFormalSlot formal
        && formal.Ordinal == ordinal
        && formal.Kind == expectedKind
        && formal.TypeFormalOrdinal == -1
        && formal.ConstantFormalOrdinal == expectedKindOrdinal;

    private static bool AreGenericMethodConstantDependenciesValid(
        ImmutableArray<int> dependencies,
        ImmutableArray<BoundGenericMethodFormalSlot> formalOrder,
        int formalOrdinal)
    {
        if (dependencies.IsDefault || formalOrder.IsDefault
            || (uint)formalOrdinal >= (uint)formalOrder.Length)
        {
            return false;
        }

        var previous = -1;
        foreach (var dependency in dependencies)
        {
            if (dependency <= previous || dependency >= formalOrdinal
                || (uint)dependency >= (uint)formalOrder.Length
                || formalOrder[dependency].Kind
                    != BoundGenericMethodFormalKind.Constant)
            {
                return false;
            }
            previous = dependency;
        }

        return true;
    }

    private static bool IsValidGenericMethodConstantDomain(
        BoundGenericMethodTypeTerm domain,
        ImmutableArray<BoundGenericMethodFormal> formals,
        BoundProgram program,
        ImmutableArray<BoundGenericMethodConstantFormal>
            constantFormals = default,
        ImmutableArray<BoundGenericMethodFormalSlot>
            formalOrder = default,
        int formalOrdinal = -1,
        int definitionOrdinal = -1,
        BoundGenericTypeFormalOwnerKind formalOwnerKind
            = BoundGenericTypeFormalOwnerKind.GenericMethod)
    {
        if (domain is null || formals.IsDefault
            || domain.IsWritable || domain.IsGarbageCollected
            || domain.IsInitialization || domain.IsOptional
            || !IsValidGenericMethodConstantDomainTypeTerm(domain,
                formals, program, constantFormals, formalOrder,
                formalOrdinal, definitionOrdinal, formalOwnerKind))
        {
            return false;
        }

        if (domain.Kind == BoundGenericMethodTypeTermKind.Concrete)
        {
            var type = domain.ConcreteType;
            if (PrimitiveTypeFacts.IsIntegerOrWide(type)
                || type == PrimitiveType.Bool
                || BoundEnumTypes.IsType(type))
            {
                return true;
            }

            var structureIndex = (int)type - 100;
            return structureIndex >= 0
                && (uint)structureIndex < (uint)program.Structures.Length
                && program.Structures[structureIndex] is BoundStruct {
                    IsTransparent: true,
                    IsUnique: false,
                    BlittableTargetRequirement:
                        FixedLayoutStorage.WindowsX64TargetRequirement,
                    Fields: [{ } carrier],
                }
                && (PrimitiveTypeFacts.IsIntegerOrWide(carrier.Type)
                    || carrier.Type == PrimitiveType.Bool);
        }

        if (domain.Kind == BoundGenericMethodTypeTermKind.ImportedGeneric)
        {
            if (domain.NominalTypeIdentity
                    is not BoundGenericNominalTypeIdentity identity
                || domain.TypeArguments.IsDefault
                || !domain.ConstantArguments.IsEmpty
                || program.GenericNominalTypeDefinitions.IsDefault
                || !IsGenericMethodTypeTermInOwnershipDomain(domain, 1,
                    formals, program, 0)
                || !program.GenericNominalTypeDefinitions.Any(candidate =>
                    candidate.Identity == identity
                    && candidate.NominalKind == 1
                    && candidate.TransparentConstantCarrierType
                        is PrimitiveType carrierType
                    && (PrimitiveTypeFacts.IsIntegerOrWide(carrierType)
                        || carrierType == PrimitiveType.Bool)))
            {
                return false;
            }

            var definition = program.GenericNominalTypeDefinitions.Single(
                candidate => candidate.Identity == identity);
            return definition.Formals.Length == domain.TypeArguments.Length
                && definition.Formals.All(static formal =>
                    formal.Kind == BoundGenericArgumentKind.Type
                    && formal.Constraints.IsEmpty)
                && domain.TypeArguments.All(argument =>
                    IsGenericMethodTypeTermInOwnershipDomain(argument, 1,
                        formals, program, 0));
        }

        if (domain.Kind != BoundGenericMethodTypeTermKind.SourceGeneric
            || (uint)domain.SourceGenericTypeDefinitionIndex
                >= (uint)program.SourceGenericTypeDefinitions.Length
            || !IsGenericMethodTypeTermInOwnershipDomain(domain, 1,
                formals, program, 0))
        {
            return false;
        }

        var sourceDefinition = program.SourceGenericTypeDefinitions[
            domain.SourceGenericTypeDefinitionIndex];
        return sourceDefinition is not null && !sourceDefinition.IsUnique
            && sourceDefinition.TransparentConstantCarrierType
                is PrimitiveType carrierType
            && (PrimitiveTypeFacts.IsIntegerOrWide(carrierType)
                || carrierType == PrimitiveType.Bool)
            && sourceDefinition.Formals.Count(static formal =>
                formal.Kind == BoundGenericMethodFormalKind.Type)
                == domain.TypeArguments.Length
            && sourceDefinition.ConstantFormals.Length
                == domain.ConstantArguments.Length;
    }

    private static bool IsValidGenericMethodConstantDomainTypeTerm(
        BoundGenericMethodTypeTerm term,
        ImmutableArray<BoundGenericMethodFormal> formals,
        BoundProgram program,
        ImmutableArray<BoundGenericMethodConstantFormal>
            constantFormals,
        ImmutableArray<BoundGenericMethodFormalSlot> existingFormalOrder,
        int formalOrdinal,
        int definitionOrdinal,
        BoundGenericTypeFormalOwnerKind formalOwnerKind)
    {
        if (!BoundGenericMethodTypeTerms.TryGetFormalDependencies(term,
                out var dependencies)
            || !BoundGenericMethodTypeTerms
                .TryGetConstantFormalDependencies(term,
                    out var constantDependencies))
        {
            return false;
        }

        var ownerFormalOrdinal = formalOrdinal >= 0
            ? formalOrdinal : existingFormalOrder.IsDefault
                ? formals.Length : existingFormalOrder.Length;
        var extendedFormals = ImmutableArray.CreateBuilder<
            BoundGenericMethodFormal>(formals.Length + 1);
        extendedFormals.AddRange(formals);
        extendedFormals.Add(new BoundGenericMethodFormal(formals.Length,
            "$constant-domain", PrimitiveType.Int32, 3, 2, []));
        var validationFormalOrder = ImmutableArray.CreateBuilder<
            BoundGenericMethodFormalSlot>(
                (existingFormalOrder.IsDefault
                    ? formals.Length : existingFormalOrder.Length)
                    + 1);
        if (existingFormalOrder.IsDefault)
        {
            for (var ordinal = 0; ordinal < formals.Length; ordinal++)
            {
                validationFormalOrder.Add(
                    new BoundGenericMethodFormalSlot(ordinal,
                    BoundGenericMethodFormalKind.Type, ordinal, -1));
            }
        }
        else
        {
            validationFormalOrder.AddRange(existingFormalOrder);
        }

        validationFormalOrder.Add(new BoundGenericMethodFormalSlot(
            ownerFormalOrdinal,
            BoundGenericMethodFormalKind.Type, formals.Length, -1));
        var typeDefault = new BoundGenericMethodTypeDefault(term,
            dependencies) {
            ConstantFormalDependencies = constantDependencies,
        };
        return IsValidGenericMethodTypeDefault(program, typeDefault,
            extendedFormals.MoveToImmutable(),
            constantFormals.IsDefault ? [] : constantFormals,
            validationFormalOrder.MoveToImmutable(), formals.Length,
            definitionOrdinal, formalOwnerKind);
    }

    private static ImmutableArray<BoundGenericMethodFormal>
        ProjectGenericMethodTypeFormals(
            ImmutableArray<BoundGenericMethodFormalSignature> formals)
    {
        var result = ImmutableArray.CreateBuilder<
            BoundGenericMethodFormal>(formals.Length);
        foreach (var formal in formals)
        {
            result.Add(new BoundGenericMethodFormal(formal.Ordinal,
                formal.Name, PrimitiveType.Int32, formal.OwnershipDomain,
                formal.NullabilityDomain, formal.Requirements) {
                RequiresBlittable = formal.RequiresBlittable,
                RequiresWritable = formal.RequiresWritable,
                InterfaceConstraints = formal.InterfaceConstraints,
            });
        }
        return result.MoveToImmutable();
    }

    private static ImmutableArray<BoundGenericMethodConstantFormal>
        ProjectGenericMethodConstantFormals(
            ImmutableArray<BoundGenericMethodConstantFormalSignature>
                formals)
    {
        if (formals.IsDefault)
        {
            return [];
        }

        var result = ImmutableArray.CreateBuilder<
            BoundGenericMethodConstantFormal>(formals.Length);
        foreach (var formal in formals)
        {
            if (formal is null)
            {
                return [];
            }

            result.Add(new BoundGenericMethodConstantFormal(
                formal.Ordinal, formal.ConstantOrdinal, formal.Name,
                formal.Domain, PrimitiveType.Int32, -1, null));
        }
        return result.MoveToImmutable();
    }

    private static bool IsGenericMethodConstantProofType(
        BoundGenericMethodTypeTerm domain, PrimitiveType proofType,
        BoundProgram sourceProgram, BoundProgram proofProgram,
        BoundFunction? proofFunction = null)
    {
        if (domain.Kind == BoundGenericMethodTypeTermKind.SourceGeneric)
        {
            if ((uint)domain.SourceGenericTypeDefinitionIndex
                    >= (uint)sourceProgram.SourceGenericTypeDefinitions.Length
                || sourceProgram.SourceGenericTypeDefinitions[
                        domain.SourceGenericTypeDefinitionIndex]
                    .TransparentConstantCarrierType is not PrimitiveType
                    carrier
                || (PrimitiveTypeFacts.IsIntegerOrWide(carrier)
                    == false && carrier != PrimitiveType.Bool))
            {
                return false;
            }

            if (proofFunction is not null
                && TryGetGenericMethodActualTypeTerm(proofType,
                    proofFunction, proofProgram, 0, out var proofDomain)
                && AreGenericMethodConstantDomainTermsEquivalent(domain,
                    proofDomain, sourceProgram, proofProgram))
            {
                return true;
            }

            var constantPlaceholderIndex = (int)proofType - 100;
            return constantPlaceholderIndex >= 0
                && (uint)constantPlaceholderIndex
                    < (uint)proofProgram.Structures.Length
                && proofProgram.Structures[constantPlaceholderIndex]
                    is BoundStruct {
                    Name: var name,
                    IsInternal: true,
                    IsUnique: false,
                    IsTransparent: false,
                    Fields: [{
                        Name: "$opaque",
                        Type: PrimitiveType.Int32,
                        Offset: 0,
                        Size: sizeof(int),
                        IsPrivate: true,
                    }],
                }
                && name.StartsWith("$C", StringComparison.Ordinal);
        }

        if (domain.Kind == BoundGenericMethodTypeTermKind.ImportedGeneric)
        {
            return proofFunction is not null
                && domain.NominalTypeIdentity
                    is BoundGenericNominalTypeIdentity identity
                && sourceProgram.GenericNominalTypeDefinitions.Any(
                    candidate => candidate.Identity == identity
                        && candidate.TransparentConstantCarrierType
                            is not null)
                && TryMatchGenericMethodConstantProofTypeTerm(domain,
                    proofType, proofFunction, sourceProgram, proofProgram,
                    0);
        }

        if (domain.Kind != BoundGenericMethodTypeTermKind.Concrete)
        {
            return false;
        }
        if (PrimitiveTypeFacts.IsIntegerOrWide(domain.ConcreteType)
            || domain.ConcreteType == PrimitiveType.Bool
            || BoundEnumTypes.IsType(domain.ConcreteType))
        {
            return domain.ConcreteType == proofType;
        }

        var sourceIndex = (int)domain.ConcreteType - 100;
        var proofIndex = (int)proofType - 100;
        if ((uint)sourceIndex >= (uint)sourceProgram.Structures.Length
            || (uint)proofIndex >= (uint)proofProgram.Structures.Length)
        {
            return false;
        }

        var source = sourceProgram.Structures[sourceIndex];
        var proof = proofProgram.Structures[proofIndex];
        if (source is null || proof is null
            || source.Name != proof.Name
            || source.IsTransparent != proof.IsTransparent
            || !source.IsTransparent || source.IsUnique || proof.IsUnique
            || source.BlittableTargetRequirement
                != proof.BlittableTargetRequirement
            || source.Size != proof.Size
            || source.Alignment != proof.Alignment
            || source.RequiredAlignment != proof.RequiredAlignment
            || source.Fields is not [{ } sourceField]
            || proof.Fields is not [{ } proofField])
        {
            return false;
        }

        return sourceField.Name == proofField.Name
            && sourceField.Type == proofField.Type
            && sourceField.Offset == proofField.Offset
            && sourceField.Size == proofField.Size
            && sourceField.IsMutable == proofField.IsMutable
            && sourceField.IsPrivate == proofField.IsPrivate
            && sourceField.IsInternal == proofField.IsInternal
            && sourceField.RequiresUnsafeCaller
                == proofField.RequiresUnsafeCaller;
    }

    private static bool TryMatchGenericMethodConstantProofTypeTerm(
        BoundGenericMethodTypeTerm term, PrimitiveType proofType,
        BoundFunction proofFunction, BoundProgram sourceProgram,
        BoundProgram proofProgram, int depth)
    {
        if (term is null || depth > MaximumDepth)
        {
            return false;
        }

        if (term.Kind == BoundGenericMethodTypeTermKind.Formal)
        {
            return term.TypeArguments.IsEmpty
                && term.ConstantArguments.IsEmpty
                && (uint)term.FormalOrdinal
                    < (uint)proofFunction
                        .GenericMethodProofTypeParameters.Length
                && proofFunction.GenericMethodProofTypeParameters[
                    term.FormalOrdinal] == proofType;
        }

        if (term.Kind == BoundGenericMethodTypeTermKind.Concrete)
        {
            return term.ConcreteType == proofType;
        }

        if (term.Kind != BoundGenericMethodTypeTermKind.ImportedGeneric
            || term.NominalTypeIdentity
                is not BoundGenericNominalTypeIdentity identity
            || !BoundGenericNominalTypeTypes.IsType(proofType)
            || (uint)BoundGenericNominalTypeTypes.Index(proofType)
                >= (uint)proofProgram.GenericNominalTypeInstances.Length
            || term.ConstantArguments.IsDefault
            || term.TypeArguments.IsDefault)
        {
            return false;
        }

        var sourceDefinition = sourceProgram.GenericNominalTypeDefinitions
            .FirstOrDefault(candidate => candidate.Identity == identity);
        var proofInstance = proofProgram.GenericNominalTypeInstances[
            BoundGenericNominalTypeTypes.Index(proofType)];
        var proofDefinition = proofProgram.GenericNominalTypeDefinitions
            .FirstOrDefault(candidate => candidate.Identity == identity);
        if (sourceDefinition is null || proofDefinition is null
            || proofDefinition.NominalKind != sourceDefinition.NominalKind
            || proofDefinition.TransparentConstantCarrierType
                != sourceDefinition.TransparentConstantCarrierType
            || proofInstance.Definition != identity
            || proofInstance.Arguments.Length
                != sourceDefinition.Formals.Length
            || sourceDefinition.Formals.Count(static formal =>
                formal.Kind == BoundGenericArgumentKind.Type)
                != term.TypeArguments.Length
            || sourceDefinition.Formals.Count(static formal =>
                formal.Kind == BoundGenericArgumentKind.Constant)
                != term.ConstantArguments.Length
            || proofInstance.Qualifiers
                != ((term.IsWritable ? 0x01 : 0)
                    | (term.IsGarbageCollected ? 0x02 : 0)
                    | (term.IsInitialization ? 0x04 : 0))
            || proofInstance.TypeSpecForm == 0x06 != term.IsOptional)
        {
            return false;
        }

        var typeArgumentOrdinal = 0;
        var constantArgumentOrdinal = 0;
        for (var ordinal = 0;
            ordinal < sourceDefinition.Formals.Length; ordinal++)
        {
            var proofArgument = proofInstance.Arguments[ordinal];
            var formal = sourceDefinition.Formals[ordinal];
            if (formal.Kind == BoundGenericArgumentKind.Type)
            {
                var sourceArgument = term.TypeArguments[
                    typeArgumentOrdinal++];
                var expectedQualifiers =
                    (sourceArgument.IsWritable ? 0x01 : 0)
                    | (sourceArgument.IsGarbageCollected ? 0x02 : 0)
                    | (sourceArgument.IsInitialization ? 0x04 : 0);
                if (proofArgument.Kind != BoundGenericArgumentKind.Type
                    || proofArgument.Qualifiers != expectedQualifiers
                    || !TryMatchGenericMethodConstantProofTypeTerm(
                        sourceArgument, proofArgument.Type, proofFunction,
                        sourceProgram, proofProgram, depth + 1))
                {
                    return false;
                }
                continue;
            }

            if (formal.Kind != BoundGenericArgumentKind.Constant
                || formal.ConstantDomainType is not PrimitiveType domainType
                || formal.ConstantCarrierType is not
                    PrimitiveType carrierType)
            {
                return false;
            }

            var sourceConstant = term.ConstantArguments[
                constantArgumentOrdinal++];
            if (sourceConstant.Kind
                == BoundGenericMethodTypeConstantArgumentKind.Value)
            {
                if (!proofArgument.HasDecodedConstant
                    || proofArgument.ConstantDomainType != domainType
                    || proofArgument.ConstantCarrierType != carrierType
                    || sourceConstant.DomainType != domainType
                    || sourceConstant.CarrierType != carrierType
                    || proofArgument.ConstantLow
                        != sourceConstant.Bits.Low
                    || proofArgument.ConstantHigh
                        != sourceConstant.Bits.High)
                {
                    return false;
                }
                continue;
            }

            if (sourceConstant.Kind
                    != BoundGenericMethodTypeConstantArgumentKind.Formal
                || !proofArgument.HasConstantFormalIdentity
                || proofArgument.ConstantFormalOwnerKind
                    != sourceConstant.FormalOwnerKind
                || proofArgument.ConstantFormalDefinitionOrdinal
                    != sourceConstant.FormalDefinitionOrdinal
                || proofArgument.ConstantFormalOrdinal
                    != sourceConstant.FormalOrdinal
                || proofArgument.ConstantFormalDomain is not
                    BoundGenericMethodTypeTerm proofDomain)
            {
                return false;
            }

            BoundGenericMethodTypeTerm? sourceDomain = null;
            if (sourceConstant.FormalOwnerKind
                == BoundGenericTypeFormalOwnerKind.GenericMethod)
            {
                if ((uint)sourceConstant.FormalDefinitionOrdinal
                    >= (uint)sourceProgram.GenericMethodDefinitions.Length)
                {
                    return false;
                }
                sourceDomain = sourceProgram.GenericMethodDefinitions[
                    sourceConstant.FormalDefinitionOrdinal].ConstantFormals
                    .FirstOrDefault(candidate =>
                        candidate.ConstantOrdinal
                            == sourceConstant.FormalOrdinal)?.Domain;
            }
            else if (sourceConstant.FormalOwnerKind
                == BoundGenericTypeFormalOwnerKind.SourceGenericType)
            {
                if ((uint)sourceConstant.FormalDefinitionOrdinal
                    >= (uint)sourceProgram.SourceGenericTypeDefinitions
                        .Length)
                {
                    return false;
                }
                sourceDomain = sourceProgram.SourceGenericTypeDefinitions[
                    sourceConstant.FormalDefinitionOrdinal].ConstantFormals
                    .FirstOrDefault(candidate =>
                        candidate.ConstantOrdinal
                            == sourceConstant.FormalOrdinal)?.Domain;
            }
            else
            {
                return false;
            }

            if (sourceDomain is null
                || !AreGenericMethodConstantDomainTermsEquivalent(
                    sourceDomain, proofDomain, sourceProgram, proofProgram))
            {
                return false;
            }
        }

        return true;
    }

    private static bool AreGenericMethodConstantDomainTermsEquivalent(
        BoundGenericMethodTypeTerm source,
        BoundGenericMethodTypeTerm proof,
        BoundProgram sourceProgram, BoundProgram proofProgram,
        int depth = 0)
    {
        if (depth > MaximumDepth || source.Kind != proof.Kind
            || source.FormalOrdinal != proof.FormalOrdinal
            || source.SourceGenericTypeDefinitionIndex
                != proof.SourceGenericTypeDefinitionIndex
            || source.IsWritable != proof.IsWritable
            || source.IsGarbageCollected != proof.IsGarbageCollected
            || source.IsInitialization != proof.IsInitialization
            || source.IsOptional != proof.IsOptional
            || source.NominalTypeIdentity != proof.NominalTypeIdentity
            || source.ElementCount != proof.ElementCount
            || source.CallingConvention != proof.CallingConvention
            || source.ParameterCount != proof.ParameterCount
            || source.AllowsVoid != proof.AllowsVoid
            || source.TypeArguments.IsDefault
            || proof.TypeArguments.IsDefault
            || source.TypeArguments.Length != proof.TypeArguments.Length
            || source.ConstantArguments.IsDefault
            || proof.ConstantArguments.IsDefault
            || source.ConstantArguments.Length
                != proof.ConstantArguments.Length
            || (source.Kind == BoundGenericMethodTypeTermKind.Concrete
                ? !IsGenericMethodConstantProofType(source,
                    proof.ConcreteType, sourceProgram, proofProgram)
                : source.ConcreteType != proof.ConcreteType))
        {
            return false;
        }

        for (var index = 0; index < source.TypeArguments.Length; index++)
        {
            if (!AreGenericMethodConstantDomainTermsEquivalent(
                source.TypeArguments[index], proof.TypeArguments[index],
                sourceProgram, proofProgram, depth + 1))
            {
                return false;
            }
        }

        for (var index = 0; index < source.ConstantArguments.Length;
            index++)
        {
            var sourceArgument = source.ConstantArguments[index];
            var proofArgument = proof.ConstantArguments[index];
            if (sourceArgument.Kind != proofArgument.Kind
                || sourceArgument.FormalOrdinal
                    != proofArgument.FormalOrdinal
                || sourceArgument.FormalDefinitionOrdinal
                    != proofArgument.FormalDefinitionOrdinal
                || sourceArgument.FormalOwnerKind
                    != proofArgument.FormalOwnerKind
                || sourceArgument.DomainType != proofArgument.DomainType
                || sourceArgument.CarrierType != proofArgument.CarrierType
                || sourceArgument.Bits != proofArgument.Bits)
            {
                return false;
            }
        }

        return true;
    }

    private static bool AreOrderedEarlierFormalDependencies(
        ImmutableArray<int> dependencies, int formalOrdinal)
    {
        var previous = -1;
        foreach (var dependency in dependencies)
        {
            if (dependency <= previous || dependency >= formalOrdinal)
            {
                return false;
            }
            previous = dependency;
        }

        return true;
    }

    private static bool AreGenericMethodOperatorProtocolsEqual(
        ImmutableArray<BoundGenericMethodOperatorProtocol> left,
        ImmutableArray<BoundGenericMethodOperatorProtocol> right)
    {
        // A proof may predate protocols first used by later closed owners.
        if (left.IsDefault || right.IsDefault
            || right.Length > left.Length)
        {
            return false;
        }

        for (var index = 0; index < right.Length; index++)
        {
            var leftProtocol = left[index];
            var rightProtocol = right[index];
            if (leftProtocol is null || rightProtocol is null
                || leftProtocol.DefinitionOrdinal
                    != rightProtocol.DefinitionOrdinal
                || leftProtocol.Name != rightProtocol.Name
                || leftProtocol.SourceInputOrdinal
                    != rightProtocol.SourceInputOrdinal
                || leftProtocol.Span != rightProtocol.Span
                || leftProtocol.Operator != rightProtocol.Operator
                || leftProtocol.Arity != rightProtocol.Arity
                || leftProtocol.HasSelf != rightProtocol.HasSelf
                || leftProtocol.RequiresUnsafeCaller
                    != rightProtocol.RequiresUnsafeCaller)
            {
                return false;
            }
        }

        return true;
    }

    private static bool IsGenericMethodOperatorArity(TokenKind operation,
        int arity) =>
        arity == 1
            ? operation is TokenKind.Plus or TokenKind.Minus
                or TokenKind.Bang or TokenKind.Tilde
                or TokenKind.PlusPlus or TokenKind.MinusMinus
            : operation is TokenKind.Plus or TokenKind.Minus
                or TokenKind.Star or TokenKind.Slash or TokenKind.Percent
                or TokenKind.Ampersand or TokenKind.Pipe or TokenKind.Caret
                or TokenKind.EqualsEquals or TokenKind.BangEquals
                or TokenKind.Less or TokenKind.LessEquals
                or TokenKind.Greater or TokenKind.GreaterEquals;

    private static bool AreGenericMethodInterfaceConstraintsEqual(
        ImmutableArray<BoundInterfaceType> source,
        ImmutableArray<BoundInterfaceType> proof,
        BoundProgram sourceProgram, BoundProgram proofProgram,
        ref int remainingVisits)
    {
        if (source.IsEmpty && proof.IsEmpty)
        {
            return true;
        }
        if (source.IsDefault || proof.IsDefault
            || source.Length != proof.Length)
        {
            return false;
        }

        for (var index = 0; index < source.Length; index++)
        {
            if (!AreGenericMethodInterfaceTypesEqual(source[index],
                proof[index], sourceProgram, proofProgram, 0,
                ref remainingVisits))
            {
                return false;
            }
        }
        return true;
    }

    private static bool AreGenericMethodInterfaceTypesEqual(
        BoundInterfaceType? source, BoundInterfaceType? proof,
        BoundProgram sourceProgram, BoundProgram proofProgram, int depth,
        ref int remainingVisits)
    {
        if (source is null || proof is null)
        {
            return source is null && proof is null;
        }
        if (depth > MaximumDepth || --remainingVisits < 0
            || source.Kind != proof.Kind
            || source.TypeParameterScope != proof.TypeParameterScope
            || source.TypeParameterOrdinal != proof.TypeParameterOrdinal
            || source.NominalName != proof.NominalName
            || source.IsWritable != proof.IsWritable
            || source.IsOptional != proof.IsOptional
            || source.IsGarbageCollected != proof.IsGarbageCollected
            || source.IsInitialization != proof.IsInitialization
            || source.ModuleImport != proof.ModuleImport
            || source.GenericNominalTypeIdentity
                != proof.GenericNominalTypeIdentity
            || source.IsGenericNominalConstantDomain
                != proof.IsGenericNominalConstantDomain
            || source.TypeArguments.IsDefault
            || proof.TypeArguments.IsDefault
            || source.TypeArguments.Length != proof.TypeArguments.Length)
        {
            return false;
        }

        if (source.Kind == BoundInterfaceTypeKind.Primitive
            ? !AreGenericMethodProofTypesEquivalent(source.PrimitiveType,
                proof.PrimitiveType, sourceProgram, proofProgram, 0,
                ref remainingVisits)
            : source.PrimitiveType != proof.PrimitiveType)
        {
            return false;
        }

        for (var index = 0; index < source.TypeArguments.Length; index++)
        {
            var sourceArgument = source.TypeArguments[index];
            var proofArgument = proof.TypeArguments[index];
            if (sourceArgument is null || proofArgument is null
                || sourceArgument.Kind != proofArgument.Kind
                || sourceArgument.ConstantParameterScope
                    != proofArgument.ConstantParameterScope
                || sourceArgument.ConstantParameterOrdinal
                    != proofArgument.ConstantParameterOrdinal
                || sourceArgument.ConstantValue
                    != proofArgument.ConstantValue
                || !AreGenericMethodInterfaceTypesEqual(
                    sourceArgument.Type, proofArgument.Type,
                    sourceProgram, proofProgram, depth + 1,
                    ref remainingVisits)
                || !AreGenericMethodInterfaceTypesEqual(
                    sourceArgument.ConstantType,
                    proofArgument.ConstantType, sourceProgram,
                    proofProgram, depth + 1, ref remainingVisits))
            {
                return false;
            }
        }
        return true;
    }

    private static bool AreGenericMethodProofTypesEquivalent(
        PrimitiveType sourceType, PrimitiveType proofType,
        BoundProgram sourceProgram, BoundProgram proofProgram, int depth,
        ref int remainingVisits)
    {
        if (depth > MaximumDepth || --remainingVisits < 0)
        {
            return false;
        }

        if (BoundEnumTypes.IsType(sourceType)
            || BoundEnumTypes.IsType(proofType))
        {
            if (!BoundEnumTypes.IsType(sourceType)
                || !BoundEnumTypes.IsType(proofType))
            {
                return false;
            }
            var sourceEnum = BoundEnumTypes.Index(sourceType);
            var proofEnum = BoundEnumTypes.Index(proofType);
            return (uint)sourceEnum
                    < (uint)sourceProgram.EnumDefinitions.Length
                && (uint)proofEnum
                    < (uint)proofProgram.EnumDefinitions.Length
                && sourceProgram.EnumDefinitions[sourceEnum].Identity
                    == proofProgram.EnumDefinitions[proofEnum].Identity;
        }

        if (ManagedClassTypes.IsClass(sourceType)
            || ManagedClassTypes.IsClass(proofType))
        {
            if (!ManagedClassTypes.IsClass(sourceType)
                || !ManagedClassTypes.IsClass(proofType)
                || ManagedClassTypes.IsWritable(sourceType)
                    != ManagedClassTypes.IsWritable(proofType)
                || ManagedClassTypes.IsOptional(sourceType)
                    != ManagedClassTypes.IsOptional(proofType))
            {
                return false;
            }
            var sourceIndex = ManagedClassTypes.ClassIndex(sourceType);
            var proofIndex = ManagedClassTypes.ClassIndex(proofType);
            return (uint)sourceIndex < (uint)sourceProgram.Classes.Length
                && (uint)proofIndex < (uint)proofProgram.Classes.Length
                && AreGenericMethodProofClassTypesEquivalent(
                    sourceProgram.Classes[sourceIndex],
                    proofProgram.Classes[proofIndex],
                    sourceProgram, proofProgram, depth + 1,
                    ref remainingVisits);
        }

        if (BoundGenericNominalTypeTypes.IsType(sourceType)
            || BoundGenericNominalTypeTypes.IsType(proofType)
            || CheckedReferenceTypes.IsType(sourceType)
            || CheckedReferenceTypes.IsType(proofType)
            || NativePointerTypes.IsType(sourceType)
            || NativePointerTypes.IsType(proofType)
            || NativeFixedArrayTypes.IsType(sourceType)
            || NativeFixedArrayTypes.IsType(proofType)
            || NativeFunctionPointerTypes.IsType(sourceType)
            || NativeFunctionPointerTypes.IsType(proofType))
        {
            return false;
        }

        var sourceIndexInStructures = (int)sourceType - 100;
        var proofIndexInStructures = (int)proofType - 100;
        if (sourceIndexInStructures >= 0
            && proofIndexInStructures >= 0
            && (uint)sourceIndexInStructures
                < (uint)sourceProgram.Structures.Length
            && (uint)proofIndexInStructures
                < (uint)proofProgram.Structures.Length
            && AreGenericMethodProofStructTypesEquivalent(
                sourceProgram.Structures[sourceIndexInStructures],
                proofProgram.Structures[proofIndexInStructures],
                sourceProgram, proofProgram, depth + 1,
                ref remainingVisits))
        {
            return true;
        }
        return sourceType == proofType
            && IsValidType(sourceType, false, sourceProgram)
            && IsValidType(proofType, false, proofProgram);
    }

    private static bool AreGenericMethodProofClassTypesEquivalent(
        BoundClass? source, BoundClass? proof,
        BoundProgram sourceProgram, BoundProgram proofProgram, int depth,
        ref int remainingVisits)
    {
        if (source is null || proof is null
            || source.Name != proof.Name
            || source.Size != proof.Size
            || source.IsInternal != proof.IsInternal
            || source.IsMutable != proof.IsMutable
            || source.Fields.IsDefault || proof.Fields.IsDefault
            || source.Fields.Length != proof.Fields.Length)
        {
            return false;
        }
        for (var index = 0; index < source.Fields.Length; index++)
        {
            if (!AreGenericMethodProofFieldsEquivalent(
                source.Fields[index], proof.Fields[index], sourceProgram,
                proofProgram, depth + 1, ref remainingVisits))
            {
                return false;
            }
        }
        return true;
    }

    private static bool AreGenericMethodProofStructTypesEquivalent(
        BoundStruct? source, BoundStruct? proof,
        BoundProgram sourceProgram, BoundProgram proofProgram, int depth,
        ref int remainingVisits)
    {
        if (source is null || proof is null
            || source.Name != proof.Name
            || source.Size != proof.Size
            || source.TokenSpanRole != proof.TokenSpanRole
            || source.StandardTypeOrigin != proof.StandardTypeOrigin
            || source.SourceGenericTypeDefinitionIndex
                != proof.SourceGenericTypeDefinitionIndex
            || source.StandardLayoutOnly != proof.StandardLayoutOnly
            || source.IsSequential != proof.IsSequential
            || source.BlittableTargetRequirement
                != proof.BlittableTargetRequirement
            || source.IsTransparent != proof.IsTransparent
            || source.Packing != proof.Packing
            || source.DeclaredAlignment != proof.DeclaredAlignment
            || source.Alignment != proof.Alignment
            || source.RequiredAlignment != proof.RequiredAlignment
            || source.IsUnique != proof.IsUnique
            || source.CleanupMethod != proof.CleanupMethod
            || source.IsPrivate != proof.IsPrivate
            || source.IsInternal != proof.IsInternal
            || source.Fields.IsDefault || proof.Fields.IsDefault
            || source.Fields.Length != proof.Fields.Length)
        {
            return false;
        }
        for (var index = 0; index < source.Fields.Length; index++)
        {
            if (!AreGenericMethodProofFieldsEquivalent(
                source.Fields[index], proof.Fields[index], sourceProgram,
                proofProgram, depth + 1, ref remainingVisits))
            {
                return false;
            }
        }
        return true;
    }

    private static bool AreGenericMethodProofFieldsEquivalent(
        BoundStructField? source, BoundStructField? proof,
        BoundProgram sourceProgram, BoundProgram proofProgram, int depth,
        ref int remainingVisits)
    {
        return source is not null && proof is not null
            && source.Name == proof.Name
            && source.Offset == proof.Offset
            && source.Size == proof.Size
            && source.IsMutable == proof.IsMutable
            && source.IsPrivate == proof.IsPrivate
            && source.IsInternal == proof.IsInternal
            && source.RequiresUnsafeCaller
                == proof.RequiresUnsafeCaller
            && AreGenericMethodProofTypesEquivalent(source.Type,
                proof.Type, sourceProgram, proofProgram, depth + 1,
                ref remainingVisits);
    }

    private static bool AreGenericMethodSignaturesEqual(
        ImmutableArray<BoundGenericMethodSignature> left,
        ImmutableArray<BoundGenericMethodSignature> right,
        BoundProgram sourceProgram, BoundProgram proofProgram)
    {
        // A proof may predate later closed owner specializations; its catalog is a prefix.
        if (left.IsDefault || right.IsDefault || right.Length > left.Length)
        {
            return false;
        }

        var remainingVisits = MaximumAnalysisVisits;
        for (var index = 0; index < right.Length; index++)
        {
            var leftSignature = left[index];
            var rightSignature = right[index];
            if (leftSignature is null || rightSignature is null
                || leftSignature.DefinitionOrdinal
                    != rightSignature.DefinitionOrdinal
                || leftSignature.Name != rightSignature.Name
                || leftSignature.IsPublic != rightSignature.IsPublic
                || leftSignature.RequiresUnsafeCaller
                    != rightSignature.RequiresUnsafeCaller
                || leftSignature.IsStatic != rightSignature.IsStatic
                || leftSignature.IsMutable != rightSignature.IsMutable
                || !AreGenericMethodOwnersEquivalent(
                    leftSignature.Owner, rightSignature.Owner,
                    sourceProgram, proofProgram)
                || leftSignature.Formals.IsDefault
                || rightSignature.Formals.IsDefault
                || leftSignature.Formals.Length
                    != rightSignature.Formals.Length
                || leftSignature.ConstantFormals.IsDefault
                || rightSignature.ConstantFormals.IsDefault
                || leftSignature.ConstantFormals.Length
                    != rightSignature.ConstantFormals.Length
                || leftSignature.FormalOrder.IsDefault
                || rightSignature.FormalOrder.IsDefault
                || !leftSignature.FormalOrder.SequenceEqual(
                    rightSignature.FormalOrder))
            {
                return false;
            }
            for (var formal = 0; formal < leftSignature.Formals.Length;
                formal++)
            {
                var leftFormal = leftSignature.Formals[formal];
                var rightFormal = rightSignature.Formals[formal];
                if (leftFormal is null || rightFormal is null
                    || leftFormal.Ordinal != rightFormal.Ordinal
                    || leftFormal.Name != rightFormal.Name
                    || leftFormal.OwnershipDomain
                        != rightFormal.OwnershipDomain
                    || leftFormal.NullabilityDomain
                        != rightFormal.NullabilityDomain
                    || leftFormal.RequiresBlittable
                        != rightFormal.RequiresBlittable
                    || leftFormal.RequiresWritable
                        != rightFormal.RequiresWritable
                    || leftFormal.InterfaceConstraints.IsDefault
                    || rightFormal.InterfaceConstraints.IsDefault
                    || leftFormal.InterfaceConstraints.Length
                        != rightFormal.InterfaceConstraints.Length
                    || leftFormal.HasTypeDefault
                        != rightFormal.HasTypeDefault
                    || leftFormal.DefaultTypeParameterDependencies.IsDefault
                    || rightFormal
                        .DefaultTypeParameterDependencies.IsDefault
                    || !leftFormal.DefaultTypeParameterDependencies
                        .SequenceEqual(
                            rightFormal
                                .DefaultTypeParameterDependencies)
                    || !leftFormal.Requirements.SequenceEqual(
                        rightFormal.Requirements))
                {
                    return false;
                }
                if (!AreGenericMethodInterfaceConstraintsEqual(
                    leftFormal.InterfaceConstraints,
                    rightFormal.InterfaceConstraints, sourceProgram,
                    proofProgram, ref remainingVisits))
                {
                    return false;
                }
            }
            for (var formal = 0;
                formal < leftSignature.ConstantFormals.Length; formal++)
            {
                var leftFormal =
                    leftSignature.ConstantFormals[formal];
                var rightFormal =
                    rightSignature.ConstantFormals[formal];
                if (leftFormal is null || rightFormal is null
                    || leftFormal.Ordinal != rightFormal.Ordinal
                    || leftFormal.ConstantOrdinal
                        != rightFormal.ConstantOrdinal
                    || leftFormal.Name != rightFormal.Name
                    || leftFormal.Domain is null
                    || rightFormal.Domain is null
                    || !AreGenericMethodConstantDomainTermsEquivalent(
                        leftFormal.Domain, rightFormal.Domain,
                        sourceProgram, proofProgram)
                    || leftFormal.HasDefault != rightFormal.HasDefault
                    || leftFormal.DefaultFormalDependencies.IsDefault
                    || rightFormal.DefaultFormalDependencies.IsDefault
                    || !leftFormal.DefaultFormalDependencies.SequenceEqual(
                        rightFormal.DefaultFormalDependencies))
                {
                    return false;
                }
            }
        }

        return true;
    }

    private static bool AreGenericMethodOwnersEquivalent(
        BoundGenericMethodOwner? source,
        BoundGenericMethodOwner? proof,
        BoundProgram sourceProgram, BoundProgram proofProgram)
    {
        if (source is null || proof is null)
        {
            return source is null && proof is null;
        }

        if (!IsValidGenericMethodOwner(source, sourceProgram)
            || !IsValidGenericMethodOwner(proof, proofProgram)
            || source.SourceGenericTypeDefinitionIndex
                != proof.SourceGenericTypeDefinitionIndex
            || source.TypeArguments.Length != proof.TypeArguments.Length
            || source.ConstantArguments.Length
                != proof.ConstantArguments.Length)
        {
            return false;
        }

        var remainingVisits = MaximumAnalysisVisits;
        if (!AreGenericMethodProofTypesEquivalent(source.ClosedType,
                proof.ClosedType, sourceProgram, proofProgram, 0,
                ref remainingVisits))
        {
            return false;
        }
        for (var index = 0; index < source.TypeArguments.Length; index++)
        {
            if (!AreGenericMethodProofTypesEquivalent(
                source.TypeArguments[index], proof.TypeArguments[index],
                sourceProgram, proofProgram, 0, ref remainingVisits))
            {
                return false;
            }
        }
        for (var index = 0; index < source.ConstantArguments.Length;
            index++)
        {
            if (!AreGenericMethodProofConstantArgumentsEquivalent(
                source.ConstantArguments[index],
                proof.ConstantArguments[index], sourceProgram,
                proofProgram, ref remainingVisits))
            {
                return false;
            }
        }

        return true;
    }

    private static bool AreGenericMethodProofConstantArgumentsEquivalent(
        BoundGenericMethodConstantArgument? source,
        BoundGenericMethodConstantArgument? proof,
        BoundProgram sourceProgram, BoundProgram proofProgram,
        ref int remainingVisits)
    {
        if (source is null || proof is null
            || source.Ordinal != proof.Ordinal
            || source.ConstantOrdinal != proof.ConstantOrdinal
            || source.Kind != proof.Kind
            || source.CallerFormalOrdinal != proof.CallerFormalOrdinal
            || source.CallerDefinitionOrdinal
                != proof.CallerDefinitionOrdinal
            || source.CallerFormalOwnerKind
                != proof.CallerFormalOwnerKind
            || source.CallerConstantFormalOrdinal
                != proof.CallerConstantFormalOrdinal
            || source.Bits != proof.Bits
            || !AreGenericMethodProofTypeTermsEquivalent(source.Domain,
                proof.Domain, sourceProgram, proofProgram, 0,
                ref remainingVisits))
        {
            return false;
        }

        if (source.Kind
            == BoundGenericMethodConstantArgumentKind.Value)
        {
            return AreGenericMethodProofTypesEquivalent(source.DomainType,
                    proof.DomainType, sourceProgram, proofProgram, 0,
                    ref remainingVisits)
                && AreGenericMethodProofTypesEquivalent(
                    source.CarrierType, proof.CarrierType, sourceProgram,
                    proofProgram, 0, ref remainingVisits);
        }

        return source.Kind
                == BoundGenericMethodConstantArgumentKind.Formal
            && source.DomainType == proof.DomainType
            && source.CarrierType == proof.CarrierType;
    }

    private static bool AreGenericMethodProofTypeTermsEquivalent(
        BoundGenericMethodTypeTerm? source,
        BoundGenericMethodTypeTerm? proof,
        BoundProgram sourceProgram, BoundProgram proofProgram,
        int depth, ref int remainingVisits)
    {
        if (source is null || proof is null
            || depth > MaximumDepth || --remainingVisits < 0
            || source.Kind != proof.Kind
            || source.FormalOrdinal != proof.FormalOrdinal
            || source.SourceGenericTypeDefinitionIndex
                != proof.SourceGenericTypeDefinitionIndex
            || source.IsWritable != proof.IsWritable
            || source.IsGarbageCollected != proof.IsGarbageCollected
            || source.IsInitialization != proof.IsInitialization
            || source.IsOptional != proof.IsOptional
            || source.NominalTypeIdentity != proof.NominalTypeIdentity
            || source.ElementCount != proof.ElementCount
            || source.CallingConvention != proof.CallingConvention
            || source.ParameterCount != proof.ParameterCount
            || source.AllowsVoid != proof.AllowsVoid
            || source.TypeArguments.IsDefault
            || proof.TypeArguments.IsDefault
            || source.TypeArguments.Length != proof.TypeArguments.Length
            || source.ConstantArguments.IsDefault
            || proof.ConstantArguments.IsDefault
            || source.ConstantArguments.Length
                != proof.ConstantArguments.Length)
        {
            return false;
        }

        if (source.Kind == BoundGenericMethodTypeTermKind.Concrete
            ? source.ConcreteType == PrimitiveType.Void
                ? proof.ConcreteType != PrimitiveType.Void
                : !AreGenericMethodProofTypesEquivalent(
                    source.ConcreteType, proof.ConcreteType, sourceProgram,
                    proofProgram, depth + 1, ref remainingVisits)
            : source.ConcreteType != proof.ConcreteType)
        {
            return false;
        }

        for (var index = 0; index < source.TypeArguments.Length; index++)
        {
            if (!AreGenericMethodProofTypeTermsEquivalent(
                source.TypeArguments[index], proof.TypeArguments[index],
                sourceProgram, proofProgram, depth + 1,
                ref remainingVisits))
            {
                return false;
            }
        }

        for (var index = 0; index < source.ConstantArguments.Length; index++)
        {
            var sourceArgument = source.ConstantArguments[index];
            var proofArgument = proof.ConstantArguments[index];
            if (sourceArgument.Kind != proofArgument.Kind
                || sourceArgument.FormalOwnerKind
                    != proofArgument.FormalOwnerKind
                || sourceArgument.FormalOrdinal
                    != proofArgument.FormalOrdinal
                || sourceArgument.FormalDefinitionOrdinal
                    != proofArgument.FormalDefinitionOrdinal
                || sourceArgument.Bits != proofArgument.Bits)
            {
                return false;
            }

            if (sourceArgument.Kind
                == BoundGenericMethodTypeConstantArgumentKind.Value)
            {
                if (!AreGenericMethodProofTypesEquivalent(
                        sourceArgument.DomainType, proofArgument.DomainType,
                        sourceProgram, proofProgram, depth + 1,
                        ref remainingVisits)
                    || !AreGenericMethodProofTypesEquivalent(
                        sourceArgument.CarrierType,
                        proofArgument.CarrierType, sourceProgram,
                        proofProgram, depth + 1, ref remainingVisits))
                {
                    return false;
                }
            }
            else if (sourceArgument.DomainType
                    != proofArgument.DomainType
                || sourceArgument.CarrierType
                    != proofArgument.CarrierType)
            {
                return false;
            }
        }

        return true;
    }

    private static bool IsValidGenericMethodOwner(
        BoundGenericMethodOwner? owner, BoundProgram program)
    {
        if (owner is null)
        {
            return true;
        }

        if (owner.TypeArguments.IsDefault
            || owner.ConstantArguments.IsDefault
            || !IsValidType(owner.ClosedType, false, program)
            || ManagedClassTypes.IsOptional(owner.ClosedType)
            || ManagedClassTypes.IsWritable(owner.ClosedType))
        {
            return false;
        }

        if (ManagedClassTypes.IsClass(owner.ClosedType))
        {
            return owner.SourceGenericTypeDefinitionIndex == -1
                && owner.TypeArguments.IsEmpty
                && owner.ConstantArguments.IsEmpty;
        }

        var structureIndex = (int)owner.ClosedType - 100;
        if ((uint)structureIndex >= (uint)program.Structures.Length
            || program.Structures[structureIndex]
                is not BoundStruct structure
            || structure.SourceGenericTypeDefinitionIndex
                != owner.SourceGenericTypeDefinitionIndex)
        {
            return false;
        }

        if (owner.SourceGenericTypeDefinitionIndex == -1)
        {
            return owner.TypeArguments.IsEmpty
                && owner.ConstantArguments.IsEmpty;
        }
        if ((uint)owner.SourceGenericTypeDefinitionIndex
                >= (uint)program.SourceGenericTypeDefinitions.Length
            || program.SourceGenericTypeInstances.IsDefault
            || program.SourceGenericTypeDefinitions[
                    owner.SourceGenericTypeDefinitionIndex]
                is not BoundSourceGenericTypeDefinition definition
            || definition.Formals.IsDefault
            || definition.Formals.Count(static formal =>
                formal.Kind == BoundGenericMethodFormalKind.Type)
                != owner.TypeArguments.Length
            || definition.ConstantFormals.IsDefault
            || definition.ConstantFormals.Length
                != owner.ConstantArguments.Length)
        {
            return false;
        }

        BoundSourceGenericTypeInstance? instance = null;
        foreach (var candidate in program.SourceGenericTypeInstances)
        {
            if (candidate is null
                || candidate.StructureIndex != structureIndex)
            {
                continue;
            }
            if (instance is not null)
            {
                return false;
            }

            instance = candidate;
        }
        if (instance is null
            || instance.DefinitionIndex
                != owner.SourceGenericTypeDefinitionIndex
            || instance.TypeArguments.IsDefault
            || !instance.TypeArguments.SequenceEqual(
                owner.TypeArguments)
            || instance.ConstantArguments.IsDefault
            || instance.ConstantArguments.Length
                != owner.ConstantArguments.Length)
        {
            return false;
        }

        var remainingVisits = MaximumAnalysisVisits;
        for (var ordinal = 0;
            ordinal < instance.ConstantArguments.Length; ordinal++)
        {
            if (!AreGenericMethodProofConstantArgumentsEquivalent(
                instance.ConstantArguments[ordinal],
                owner.ConstantArguments[ordinal], program, program,
                ref remainingVisits))
            {
                return false;
            }
        }

        return owner.TypeArguments.All(typeArgument =>
            IsValidType(typeArgument, false, program));
    }

    private static string? GenericMethodOwnerName(
        BoundGenericMethodOwner? owner, BoundProgram program)
    {
        if (owner is null)
        {
            return null;
        }

        if (ManagedClassTypes.IsClass(owner.ClosedType))
        {
            var classIndex = ManagedClassTypes.ClassIndex(
                owner.ClosedType);
            return (uint)classIndex < (uint)program.Classes.Length
                ? program.Classes[classIndex].Name : null;
        }

        var structureIndex = (int)owner.ClosedType - 100;
        return (uint)structureIndex < (uint)program.Structures.Length
            ? program.Structures[structureIndex].Name : null;
    }

    private static bool IsValidGenericMethodProofReceiver(
        BoundFunction function, BoundGenericMethodSignature signature,
        BoundProgram program)
    {
        if (signature.Owner is not BoundGenericMethodOwner owner
            || signature.IsStatic)
        {
            return !function.Variables.IsDefault;
        }

        if (function.Variables.IsDefaultOrEmpty
            || function.Variables[0] is not BoundVariable receiver
            || receiver.Name != "this")
        {
            return false;
        }

        var expectedType = owner.ClosedType;
        var expectedMutable = signature.IsMutable;
        if (ManagedClassTypes.IsClass(owner.ClosedType))
        {
            var classIndex = ManagedClassTypes.ClassIndex(
                owner.ClosedType);
            if ((uint)classIndex >= (uint)program.Classes.Length)
            {
                return false;
            }

            if (program.Classes[classIndex].IsMutable
                && signature.IsMutable)
            {
                expectedType = ManagedClassTypes.Writable(
                    owner.ClosedType);
            }
            expectedMutable = false;
        }

        return receiver.Type == expectedType
            && receiver.IsMutable == expectedMutable;
    }

    private static bool IsGenericMethodOwnerCompatible(
        BoundGenericMethodInstantiation? instantiation,
        BoundFunction function, BoundProgram program)
    {
        if (instantiation is null)
        {
            return true;
        }

        var signatures = program.GenericMethodSignatures;
        if (signatures.IsDefault
            || (uint)instantiation.DefinitionOrdinal
                >= (uint)signatures.Length)
        {
            return false;
        }

        var signature = signatures[instantiation.DefinitionOrdinal];
        if (signature is null
            || !IsValidGenericMethodOwner(signature.Owner, program)
            || signature.IsStatic != function.IsStatic
            || GenericMethodOwnerName(signature.Owner, program)
                != function.DeclaringStruct)
        {
            return false;
        }

        if (signature.Owner is null || signature.IsStatic)
        {
            return true;
        }

        var expectedType = signature.Owner.ClosedType;
        var expectedMutable = signature.IsMutable;
        if (ManagedClassTypes.IsClass(signature.Owner.ClosedType))
        {
            var classIndex = ManagedClassTypes.ClassIndex(
                signature.Owner.ClosedType);
            if ((uint)classIndex >= (uint)program.Classes.Length)
            {
                return false;
            }

            if (program.Classes[classIndex].IsMutable
                && signature.IsMutable)
            {
                expectedType = ManagedClassTypes.Writable(
                    signature.Owner.ClosedType);
            }
            expectedMutable = false;
        }

        return !function.Variables.IsDefaultOrEmpty
            && function.Variables[0] is BoundVariable receiver
            && receiver.Name == "this"
            && receiver.Type == expectedType
            && receiver.IsMutable == expectedMutable;
    }

    private static bool IsValidGenericMethodImport(
        BoundGenericMethodImport? import)
    {
        if (import is null)
        {
            return true;
        }

        var origin = import.Origin;
        var signature = import.Signature;
        return origin is not null
            && !string.IsNullOrEmpty(origin.ProviderIdentity)
            && (origin.IsMethodDefTarget
                ? string.IsNullOrEmpty(origin.ExportKey)
                    && (origin.MethodDefId >> 24) == 0x16
                    && (origin.MethodDefId & 0x00FF_FFFF) != 0
                : !string.IsNullOrEmpty(origin.ExportKey)
                    && (origin.MethodDefId >> 24) == 0x16
                    && (origin.MethodDefId & 0x00FF_FFFF) != 0)
            && StandardGenericMethodSchema.IsGenericMethodCalls(
                origin.SchemaIdentity)
            && origin.TargetRequirement <= 1
            && origin.RuntimePolicy <= 1
            && !origin.ProviderArtifactDigest.IsDefault
            && origin.ProviderArtifactDigest.Length == SHA256.HashSizeInBytes
            && signature is not null
            && signature.Owner is null
            && signature.IsStatic
            && signature.ConstantFormals.IsEmpty
            && !signature.Formals.IsDefault
            && signature.Formals.Length == import.Formals.Length
            && !signature.FormalOrder.IsDefault
            && signature.FormalOrder.Length == import.Formals.Length
            && !import.Formals.IsDefault
            && !import.ProofSupportFunctions.IsDefault
            && import.ProofSupportFunctions.Length
                <= MaximumFunctions
            && import.ProofSupportFunctions.All(
                static supportFunction => supportFunction is not null
                    && supportFunction.IsExternal
                    && supportFunction.IsPrivate
                    && !supportFunction.IsStatic
                    && supportFunction.DeclaringStruct is null
                    && supportFunction.InterfaceRequirement is not null
                    && supportFunction.GenericMethodProofCall is null
                    && supportFunction.ParameterCount
                        <= supportFunction.Variables.Length)
            && import.ProofFunction is not null
            && !import.ProofFunction.IsExternal
            && import.ProofFunction.ParameterCount
                <= import.ProofFunction.Variables.Length
            && IsValidGenericMethodImportSpanTypes(import)
            && IsValidGenericMethodImportSupportFunctions(import)
            && IsValidGenericMethodImportParameterDefaults(import)
            && IsValidGenericMethodImportBinding(import);
    }

    private static bool IsValidGenericMethodImportParameterDefaults(
        BoundGenericMethodImport import)
    {
        var defaults = import.OrdinaryParameterDefaults;
        if (defaults.IsDefault)
        {
            return false;
        }

        var parameterCount = import.ProofFunction.ParameterCount;
        if (!StringComparer.Ordinal.Equals(import.Origin.SchemaIdentity,
                StandardGenericMethodSchema
                    .C1M1Construction2ParameterLabelsReceiverAccessClassParameterDefaults))
        {
            return defaults.IsEmpty
                || defaults.Length == parameterCount
                    && defaults.All(static value => value is null);
        }

        if (defaults.Length != parameterCount)
        {
            return false;
        }

        for (var ordinal = 0; ordinal < defaults.Length; ordinal++)
        {
            var parameterDefault = defaults[ordinal];
            if (parameterDefault is null)
            {
                continue;
            }

            var parameter = import.ProofFunction.Variables[ordinal];
            if (parameterDefault.ParameterIndex != ordinal
                || !StringComparer.Ordinal.Equals(
                    parameterDefault.ParameterName, parameter.Name)
                || parameterDefault.ParameterType != parameter.Type
                || parameterDefault.Value is not BoundConstant value
                || value.Type != parameter.Type
                || !parameterDefault.FormalDependencies.IsEmpty
                || !value.Bits.IsCanonicalFor(parameter.Type)
                || (parameter.Type is PrimitiveType.NativeInt
                    or PrimitiveType.NativeUInt))
            {
                return false;
            }
        }

        return true;
    }

    private static bool IsValidGenericMethodImportSpanTypes(
        BoundGenericMethodImport import)
    {
        if (import.FormalTypeOwnerOrdinal < 0
            || import.FormalTypeOwnerOrdinal >= MaximumAnalysisVisits
            || !BoundSpanTypeContract.TryCreateTypeIdentityIndex(
                import.SpanTypes, out _))
        {
            return false;
        }

        var formalOwner = BoundSpanTypeContract
            .ImportedFormalDefinitionOrdinal
            - import.FormalTypeOwnerOrdinal;
        foreach (var spanType in import.SpanTypes)
        {
            if (spanType.ElementFormalDefinitionOrdinal != formalOwner)
            {
                continue;
            }

            var formalOrdinal = spanType.ElementFormalOrdinal;
            if ((uint)formalOrdinal >= (uint)import.Formals.Length
                || import.Formals[formalOrdinal].PlaceholderType
                    != spanType.ElementType
                || (spanType.IsElementWritable
                    && !import.Formals[formalOrdinal].RequiresWritable))
            {
                return false;
            }
        }

        return IsValidImportedSpanTypeUse(import.ProofFunction, import,
            formalOwner);
    }

    private static bool IsValidImportedSpanTypeUse(
        BoundFunction function, BoundGenericMethodImport import,
        int formalOwner)
    {
        if (function.Variables.IsDefault)
        {
            return false;
        }

        var valid = function.Variables.All(variable =>
            IsValidImportedSpanTypeUse(variable.Type, import,
                formalOwner))
            && IsValidImportedSpanTypeUse(function.ReturnType, import,
                formalOwner);
        if (!valid)
        {
            return false;
        }

        if (function.GenericMethodInstantiation
                is BoundGenericMethodInstantiation instantiation
            && (instantiation.TypeArguments.IsDefault
                || instantiation.TypeArguments.Any(type =>
                    !IsValidImportedSpanTypeUse(type, import,
                        formalOwner))))
        {
            return false;
        }
        if (function.GenericMethodProofCall
                is BoundGenericMethodInstantiation proofCall
            && (proofCall.TypeArguments.IsDefault
                || proofCall.TypeArguments.Any(type =>
                    !IsValidImportedSpanTypeUse(type, import,
                        formalOwner))))
        {
            return false;
        }
        if (!function.ImportedGenericMethodTypeArguments.IsDefaultOrEmpty
            && function.ImportedGenericMethodTypeArguments.Any(type =>
                !IsValidImportedSpanTypeUse(type, import, formalOwner)))
        {
            return false;
        }

        return BoundTreeTraversal.VisitExpressions(function.Body,
            expression =>
            {
                valid &= IsValidImportedSpanTypeUse(expression.Type, import,
                    formalOwner);
                if (expression is BoundCall call)
                {
                    if (call.GenericMethodCall
                            is BoundGenericMethodInstantiation genericCall)
                    {
                        valid &= !genericCall.TypeArguments.IsDefault
                            && genericCall.TypeArguments.All(type =>
                                IsValidImportedSpanTypeUse(type, import,
                                    formalOwner));
                    }
                    if (!call.ImportedGenericMethodTypeArguments
                        .IsDefaultOrEmpty)
                    {
                        valid &= call.ImportedGenericMethodTypeArguments
                            .All(type =>
                                IsValidImportedSpanTypeUse(type, import,
                                    formalOwner));
                    }
                }
            }) && valid;
    }

    private static bool IsValidImportedSpanTypeUse(PrimitiveType type,
        BoundGenericMethodImport import, int formalOwner, int depth = 0)
    {
        if (!BoundSpanTypeTypes.IsType(type))
        {
            return true;
        }
        if (depth > MaximumDepth
            || !BoundSpanTypeTypes.IsValidType(type, import.SpanTypes))
        {
            return false;
        }

        var spanType = import.SpanTypes[BoundSpanTypeTypes.Index(type)];
        if (spanType.ElementFormalDefinitionOrdinal != -1
            && spanType.ElementFormalDefinitionOrdinal != formalOwner)
        {
            return false;
        }
        if (spanType.ElementFormalDefinitionOrdinal == formalOwner)
        {
            var formalOrdinal = spanType.ElementFormalOrdinal;
            if ((uint)formalOrdinal >= (uint)import.Formals.Length
                || import.Formals[formalOrdinal].PlaceholderType
                    != spanType.ElementType
                || (spanType.IsElementWritable
                    && !import.Formals[formalOrdinal].RequiresWritable))
            {
                return false;
            }
        }

        return IsValidImportedSpanTypeUse(spanType.ElementType, import,
            formalOwner, depth + 1);
    }

    private static bool IsValidGenericMethodImportSupportFunctions(
        BoundGenericMethodImport import)
    {
        var supportFunctions = import.ProofSupportFunctions;
        var usedSupportFunctions = new bool[supportFunctions.Length];
        var valid = true;
        var visited = BoundTreeTraversal.VisitExpressions(
            import.ProofFunction.Body, expression =>
            {
                if (expression is not BoundCall call
                    || call.InterfaceCallIdentity is not
                        BoundInterfaceCallIdentity identity)
                {
                    return;
                }

                if ((uint)call.Function
                        >= (uint)supportFunctions.Length
                    || supportFunctions[call.Function]
                        .InterfaceRequirement
                        is not BoundInterfaceMemberIdentity requirement
                    || !identity.IsConstraintCall
                    || !BoundInterfaceContract.AreEquivalent(
                        requirement, identity.Requirement)
                    || supportFunctions[call.Function].ParameterCount
                        != call.Arguments.Length)
                {
                    valid = false;
                    return;
                }

                usedSupportFunctions[call.Function] = true;
            });
        return valid && visited
            && usedSupportFunctions.All(static used => used);
    }

    private static bool IsValidGenericMethodImportBinding(
        BoundGenericMethodImport import)
    {
        if (import.Binding is not BoundGenericMethodImportBinding binding)
        {
            return true;
        }

        var expected = binding.Expected;
        var provider = binding.Provider;
        if (binding.ImportRow is < 1 or > 0x00FF_FFFF
            || binding.ModuleRefRow is < 1 or > 0x00FF_FFFF
            || expected is null || provider is null
            || binding.ExpectedInterfaceDefinitions.IsDefault
            || binding.ExpectedInterfaceDefinitions.Length
                > MaximumAnalysisVisits
            || expected.Binding is not null || provider.Binding is not null
            || ReferenceEquals(import, expected)
            || ReferenceEquals(import, provider)
            || !import.Origin.IsMethodDefTarget
            || import.Origin != expected.Origin
            || !ReferenceEquals(import.Signature, expected.Signature)
            || import.Formals != expected.Formals
            || !expected.ProofFunction.IsExternal
            || !IsValidGenericMethodImport(provider)
            || provider.Origin.IsMethodDefTarget
            || !StringComparer.Ordinal.Equals(binding.ProviderIdentity,
                provider.Origin.ProviderIdentity)
            || !StringComparer.Ordinal.Equals(binding.ExportKey,
                provider.Origin.ExportKey)
            || binding.TargetRequirement != provider.Origin.TargetRequirement
            || binding.RuntimePolicy != provider.Origin.RuntimePolicy)
        {
            return false;
        }

        var function = import.ProofFunction;
        var expectedFunction = expected.ProofFunction;
        return function.ReturnType == expectedFunction.ReturnType
            && function.ParameterCount == expectedFunction.ParameterCount
            && function.RequiresUnsafeCaller
                == expectedFunction.RequiresUnsafeCaller
            && function.DoesNotReturn == expectedFunction.DoesNotReturn
            && ReferenceEquals(function.Body, provider.ProofFunction.Body)
            && import.ProofSupportFunctions
                .SequenceEqual(provider.ProofSupportFunctions)
            && function.Variables.Take(function.ParameterCount)
                .Select(static variable =>
                    (variable.Type, variable.IsOut, variable.IsInit))
                .SequenceEqual(expectedFunction.Variables
                    .Select(static variable =>
                        (variable.Type, variable.IsOut, variable.IsInit)));
    }

    private static bool AreGenericMethodImportCallsEqual(
        BoundCall call, BoundFunction target)
    {
        if (call.ImportedGenericMethodCall is not
            BoundGenericMethodImport imported)
        {
            return target.ImportedGenericMethod is null
                && call.ImportedGenericMethodTypeArguments.IsEmpty
                && target.ImportedGenericMethodTypeArguments.IsEmpty;
        }

        return ReferenceEquals(imported, target.ImportedGenericMethod)
            && call.ImportedGenericMethodTypeArguments.Length
                == imported.Formals.Length
            && call.ImportedGenericMethodTypeArguments.SequenceEqual(
                target.ImportedGenericMethodTypeArguments);
    }

    private static bool IsValidGenericMethodTypeIdentitySpecialization(
        BoundFunction function, BoundProgram program)
    {
        if (function.GenericMethodInstantiation is not
            BoundGenericMethodInstantiation instantiation)
        {
            return true;
        }

        var specializedQueries = new List<BoundTypeIdentityQuery>();
        if (!BoundTreeTraversal.VisitExpressions(function.Body,
                expression =>
                {
                    if (expression is BoundTypeIdentityQuery query)
                    {
                        specializedQueries.Add(query);
                    }
                }))
        {
            return false;
        }
        if (specializedQueries.Count == 0)
        {
            return true;
        }

        var definitionOrdinal = instantiation.DefinitionOrdinal;
        if ((uint)definitionOrdinal
                >= (uint)program.GenericMethodDefinitions.Length
            || function.SourceInputOrdinal
                != program.GenericMethodDefinitions[definitionOrdinal]
                    .SourceInputOrdinal)
        {
            return false;
        }

        var definition
            = program.GenericMethodDefinitions[definitionOrdinal];
        var proofProgram = definition.ProofProgram;
        if (definition.DefinitionOrdinal != definitionOrdinal
            || (uint)definition.FunctionIndex
                >= (uint)proofProgram.Functions.Length)
        {
            return false;
        }

        var proofFunction = proofProgram.Functions[
            definition.FunctionIndex];
        if (proofFunction.GenericMethodProofDefinitionOrdinal
            != definitionOrdinal)
        {
            return false;
        }

        var proofQueries = new List<BoundTypeIdentityQuery>();
        if (!BoundTreeTraversal.VisitExpressions(proofFunction.Body,
                expression =>
                {
                    if (expression is BoundTypeIdentityQuery query)
                    {
                        proofQueries.Add(query);
                    }
                }))
        {
            return false;
        }

        var typeArguments = ImmutableArray.CreateBuilder<
            BoundGenericMethodTypeTerm>(
                instantiation.TypeArguments.Length);
        foreach (var typeArgument in instantiation.TypeArguments)
        {
            if (!TryGetGenericMethodActualTypeTerm(typeArgument, function,
                    program, 0, out var typeTerm))
            {
                return false;
            }
            typeArguments.Add(typeTerm);
        }

        if (instantiation.ConstantArguments.IsDefault)
        {
            return false;
        }
        var constantArguments = ImmutableArray.CreateBuilder<
            BoundGenericMethodConstantArgument?>(
                instantiation.ConstantArguments.Length);
        foreach (var constantArgument in instantiation.ConstantArguments)
        {
            constantArguments.Add(constantArgument);
        }

        var checkedTypeArguments = typeArguments.MoveToImmutable();
        var checkedConstantArguments
            = constantArguments.MoveToImmutable();
        var usedProofQueries = new bool[proofQueries.Count];
        foreach (var specializedQuery in specializedQueries)
        {
            var proofQueryIndex = -1;
            for (var index = 0; index < proofQueries.Count; index++)
            {
                var proofQuery = proofQueries[index];
                if (!usedProofQueries[index]
                    && proofQuery.Span == specializedQuery.Span
                    && proofQuery.Subject.Kind
                        == specializedQuery.Subject.Kind)
                {
                    proofQueryIndex = index;
                    break;
                }
            }
            if (proofQueryIndex < 0)
            {
                return false;
            }

            usedProofQueries[proofQueryIndex] = true;
            var proofSubject = proofQueries[proofQueryIndex].Subject;
            if (!TryGetGenericQueryTypeIdentityTerm(proofSubject.Type,
                    proofFunction, proofProgram, 0, out var proofTerm)
                || !BoundGenericMethodTypeTerms.TryGetFormalDependencies(
                    proofTerm, out var formalDependencies)
                || !BoundGenericMethodTypeTerms
                    .TryGetConstantFormalDependencies(proofTerm,
                        out var constantFormalDependencies))
            {
                return false;
            }
            if ((formalDependencies.IsEmpty
                    && constantFormalDependencies.IsEmpty)
                != (proofSubject.TypeIdentityTerm is null)
                || (proofSubject.TypeIdentityTerm is
                        BoundGenericMethodTypeTerm recordedProofTerm
                    && !AreGenericMethodTypeTermsEqual(recordedProofTerm,
                        proofTerm, 0)))
            {
                return false;
            }

            var proofDefault
                = new BoundGenericMethodTypeDefault(proofTerm,
                    formalDependencies) {
                    ConstantFormalDependencies
                        = constantFormalDependencies,
                };
            if (!BoundGenericMethodTypeTerms.TrySubstitute(proofDefault,
                    checkedTypeArguments, checkedConstantArguments,
                    out var specializedDefault)
                || !TryGetGenericMethodActualTypeTerm(
                    specializedQuery.Subject.Type, function, program, 0,
                    out var specializedTerm)
                || !AreGenericMethodTypeTermsEqual(
                    specializedDefault.Term, specializedTerm, 0)
                || (specializedQuery.Subject.TypeIdentityTerm is
                        BoundGenericMethodTypeTerm recordedSpecializedTerm
                    && !AreGenericMethodTypeTermsEqual(
                        specializedDefault.Term, recordedSpecializedTerm, 0)))
            {
                return false;
            }
        }

        return true;
    }

    internal static bool IsGenericMethodFormalContractSatisfied(
        byte targetOwnershipDomain, byte targetNullabilityDomain,
        bool targetRequiresWritable, bool targetRequiresBlittable,
        byte actualOwnershipDomain, byte actualNullabilityDomain,
        bool actualRequiresWritable, bool actualRequiresBlittable)
        => targetOwnershipDomain is 1 or 2 or 3
            && targetNullabilityDomain is 1 or 2
            && actualOwnershipDomain is 1 or 2 or 3
            && actualNullabilityDomain is 1 or 2
            && (targetOwnershipDomain != 1
                || actualOwnershipDomain == 1)
            && (targetOwnershipDomain != 2
                || actualOwnershipDomain == 2)
            && (targetNullabilityDomain != 1
                || actualNullabilityDomain == 1)
            && (!targetRequiresWritable || actualRequiresWritable)
            && (!targetRequiresBlittable || actualRequiresBlittable);

    private static bool IsValidGenericMethodInstantiation(
        BoundGenericMethodInstantiation? instantiation,
        BoundProgram program, BoundFunction? callerFunction = null,
        InitializationState? callerState = null)
    {
        if (instantiation is null)
        {
            return true;
        }
        var signatures = program.GenericMethodSignatures;
        if (signatures.IsDefault
            || (uint)instantiation.DefinitionOrdinal
                >= (uint)signatures.Length
            || instantiation.TypeArguments.IsDefault
            || instantiation.TypeArguments.Length
                != signatures[instantiation.DefinitionOrdinal].Formals.Length)
        {
            return false;
        }

        var signature = signatures[instantiation.DefinitionOrdinal];
        if (!IsValidGenericMethodOwner(signature.Owner, program)
            || (signature.Owner is null
                && (!signature.IsStatic || signature.IsMutable))
            || (signature.IsStatic && signature.IsMutable))
        {
            return false;
        }

        var formals = signature.Formals;
        for (var ordinal = 0;
            ordinal < instantiation.TypeArguments.Length; ordinal++)
        {
            var typeArgument = instantiation.TypeArguments[ordinal];
            var formal = formals[ordinal];
            if (!BoundGenericNominalTypeContract.IsValidConstantFormalUse(
                    typeArgument, callerFunction, program))
            {
                return false;
            }
            var isUnique = IsUniqueGenericMethodTypeArgument(
                typeArgument, program);
            var isCopy = IsCopyGenericMethodTypeArgument(
                typeArgument, program);
            if (callerFunction is not null
                && callerState is not null
                && TryGetCallerGenericTypeFormal(callerFunction,
                    program, typeArgument, out var callerFormal,
                    out var callerOrdinal))
            {
                if (callerFormal is null)
                {
                    return false;
                }
                var callerOwnershipDomain = callerFormal.OwnershipDomain;
                if (callerState.TryGetGenericUniqueProperty(
                    callerOrdinal, out var refinedUnique))
                {
                    callerOwnershipDomain = refinedUnique ? (byte)2 : (byte)1;
                }

                if (!IsValidType(typeArgument, false, program)
                    || !IsGenericMethodFormalContractSatisfied(
                        formal.OwnershipDomain,
                        formal.NullabilityDomain,
                        formal.RequiresWritable,
                        formal.RequiresBlittable,
                        callerOwnershipDomain,
                        callerFormal.NullabilityDomain,
                        callerFormal.RequiresWritable,
                        callerFormal.RequiresBlittable))
                {
                    return false;
                }
                continue;
            }

            if (!IsValidType(typeArgument, false, program)
                || (formal.OwnershipDomain == 1
                    && (!isCopy || isUnique))
                || (formal.OwnershipDomain == 2 && !isUnique)
                || (formal.OwnershipDomain == 3
                    && !isCopy && !isUnique)
                || (formal.NullabilityDomain == 1
                    && IsSupportedOptionalType(typeArgument, program))
                || (formal.RequiresBlittable
                    && !IsBlittableGenericMethodArgument(
                        typeArgument, program))
                || (formal.RequiresWritable
                    && !IsWritableGenericMethodTypeArgument(
                        typeArgument, program)))
            {
                return false;
            }
        }

        return IsValidGenericMethodConstantArguments(instantiation,
            signature, program, callerFunction);
    }

    internal static bool IsValidGenericNominalConstantFormalBindings(
        BoundProgram program)
    {
        for (var instanceIndex = 0;
            instanceIndex < program.GenericNominalTypeInstances.Length;
            instanceIndex++)
        {
            var instance = program.GenericNominalTypeInstances[instanceIndex];
            if (instance.Arguments.IsDefault)
            {
                return false;
            }

            var definition = program.GenericNominalTypeDefinitions
                .FirstOrDefault(candidate =>
                    candidate.Identity == instance.Definition);
            if (definition is null)
            {
                return false;
            }

            BoundFunction? callerFunction = null;
            var methodOwnerOrdinals = instance.Arguments
                .Where(static argument =>
                    argument.HasConstantFormalIdentity
                    && argument.ConstantFormalOwnerKind
                        == BoundGenericTypeFormalOwnerKind.GenericMethod)
                .Select(static argument =>
                    argument.ConstantFormalDefinitionOrdinal)
                .Distinct().Take(2).ToArray();
            if (methodOwnerOrdinals.Length > 1)
            {
                return false;
            }
            var sourceOwnerOrdinals = instance.Arguments
                .Where(static argument =>
                    argument.HasConstantFormalIdentity
                    && argument.ConstantFormalOwnerKind
                        == BoundGenericTypeFormalOwnerKind.SourceGenericType)
                .Select(static argument =>
                    argument.ConstantFormalDefinitionOrdinal)
                .Distinct().Take(2).ToArray();
            if (sourceOwnerOrdinals.Length > 1)
            {
                return false;
            }
            if (methodOwnerOrdinals.Length != 0)
            {
                callerFunction = program.Functions.FirstOrDefault(function =>
                    function.GenericMethodProofDefinitionOrdinal
                        == methodOwnerOrdinals[0]);
                if (callerFunction is null)
                {
                    return false;
                }
            }
            else if (sourceOwnerOrdinals.Length != 0)
            {
                // Resolve open owner type arguments in their exact proof context.
                var matchingOwnerFunctions = program.Functions.Where(
                    function =>
                    {
                        var definitionOrdinal
                            = function.GenericMethodProofDefinitionOrdinal;
                        return (uint)definitionOrdinal
                                < (uint)program.GenericMethodSignatures.Length
                            && program.GenericMethodSignatures[
                                definitionOrdinal]?.Owner
                                is BoundGenericMethodOwner owner
                            && owner.SourceGenericTypeDefinitionIndex
                                == sourceOwnerOrdinals[0];
                    }).Take(2).ToArray();
                if (matchingOwnerFunctions.Length > 1)
                {
                    return false;
                }
                if (matchingOwnerFunctions.Length == 1)
                {
                    callerFunction = matchingOwnerFunctions[0];
                }
            }
            if (instance.Arguments.Any(static argument =>
                    argument.HasConstantFormalIdentity)
                && !BoundGenericNominalTypeContract
                    .IsValidConstantFormalUse(
                        BoundGenericNominalTypeTypes.Type(instanceIndex),
                        callerFunction, program))
            {
                return false;
            }

            var typeArguments = ImmutableArray.CreateBuilder<
                BoundGenericMethodTypeTerm>(
                    definition.Formals.Count(static formal =>
                        formal.Kind == BoundGenericArgumentKind.Type));
            for (var ordinal = 0; ordinal < definition.Formals.Length;
                ordinal++)
            {
                if (definition.Formals[ordinal].Kind
                    != BoundGenericArgumentKind.Type)
                {
                    continue;
                }

                var argument = instance.Arguments[ordinal];
                if (argument.Kind != BoundGenericArgumentKind.Type
                    || !TryGetGenericMethodActualTypeTerm(argument.Type,
                        callerFunction, program, 0, out var typeTerm))
                {
                    return false;
                }

                var qualifiedArgument = ApplyGenericQueryTypeQualifiers(
                    typeTerm, argument.Qualifiers);
                if (!TryNormalizeGenericQueryFormalWriteQualifier(
                        qualifiedArgument, callerFunction, program,
                        out var normalizedArgument))
                {
                    return false;
                }
                typeArguments.Add(normalizedArgument);
            }

            var checkedTypeArguments = typeArguments.MoveToImmutable();
            for (var ordinal = 0; ordinal < definition.Formals.Length;
                ordinal++)
            {
                var formal = definition.Formals[ordinal];
                var argument = instance.Arguments[ordinal];
                if (formal.Kind != BoundGenericArgumentKind.Constant
                    || formal.ConstantDomainTypeTerm is not
                        BoundGenericMethodTypeTerm domainTemplate)
                {
                    continue;
                }

                if (!BoundGenericMethodTypeTerms.TrySubstitute(
                    domainTemplate, checkedTypeArguments, [],
                    out var expectedDomain)
                    || !BoundGenericMethodTypeTerms
                        .TryGetFormalDependencies(expectedDomain,
                            out var domainTypeDependencies)
                    || !BoundGenericMethodTypeTerms
                        .TryGetConstantFormalDependencies(expectedDomain,
                            out var domainConstantDependencies)
                    || !domainConstantDependencies.IsEmpty)
                {
                    return false;
                }

                if (argument.HasConstantFormalIdentity)
                {
                    if (!AreGenericMethodTypeTermsEqual(
                            argument.ConstantFormalDomain,
                            expectedDomain, 0))
                    {
                        return false;
                    }
                    continue;
                }

                if (argument.HasDecodedConstant)
                {
                    if (!domainTypeDependencies.IsEmpty
                        || !TryGetGenericMethodConstantValueDomain(
                            expectedDomain, callerFunction, program,
                            out var domainType, out var carrierType)
                        || argument.ConstantDomainType != domainType
                        || argument.ConstantCarrierType != carrierType
                        || !new ScalarBits(argument.ConstantLow,
                            argument.ConstantHigh)
                            .IsCanonicalFor(carrierType))
                    {
                        return false;
                    }
                    continue;
                }

                if (argument.ConstantProviderIdentity is not null
                    && !domainTypeDependencies.IsEmpty)
                {
                    return false;
                }
            }
        }

        return true;
    }

    internal static bool IsValidGenericNominalTypeFormalBindings(
        BoundProgram program)
    {
        if (program.GenericMethodTypeFormalOwners.IsDefault)
        {
            return false;
        }

        var formalOwners = new Dictionary<int,
            ImmutableArray<BoundGenericTypeFormal>>();
        foreach (var owner in program.GenericMethodTypeFormalOwners)
        {
            if (owner.Ordinal < 0)
            {
                if (owner.TypeFormalCount != 0 || owner.Formals.IsDefault)
                {
                    return false;
                }
                continue;
            }
            if (owner.Ordinal >= BoundSpanTypeTypes.MaximumCount
                || owner.Formals.IsDefault
                || owner.TypeFormalCount
                    > MaximumArguments)
            {
                return false;
            }
            for (var formalOrdinal = 0;
                formalOrdinal < owner.Formals.Length; formalOrdinal++)
            {
                var formal = owner.Formals[formalOrdinal];
                if (formal.Ordinal != formalOrdinal
                    || formal.OwnershipDomain is < 1 or > 3
                    || formal.NullabilityDomain is < 1 or > 2)
                {
                    return false;
                }
            }
            if (formalOwners.TryGetValue(owner.Ordinal,
                    out var existingFormals))
            {
                if (!existingFormals.AsSpan().SequenceEqual(
                        owner.Formals.AsSpan()))
                {
                    return false;
                }
            }
            else
            {
                formalOwners.Add(owner.Ordinal, owner.Formals);
            }
        }

        foreach (var definition in program.GenericMethodDefinitions)
        {
            if (definition.FormalTypeOwnerOrdinal >= 0
                && !MatchesOwner(definition.FormalTypeOwnerOrdinal,
                    definition.Formals))
            {
                return false;
            }
        }
        foreach (var function in program.Functions)
        {
            if (function.ImportedGenericMethod is
                BoundGenericMethodImport import
                && import.FormalTypeOwnerOrdinal >= 0
                && !MatchesOwner(import.FormalTypeOwnerOrdinal,
                    import.Formals))
            {
                return false;
            }

            if (function.GenericMethodProofTypeFormalOwnerOrdinal >= 0
                && !MatchesProofOwner(function))
            {
                return false;
            }
        }

        foreach (var instance in program.GenericNominalTypeInstances)
        {
            foreach (var argument in instance.Arguments)
            {
                if (argument.TypeArgumentTerm is
                    BoundGenericMethodTypeTerm typeArgumentTerm)
                {
                    if (!BoundGenericMethodTypeTerms
                            .TryGetFormalDependencies(typeArgumentTerm,
                                out var dependencies)
                        || !BoundGenericMethodTypeTerms
                            .TryGetConstantFormalDependencies(
                                typeArgumentTerm, out _)
                        || (!dependencies.IsEmpty
                            && !argument.HasTypeFormalOwnerIdentity))
                    {
                        return false;
                    }
                }

                if (!argument.HasTypeFormalOwnerIdentity)
                {
                    continue;
                }

                if (!formalOwners.TryGetValue(
                        argument.TypeFormalDefinitionOrdinal,
                        out var formals)
                    || (argument.TypeFormalOrdinal >= 0
                        && argument.TypeFormalOrdinal >= formals.Length)
                    || (argument.TypeArgumentTerm is
                            BoundGenericMethodTypeTerm typeTerm
                        && BoundGenericMethodTypeTerms
                            .TryGetFormalDependencies(typeTerm,
                                out var termDependencies)
                        && termDependencies.Any(dependency =>
                            (uint)dependency >= (uint)formals.Length)))
                {
                    return false;
                }
            }
        }

        return true;

        bool MatchesOwner(int ownerOrdinal,
            ImmutableArray<BoundGenericMethodFormal> formals)
        {
            if (!formalOwners.TryGetValue(ownerOrdinal,
                    out var ownerFormals)
                || formals.IsDefault
                || ownerFormals.Length != formals.Length)
            {
                return false;
            }

            for (var formalOrdinal = 0;
                formalOrdinal < formals.Length; formalOrdinal++)
            {
                var sourceFormal = formals[formalOrdinal];
                var ownerFormal = ownerFormals[formalOrdinal];
                if (ownerFormal.Ordinal != sourceFormal.Ordinal
                    || ownerFormal.PlaceholderType
                        != sourceFormal.PlaceholderType
                    || ownerFormal.OwnershipDomain
                        != sourceFormal.OwnershipDomain
                    || ownerFormal.NullabilityDomain
                        != sourceFormal.NullabilityDomain
                    || ownerFormal.RequiresWritable
                        != sourceFormal.RequiresWritable
                    || ownerFormal.RequiresBlittable
                        != sourceFormal.RequiresBlittable)
                {
                    return false;
                }
            }

            return true;
        }

        bool MatchesProofOwner(BoundFunction function)
        {
            var definitionOrdinal
                = function.GenericMethodProofDefinitionOrdinal;
            var ownerOrdinal
                = function.GenericMethodProofTypeFormalOwnerOrdinal;
            if ((uint)definitionOrdinal
                    >= (uint)program.GenericMethodSignatures.Length
                || !formalOwners.TryGetValue(ownerOrdinal,
                    out var ownerFormals)
                || function.GenericMethodProofTypeParameters.IsDefault)
            {
                return false;
            }

            var signature = program.GenericMethodSignatures[
                definitionOrdinal];
            var formals = signature.Formals;
            if (formals.IsDefault
                || function.GenericMethodProofTypeParameters.Length
                    != formals.Length
                || ownerFormals.Length != formals.Length)
            {
                return false;
            }

            for (var ordinal = 0; ordinal < formals.Length; ordinal++)
            {
                var formal = formals[ordinal];
                var ownerFormal = ownerFormals[ordinal];
                if (formal.Ordinal != ordinal
                    || function.GenericMethodProofTypeParameters[ordinal]
                        != ownerFormal.PlaceholderType
                    || formal.OwnershipDomain
                        != ownerFormal.OwnershipDomain
                    || formal.NullabilityDomain
                        != ownerFormal.NullabilityDomain
                    || formal.RequiresWritable
                        != ownerFormal.RequiresWritable
                    || formal.RequiresBlittable
                        != ownerFormal.RequiresBlittable)
                {
                    return false;
                }
            }

            return true;
        }
    }

    private static bool IsValidGenericMethodConstantFormalUse(
        BoundFunction function, BoundProgram program)
    {
        if (function.IsExternal && function.GenericMethodProofCall is not null)
        {
            return true;
        }

        if (!BoundGenericNominalTypeContract.IsValidConstantFormalUse(
                function.ReturnType, function, program))
        {
            return false;
        }

        foreach (var variable in function.Variables)
        {
            if (!BoundGenericNominalTypeContract.IsValidConstantFormalUse(
                variable.Type, function, program))
            {
                return false;
            }
        }

        var isValid = true;
        return BoundTreeTraversal.VisitExpressions(function.Body,
                expression =>
                {
                    if (!BoundGenericNominalTypeContract
                            .IsValidConstantFormalUse(expression.Type,
                                function, program))
                    {
                        isValid = false;
                    }
                })
            && isValid;
    }

    private static bool IsValidGenericMethodConstantArguments(
        BoundGenericMethodInstantiation instantiation,
        BoundGenericMethodSignature signature, BoundProgram program,
        BoundFunction? callerFunction)
    {
        var actuals = instantiation.ConstantArguments;
        if (actuals.IsDefault
            || actuals.Length != signature.ConstantFormals.Length)
        {
            return false;
        }

        var typeArguments = ImmutableArray.CreateBuilder<
            BoundGenericMethodTypeTerm>(instantiation.TypeArguments.Length);
        foreach (var typeArgument in instantiation.TypeArguments)
        {
            if (!TryGetGenericMethodActualTypeTerm(typeArgument,
                callerFunction, program, 0, out var typeTerm))
            {
                return false;
            }
            typeArguments.Add(typeTerm);
        }
        var checkedTypeArguments = typeArguments.MoveToImmutable();
        var checkedConstantArguments = actuals
            .Select(static actual =>
                (BoundGenericMethodConstantArgument?)actual)
            .ToImmutableArray();

        for (var ordinal = 0; ordinal < actuals.Length; ordinal++)
        {
            var actual = actuals[ordinal];
            var formal = signature.ConstantFormals[ordinal];
            if (actual is null
                || actual.Ordinal != formal.Ordinal
                || actual.ConstantOrdinal != formal.ConstantOrdinal
                || !BoundGenericMethodTypeTerms.TrySubstitute(
                    formal.Domain, checkedTypeArguments,
                    checkedConstantArguments,
                    out var expectedDomain)
                || !AreGenericMethodTypeTermsEqual(actual.Domain,
                    expectedDomain, 0))
            {
                return false;
            }

            if (actual.Kind
                == BoundGenericMethodConstantArgumentKind.Value)
            {
                if (actual.CallerFormalOrdinal != -1
                    || actual.CallerDefinitionOrdinal != -1
                    || actual.CallerConstantFormalOrdinal != -1
                    || actual.CallerFormalOwnerKind
                        != BoundGenericTypeFormalOwnerKind.GenericMethod
                    || !BoundGenericMethodTypeTerms.TryGetFormalDependencies(
                        expectedDomain, out var dependencies)
                    || !dependencies.IsEmpty
                    || !TryGetGenericMethodConstantValueDomain(
                        expectedDomain, callerFunction, program,
                        out var domainType, out var carrierType)
                    || actual.DomainType != domainType
                    || actual.CarrierType != carrierType
                    || !actual.Bits.IsCanonicalFor(carrierType))
                {
                    return false;
                }
                continue;
            }

            if (actual.Kind
                    != BoundGenericMethodConstantArgumentKind.Formal
                || actual.DomainType != PrimitiveType.Void
                || actual.CarrierType != PrimitiveType.Void
                || actual.Bits != default
                || !IsValidGenericMethodConstantFormalForward(
                    actual, expectedDomain, callerFunction, program))
            {
                return false;
            }
        }

        return true;
    }

    private static bool IsValidGenericMethodConstantFormalForward(
        BoundGenericMethodConstantArgument actual,
        BoundGenericMethodTypeTerm expectedDomain,
        BoundFunction? callerFunction, BoundProgram program)
    {
        if (actual.CallerFormalOwnerKind
            == BoundGenericTypeFormalOwnerKind.SourceGenericType)
        {
            return IsValidGenericMethodOwnerConstantFormalForward(
                actual, expectedDomain, callerFunction, program);
        }

        if (callerFunction?.GenericMethodProofDefinitionOrdinal
                is not int callerDefinitionOrdinal
            || actual.CallerFormalOwnerKind
                != BoundGenericTypeFormalOwnerKind.GenericMethod
            || actual.CallerDefinitionOrdinal
                != callerDefinitionOrdinal
            || (uint)callerDefinitionOrdinal
                >= (uint)program.GenericMethodSignatures.Length
            || callerFunction.GenericMethodProofTypeParameters.Length
                != program.GenericMethodSignatures[
                    callerDefinitionOrdinal].Formals.Length)
        {
            return false;
        }

        var callerSignature = program.GenericMethodSignatures[
            callerDefinitionOrdinal];
        var callerFormal = callerSignature.ConstantFormals
            .FirstOrDefault(candidate =>
                candidate.Ordinal == actual.CallerFormalOrdinal);
        if (callerFormal is null
            || callerFormal.ConstantOrdinal
                != actual.CallerConstantFormalOrdinal
            || !AreGenericMethodTypeTermsEqual(callerFormal.Domain,
                expectedDomain, 0)
            || callerFunction.ParameterCount
                < callerSignature.ConstantFormals.Length)
        {
            return false;
        }

        if (!TryGetGenericMethodOwnerProofConstantFormalCount(
                callerSignature.Owner, callerSignature.ConstantFormals,
                program, out var ownerProofFormalCount))
        {
            return false;
        }

        var parameterIndex = callerFunction.ParameterCount
            - ownerProofFormalCount
            - callerSignature.ConstantFormals.Length
            + callerFormal.ConstantOrdinal;
        return (uint)parameterIndex
                < (uint)callerFunction.Variables.Length
            && callerFunction.Variables[parameterIndex].Name
                == callerFormal.Name
            && !callerFunction.Variables[parameterIndex].IsMutable;
    }

    private static bool IsValidGenericMethodOwnerConstantFormalForward(
        BoundGenericMethodConstantArgument actual,
        BoundGenericMethodTypeTerm expectedDomain,
        BoundFunction? callerFunction, BoundProgram program)
    {
        if (callerFunction?.GenericMethodProofDefinitionOrdinal
                is not int callerDefinitionOrdinal
            || (uint)callerDefinitionOrdinal
                >= (uint)program.GenericMethodSignatures.Length
            || (uint)actual.CallerDefinitionOrdinal
                >= (uint)program.SourceGenericTypeDefinitions.Length
            || actual.CallerFormalOrdinal != -1)
        {
            return false;
        }

        var callerSignature = program.GenericMethodSignatures[
            callerDefinitionOrdinal];
        var owner = callerSignature.Owner;
        var ownerDefinition = program.SourceGenericTypeDefinitions[
            actual.CallerDefinitionOrdinal];
        if (owner is null
            || owner.SourceGenericTypeDefinitionIndex
                != actual.CallerDefinitionOrdinal
            || owner.ConstantArguments.IsDefault
            || owner.ConstantArguments.Length
                != ownerDefinition.ConstantFormals.Length
            || (uint)actual.CallerConstantFormalOrdinal
                >= (uint)owner.ConstantArguments.Length)
        {
            return false;
        }

        var ownerFormal = ownerDefinition.ConstantFormals.FirstOrDefault(
            candidate => candidate.ConstantOrdinal
                == actual.CallerConstantFormalOrdinal);
        var ownerArgument = owner.ConstantArguments[
            actual.CallerConstantFormalOrdinal];
        if (ownerFormal is null
            || ownerArgument.Kind
                != BoundGenericMethodConstantArgumentKind.Formal
            || !IsValidGenericMethodConstantFormalIdentity(
                ownerArgument, program)
            || !AreGenericMethodTypeTermsEqual(ownerArgument.Domain,
                expectedDomain, 0)
            || !AreGenericMethodTypeTermsEqual(actual.Domain,
                expectedDomain, 0)
            || !TryGetGenericMethodConstantValueDomain(expectedDomain,
                callerFunction, program, out var domainType,
                out _))
        {
            return false;
        }

        var ownerFormalRank = 0;
        var ownerProofFormalCount = 0;
        foreach (var formal in ownerDefinition.ConstantFormals)
        {
            if (callerSignature.ConstantFormals.Any(methodFormal =>
                    methodFormal.Name == formal.Name))
            {
                continue;
            }

            var argument = owner.ConstantArguments[formal.ConstantOrdinal];
            if (argument.Kind
                != BoundGenericMethodConstantArgumentKind.Formal)
            {
                continue;
            }

            if (!IsValidGenericMethodConstantFormalIdentity(argument,
                program))
            {
                return false;
            }

            if (formal.ConstantOrdinal
                < actual.CallerConstantFormalOrdinal)
            {
                ownerFormalRank++;
            }
            ownerProofFormalCount++;
        }

        var parameterIndex = callerFunction.ParameterCount
            - ownerProofFormalCount + ownerFormalRank;
        return (uint)parameterIndex
                < (uint)callerFunction.Variables.Length
            && callerFunction.Variables[parameterIndex].Name
                == ownerFormal.Name
            && callerFunction.Variables[parameterIndex].Type == domainType
            && !callerFunction.Variables[parameterIndex].IsMutable;
    }

    private static bool TryGetGenericMethodConstantValueDomain(
        BoundGenericMethodTypeTerm domain,
        BoundFunction? callerFunction, BoundProgram program,
        out PrimitiveType domainType, out PrimitiveType carrierType)
    {
        domainType = PrimitiveType.Void;
        carrierType = PrimitiveType.Void;
        if (!TryGetGenericMethodConstantDomainType(domain,
                callerFunction, program, out domainType))
        {
            return false;
        }

        return TryGetGenericMethodConstantCarrierType(domainType, program,
            out carrierType);
    }

    private static bool TryGetGenericMethodConstantCarrierType(
        PrimitiveType domainType, BoundProgram program,
        out PrimitiveType carrierType)
    {
        carrierType = PrimitiveType.Void;
        if (PrimitiveTypeFacts.IsIntegerOrWide(domainType)
            || domainType == PrimitiveType.Bool)
        {
            carrierType = domainType;
            return true;
        }

        if (BoundEnumTypes.IsValidType(domainType,
                program.EnumDefinitions))
        {
            var underlyingType = program.EnumDefinitions[
                BoundEnumTypes.Index(domainType)].UnderlyingType;
            if (!PrimitiveTypeFacts.IsIntegerOrWide(underlyingType))
            {
                return false;
            }
            carrierType = underlyingType;
            return true;
        }

        if (BoundGenericNominalTypeContract.IsValidType(domainType, program))
        {
            var instance = program.GenericNominalTypeInstances[
                BoundGenericNominalTypeTypes.Index(domainType)];
            var definition = program.GenericNominalTypeDefinitions
                .FirstOrDefault(candidate =>
                    candidate.Identity == instance.Definition);
            if (definition?.TransparentConstantCarrierType
                is PrimitiveType nominalCarrier
                && (PrimitiveTypeFacts.IsIntegerOrWide(nominalCarrier)
                    || nominalCarrier == PrimitiveType.Bool))
            {
                carrierType = nominalCarrier;
                return true;
            }

            return false;
        }

        var typeValue = (int)domainType;
        if (typeValue is < 100 or >= BoundEnumTypes.First)
        {
            return false;
        }

        var structureIndex = typeValue - 100;
        if ((uint)structureIndex >= (uint)program.Structures.Length
            || program.Structures[structureIndex] is not BoundStruct {
                IsTransparent: true,
                IsUnique: false,
                BlittableTargetRequirement:
                    FixedLayoutStorage.WindowsX64TargetRequirement,
                Fields: [{ } field],
            }
            || (!PrimitiveTypeFacts.IsIntegerOrWide(field.Type)
                && field.Type != PrimitiveType.Bool))
        {
            return false;
        }

        var sourceGenericDefinitionIndex =
            program.Structures[structureIndex]
                .SourceGenericTypeDefinitionIndex;
        if (sourceGenericDefinitionIndex >= 0
            && ((uint)sourceGenericDefinitionIndex
                    >= (uint)program.SourceGenericTypeDefinitions.Length
                || program.SourceGenericTypeDefinitions[
                    sourceGenericDefinitionIndex]
                    .TransparentConstantCarrierType != field.Type))
        {
            return false;
        }

        carrierType = field.Type;
        return true;
    }

    private static bool TryGetGenericMethodConstantDomainType(
        BoundGenericMethodTypeTerm domain,
        BoundFunction? callerFunction, BoundProgram program,
        out PrimitiveType domainType)
    {
        domainType = PrimitiveType.Void;
        if (domain.Kind == BoundGenericMethodTypeTermKind.Concrete
            && IsValidType(domain.ConcreteType, false, program))
        {
            domainType = domain.ConcreteType;
            return true;
        }
        if (domain.Kind
                == BoundGenericMethodTypeTermKind.ImportedGeneric
            && domain.NominalTypeIdentity
                is BoundGenericNominalTypeIdentity identity)
        {
            for (var index = 0;
                index < program.GenericNominalTypeInstances.Length; index++)
            {
                var candidateType = BoundGenericNominalTypeTypes.Type(index);
                if (!TryGetGenericMethodActualTypeTerm(candidateType,
                        callerFunction, program, 0,
                        out var candidateTerm)
                    || !AreGenericMethodTypeTermsEqual(candidateTerm,
                        domain, 0))
                {
                    continue;
                }

                var candidateInstance
                    = program.GenericNominalTypeInstances[index];
                if (candidateInstance.Definition != identity)
                {
                    return false;
                }
                domainType = candidateType;
                return true;
            }

            return false;
        }
        if (domain.Kind
            != BoundGenericMethodTypeTermKind.SourceGeneric
            || (uint)domain.SourceGenericTypeDefinitionIndex
                >= (uint)program.SourceGenericTypeDefinitions.Length)
        {
            return false;
        }

        foreach (var instance in program.SourceGenericTypeInstances)
        {
            if (instance.DefinitionIndex
                    != domain.SourceGenericTypeDefinitionIndex
                || instance.TypeArguments.IsDefault
                || instance.ConstantArguments.IsDefault)
            {
                continue;
            }

            var instanceType = (PrimitiveType)(100
                + instance.StructureIndex);
            if (!TryGetGenericMethodActualTypeTerm(instanceType,
                    callerFunction, program, 0, out var actualTypeTerm)
                || !AreGenericMethodTypeTermsEqual(actualTypeTerm,
                    domain, 0))
            {
                continue;
            }

            var structureIndex = instance.StructureIndex;
            if ((uint)structureIndex >= (uint)program.Structures.Length)
            {
                return false;
            }
            domainType = (PrimitiveType)(100 + structureIndex);
            return true;
        }

        return false;
    }

    internal static bool TryGetGenericMethodActualTypeTerm(
        PrimitiveType type, BoundFunction? callerFunction,
        BoundProgram program, int depth,
        out BoundGenericMethodTypeTerm term)
    {
        term = null!;
        if (depth > MaximumDepth)
        {
            return false;
        }

        var remaining = MaximumAnalysisVisits;
        if (TryBuildGenericQueryTypeIdentityTerm(type, callerFunction,
                program, ref remaining, depth, out term))
        {
            return true;
        }

        if (RequiresStructuredGenericMethodTypeTerm(type, program))
        {
            return false;
        }

        term = new BoundGenericMethodTypeTerm(
            BoundGenericMethodTypeTermKind.Concrete, type, -1, -1, [],
            false, false, false, false) {
            AllowsVoid = type == PrimitiveType.Void,
        };
        return true;
    }

    private static bool RequiresStructuredGenericMethodTypeTerm(
        PrimitiveType type, BoundProgram program)
    {
        if (BoundGenericNominalTypeContract.IsValidType(type, program)
            || CheckedReferenceTypeContract.IsValidType(type,
                program.CheckedReferenceTypes)
            || ManagedClassTypes.IsOptional(type)
            || NativePointerTypeContract.IsValidType(type,
                program.NativePointerTypes)
            || NativeFixedArrayTypes.IsType(type)
            || NativeFunctionPointerTypes.IsType(type))
        {
            return true;
        }

        var structureIndex = (int)type - 100;
        return structureIndex >= 0
            && program.SourceGenericTypeInstances.Any(instance =>
                instance.StructureIndex == structureIndex);
    }

    internal static bool AreGenericMethodTypeTermsEqual(
        BoundGenericMethodTypeTerm? left,
        BoundGenericMethodTypeTerm? right, int depth)
    {
        if (left is null || right is null || depth > MaximumDepth
            || left.Kind != right.Kind
            || left.ConcreteType != right.ConcreteType
            || left.FormalOrdinal != right.FormalOrdinal
            || left.SourceGenericTypeDefinitionIndex
                != right.SourceGenericTypeDefinitionIndex
            || left.IsWritable != right.IsWritable
            || left.IsGarbageCollected != right.IsGarbageCollected
            || left.IsInitialization != right.IsInitialization
            || left.IsOptional != right.IsOptional
            || left.NominalTypeIdentity != right.NominalTypeIdentity
            || left.ElementCount != right.ElementCount
            || left.CallingConvention != right.CallingConvention
            || left.ParameterCount != right.ParameterCount
            || left.AllowsVoid != right.AllowsVoid
            || left.IsElementWritable != right.IsElementWritable
            || left.TypeArguments.IsDefault
            || right.TypeArguments.IsDefault
            || left.TypeArguments.Length != right.TypeArguments.Length
            || left.ConstantArguments.IsDefault
            || right.ConstantArguments.IsDefault
            || left.ConstantArguments.Length
                != right.ConstantArguments.Length)
        {
            return false;
        }

        for (var ordinal = 0; ordinal < left.TypeArguments.Length;
            ordinal++)
        {
            if (!AreGenericMethodTypeTermsEqual(
                left.TypeArguments[ordinal],
                right.TypeArguments[ordinal], depth + 1))
            {
                return false;
            }
        }

        for (var ordinal = 0;
            ordinal < left.ConstantArguments.Length; ordinal++)
        {
            var leftArgument = left.ConstantArguments[ordinal];
            var rightArgument = right.ConstantArguments[ordinal];
            if (leftArgument.Kind != rightArgument.Kind
                || leftArgument.FormalOwnerKind
                    != rightArgument.FormalOwnerKind
                || leftArgument.FormalOrdinal
                    != rightArgument.FormalOrdinal
                || leftArgument.FormalDefinitionOrdinal
                    != rightArgument.FormalDefinitionOrdinal
                || leftArgument.DomainType != rightArgument.DomainType
                || leftArgument.CarrierType
                    != rightArgument.CarrierType
                || leftArgument.Bits != rightArgument.Bits)
            {
                return false;
            }
        }

        return true;
    }

    private static bool TryGetGenericQuerySpanFormalOrdinal(
        BoundSpanTypeDefinition spanType, BoundFunction? function,
        BoundProgram program, out int formalOrdinal)
    {
        formalOrdinal = -1;
        if (spanType.ElementFormalDefinitionOrdinal == -1)
        {
            return spanType.ElementFormalOrdinal == -1
                && !spanType.IsElementWritable;
        }

        if (function is null)
        {
            return false;
        }

        if (spanType.ElementFormalDefinitionOrdinal >= 0)
        {
            var formalOwnerOrdinal
                = function.GenericMethodProofTypeFormalOwnerOrdinal >= 0
                    ? function.GenericMethodProofTypeFormalOwnerOrdinal
                    : function.GenericMethodProofDefinitionOrdinal;
            if (formalOwnerOrdinal
                != spanType.ElementFormalDefinitionOrdinal)
            {
                return false;
            }
        }
        else
        {
            var importedOwnerOrdinal = function.ImportedGenericMethod
                    ?.FormalTypeOwnerOrdinal
                    ?? function.GenericMethodProofTypeFormalOwnerOrdinal;
            if (importedOwnerOrdinal < 0
                    || spanType.ElementFormalDefinitionOrdinal
                        != (long)BoundSpanTypeContract
                            .ImportedFormalDefinitionOrdinal
                        - importedOwnerOrdinal)
            {
                    return false;
            }
        }

        if (!TryGetCallerGenericTypeFormal(function, program,
                spanType.ElementType, out var formal, out formalOrdinal)
            || formal is null
            || (spanType.IsElementWritable
                && !formal.RequiresWritable))
        {
            return false;
        }
        return true;
    }

    private static bool TryGetCallerGenericTypeFormal(
        BoundFunction callerFunction, BoundProgram program,
        PrimitiveType typeArgument,
        out BoundGenericMethodFormalSignature? formal, out int ordinal)
    {
        formal = null;
        ordinal = -1;
        var definitionOrdinal
            = callerFunction.GenericMethodProofDefinitionOrdinal;
        if (definitionOrdinal >= 0
            && definitionOrdinal < program.GenericMethodSignatures.Length
            && callerFunction.GenericMethodProofTypeParameters.Length
                == program.GenericMethodSignatures[definitionOrdinal]
                    .Formals.Length)
        {
            for (var formalOrdinal = 0;
                formalOrdinal
                    < callerFunction.GenericMethodProofTypeParameters.Length;
                formalOrdinal++)
            {
                if (callerFunction.GenericMethodProofTypeParameters[
                        formalOrdinal] != typeArgument)
                {
                    continue;
                }

                formal = program.GenericMethodSignatures[definitionOrdinal]
                    .Formals[formalOrdinal];
                ordinal = formalOrdinal;
                return true;
            }
        }

        if (callerFunction.ImportedGenericMethod
            is not BoundGenericMethodImport imported
            || imported.FormalTypeOwnerOrdinal < 0
            || imported.Formals.Length
                != imported.Signature.Formals.Length)
        {
            return false;
        }

        for (var formalOrdinal = 0;
            formalOrdinal < imported.Formals.Length;
            formalOrdinal++)
        {
            if (imported.Formals[formalOrdinal].PlaceholderType
                != typeArgument)
            {
                continue;
            }

            formal = imported.Signature.Formals[formalOrdinal];
            ordinal = formalOrdinal;
            return true;
        }

        var ownerOrdinal
            = callerFunction.GenericMethodProofTypeFormalOwnerOrdinal;
        if (ownerOrdinal >= 0
            && !callerFunction.GenericMethodProofTypeParameters.IsDefault)
        {
            var owner = program.GenericMethodTypeFormalOwners
                .FirstOrDefault(candidate => candidate.Ordinal
                    == ownerOrdinal);
            for (var formalOrdinal = 0;
                formalOrdinal
                    < callerFunction.GenericMethodProofTypeParameters.Length
                    && (uint)formalOrdinal < (uint)owner.Formals.Length;
                formalOrdinal++)
            {
                if (callerFunction.GenericMethodProofTypeParameters[
                        formalOrdinal] != typeArgument)
                {
                    continue;
                }

                var ownerFormal = owner.Formals[formalOrdinal];
                formal = new BoundGenericMethodFormalSignature(
                    formalOrdinal, string.Empty,
                    ownerFormal.OwnershipDomain,
                    ownerFormal.NullabilityDomain, []) {
                    RequiresWritable = ownerFormal.RequiresWritable,
                    RequiresBlittable = ownerFormal.RequiresBlittable,
                };
                ordinal = formalOrdinal;
                return true;
            }
        }

        return false;
    }

    private static bool TryGetCallerGenericTypeFormalOwner(
        BoundFunction callerFunction, BoundProgram program,
        out int ownerOrdinal, out int formalCount)
    {
        ownerOrdinal = -1;
        formalCount = 0;
        if (callerFunction.ImportedGenericMethod
            is BoundGenericMethodImport imported)
        {
            ownerOrdinal = imported.FormalTypeOwnerOrdinal;
            formalCount = imported.Formals.Length;
            return ownerOrdinal >= 0 && !imported.Formals.IsDefault;
        }

        if (callerFunction.GenericMethodProofTypeFormalOwnerOrdinal >= 0)
        {
            ownerOrdinal
                = callerFunction.GenericMethodProofTypeFormalOwnerOrdinal;
            formalCount
                = callerFunction.GenericMethodProofTypeParameters.Length;
            return !callerFunction.GenericMethodProofTypeParameters.IsDefault;
        }

        var definitionOrdinal
            = callerFunction.GenericMethodProofDefinitionOrdinal;
        if (definitionOrdinal < 0
            || program.GenericMethodDefinitions.FirstOrDefault(definition =>
                definition.DefinitionOrdinal == definitionOrdinal) is not
                BoundGenericMethodDefinition definition)
        {
            return false;
        }

        ownerOrdinal = definition.FormalTypeOwnerOrdinal;
        formalCount = definition.Formals.Length;
        return ownerOrdinal >= 0 && !definition.Formals.IsDefault;
    }

    private static bool IsUniqueGenericMethodTypeArgument(
        PrimitiveType type, BoundProgram program) =>
        IsUnique(program, type)
        || (IsSupportedOptionalType(type, program)
            && TryGetOptionalPayloadType(type, program,
                out var payloadType)
            && IsUnique(program, payloadType));

    private static bool IsValidGenericTypePropertyTest(
        BoundGenericTypePropertyTest test, BoundFunction function,
        BoundProgram program)
    {
        var definitionOrdinal
            = function.GenericMethodProofDefinitionOrdinal;
        if (definitionOrdinal < 0
            || definitionOrdinal
                >= program.GenericMethodSignatures.Length
            || test.FormalOrdinal < 0
            || test.FormalOrdinal
                >= function.GenericMethodProofTypeParameters.Length
            || function.GenericMethodProofTypeParameters.Length
                != program.GenericMethodSignatures[definitionOrdinal]
                    .Formals.Length
            || function.GenericMethodProofTypeParameters[
                test.FormalOrdinal] != test.FormalType)
        {
            return false;
        }

        var formal = program.GenericMethodSignatures[definitionOrdinal]
            .Formals[test.FormalOrdinal];
        var expectedResult = formal.OwnershipDomain switch {
            1 => false,
            2 => true,
            3 => (bool?)null,
            _ => (bool?)null,
        };
        return formal.OwnershipDomain is 1 or 2 or 3
            && test.KnownResult == expectedResult;
    }

    private static bool IsValidGenericUniquePropertyConstant(
        BoundConstant constant, BoundFunction function,
        BoundProgram program)
    {
        var whenTrue = constant.GenericUniquePropertyWhenTrue;
        var whenFalse = constant.GenericUniquePropertyWhenFalse;
        if (whenTrue.IsDefaultOrEmpty && whenFalse.IsDefaultOrEmpty)
        {
            return constant.GenericUniquePropertyKnownResult is null;
        }

        if (whenTrue.IsDefault || whenFalse.IsDefault
            || constant.Type != PrimitiveType.Bool
            || constant.Value is not (0 or 1)
            || constant.GenericUniquePropertyKnownResult
                != (constant.Value != 0))
        {
            return false;
        }

        var result = constant.Value != 0;
        return IsValidGenericUniquePropertyFacts(whenTrue, function,
                program, result)
            && IsValidGenericUniquePropertyFacts(whenFalse, function,
                program, !result);
    }

    private static bool IsValidGenericUniquePropertyFacts(
        ImmutableArray<BoundGenericUniquePropertyFact> facts,
        BoundFunction function, BoundProgram program, bool outcomeReachable)
    {
        var previousOrdinal = -1;
        foreach (var fact in facts)
        {
            if (fact.FormalOrdinal <= previousOrdinal
                || !IsGenericUniqueRefinementFormal(function, program,
                    fact.FormalOrdinal, fact.FormalType)
                || !TryGetGenericTypeFormalType(function, program,
                    fact.FormalOrdinal, out var formalType)
                || formalType != fact.FormalType
                || (outcomeReachable
                    && IsUniqueGenericMethodTypeArgument(formalType,
                        program) != fact.IsUnique))
            {
                return false;
            }
            previousOrdinal = fact.FormalOrdinal;
        }
        return true;
    }

    private static bool IsValidGenericUniquePropertyIf(
        BoundIf conditional, BoundFunction function, BoundProgram program)
    {
        var flow = BoundGenericUniquePropertyFlowAnalysis.Analyze(
            conditional.Condition, function.Variables);
        if (!flow.HasFacts)
        {
            return conditional.GenericUniquePropertyWhenTrue.IsDefaultOrEmpty
                && conditional.GenericUniquePropertyWhenFalse.IsDefaultOrEmpty
                && conditional.GenericUniquePropertyKnownResult is null;
        }

        return !conditional.GenericUniquePropertyWhenTrue.IsDefault
            && !conditional.GenericUniquePropertyWhenFalse.IsDefault
            && conditional.GenericUniquePropertyWhenTrue
                .SequenceEqual(flow.WhenTrue)
            && conditional.GenericUniquePropertyWhenFalse
                .SequenceEqual(flow.WhenFalse)
            && conditional.GenericUniquePropertyKnownResult
                == flow.KnownResult;
    }

    private static bool IsValidGenericUniquePropertyLocal(
        BoundVariable variable, BoundExpression initializer,
        BoundFunction function, BoundProgram program)
    {
        if (variable.Type != PrimitiveType.Bool || variable.IsMutable)
        {
            return variable.GenericUniquePropertyWhenTrue.IsDefaultOrEmpty
                && variable.GenericUniquePropertyWhenFalse.IsDefaultOrEmpty
                && variable.GenericUniquePropertyKnownResult is null;
        }

        var flow = BoundGenericUniquePropertyFlowAnalysis.Analyze(
            initializer, function.Variables);
        var hasMetadata
            = !variable.GenericUniquePropertyWhenTrue.IsDefaultOrEmpty
                || !variable.GenericUniquePropertyWhenFalse.IsDefaultOrEmpty
                || variable.GenericUniquePropertyKnownResult is not null;
        if (!hasMetadata)
        {
            return !flow.HasFacts;
        }

        return flow.HasFacts
            && !variable.GenericUniquePropertyWhenTrue.IsDefault
            && !variable.GenericUniquePropertyWhenFalse.IsDefault
            && variable.GenericUniquePropertyWhenTrue
                    .SequenceEqual(flow.WhenTrue)
            && variable.GenericUniquePropertyWhenFalse
                    .SequenceEqual(flow.WhenFalse)
            && variable.GenericUniquePropertyKnownResult
                == flow.KnownResult;
    }

    private static bool IsGenericUniqueRefinementFormal(
        BoundFunction function, BoundProgram program, int formalOrdinal,
        PrimitiveType type)
    {
        if (!TryGetGenericTypeFormalType(function, program, formalOrdinal,
            out var formalType) || formalType != type)
        {
            return false;
        }

        if (function.GenericMethodProofDefinitionOrdinal
            is int proofOrdinal and >= 0)
        {
            return program.GenericMethodSignatures[proofOrdinal]
                .Formals[formalOrdinal].OwnershipDomain is 1 or 2 or 3;
        }

        return function.GenericMethodInstantiation is
                BoundGenericMethodInstantiation instantiation
            && (uint)instantiation.DefinitionOrdinal
                < (uint)program.GenericMethodSignatures.Length
            && formalOrdinal
                < program.GenericMethodSignatures[
                    instantiation.DefinitionOrdinal].Formals.Length
            && program.GenericMethodSignatures[
                instantiation.DefinitionOrdinal]
                .Formals[formalOrdinal].OwnershipDomain is 1 or 2 or 3;
    }

    private static bool TryGetGenericTypeFormalType(
        BoundFunction function, BoundProgram program, int formalOrdinal,
        out PrimitiveType type)
    {
        type = default;
        if (function.GenericMethodProofDefinitionOrdinal
            is int proofOrdinal and >= 0)
        {
            if (proofOrdinal >= program.GenericMethodSignatures.Length
                || proofOrdinal != function.GenericMethodProofDefinitionOrdinal
                || formalOrdinal
                    >= function.GenericMethodProofTypeParameters.Length
                || function.GenericMethodProofTypeParameters.Length
                    != program.GenericMethodSignatures[proofOrdinal]
                        .Formals.Length)
            {
                return false;
            }

            type = function.GenericMethodProofTypeParameters[
                formalOrdinal];
            return true;
        }

        if (function.GenericMethodInstantiation is not
                BoundGenericMethodInstantiation instantiation
            || (uint)instantiation.DefinitionOrdinal
                >= (uint)program.GenericMethodSignatures.Length
            || formalOrdinal >= instantiation.TypeArguments.Length
            || instantiation.TypeArguments.Length
                != program.GenericMethodSignatures[
                    instantiation.DefinitionOrdinal].Formals.Length)
        {
            return false;
        }

        type = instantiation.TypeArguments[formalOrdinal];
        return true;
    }

    private static bool IsCopyGenericMethodTypeArgument(
        PrimitiveType type, BoundProgram program)
    {
        if (IsUniqueGenericMethodTypeArgument(type, program))
        {
            return false;
        }

        return PrimitiveTypeFacts.ScalarWidth(type,
                program.EnumDefinitions) > 0
            || type == PrimitiveType.NativeRawPointer
            || (BoundSpanTypeTypes.IsValidType(type, program.SpanTypes)
                && !program.SpanTypes[BoundSpanTypeTypes.Index(type)]
                    .IsInitialization)
            || NativePointerTypeContract.IsValidType(type,
                program.NativePointerTypes)
            || NativeFunctionPointerContract.IsValidType(type,
                program.NativeFunctionPointerSignatures)
            || IsKnownCopyClassHandle(type, program)
            || BoundEnumTypes.IsValidType(type, program.EnumDefinitions)
            || ((int)type >= 100
                && (int)type - 100 < program.Structures.Length
                && !program.Structures[(int)type - 100].IsUnique
                && !IsClassOwnershipUnknown(type, program))
            || (NativeFixedArrayTypes.IsType(type)
                && NativeFixedArrayContract.IsRootlessCopyFieldType(
                    type, program.Structures,
                    program.NativeFixedArrayTypes,
                    program.CheckedReferenceTypes))
            || (CheckedReferenceTypeContract.IsValidType(
                    type, program.CheckedReferenceTypes)
                && CheckedReferenceTypeContract
                    .IsSupportedReferenceStoreValueType(type,
                        program.Structures, program.Classes,
                        program.EnumDefinitions.Length,
                        program.CheckedReferenceTypes,
                        program.NativePointerTypes));
    }

    private static bool IsWritableGenericMethodTypeArgument(
        PrimitiveType type, BoundProgram program)
    {
        if (BoundSpanTypeTypes.IsValidType(type, program.SpanTypes)
            && program.SpanTypes[BoundSpanTypeTypes.Index(type)]
                .IsWritable)
        {
            return true;
        }
        if (ManagedClassTypes.IsManaged(type)
            && ManagedClassTypes.IsWritable(type))
        {
            return true;
        }
        if (CheckedReferenceTypeContract.IsValidType(
                type, program.CheckedReferenceTypes)
            && program.CheckedReferenceTypes[
                CheckedReferenceTypes.Index(type)].IsWritable)
        {
            return true;
        }
        if (NativePointerTypeContract.IsValidType(type,
                program.NativePointerTypes)
            && program.NativePointerTypes[
                NativePointerTypes.Index(type)].IsWritable)
        {
            return true;
        }
        return IsSupportedOptionalType(type, program)
            && TryGetOptionalPayloadType(type, program,
                out var payloadType)
            && IsWritableGenericMethodTypeArgument(payloadType, program);
    }

    private static bool AreGenericMethodInstantiationsEqual(
        BoundGenericMethodInstantiation? left,
        BoundGenericMethodInstantiation? right)
    {
        if (left is null || right is null)
        {
            return left is null && right is null;
        }

        if (left.DefinitionOrdinal != right.DefinitionOrdinal
            || left.TypeArguments.IsDefault
            || right.TypeArguments.IsDefault
            || !left.TypeArguments.SequenceEqual(right.TypeArguments)
            || left.ConstantArguments.IsDefault
            || right.ConstantArguments.IsDefault
            || left.ConstantArguments.Length
                != right.ConstantArguments.Length)
        {
            return false;
        }

        for (var ordinal = 0;
            ordinal < left.ConstantArguments.Length; ordinal++)
        {
            var leftArgument = left.ConstantArguments[ordinal];
            var rightArgument = right.ConstantArguments[ordinal];
            if (leftArgument is null || rightArgument is null
                || leftArgument.Ordinal != rightArgument.Ordinal
                || leftArgument.ConstantOrdinal
                    != rightArgument.ConstantOrdinal
                || leftArgument.Kind != rightArgument.Kind
                || leftArgument.CallerFormalOrdinal
                    != rightArgument.CallerFormalOrdinal
                || leftArgument.CallerDefinitionOrdinal
                    != rightArgument.CallerDefinitionOrdinal
                || leftArgument.CallerConstantFormalOrdinal
                    != rightArgument.CallerConstantFormalOrdinal
                || leftArgument.DomainType != rightArgument.DomainType
                || leftArgument.CarrierType != rightArgument.CarrierType
                || leftArgument.Bits != rightArgument.Bits
                || !AreGenericMethodTypeTermsEqual(leftArgument.Domain,
                    rightArgument.Domain, 0))
            {
                return false;
            }
        }

        return true;
    }

    internal static bool IsClassArgumentType(PrimitiveType type, IReadOnlyList<BoundStruct> structures,
        int enumDefinitionCount = 0) =>
        type is PrimitiveType.Char8 or PrimitiveType.Char16 or PrimitiveType.Char32 or PrimitiveType.Rune
            or PrimitiveType.Int8 or PrimitiveType.Int16 or PrimitiveType.Int32 or PrimitiveType.UInt8
            or PrimitiveType.UInt16 or PrimitiveType.UInt32 or PrimitiveType.Int64 or PrimitiveType.UInt64
            or PrimitiveType.NativeInt or PrimitiveType.NativeUInt
            or PrimitiveType.Int128 or PrimitiveType.UInt128 or PrimitiveType.Float16 or PrimitiveType.BFloat16
            or PrimitiveType.Float32 or PrimitiveType.Float64 or PrimitiveType.Float128
            or PrimitiveType.Decimal32 or PrimitiveType.Decimal64 or PrimitiveType.Decimal128 or PrimitiveType.Bool
            || NativePointerTypes.IsType(type)
            || NativeFunctionPointerTypes.IsType(type)
            || ManagedClassTypes.IsManaged(type)
            || BoundEnumTypes.IsValidType(type, enumDefinitionCount)
            || ((int)type >= 100 && (int)type - 100 < structures.Count
                && !structures[(int)type - 100].IsUnique);

    private static bool IsClassArgumentType(PrimitiveType type,
        BoundProgram program)
    {
        if (!IsClassArgumentType(type, program.Structures,
                program.EnumDefinitions.Length))
        {
            return false;
        }

        return !IsStructType(type, program)
            || IsCopyStruct(program, type);
    }

    private static bool IsStructType(PrimitiveType type,
        BoundProgram program) =>
        (int)type >= 100
        && (int)type - 100 < program.Structures.Length
        && !BoundEnumTypes.IsType(type);

    private static bool IsUnique(BoundProgram program, PrimitiveType type) =>
        type == PrimitiveType.OwnedInt32Buffer
            || BoundGenericNominalTypeContract.IsCoreTaskType(type, program)
            || ((int)type >= 100 && (int)type - 100 < program.Structures.Length
                && program.Structures[(int)type - 100].IsUnique)
            || IsUniqueClassHandle(type, program);

    private static bool IsUniqueClassHandle(PrimitiveType type,
        BoundProgram program)
    {
        if ((int)type < ManagedClassTypes.First
            || !ManagedClassTypes.IsManaged(type))
        {
            return false;
        }

        var classIndex = ManagedClassTypes.ClassIndex(type);
        return (uint)classIndex < (uint)program.Classes.Length
            && program.Classes[classIndex].IsUnique == true;
    }

    private static string? GetDeclaredCleanupMethod(
        BoundProgram program, PrimitiveType type)
    {
        if (type == PrimitiveType.OwnedInt32Buffer)
        {
            return null;
        }
        if ((int)type >= ManagedClassTypes.First
            && ManagedClassTypes.IsManaged(type))
        {
            var classIndex = ManagedClassTypes.ClassIndex(type);
            return (uint)classIndex < (uint)program.Classes.Length
                && program.Classes[classIndex].HasCleanup == true
                    ? program.Classes[classIndex].CleanupMethod : null;
        }
        if (ManagedClassTypes.IsManaged(type))
        {
            return null;
        }

        var structureIndex = (int)type - 100;
        return (uint)structureIndex < (uint)program.Structures.Length
            ? program.Structures[structureIndex].CleanupMethod : null;
    }

    private static bool IsKnownCopyClassHandle(PrimitiveType type,
        BoundProgram program)
    {
        if (!ManagedClassTypes.IsManaged(type))
        {
            return false;
        }
        if ((int)type < ManagedClassTypes.First)
        {
            return true;
        }

        var classIndex = ManagedClassTypes.ClassIndex(type);
        return (uint)classIndex < (uint)program.Classes.Length
            && program.Classes[classIndex].IsUnique == false;
    }

    private static bool IsClassOwnershipUnknown(PrimitiveType type,
        BoundProgram program)
    {
        if (IsClassHandleOwnershipUnknown(type, program))
        {
            return true;
        }

        return IsStructType(type, program)
            && IsClassOwnershipUnknown(type, program, new HashSet<int>());
    }

    private static bool IsClassOwnershipUnknown(PrimitiveType type,
        BoundProgram program, HashSet<int> visitedStructures)
    {
        if (IsClassHandleOwnershipUnknown(type, program))
        {
            return true;
        }

        if (!IsStructType(type, program))
        {
            return false;
        }

        var structureIndex = (int)type - 100;
        if ((uint)structureIndex >= (uint)program.Structures.Length)
        {
            return false;
        }
        if (!visitedStructures.Add(structureIndex))
        {
            return true;
        }

        var structure = program.Structures[structureIndex];
        foreach (var field in structure.Fields)
        {
            if (field is null
                || IsClassOwnershipUnknown(field.Type, program,
                    visitedStructures))
            {
                _ = visitedStructures.Remove(structureIndex);
                return true;
            }
        }

        _ = visitedStructures.Remove(structureIndex);
        return false;
    }

    private static bool IsClassHandleOwnershipUnknown(PrimitiveType type,
        BoundProgram program)
    {
        if (BoundGenericNominalTypeContract.IsNominalClassType(type,
                program.GenericNominalTypeInstances,
                program.GenericNominalTypeDefinitions))
        {
            return !BoundGenericNominalTypeContract.IsCoreTaskType(
                type, program);
        }

        if (!ManagedClassTypes.IsManaged(type)
            || (int)type < ManagedClassTypes.First)
        {
            return false;
        }

        var classIndex = ManagedClassTypes.ClassIndex(type);
        return (uint)classIndex < (uint)program.Classes.Length
            && program.Classes[classIndex].IsUnique is null;
    }

    private static bool IsStandardClassHandleType(PrimitiveType type,
        BoundProgram program)
    {
        if (!BoundGenericNominalTypeContract.IsNominalClassType(type,
                program.GenericNominalTypeInstances,
                program.GenericNominalTypeDefinitions))
        {
            return false;
        }

        var instanceIndex = BoundGenericNominalTypeTypes.Index(type);
        if ((uint)instanceIndex
                >= (uint)program.GenericNominalTypeInstances.Length
            || program.GenericNominalTypeInstances[instanceIndex]
                .TypeSpecReference == 0
            || program.GenericNominalTypeInstances[instanceIndex]
                .TypeSpecForm is not (0x02 or 0x03 or 0x06)
            || !BoundGenericNominalTypeContract.TryGetDefinition(type,
                program, out var definition)
            || definition is null || !definition.Formals.IsEmpty)
        {
            return false;
        }

        return program.StandardClassDeclarations.Any(declaration =>
            declaration.Declaration.Identity == definition.Identity);
    }

    private static bool RequiresUnsafeFieldAccess(BoundProgram program,
        PrimitiveType ownerType, BoundStructField field)
        => field.RequiresUnsafeCaller || IsUnion(program, ownerType);

    internal static bool IsRawUnionType(BoundProgram program,
        PrimitiveType type)
    {
        var typeValue = (int)type;
        if (typeValue is < 100 or >= BoundEnumTypes.First)
        {
            return false;
        }

        var index = typeValue - 100;
        return (uint)index < (uint)program.Structures.Length
            && program.Structures[index].IsUnion;
    }

    private static bool CanMaterializeRawUnionPayloadFacts(
        PrimitiveType type, BoundProgram program)
    {
        if (!CarriesRawUnionPayloadFacts(program, type))
        {
            return false;
        }

        var size = NativeFixedArrayTypes.IsType(type)
            ? NativeFixedArrayContract.TryGetLayout(type,
                program.Structures, program.NativeFixedArrayTypes,
                out var layout, program.CheckedReferenceTypes,
                program.EnumDefinitions)
                ? layout.ByteExtent
                : throw InvalidEffect(default, "NativeImport")
            : ValueLayout.Size(type, program.Structures,
                program.CheckedReferenceTypes,
                program.NativeLoweringAgreement,
                program.NativeFixedArrayTypes, program.EnumDefinitions);
        return size <= (ulong)ValueLayout.MaximumStructureSize;
    }

    private static bool CarriesRawUnionPayloadFacts(
        BoundProgram program, PrimitiveType type)
    {
        var pending = new Stack<PrimitiveType>();
        var visited = new HashSet<PrimitiveType>();
        pending.Push(type);
        var carriesRawUnion = false;
        while (pending.TryPop(out var current))
        {
            if (IsRawUnionType(program, current))
            {
                carriesRawUnion = true;
                continue;
            }
            if (NativeFixedArrayTypes.IsType(current))
            {
                if (!visited.Add(current))
                {
                    continue;
                }
                if (!NativeFixedArrayContract.TryGetLayout(current,
                        program, out var layout))
                {
                    throw InvalidEffect(default, "NativeImport");
                }
                if (layout.ElementCount != 0)
                {
                    pending.Push(layout.ElementType);
                }
                continue;
            }
            if (NativeFixedArrayContract.IsCarrier(current)
                || ManagedClassTypes.IsClass(current))
            {
                return false;
            }
            if (!HasFields(program, current) || !visited.Add(current))
            {
                continue;
            }

            foreach (var field in Fields(program, current))
            {
                pending.Push(field.Type);
            }
        }

        return carriesRawUnion;
    }

    private static bool CarriesRawUnionArrayFacts(
        BoundProgram program, PrimitiveType type)
    {
        var pending = new Stack<(PrimitiveType Type,
            bool IsArrayElement)>();
        var visited = new HashSet<(PrimitiveType Type,
            bool IsArrayElement)>();
        pending.Push((type, false));
        while (pending.TryPop(out var item))
        {
            if (NativeFixedArrayTypes.IsType(item.Type))
            {
                if (!NativeFixedArrayContract.TryGetLayout(item.Type,
                        program, out var layout))
                {
                    throw InvalidEffect(default, "NativeImport");
                }
                if (layout.ElementCount != 0)
                {
                    pending.Push((layout.ElementType,
                        IsArrayElement: true));
                }
                continue;
            }

            if (IsRawUnionType(program, item.Type))
            {
                if (item.IsArrayElement)
                {
                    return true;
                }
                continue;
            }
            if (!HasFields(program, item.Type)
                || !visited.Add(item))
            {
                continue;
            }

            foreach (var field in Fields(program, item.Type))
            {
                pending.Push((field.Type, item.IsArrayElement));
            }
        }

        return false;
    }

    private static bool IsUnion(BoundProgram program, PrimitiveType type)
    {
        if (ManagedClassTypes.IsClass(type) || BoundEnumTypes.IsType(type)
            || BoundGenericNominalTypeTypes.IsType(type))
        {
            return false;
        }

        var index = (int)type - 100;
        return (uint)index < (uint)program.Structures.Length
            && program.Structures[index].IsUnion;
    }

    private static bool IsManagedLifetimeValue(BoundProgram program, PrimitiveType type)
    {
        if (ManagedClassTypes.IsManaged(type))
        {
            return true;
        }
        if (program.NativeLoweringAgreement
                != CompilationOptions.WindowsX64NormalBackingAgreement)
        {
            return false;
        }
        return ContainsNormalBackingReference(program, type, []);
    }

    private static bool ContainsNormalBackingReference(
        BoundProgram program, PrimitiveType type, HashSet<int> activeStructures)
    {
        if (CheckedReferenceTypes.IsType(type))
        {
            if (!CheckedReferenceTypeContract.IsValidType(
                type, program.CheckedReferenceTypes))
            {
                return false;
            }
            var reference = program.CheckedReferenceTypes[
                CheckedReferenceTypes.Index(type)];
            return !reference.IsGarbageCollected && !reference.IsInitialization
                && !reference.IsOptional;
        }

        var structureIndex = (int)type - 100;
        if (structureIndex < 0 || structureIndex >= program.Structures.Length
            || ManagedClassTypes.IsClass(type) || BoundEnumTypes.IsType(type)
            || !activeStructures.Add(structureIndex))
        {
            return false;
        }
        var contains = program.Structures[structureIndex].Fields.Any(field =>
            ContainsNormalBackingReference(program, field.Type, activeStructures));
        _ = activeStructures.Remove(structureIndex);
        return contains;
    }

    private static bool IsCopyStruct(BoundProgram program, PrimitiveType type) =>
        IsStructType(type, program)
            && !program.Structures[(int)type - 100].IsUnique
            && !IsClassOwnershipUnknown(type, program);

    private static void VerifyClassFactory(BoundProgram program, BoundFunction function, int index)
    {
        var constructorIndex = function.ClassConstructor;
        if (constructorIndex < 0 || constructorIndex >= program.Functions.Length || constructorIndex == index
            || function.DeclaringStruct is not string name
            || function.Name != name + ".TryCreate"
            || function.ReturnType != PrimitiveType.Bool || function.IsConstructor
            || function.IsClassConstructor || function.IsExternal
            || !function.IsStatic || function.IsCleanup || function.DoesNotReturn
            || function.Body.Statements.IsDefault || !function.Body.Statements.IsEmpty
            || function.ParameterCount < 1 || function.ParameterCount > MaximumArguments
            || function.Variables.Length != function.ParameterCount + 1)
        {
            throw Invalid();
        }
        var constructor = program.Functions[constructorIndex];
        var type = function.Variables[function.ParameterCount - 1].Type;
        if (constructor is null || constructor.Variables.IsDefaultOrEmpty
            || constructor.ParameterCount < 1 || constructor.ParameterCount > MaximumArguments
            || constructor.Variables.Length < constructor.ParameterCount
            || !ManagedClassTypes.IsClass(type)
            || ManagedClassTypes.ClassIndex(type) >= program.Classes.Length
            || program.Classes[ManagedClassTypes.ClassIndex(type)].Name != name
            || ManagedClassTypes.IsWritable(type) != program.Classes[ManagedClassTypes.ClassIndex(type)].IsMutable
            || !constructor.IsClassConstructor || constructor.DeclaringStruct != name
            || function.IsPrivate != constructor.IsPrivate
            || function.IsInternal != !constructor.IsPrivate
            || constructor.ParameterCount != function.ParameterCount
            || constructor.Variables[0].Type != type
            || function.Variables[function.ParameterCount - 1] is not { IsOut: true, IsMutable: false }
            || function.Variables[function.ParameterCount] is not { IsOut: false, IsMutable: false }
            || function.Variables[function.ParameterCount].Type != type
            || function.NoFailureProof != constructor.NoFailureProof
            || function.RequiresUnsafeCaller != constructor.RequiresUnsafeCaller)
        {
            throw Invalid();
        }
        for (var parameter = 0; parameter < function.ParameterCount - 1; parameter++)
        {
            if (function.Variables[parameter].Type != constructor.Variables[parameter + 1].Type
                || function.Variables[parameter].IsOut || function.Variables[parameter].IsMutable
                || constructor.Variables[parameter + 1].IsOut
                || !IsClassArgumentType(function.Variables[parameter].Type,
                    program))
            {
                throw Invalid();
            }
        }
    }

    private static HashSet<int> ValidatePrivateClassReferences(
        BoundProgram program)
    {
        var result = new HashSet<int>();
        if (program.PrivateClassReferences.IsDefault)
        {
            throw Invalid();
        }

        foreach (var reference in program.PrivateClassReferences)
        {
            if (reference is null
                || !ManagedClassTypes.IsClass(reference.ClassType)
                || reference.ClassType
                    != (PrimitiveType)(ManagedClassTypes.First
                        + ManagedClassTypes.ClassIndex(
                            reference.ClassType))
                || (uint)ManagedClassTypes.ClassIndex(reference.ClassType)
                    >= (uint)program.Classes.Length
                || !ManagedClassTypes.IsClass(reference.ExpectedClassType)
                || reference.Origin is null
                || reference.ExpectedSnapshot is null
                || reference.ExpectedSnapshot.Structures.IsDefault
                || reference.ExpectedSnapshot.Classes.IsDefault
                || reference.ExpectedSnapshot.CheckedReferenceTypes.IsDefault
                || reference.ExpectedSnapshot.NativeFunctionPointerSignatures.IsDefault
                || reference.ExpectedSnapshot.NativePointerTypes.IsDefault
                || reference.ExpectedSnapshot.NativeFixedArrayTypes.IsDefault
                || reference.ExpectedSnapshot.EnumDefinitions.IsDefault
                || !BoundEnumTypes.IsValidTable(
                    reference.ExpectedSnapshot.EnumDefinitions)
                || reference.ExpectedNativePointerMapping.IsDefault
                || reference.ExpectedNativePointerMapping.Length
                    != reference.ExpectedSnapshot.NativePointerTypes.Length
                || reference.ExpectedNativeFunctionPointerMapping.IsDefault
                || reference.ExpectedNativeFunctionPointerMapping.Length
                    != reference.ExpectedSnapshot
                        .NativeFunctionPointerSignatures.Length
                || reference.ExpectedNativeFixedArrayMapping.IsDefault
                || reference.ExpectedNativeFixedArrayMapping.Length
                    != reference.ExpectedSnapshot.NativeFixedArrayTypes.Length
                || reference.ExpectedCheckedReferenceMapping.IsDefault
                || reference.ExpectedCheckedReferenceMapping.Length
                    != reference.ExpectedSnapshot.CheckedReferenceTypes.Length
                || reference.ExpectedEnumMapping.IsDefault
                || reference.ExpectedEnumMapping.Length
                    != reference.ExpectedSnapshot.EnumDefinitions.Length
                || reference.ExpectedSnapshot.NominalTypeOrigins.IsDefault)
            {
                throw Invalid();
            }

            var classIndex = ManagedClassTypes.ClassIndex(
                reference.ClassType);
            var expectedClassIndex = ManagedClassTypes.ClassIndex(
                reference.ExpectedClassType);
            if ((uint)expectedClassIndex
                    >= (uint)reference.ExpectedSnapshot.Classes.Length
                || reference.ExpectedStructureMapping.IsDefault
                || reference.ExpectedClassMapping.IsDefault
                || reference.ExpectedStructureMapping.Length
                    != reference.ExpectedSnapshot.Structures.Length
                || reference.ExpectedClassMapping.Length
                    != reference.ExpectedSnapshot.Classes.Length
                || reference.ExpectedNativePointerMapping.Any(index =>
                    index < -1
                    || (index >= 0
                        && (uint)index >= (uint)program.NativePointerTypes.Length))
                || reference.ExpectedNativeFunctionPointerMapping.Any(index =>
                    index < -1
                    || (index >= 0 && (uint)index
                        >= (uint)program.NativeFunctionPointerSignatures.Length))
                || reference.ExpectedNativeFixedArrayMapping.Any(index =>
                    index < -1
                    || (index >= 0 && (uint)index
                        >= (uint)program.NativeFixedArrayTypes.Length))
                || reference.ExpectedCheckedReferenceMapping.Any(index =>
                    index < -1
                    || (index >= 0 && (uint)index
                        >= (uint)program.CheckedReferenceTypes.Length))
                || reference.ExpectedEnumMapping.Any(index =>
                    index < -1
                    || (index >= 0 && (uint)index
                        >= (uint)program.EnumDefinitions.Length))
                || reference.ExpectedStructureMapping.Any(index =>
                    (uint)index >= (uint)program.Structures.Length)
                || reference.ExpectedClassMapping.Any(index =>
                    (uint)index >= (uint)program.Classes.Length)
                || reference.ExpectedClassMapping[expectedClassIndex]
                    != ManagedClassTypes.ClassIndex(
                        reference.ClassType)
                || !MatchesPrivateClassTypeMappings(program, reference)
                || !MatchesPrivateClassSnapshot(program,
                    classIndex, reference, expectedClassIndex)
                || reference.Origin.PrivateType != reference.ClassType
                || !program.PrivateNominalTypeOrigins.Contains(
                    reference.Origin)
                || !reference.ExpectedSnapshot.NominalTypeOrigins.Any(
                    origin => origin.PrivateType
                        == reference.ExpectedClassType
                        && origin == (reference.Origin with {
                            PrivateType = reference.ExpectedClassType,
                        })))
            {
                throw Invalid();
            }
            _ = result.Add(classIndex);
        }

        return result;
    }

    private static bool MatchesPrivateClassSnapshot(BoundProgram program,
        int classIndex, BoundPrivateClassReference reference,
        int expectedClassIndex)
    {
        var snapshot = reference.ExpectedSnapshot;
        if (reference.ExpectedStructureMapping.IsDefault
            || reference.ExpectedClassMapping.IsDefault
            || reference.ExpectedNativePointerMapping.IsDefault
            || reference.ExpectedNativeFunctionPointerMapping.IsDefault
            || reference.ExpectedNativeFixedArrayMapping.IsDefault
            || reference.ExpectedCheckedReferenceMapping.IsDefault
            || reference.ExpectedEnumMapping.IsDefault
            || reference.ExpectedStructureMapping.Length
                != snapshot.Structures.Length
            || reference.ExpectedClassMapping.Length
                != snapshot.Classes.Length
            || reference.ExpectedNativePointerMapping.Length
                != snapshot.NativePointerTypes.Length
            || reference.ExpectedNativeFunctionPointerMapping.Length
                != snapshot.NativeFunctionPointerSignatures.Length
            || reference.ExpectedNativeFixedArrayMapping.Length
                != snapshot.NativeFixedArrayTypes.Length
            || reference.ExpectedCheckedReferenceMapping.Length
                != snapshot.CheckedReferenceTypes.Length
            || reference.ExpectedEnumMapping.Length
                != snapshot.EnumDefinitions.Length)
        {
            return false;
        }

        var expected = snapshot.Classes[expectedClassIndex];
        var actual = program.Classes[classIndex];
        if ((reference.IsSourceLookupRoot
                && expected.Name != actual.Name)
            || expected.Size != actual.Size
            || expected.IsMutable != actual.IsMutable
            || expected.Fields.Length != actual.Fields.Length)
        {
            return false;
        }

        for (var fieldIndex = 0; fieldIndex < expected.Fields.Length;
            fieldIndex++)
        {
            var expectedField = expected.Fields[fieldIndex];
            var actualField = actual.Fields[fieldIndex];
            if (expectedField.Name != actualField.Name
                || expectedField.Offset != actualField.Offset
                || expectedField.Size != actualField.Size
                || expectedField.IsMutable != actualField.IsMutable
                || expectedField.IsPrivate != actualField.IsPrivate
                || expectedField.IsInternal != actualField.IsInternal
                || expectedField.RequiresUnsafeCaller
                    != actualField.RequiresUnsafeCaller
                || MapExpectedClassType(expectedField.Type, reference,
                    program)
                    != actualField.Type)
            {
                return false;
            }
        }
        return true;
    }

    private static bool MatchesPrivateClassTypeMappings(
        BoundProgram program, BoundPrivateClassReference reference)
    {
        var snapshot = reference.ExpectedSnapshot;
        for (var index = 0;
            index < reference.ExpectedCheckedReferenceMapping.Length;
            index++)
        {
            var destinationIndex
                = reference.ExpectedCheckedReferenceMapping[index];
            if (destinationIndex < 0)
            {
                continue;
            }
            var expected = snapshot.CheckedReferenceTypes[index];
            var actual = program.CheckedReferenceTypes[destinationIndex];
            if (expected.IsWritable != actual.IsWritable
                || expected.IsGarbageCollected
                    != actual.IsGarbageCollected
                || expected.IsInitialization != actual.IsInitialization
                || expected.IsOptional != actual.IsOptional
                || MapExpectedClassType(expected.ReferentType, reference,
                    program) != actual.ReferentType)
            {
                return false;
            }
        }

        for (var index = 0;
            index < reference.ExpectedNativePointerMapping.Length;
            index++)
        {
            var destinationIndex
                = reference.ExpectedNativePointerMapping[index];
            if (destinationIndex < 0)
            {
                continue;
            }
            var expected = snapshot.NativePointerTypes[index];
            var actual = program.NativePointerTypes[destinationIndex];
            if (expected.IsWritable != actual.IsWritable
                || MapExpectedClassType(expected.PointeeType, reference,
                    program) != actual.PointeeType)
            {
                return false;
            }
        }

        for (var index = 0;
            index < reference.ExpectedNativeFunctionPointerMapping.Length;
            index++)
        {
            var destinationIndex
                = reference.ExpectedNativeFunctionPointerMapping[index];
            if (destinationIndex < 0)
            {
                continue;
            }
            var expected
                = snapshot.NativeFunctionPointerSignatures[index];
            var actual
                = program.NativeFunctionPointerSignatures[destinationIndex];
            if (expected.CallingConvention != actual.CallingConvention
                || expected.EffectsMask != actual.EffectsMask
                || expected.ParameterTypes.Length
                    != actual.ParameterTypes.Length
                || expected.NativeParameters.Length
                    != actual.NativeParameters.Length
                || !SameItems(expected.Selectors, actual.Selectors)
                || !SameItems(expected.OutputStates, actual.OutputStates)
                || !SameItems(expected.Dependencies, actual.Dependencies)
                || MapExpectedClassType(expected.ReturnType, reference,
                    program) != actual.ReturnType)
            {
                return false;
            }
            for (var parameterIndex = 0;
                parameterIndex < expected.ParameterTypes.Length;
                parameterIndex++)
            {
                if (MapExpectedClassType(
                        expected.ParameterTypes[parameterIndex], reference,
                        program)
                    != actual.ParameterTypes[parameterIndex])
                {
                    return false;
                }
            }
            for (var parameterIndex = 0;
                parameterIndex < expected.NativeParameters.Length;
                parameterIndex++)
            {
                var expectedParameter
                    = expected.NativeParameters[parameterIndex];
                var actualParameter
                    = actual.NativeParameters[parameterIndex];
                if (expectedParameter.ParameterIndex
                        != actualParameter.ParameterIndex
                    || expectedParameter.Access != actualParameter.Access
                    || expectedParameter.Retention
                        != actualParameter.Retention
                    || expectedParameter.Extent != actualParameter.Extent
                    || MapExpectedClassType(
                        expectedParameter.PointeeType, reference, program)
                        != actualParameter.PointeeType)
                {
                    return false;
                }
            }
        }

        for (var index = 0;
            index < reference.ExpectedNativeFixedArrayMapping.Length;
            index++)
        {
            var destinationIndex
                = reference.ExpectedNativeFixedArrayMapping[index];
            if (destinationIndex < 0)
            {
                continue;
            }
            var expected = snapshot.NativeFixedArrayTypes[index];
            var actual = program.NativeFixedArrayTypes[destinationIndex];
            if (expected.ElementCount != actual.ElementCount
                || expected.ElementStride != actual.ElementStride
                || expected.ByteExtent != actual.ByteExtent
                || expected.Alignment != actual.Alignment
                || expected.RequiredAlignment != actual.RequiredAlignment
                || MapExpectedClassType(expected.ElementType, reference,
                    program) != actual.ElementType)
            {
                return false;
            }
        }

        for (var index = 0;
            index < reference.ExpectedEnumMapping.Length;
            index++)
        {
            var destinationIndex = reference.ExpectedEnumMapping[index];
            if (destinationIndex < 0)
            {
                continue;
            }
            if ((uint)destinationIndex
                    >= (uint)program.EnumDefinitions.Length
                || !MatchesPrivateEnumSnapshot(
                    snapshot.EnumDefinitions[index],
                    program.EnumDefinitions[destinationIndex],
                    BoundEnumTypes.Type(index),
                    BoundEnumTypes.Type(destinationIndex),
                    snapshot.NominalTypeOrigins,
                    program.PrivateNominalTypeOrigins))
            {
                return false;
            }
        }
        return true;

        static bool SameItems<T>(ImmutableArray<T> left,
            ImmutableArray<T> right)
            where T : IEquatable<T>
        {
            var leftLength = left.IsDefault ? 0 : left.Length;
            var rightLength = right.IsDefault ? 0 : right.Length;
            if (leftLength != rightLength)
            {
                return false;
            }
            for (var index = 0; index < leftLength; index++)
            {
                if (!left[index].Equals(right[index]))
                {
                    return false;
                }
            }
            return true;
        }
    }

    private static bool MatchesPrivateEnumSnapshot(
        BoundEnumDefinition expected, BoundEnumDefinition actual,
        PrimitiveType expectedType, PrimitiveType actualType,
        ImmutableArray<BoundPrivateNominalTypeOrigin> expectedOrigins,
        ImmutableArray<BoundPrivateNominalTypeOrigin> actualOrigins)
    {
        if (!BoundEnumTypes.HasSameContractShape(expected, actual))
        {
            return false;
        }

        if (expected.Identity
                is BoundEnumDeclarationIdentity.Core expectedCore
            && actual.Identity
                is BoundEnumDeclarationIdentity.Core actualCore)
        {
            return expectedCore.Value == actualCore.Value
                && BoundEnumTypes.AreEquivalent(expected, actual);
        }
        if (expected.Identity
                is BoundEnumDeclarationIdentity.Standard expectedStandard
            && actual.Identity
                is BoundEnumDeclarationIdentity.Standard actualStandard)
        {
            return ReferenceEquals(expectedStandard.Value,
                    actualStandard.Value)
                && BoundEnumTypes.AreEquivalent(expected, actual);
        }
        if (expected.Identity
                is BoundEnumDeclarationIdentity.Private expectedPrivate
            && actual.Identity
                is BoundEnumDeclarationIdentity.Private actualPrivate)
        {
            var expectedOrigin = expectedPrivate.Value.Origin;
            var actualOrigin = actualPrivate.Value.Origin;
            var originalExpectationMatchesOwner
                = expectedOrigin.OriginKind
                    == BoundPrivateNominalOriginKind.ImportedExpectation
                && actualOrigin.OriginKind
                    == BoundPrivateNominalOriginKind.OwnedDefinition
                && expectedOrigin.SelectedModuleIdentity
                    == actualOrigin.UsingModuleIdentity
                && expectedOrigin.SelectedExportKey
                    == actualOrigin.LocalDeclarationKey;
            var sameRetainedOrigin
                = (expectedOrigin with {
                    PrivateType = default,
                }) == (actualOrigin with {
                    PrivateType = default,
                })
                && expected.ModuleImport == actual.ModuleImport;
            return (originalExpectationMatchesOwner || sameRetainedOrigin)
                && expectedOrigins.Any(origin =>
                    origin.PrivateType == expectedType
                    && (origin with { PrivateType = default })
                        == (expectedOrigin with {
                            PrivateType = default,
                        }))
                && actualOrigins.Any(origin =>
                    origin.PrivateType == actualType
                    && (origin with { PrivateType = default })
                        == (actualOrigin with {
                            PrivateType = default,
                        }));
        }

        return false;
    }

    private static PrimitiveType MapExpectedClassType(PrimitiveType type,
        BoundPrivateClassReference classReference, BoundProgram program)
    {
        if (ManagedClassTypes.IsClass(type)
            || (ManagedClassTypes.IsOptional(type)
                && ManagedClassTypes.IsClass(
                    ManagedClassTypes.Required(type))))
        {
            var sourceClassIndex = ManagedClassTypes.ClassIndex(type);
            if ((uint)sourceClassIndex
                >= (uint)classReference.ExpectedClassMapping.Length)
            {
                throw Invalid();
            }
            var mapped = (PrimitiveType)(ManagedClassTypes.First
                + classReference.ExpectedClassMapping[sourceClassIndex]);
            if (ManagedClassTypes.IsWritable(type))
            {
                mapped = ManagedClassTypes.Writable(mapped);
            }
            if (ManagedClassTypes.IsOptional(type))
            {
                mapped = ManagedClassTypes.Optional(mapped);
            }
            return mapped;
        }
        if (CheckedReferenceTypes.IsType(type))
        {
            var sourceIndex = CheckedReferenceTypes.Index(type);
            if ((uint)sourceIndex
                >= (uint)classReference.ExpectedCheckedReferenceMapping.Length)
            {
                throw Invalid();
            }
            var mappedIndex
                = classReference.ExpectedCheckedReferenceMapping[sourceIndex];
            if (mappedIndex < 0
                || (uint)mappedIndex
                    >= (uint)program.CheckedReferenceTypes.Length)
            {
                throw Invalid();
            }
            return CheckedReferenceTypes.Type(mappedIndex);
        }
        if (NativePointerTypes.IsType(type))
        {
            var sourceIndex = NativePointerTypes.Index(type);
            if ((uint)sourceIndex
                >= (uint)classReference.ExpectedNativePointerMapping.Length)
            {
                throw Invalid();
            }
            var mappedIndex
                = classReference.ExpectedNativePointerMapping[sourceIndex];
            if (mappedIndex < 0
                || (uint)mappedIndex
                    >= (uint)program.NativePointerTypes.Length)
            {
                throw Invalid();
            }
            return NativePointerTypes.Type(mappedIndex);
        }
        if (NativeFunctionPointerTypes.IsType(type))
        {
            var sourceIndex = NativeFunctionPointerTypes.Index(type);
            if ((uint)sourceIndex
                >= (uint)classReference
                    .ExpectedNativeFunctionPointerMapping.Length)
            {
                throw Invalid();
            }
            var mappedIndex = classReference
                .ExpectedNativeFunctionPointerMapping[sourceIndex];
            if (mappedIndex < 0
                || (uint)mappedIndex
                    >= (uint)program.NativeFunctionPointerSignatures.Length)
            {
                throw Invalid();
            }
            return NativeFunctionPointerTypes.Type(mappedIndex);
        }
        if (NativeFixedArrayTypes.IsType(type))
        {
            var sourceIndex = NativeFixedArrayTypes.Index(type);
            if ((uint)sourceIndex
                >= (uint)classReference
                    .ExpectedNativeFixedArrayMapping.Length)
            {
                throw Invalid();
            }
            var mappedIndex = classReference
                .ExpectedNativeFixedArrayMapping[sourceIndex];
            if (mappedIndex < 0
                || (uint)mappedIndex
                    >= (uint)program.NativeFixedArrayTypes.Length)
            {
                throw Invalid();
            }
            return NativeFixedArrayTypes.Type(mappedIndex);
        }
        if (BoundEnumTypes.IsType(type))
        {
            var sourceIndex = BoundEnumTypes.Index(type);
            if ((uint)sourceIndex
                >= (uint)classReference.ExpectedEnumMapping.Length)
            {
                throw Invalid();
            }
            var mappedIndex
                = classReference.ExpectedEnumMapping[sourceIndex];
            if (mappedIndex < 0
                || (uint)mappedIndex
                    >= (uint)program.EnumDefinitions.Length)
            {
                throw Invalid();
            }
            return BoundEnumTypes.Type(mappedIndex);
        }

        var sourceStructureIndex = (int)type - 100;
        if (sourceStructureIndex is >= 0
            and < BoundEnumTypes.First - 100)
        {
            if ((uint)sourceStructureIndex
                >= (uint)classReference.ExpectedStructureMapping.Length)
            {
                throw Invalid();
            }
            return (PrimitiveType)(100
                + classReference.ExpectedStructureMapping[
                    sourceStructureIndex]);
        }
        if (BoundGenericNominalTypeTypes.IsType(type)
            || (int)type < 0 || (int)type >= 100)
        {
            throw Invalid();
        }
        return type;
    }

    private static bool InvalidatesReservedOwner(BoundExpression expression, int variable, ref int remaining, int depth)
    {
        Count(ref remaining, depth);
        if (expression is BoundCall call)
        {
            foreach (var argument in call.Arguments)
            {
                if (InvalidatesReservedOwner(argument, variable, ref remaining, depth + 1))
                {
                    return true;
                }
            }
            return false;
        }
        return expression switch {
            BoundUnsafeExpression unsafeExpression => InvalidatesReservedOwner(
                unsafeExpression.Expression, variable, ref remaining, depth + 1),
            BoundMove move => move.Variable == variable,
            BoundFieldMove move => TryGetFieldRootVariable(move.Place, out var rootVariable)
                && rootVariable == variable,
            BoundOutArgument output => output.Variable == variable,
            BoundMutableReceiverLoan loan => loan.Variable == variable,
            BoundMutableFieldLoan loan => LoanRoot(loan, ref remaining, depth + 1) == variable,
            BoundUnary unary => InvalidatesReservedOwner(unary.Operand, variable, ref remaining, depth + 1),
            BoundUpdate update => WritesUpdateRoot(update.Place, variable, ref remaining, depth + 1)
                || InvalidatesReservedOwner(update.Place, variable, ref remaining, depth + 1),
            BoundNominalUpdate update => WritesUpdateRoot(update.Place, variable, ref remaining, depth + 1)
                || InvalidatesReservedOwner(update.Place, variable, ref remaining, depth + 1),
            BoundCompoundAssignment compound => WritesUpdateRoot(compound.Place, variable, ref remaining, depth + 1)
                || InvalidatesReservedOwner(compound.Place, variable, ref remaining, depth + 1)
                || InvalidatesReservedOwner(compound.Right, variable, ref remaining, depth + 1),
            BoundCast cast => InvalidatesReservedOwner(cast.Operand, variable, ref remaining, depth + 1),
            BoundOptionalLift lift => InvalidatesReservedOwner(lift.Value, variable, ref remaining, depth + 1),
            BoundReadonlyProjection projection => InvalidatesReservedOwner(projection.Value, variable, ref remaining, depth + 1),
            BoundIsNull test => InvalidatesReservedOwner(test.Value, variable, ref remaining, depth + 1),
            BoundCoalesce coalesce => InvalidatesReservedOwner(coalesce.Optional, variable, ref remaining, depth + 1)
                || InvalidatesReservedOwner(coalesce.Fallback, variable, ref remaining, depth + 1),
            BoundIsSome pattern => InvalidatesReservedOwner(pattern.Value, variable, ref remaining, depth + 1),
            BoundIsVariablePattern pattern => InvalidatesReservedOwner(pattern.Value, variable, ref remaining, depth + 1),
            BoundBinary binary => InvalidatesReservedOwner(binary.Left, variable, ref remaining, depth + 1)
                || InvalidatesReservedOwner(binary.Right, variable, ref remaining, depth + 1),
            BoundConditional conditional => InvalidatesReservedOwner(conditional.Condition, variable, ref remaining, depth + 1)
                || InvalidatesReservedOwner(conditional.WhenTrue, variable, ref remaining, depth + 1)
                || InvalidatesReservedOwner(conditional.WhenFalse, variable, ref remaining, depth + 1),
            BoundFieldRead field => InvalidatesReservedOwner(field.Receiver, variable, ref remaining, depth + 1),
            BoundBufferRead buffer => InvalidatesReservedOwner(buffer.Index, variable, ref remaining, depth + 1),
            BoundViewRead view => InvalidatesReservedOwner(view.Index, variable, ref remaining, depth + 1),
            BoundSpanLength length => InvalidatesReservedOwner(length.View, variable, ref remaining, depth + 1),
            BoundSpanRead read => InvalidatesReservedOwner(read.View, variable, ref remaining, depth + 1)
                || InvalidatesReservedOwner(read.Index, variable, ref remaining, depth + 1),
            BoundSpanAdvance advance => InvalidatesReservedOwner(advance.View, variable, ref remaining, depth + 1),
            _ => false,
        };
    }

    private static bool WritesUpdateRoot(BoundExpression place, int variable, ref int remaining, int depth)
    {
        Count(ref remaining, depth);
        return place switch {
            BoundRead read => read.Variable == variable,
            BoundFieldRead field => WritesUpdateRoot(field.Receiver, variable, ref remaining, depth + 1),
            _ => false,
        };
    }

    private static int UpdateRoot(BoundExpression place, ref int remaining, int depth)
    {
        Count(ref remaining, depth);
        return place switch {
            BoundRead read => read.Variable,
            BoundFieldRead field when !ManagedClassTypes.IsClass(field.Receiver.Type) =>
                UpdateRoot(field.Receiver, ref remaining, depth + 1),
            _ => -1,
        };
    }

    private static bool IsProvenBufferIndex(int buffer, BoundExpression index, BoundProgram program) =>
        buffer >= 0 && buffer < program.Buffers.Length
            && !program.Buffers[buffer].IsInvocationScoped
            && index is BoundConstant { Type: PrimitiveType.Int32 } constant
            && constant.Value >= 0 && constant.Value < program.Buffers[buffer].Values.Length;

    private static bool IsProvenBufferIndex(int buffer,
        BoundExpression index, BoundProgram program,
        InitializationState initialized, ref int remaining)
    {
        if (IsProvenBufferIndex(buffer, index, program))
        {
            return true;
        }
        if ((uint)buffer >= (uint)program.Buffers.Length
            || !program.Buffers[buffer].IsInvocationScoped
            || index.Type != PrimitiveType.Int32
            || !TryGetIntegerLinearExpression(index, initialized,
                out var indexExpression)
            || !initialized.TryGetBufferLengthSymbol(buffer,
                out var lengthSymbol))
        {
            return false;
        }

        var indexNonnegative = initialized
            .TryProveIntegerExpressionAtMost(
                NegateIntegerLinearExpression(indexExpression),
                BigInteger.Zero, ref remaining);
        if (!indexNonnegative)
        {
            return false;
        }
        var lengthExpression = CreateIntegerLinearExpression(
            ImmutableDictionary<long, BigInteger>.Empty.Add(lengthSymbol,
                BigInteger.One), BigInteger.Zero);
        var strictlyBelowLength = AddIntegerLinearExpressions(
            AddIntegerLinearExpressions(indexExpression,
                NegateIntegerLinearExpression(lengthExpression),
                BigInteger.One),
            IntegerConstantExpression(BigInteger.One),
            BigInteger.One);
        return initialized.TryProveIntegerExpressionAtMost(
            strictlyBelowLength, BigInteger.Zero, ref remaining);
    }

    internal static bool IsTotalConversion(PrimitiveType source, PrimitiveType destination)
    {
        if (source == destination)
        {
            return true;
        }
        if (destination == PrimitiveType.Int128)
        {
            return PrimitiveTypeFacts.IsInteger(source) || source == PrimitiveType.Char16;
        }
        if (destination == PrimitiveType.UInt128)
        {
            return source == PrimitiveType.Char16
                || (PrimitiveTypeFacts.IsInteger(source) && !PrimitiveTypeFacts.IsSignedInteger(source));
        }
        if (destination is PrimitiveType.Float32 or PrimitiveType.Float64)
        {
            return PrimitiveTypeFacts.IsInteger(source) || source == PrimitiveType.Char16
                || source is PrimitiveType.Float32 or PrimitiveType.Float64;
        }
        if (source == PrimitiveType.Char16)
        {
            if (!PrimitiveTypeFacts.IsInteger(destination))
            {
                return false;
            }
            var codeUnitDestinationWidth = PrimitiveTypeFacts.IntegerWidth(destination);
            return PrimitiveTypeFacts.IsSignedInteger(destination)
                ? codeUnitDestinationWidth >= 32 : codeUnitDestinationWidth >= 16;
        }
        if (!PrimitiveTypeFacts.IsInteger(source)
            || !(PrimitiveTypeFacts.IsInteger(destination) || destination == PrimitiveType.Char16))
        {
            return false;
        }

        var sourceWidth = PrimitiveTypeFacts.IntegerWidth(source);
        var destinationWidth = destination == PrimitiveType.Char16
            ? 16 : PrimitiveTypeFacts.IntegerWidth(destination);
        var sourceSigned = PrimitiveTypeFacts.IsSignedInteger(source);
        var destinationSigned = destination != PrimitiveType.Char16
            && PrimitiveTypeFacts.IsSignedInteger(destination);
        if (sourceSigned)
        {
            return destinationSigned && destinationWidth >= sourceWidth;
        }
        return destinationSigned ? destinationWidth > sourceWidth : destinationWidth >= sourceWidth;
    }

    private static uint FullMask(BoundProgram program, PrimitiveType type)
    {
        var count = Fields(program, type).Length;
        return count == 32 ? uint.MaxValue : (1u << count) - 1;
    }

    private static byte[] GuaranteedInitializedPayloadBytes(
        PrimitiveType type, BoundProgram program)
    {
        var remaining = MaximumAnalysisVisits;
        return GuaranteedInitializedPayloadBytes(type, program, [], ref remaining,
            depth: 0);
    }

    internal static byte[] RawUnionGuaranteedInitializedPayloadBytes(
        PrimitiveType type, BoundProgram program)
    {
        if (!IsRawUnionType(program, type))
        {
            throw Invalid();
        }

        return GuaranteedInitializedPayloadBytes(type, program);
    }

    internal static bool HasRawUnionReturnCoverageSubject(
        PrimitiveType type, BoundProgram program) =>
        HasRawUnionReturnCoverageSubjectCore(program, type);

    private static bool HasRawUnionReturnCoverageSubjectCore(
        BoundProgram program, PrimitiveType type)
    {
        var pending = new Stack<(PrimitiveType Type, int Depth)>();
        var visited = new HashSet<PrimitiveType>();
        var remaining = MaximumAnalysisVisits;
        pending.Push((type, 0));
        while (pending.TryPop(out var item))
        {
            Count(ref remaining, item.Depth);
            if (IsRawUnionType(program, item.Type))
            {
                return true;
            }
            if (NativeFixedArrayTypes.IsType(item.Type))
            {
                if (!visited.Add(item.Type))
                {
                    continue;
                }
                if (!NativeFixedArrayContract.TryGetLayout(item.Type,
                        program, out var layout))
                {
                    throw InvalidEffect(default, "NativeImport");
                }
                pending.Push((layout.ElementType, item.Depth + 1));
                continue;
            }
            if (NativeFixedArrayContract.IsCarrier(item.Type)
                || ManagedClassTypes.IsClass(item.Type)
                || !HasFields(program, item.Type)
                || !visited.Add(item.Type))
            {
                continue;
            }
            foreach (var field in Fields(program, item.Type))
            {
                Count(ref remaining, item.Depth + 1);
                pending.Push((field.Type, item.Depth + 1));
            }
        }
        return false;
    }

    internal static byte[] RawUnionReturnCoverageBaseBytes(
        PrimitiveType type, BoundProgram program)
    {
        if (!HasRawUnionReturnCoverageSubject(type, program))
        {
            throw Invalid();
        }

        return GuaranteedInitializedPayloadBytes(type, program);
    }

    internal static byte[] RawUnionReturnCoveragePossibleBytes(
        PrimitiveType type, BoundProgram program)
    {
        if (!HasRawUnionReturnCoverageSubject(type, program))
        {
            throw Invalid();
        }

        var remaining = MaximumAnalysisVisits;
        return RawUnionReturnCoveragePossibleBytes(type, program,
            new HashSet<PrimitiveType>(), ref remaining, 0);
    }

    private static byte[] RawUnionReturnCoveragePossibleBytes(
        PrimitiveType type, BoundProgram program,
        HashSet<PrimitiveType> visiting, ref int remaining, int depth)
    {
        Count(ref remaining, depth);
        var size = MaterializedPayloadSize(type, program);
        var result = new byte[size];
        if (size == 0)
        {
            return result;
        }

        if (NativeFixedArrayTypes.IsType(type))
        {
            if (!visiting.Add(type))
            {
                throw Invalid();
            }

            try
            {
                if (!NativeFixedArrayContract.TryGetLayout(type,
                        program, out var layout))
                {
                    throw Invalid();
                }

                var elementBytes = RawUnionReturnCoveragePossibleBytes(
                    layout.ElementType, program, visiting, ref remaining,
                    depth + 1);
                if (layout.ElementStride < (ulong)elementBytes.Length
                    || layout.ByteExtent != (ulong)result.Length
                    || (layout.ElementCount != 0
                        && layout.ElementStride == 0)
                    || layout.ElementCount > (ulong)size + 1UL)
                {
                    throw Invalid();
                }

                for (ulong element = 0;
                    element < layout.ElementCount; element++)
                {
                    Count(ref remaining, depth + 1);
                    var offset = checked((int)(element
                        * layout.ElementStride));
                    if (offset > result.Length
                        || elementBytes.Length > result.Length - offset)
                    {
                        throw Invalid();
                    }
                    elementBytes.CopyTo(result, offset);
                }
            }
            finally
            {
                _ = visiting.Remove(type);
            }
            return result;
        }

        if (HasFields(program, type)
            && !ManagedClassTypes.IsClass(type))
        {
            if (!visiting.Add(type))
            {
                throw Invalid();
            }

            try
            {
                var structure = program.Structures[(int)type - 100];
                foreach (var field in structure.Fields)
                {
                    Count(ref remaining, depth + 1);
                    var fieldBytes = RawUnionReturnCoveragePossibleBytes(
                        field.Type, program, visiting, ref remaining,
                        depth + 1);
                    if (field.Offset > (ulong)result.Length
                        || (ulong)fieldBytes.Length
                            > (ulong)result.Length - field.Offset
                        || field.Size != (ulong)fieldBytes.Length)
                    {
                        throw Invalid();
                    }

                    var offset = checked((int)field.Offset);
                    for (var index = 0; index < fieldBytes.Length; index++)
                    {
                        Count(ref remaining, depth + 1);
                        if (fieldBytes[index] != 0)
                        {
                            result[offset + index] = 1;
                        }
                    }
                }
            }
            finally
            {
                _ = visiting.Remove(type);
            }
            return result;
        }

        Array.Fill(result, (byte)1);
        return result;
    }

    private static bool TryGetFieldPathOffset(PrimitiveType rootType,
        FieldProjectionPath fieldPath, BoundProgram program,
        out ulong byteOffset)
    {
        byteOffset = 0;
        var currentType = rootType;
        foreach (var segment in fieldPath.Segments)
        {
            if (segment.OwnerType != currentType
                || !HasFields(program, currentType)
                || (uint)segment.Field
                    >= (uint)Fields(program, currentType).Length)
            {
                return false;
            }

            var field = Fields(program, currentType)[segment.Field];
            byteOffset = checked(byteOffset + field.Offset);
            currentType = field.Type;
        }

        return !fieldPath.Segments.IsDefaultOrEmpty;
    }

    private static bool TryGetFieldPathByteOffset(PrimitiveType rootType,
        FieldProjectionPath fieldPath, BoundProgram program,
        out int byteOffset)
    {
        byteOffset = 0;
        if (!TryGetFieldPathOffset(rootType, fieldPath, program,
                out var offset))
        {
            return false;
        }

        byteOffset = MaterializedPayloadOffset(offset);
        return true;
    }

    private static byte[] RawUnionInitializedPayloadBytesForCall(
        BoundCall call, BoundFunction target,
        BoundCopyOriginSummary? copyOriginSummary,
        IReadOnlyDictionary<int, StagedCopyOriginInput> stagedInputs,
        ImmutableArray<byte>[] returnCoverageSummaries,
        BoundProgram program)
    {
        if (call.Type != target.ReturnType)
        {
            throw Invalid(call.Span);
        }

        var resultSize = MaterializedPayloadSize(call.Type, program);

        var initializedBytes = GuaranteedInitializedPayloadBytes(
            call.Type, program);
        if ((uint)call.Function < (uint)returnCoverageSummaries.Length)
        {
            var returnCoverage = returnCoverageSummaries[call.Function];
            if (!returnCoverage.IsDefaultOrEmpty)
            {
                if (returnCoverage.Length != resultSize)
                {
                    throw Invalid(call.Span);
                }
                initializedBytes = [.. returnCoverage];
            }
        }
        if (copyOriginSummary is null)
        {
            return initializedBytes;
        }

        ValidateCopyOriginSummary(target, copyOriginSummary, program);
        foreach (var fact in copyOriginSummary.Facts)
        {
            if (!TryResolveCopyOriginFieldPath(target.ReturnType,
                    fact.DestinationPath, program,
                    out var destinationType)
                || !CarriesRawUnionPayloadFacts(program, destinationType))
            {
                continue;
            }

            if (!TryGetCopyOriginPathByteOffset(target.ReturnType,
                    fact.DestinationPath, program, out var destinationOffset))
            {
                throw Invalid(call.Span);
            }

            var destinationSize = MaterializedPayloadSize(
                destinationType, program);
            if (destinationOffset > initializedBytes.Length
                || destinationSize > initializedBytes.Length - destinationOffset)
            {
                throw Invalid(call.Span);
            }

            byte[]? commonSourceBytes = null;
            var canForwardCoverage = true;
            foreach (var origin in fact.Origins)
            {
                var parameterIndex = CopyOriginCallParameterIndex(target,
                    origin);
                if (origin.SourceKind != BoundCopyOriginSourceKind.Formal
                    || origin.SourceView
                        != BoundCopyOriginSourceView.EntryValue
                    || !stagedInputs.TryGetValue(parameterIndex,
                        out var stagedInput)
                    || stagedInput.SourceView != origin.SourceView
                    || stagedInput.RawUnionInitializedBytes is not { } sourceBytes
                    || !TryGetCopyOriginSourceType(target, origin, program,
                        out var sourceRootType)
                    || stagedInput.Argument.Type != sourceRootType
                    || !TryResolveCopyOriginFieldPath(sourceRootType,
                        origin.SourcePath, program, out var sourceType)
                    || sourceType != destinationType)
                {
                    canForwardCoverage = false;
                    break;
                }

                var sourceSize = MaterializedPayloadSize(
                    sourceRootType, program);
                if (sourceBytes.Length != sourceSize
                    || !TryGetCopyOriginPathByteOffset(sourceRootType,
                        origin.SourcePath, program, out var sourceOffset))
                {
                    throw Invalid(call.Span);
                }
                if (sourceOffset > sourceBytes.Length
                    || destinationSize > sourceBytes.Length - sourceOffset)
                {
                    throw Invalid(call.Span);
                }

                var currentSourceBytes = sourceBytes.AsSpan(sourceOffset,
                    destinationSize);
                if (commonSourceBytes is null)
                {
                    commonSourceBytes = currentSourceBytes.ToArray();
                }
                else
                {
                    for (var index = 0; index < commonSourceBytes.Length; index++)
                    {
                        commonSourceBytes[index] &= currentSourceBytes[index];
                    }
                }
            }

            if (canForwardCoverage && commonSourceBytes is not null)
            {
                for (var index = 0; index < commonSourceBytes.Length; index++)
                {
                    if (commonSourceBytes[index] != 0)
                    {
                        initializedBytes[destinationOffset + index] = 1;
                    }
                }
            }
        }

        return initializedBytes;
    }

    private static bool TryGetCopyOriginPathByteOffset(
        PrimitiveType rootType, BoundCopyOriginFieldPath path,
        BoundProgram program, out int byteOffset)
    {
        byteOffset = 0;
        var fieldPath = default(FieldProjectionPath);
        foreach (var step in path.Steps)
        {
            fieldPath = fieldPath.Append(step.OwnerType, step.FieldOrdinal);
        }
        return path.Steps.IsEmpty
            || TryGetFieldPathByteOffset(rootType, fieldPath, program,
                out byteOffset);
    }

    private static byte[] InitializedPayloadBytesOfExpression(
        BoundExpression expression, PrimitiveType type,
        InitializationState initialized, BoundFunction function,
        BoundProgram program, ref int remaining, int depth)
    {
        if (!CarriesRawUnionPayloadFacts(program, type))
        {
            return GuaranteedInitializedPayloadBytes(type, program);
        }

        if (expression is BoundCall call
            && call.Type == type)
        {
            if (initialized.Dependencies is BackingDependencies
                    callDependencies
                && callDependencies.TryGetRawUnionCallCoverageResult(
                    call, out var callInitializedBytes))
            {
                return callInitializedBytes;
            }
            if ((uint)call.Function
                    < (uint)initialized.RawUnionReturnCoverageSummaries.Length
                && initialized.RawUnionReturnCoverageSummaries[
                    call.Function].Length
                    == MaterializedPayloadSize(type, program))
            {
                return [.. initialized.RawUnionReturnCoverageSummaries[
                    call.Function]];
            }
        }

        if (expression is BoundReferenceRead referenceRead
            && referenceRead.Type == type)
        {
            return InitializedRawUnionPayloadBytesOfReferenceRead(
                referenceRead, type, initialized, function, program);
        }
        if (expression is BoundPrivatePlaceRead {
                UseKind: 1,
            } privatePlaceRead
            && privatePlaceRead.Type == type)
        {
            var placeExpression = PrivateBodyPlaceExpression(
                privatePlaceRead.Place, function, program,
                privatePlaceRead.Span, ref remaining, depth + 1);
            return InitializedPayloadBytesOfExpression(placeExpression,
                type, initialized, function, program, ref remaining,
                depth + 1);
        }

        if (expression is BoundRead read && read.Type == type
            && initialized.TryGetRawUnionInitializedBytes(read.Variable,
                out var readBytes))
        {
            return InitializedRawUnionArrayPayloadBytesOfValue(
                read.Variable, type, readBytes, initialized, program,
                ref remaining, depth + 1);
        }
        if (expression is BoundMove move && move.Type == type
            && initialized.TryGetRawUnionInitializedBytes(move.Variable,
                out var moveBytes))
        {
            return InitializedRawUnionArrayPayloadBytesOfValue(
                move.Variable, type, moveBytes, initialized, program,
                ref remaining, depth + 1);
        }
        if (expression is BoundConditional conditional
            && conditional.Type == type
            && conditional.WhenTrue.Type == type
            && conditional.WhenFalse.Type == type)
        {
            var whenTrue = InitializedPayloadBytesOfExpression(
                conditional.WhenTrue, type, initialized, function, program,
                ref remaining, depth + 1);
            var whenFalse = InitializedPayloadBytesOfExpression(
                conditional.WhenFalse, type, initialized, function, program,
                ref remaining, depth + 1);
            if (whenTrue.Length != whenFalse.Length)
            {
                throw Invalid(conditional.Span);
            }
            for (var index = 0; index < whenTrue.Length; index++)
            {
                whenTrue[index] &= whenFalse[index];
            }
            return whenTrue;
        }
        if (expression is BoundNativeFixedArrayElement fixedArrayElement
            && fixedArrayElement.Type == type)
        {
            if (!TryGetNativeFixedArrayArrayPrefix(
                    fixedArrayElement.Variable,
                    fixedArrayElement.FieldPlace,
                    fixedArrayElement.Layout, function, program,
                    out var arrayPrefix))
            {
                throw Invalid(fixedArrayElement.Span);
            }
            var elementIndex
                = NativeFixedArrayContract.TryGetUnsignedIndex(
                    fixedArrayElement.Index, out var selectedIndex)
                    ? selectedIndex : (ulong?)null;
            return initialized.RawUnionArrayElementBytes(
                fixedArrayElement.Variable, arrayPrefix,
                fixedArrayElement.Layout, elementIndex);
        }
        if (expression is BoundNativeFixedArrayPathElement pathElement
            && pathElement.Type == type
            && !pathElement.Projections.IsDefaultOrEmpty)
        {
            var parentProjections = pathElement.Projections.Length == 1
                ? [] : pathElement.Projections.RemoveAt(
                    pathElement.Projections.Length - 1);
            if (!TryGetNativeFixedArrayArrayPrefix(
                    pathElement.Variable, pathElement.FieldPlace,
                    pathElement.Projections[0].Layout, function, program,
                    out var fieldArrayPrefix))
            {
                throw Invalid(pathElement.Span);
            }
            var arrayPrefix = GetNativeFixedArrayPathPrefix(
                fieldArrayPrefix, parentProjections);
            var leafProjection = pathElement.Projections[^1];
            var elementIndex
                = NativeFixedArrayContract.TryGetUnsignedIndex(
                    leafProjection.Index, out var selectedIndex)
                    ? selectedIndex : (ulong?)null;
            return initialized.RawUnionArrayElementBytes(
                pathElement.Variable, arrayPrefix, leafProjection.Layout,
                elementIndex);
        }
        if (expression is BoundFieldRead arrayElementField
            && arrayElementField.Type == type
            && TryGetNativeFixedArrayElementFieldPath(arrayElementField,
                function, program, out var arrayVariable,
                out var arrayFieldPlace, out var arrayProjections,
                out var arrayLeafLayout, out var elementFieldPath)
            && TryGetNativeFixedArrayArrayPrefix(arrayVariable,
                arrayFieldPlace, arrayProjections[0].Layout, function,
                program, out var arrayFieldPrefix)
            && TryGetFieldPathByteOffset(arrayLeafLayout.ElementType,
                elementFieldPath, program, out var fieldOffset))
        {
            var parentProjections = arrayProjections.Length == 1
                ? [] : arrayProjections.RemoveAt(
                    arrayProjections.Length - 1);
            var arrayPrefix = GetNativeFixedArrayPathPrefix(
                arrayFieldPrefix, parentProjections);
            var leafProjection = arrayProjections[^1];
            var elementIndex
                = NativeFixedArrayContract.TryGetUnsignedIndex(
                    leafProjection.Index, out var selectedIndex)
                    ? selectedIndex : (ulong?)null;
            var initializedBytes = initialized.RawUnionArrayElementBytes(
                arrayVariable, arrayPrefix, arrayLeafLayout, elementIndex);
            var size = MaterializedPayloadSize(type, program);
            if (fieldOffset <= initializedBytes.Length
                && size <= initializedBytes.Length - fieldOffset)
            {
                return initializedBytes.AsSpan(fieldOffset, size).ToArray();
            }
        }
        if (expression is BoundFieldRead fieldRead
            && fieldRead.Type == type
            && TryGetFieldProjectionPath(fieldRead, function, program,
                out var rootVariable, out var fieldPath)
            && TryGetFieldPathByteOffset(
                function.Variables[rootVariable].Type, fieldPath, program,
                out var offset)
            && initialized.TryGetRawUnionInitializedBytes(rootVariable,
                out var rootBytes))
        {
            var size = MaterializedPayloadSize(type, program);
            if (offset <= rootBytes.Length
                && size <= rootBytes.Length - offset)
            {
                return rootBytes.AsSpan(offset, size).ToArray();
            }
        }

        return GuaranteedInitializedPayloadBytes(type, program);
    }

    private static byte[] InitializedRawUnionArrayPayloadBytesOfValue(
        int variable, PrimitiveType type, byte[] initializedBytes,
        InitializationState initialized, BoundProgram program,
        ref int remaining, int depth)
    {
        if (initializedBytes.Length
                != MaterializedPayloadSize(type, program)
            || !CarriesRawUnionArrayFacts(program, type))
        {
            return initializedBytes;
        }

        var result = (byte[])initializedBytes.Clone();
        OverlayRawUnionArrayFacts(variable, type, 0,
            StorageProjection.WholeObject, result, initialized, program,
            ref remaining, depth);
        return result;
    }

    private static void OverlayRawUnionArrayFacts(int variable,
        PrimitiveType currentType, int offset,
        StorageProjection arrayPrefix, byte[] result,
        InitializationState initialized, BoundProgram program,
        ref int remaining, int depth)
    {
        Count(ref remaining, depth);
        if (NativeFixedArrayTypes.IsType(currentType))
        {
            if (!CarriesRawUnionPayloadFacts(program, currentType))
            {
                return;
            }
            if (!NativeFixedArrayContract.TryGetLayout(currentType,
                    program, out var layout))
            {
                throw Invalid();
            }

            var elementSize = MaterializedPayloadSize(layout.ElementType,
                program);
            var extent = MaterializedPayloadSize(currentType, program);
            if (layout.ElementStride < (ulong)elementSize
                || layout.ByteExtent != (ulong)extent
                || (layout.ElementCount != 0
                    && layout.ElementStride == 0)
                || layout.ElementCount > (ulong)extent + 1UL)
            {
                throw Invalid();
            }

            for (ulong element = 0;
                element < layout.ElementCount; element++)
            {
                Count(ref remaining, depth + 1);
                var elementOffset = checked(offset
                    + checked((int)(element * layout.ElementStride)));
                if (elementOffset > result.Length
                    || elementSize > result.Length - elementOffset)
                {
                    throw Invalid();
                }

                var elementBytes =
                    initialized.RawUnionArrayElementBytes(variable,
                        arrayPrefix, layout, element);
                if (elementBytes.Length != elementSize)
                {
                    throw Invalid();
                }
                elementBytes.CopyTo(result, elementOffset);
                var elementProjection = StorageProjection.Combine(
                    arrayPrefix,
                    StorageProjection.ForArrayIndex(element));
                OverlayRawUnionArrayFacts(variable, layout.ElementType,
                    elementOffset, elementProjection, result, initialized,
                    program, ref remaining, depth + 1);
            }
            return;
        }

        if (!HasFields(program, currentType)
            || ManagedClassTypes.IsClass(currentType))
        {
            return;
        }

        var fields = Fields(program, currentType);
        for (var fieldIndex = 0; fieldIndex < fields.Length; fieldIndex++)
        {
            Count(ref remaining, depth + 1);
            var field = fields[fieldIndex];
            var fieldOffset = checked(offset
                + MaterializedPayloadOffset(field.Offset));
            var fieldSize = MaterializedPayloadSize(field.Type, program);
            if (fieldOffset > result.Length
                || fieldSize > result.Length - fieldOffset)
            {
                throw Invalid();
            }
            OverlayRawUnionArrayFacts(variable, field.Type, fieldOffset,
                arrayPrefix.AppendField(currentType, fieldIndex), result,
                initialized, program, ref remaining, depth + 1);
        }
    }

    private static byte[] InitializedRawUnionPayloadBytesOfReferenceRead(
        BoundReferenceRead referenceRead, PrimitiveType type,
        InitializationState initialized, BoundFunction function,
        BoundProgram program)
    {
        var fallback = GuaranteedInitializedPayloadBytes(type, program);
        if (referenceRead.Descriptor is not BoundRead descriptor
            || (uint)descriptor.Variable >= (uint)function.Variables.Length
            || function.Variables[descriptor.Variable].Type
                != descriptor.Type
            || initialized.Dependencies is not BackingDependencies facts
            || (uint)descriptor.Variable >= (uint)facts.ReferenceTargets.Length
            || facts.ReferenceTargets[descriptor.Variable]
                is not { Count: > 0 } targets)
        {
            return fallback;
        }

        byte[]? common = null;
        foreach (var target in targets)
        {
            var targetBytes = fallback;
            if ((target.Kind is ProvenanceAnchorKind.NativeStorage
                    or ProvenanceAnchorKind.ReferencePlace)
                && target.Storage is StorageKey storage
                && storage.IsKnown
                && target.Identity == storage.Site
                && (uint)target.Identity < (uint)function.Variables.Length)
            {
                targetBytes = InitializedRawUnionPayloadBytesOfStoragePlace(
                    target.Identity, storage.Projection, type, initialized,
                    function, program, fallback);
            }

            if (common is null)
            {
                common = [.. targetBytes];
                continue;
            }
            for (var index = 0; index < common.Length; index++)
            {
                common[index] &= targetBytes[index];
            }
        }

        return common ?? fallback;
    }

    private static byte[] InitializedRawUnionPayloadBytesOfStoragePlace(
        int variable, StorageProjection projection, PrimitiveType type,
        InitializationState initialized, BoundFunction function,
        BoundProgram program, byte[] fallback)
    {
        var rootType = function.Variables[variable].Type;
        var segments = projection.ProjectionPath.Segments;
        if (segments.IsEmpty)
        {
            return projection.Kind == StorageProjectionKind.WholeObject
                && rootType == type
                && initialized.TryGetRawUnionInitializedBytes(variable,
                    out var storedBytes)
                && storedBytes.Length == fallback.Length
                    ? storedBytes : fallback;
        }

        var currentType = rootType;
        var currentProjection = StorageProjection.WholeObject;
        var rootFieldPath = default(FieldProjectionPath);
        var crossedArray = false;
        for (var index = 0; index < segments.Length; index++)
        {
            var segment = segments[index];
            if (segment.Kind == StorageProjectionSegmentKind.Field)
            {
                if (segment.OwnerType != currentType
                    || !HasFields(program, currentType)
                    || (uint)segment.Field
                        >= (uint)Fields(program, currentType).Length)
                {
                    return fallback;
                }

                currentProjection = currentProjection.AppendField(
                    currentType, segment.Field);
                rootFieldPath = rootFieldPath.Append(currentType,
                    segment.Field);
                currentType = Fields(program, currentType)[
                    segment.Field].Type;
                continue;
            }

            if (segment.Kind is not (
                    StorageProjectionSegmentKind.ArrayIndex
                    or StorageProjectionSegmentKind.ArrayRange)
                || !NativeFixedArrayContract.TryGetLayout(currentType,
                    program, out var layout)
                || !NativeFixedArrayContract.MatchesLayout(layout, program)
                || (segment.Kind
                        == StorageProjectionSegmentKind.ArrayIndex
                    && segment.Start >= layout.ElementCount)
                || (segment.Kind
                        == StorageProjectionSegmentKind.ArrayRange
                    && (segment.Length == 0
                        || segment.Start >= layout.ElementCount
                        || segment.Length
                            > layout.ElementCount - segment.Start)))
            {
                return fallback;
            }

            crossedArray = true;
            var elementIndex = segment.Kind
                    == StorageProjectionSegmentKind.ArrayIndex
                ? segment.Start : (ulong?)null;
            if (index == segments.Length - 1
                && layout.ElementType == type)
            {
                var elementBytes = initialized.RawUnionArrayElementBytes(
                    variable, currentProjection, layout, elementIndex);
                return elementBytes.Length == fallback.Length
                    ? elementBytes : fallback;
            }

            if (CarriesRawUnionPayloadFacts(program, layout.ElementType))
            {
                var suffixPath = default(FieldProjectionPath);
                var suffixType = layout.ElementType;
                var suffixIsFields = true;
                for (var suffixIndex = index + 1;
                    suffixIndex < segments.Length; suffixIndex++)
                {
                    var suffix = segments[suffixIndex];
                    if (suffix.Kind
                            != StorageProjectionSegmentKind.Field
                        || suffix.OwnerType != suffixType
                        || !HasFields(program, suffixType)
                        || (uint)suffix.Field
                            >= (uint)Fields(program, suffixType).Length)
                    {
                        suffixIsFields = false;
                        break;
                    }

                    suffixPath = suffixPath.Append(suffixType,
                        suffix.Field);
                    suffixType = Fields(program, suffixType)[
                        suffix.Field].Type;
                }

                if (suffixIsFields && suffixType == type
                    && TryGetFieldPathByteOffset(layout.ElementType,
                        suffixPath, program, out var fieldOffset))
                {
                    var elementBytes
                        = initialized.RawUnionArrayElementBytes(variable,
                            currentProjection, layout, elementIndex);
                    var size = fallback.Length;
                    if (fieldOffset <= elementBytes.Length
                        && size <= elementBytes.Length - fieldOffset)
                    {
                        return elementBytes.AsSpan(fieldOffset, size)
                            .ToArray();
                    }
                    return fallback;
                }
            }

            currentProjection = StorageProjection.Combine(
                currentProjection,
                elementIndex is ulong selectedIndex
                    ? StorageProjection.ForArrayIndex(selectedIndex)
                    : StorageProjection.ForArrayRange(
                        segment.Start, segment.Length));
            currentType = layout.ElementType;
            rootFieldPath = default;
        }

        if (!crossedArray && currentType == type
            && projection.Kind == StorageProjectionKind.InlineFieldPath
            && TryGetFieldPathByteOffset(rootType, rootFieldPath, program,
                out var offset)
            && initialized.TryGetRawUnionInitializedBytes(variable,
                out var rootBytes)
            && offset <= rootBytes.Length
            && fallback.Length <= rootBytes.Length - offset)
        {
            return rootBytes.AsSpan(offset, fallback.Length).ToArray();
        }

        return fallback;
    }

    private static void ValidateRawUnionReferenceFieldFormation(
        BoundReferenceFormation formation, ProvenanceAnchor target,
        InitializationState initialized, BoundFunction function,
        BoundProgram program, ref int remaining, int depth)
    {
        if (target.Kind is not (ProvenanceAnchorKind.NativeStorage
                or ProvenanceAnchorKind.ReferencePlace)
            || target.Storage is not StorageKey storage
            || !storage.IsKnown || target.Identity != storage.Site
            || (uint)target.Identity >= (uint)function.Variables.Length)
        {
            return;
        }

        var segments = storage.Projection.ProjectionPath.Segments;
        if (segments.IsEmpty)
        {
            return;
        }

        var currentType = function.Variables[target.Identity].Type;
        var currentProjection = StorageProjection.WholeObject;
        foreach (var segment in segments)
        {
            Count(ref remaining, depth + 1);
            if (segment.Kind == StorageProjectionSegmentKind.Field)
            {
                if (segment.OwnerType != currentType
                    || !HasFields(program, currentType)
                    || (uint)segment.Field
                        >= (uint)Fields(program, currentType).Length)
                {
                    throw InvalidEffect(formation.Span, "CheckedReference");
                }

                var field = Fields(program, currentType)[segment.Field];
                if (IsRawUnionType(program, currentType))
                {
                    var unionBytes
                        = InitializedRawUnionPayloadBytesOfStoragePlace(
                            target.Identity, currentProjection, currentType,
                            initialized, function, program,
                            GuaranteedInitializedPayloadBytes(currentType,
                                program));
                    var fieldOffset
                        = MaterializedPayloadOffset(field.Offset);
                    var fieldSize = MaterializedPayloadSize(field.Size);
                    if (fieldOffset > unionBytes.Length
                        || fieldSize > unionBytes.Length - fieldOffset
                        || unionBytes.AsSpan(fieldOffset, fieldSize)
                            .Contains((byte)0))
                    {
                        throw Invalid(formation.Span);
                    }
                }

                currentProjection = currentProjection.AppendField(
                    currentType, segment.Field);
                currentType = field.Type;
                continue;
            }

            if (segment.Kind is not (
                    StorageProjectionSegmentKind.ArrayIndex
                    or StorageProjectionSegmentKind.ArrayRange)
                || !NativeFixedArrayContract.TryGetLayout(currentType,
                    program, out var layout)
                || !NativeFixedArrayContract.MatchesLayout(layout, program)
                || (segment.Kind
                        == StorageProjectionSegmentKind.ArrayIndex
                    && segment.Start >= layout.ElementCount)
                || (segment.Kind
                        == StorageProjectionSegmentKind.ArrayRange
                    && (segment.Length == 0
                        || segment.Start >= layout.ElementCount
                        || segment.Length
                            > layout.ElementCount - segment.Start)))
            {
                throw InvalidEffect(formation.Span, "CheckedReference");
            }

            currentProjection = StorageProjection.Combine(
                currentProjection,
                segment.Kind == StorageProjectionSegmentKind.ArrayIndex
                    ? StorageProjection.ForArrayIndex(segment.Start)
                    : StorageProjection.ForArrayRange(segment.Start,
                        segment.Length));
            currentType = layout.ElementType;
        }
    }

    private static bool TryGetNativeFixedArrayElementFieldPath(
        BoundFieldRead fieldRead, BoundFunction function, BoundProgram program,
        out int variable, out BoundExpression? fieldPlace,
        out ImmutableArray<BoundNativeFixedArrayProjection> projections,
        out BoundNativeFixedArrayLayout leafLayout,
        out FieldProjectionPath fieldPath)
    {
        variable = -1;
        fieldPlace = null;
        projections = [];
        leafLayout = default;
        fieldPath = default;
        var fields = new Stack<BoundFieldRead>();
        BoundExpression root = fieldRead;
        while (true)
        {
            while (root is BoundUnsafeExpression unsafeExpression)
            {
                root = unsafeExpression.Expression;
            }
            if (root is not BoundFieldRead current)
            {
                break;
            }
            fields.Push(current);
            root = current.Receiver;
        }

        if (fields.Count == 0)
        {
            return false;
        }
        while (root is BoundUnsafeExpression unsafeExpression)
        {
            root = unsafeExpression.Expression;
        }

        switch (root)
        {
            case BoundNativeFixedArrayElement element:
                variable = element.Variable;
                fieldPlace = element.FieldPlace;
                projections = [new BoundNativeFixedArrayProjection(
                    element.Layout, element.Index)];
                leafLayout = element.Layout;
                break;
            case BoundNativeFixedArrayPathElement pathElement
                when !pathElement.Projections.IsDefaultOrEmpty:
                variable = pathElement.Variable;
                fieldPlace = pathElement.FieldPlace;
                projections = pathElement.Projections;
                leafLayout = pathElement.Projections[^1].Layout;
                break;
            default:
                return false;
        }

        if (projections.Length + fields.Count > MaximumDepth)
        {
            return false;
        }
        var ownerType = leafLayout.ElementType;
        while (fields.TryPop(out var field))
        {
            if (field.Receiver.Type != ownerType
                || !HasFields(program, ownerType)
                || (uint)field.Field
                    >= (uint)Fields(program, ownerType).Length
                || field.Type
                    != Fields(program, ownerType)[field.Field].Type)
            {
                return false;
            }
            fieldPath = fieldPath.Append(ownerType, field.Field);
            ownerType = field.Type;
        }
        return ownerType == fieldRead.Type;
    }

    private static byte[] GuaranteedInitializedPayloadBytes(
        PrimitiveType type, BoundProgram program,
        HashSet<PrimitiveType> visiting, ref int remaining, int depth)
    {
        Count(ref remaining, depth);
        var size = MaterializedPayloadSize(type, program);
        var result = new byte[size];
        if (size == 0)
        {
            return result;
        }

        if (NativeFixedArrayTypes.IsType(type))
        {
            var array = program.NativeFixedArrayTypes[
                NativeFixedArrayTypes.Index(type)];
            var elementBytes = GuaranteedInitializedPayloadBytes(
                array.ElementType, program, visiting, ref remaining,
                depth + 1);
            if (elementBytes.Length == 0)
            {
                return result;
            }
            if (array.ElementStride < (ulong)elementBytes.Length
                || array.ByteExtent != (ulong)size
                || (array.ElementCount != 0
                    && array.ElementStride == 0)
                || array.ElementCount > (ulong)size + 1UL)
            {
                throw Invalid();
            }

            for (ulong element = 0; element < array.ElementCount; element++)
            {
                Count(ref remaining, depth + 1);
                var offset = checked((int)(element * array.ElementStride));
                elementBytes.CopyTo(result, offset);
            }

            return result;
        }

        if (HasFields(program, type)
            && !ManagedClassTypes.IsClass(type))
        {
            if (!visiting.Add(type))
            {
                throw Invalid();
            }

            try
            {
                var structure = program.Structures[(int)type - 100];
                if (structure.Fields.IsDefaultOrEmpty)
                {
                    return result;
                }

                if (structure.IsUnion)
                {
                    Array.Fill(result, (byte)1);
                    foreach (var field in structure.Fields)
                    {
                        Count(ref remaining, depth + 1);
                        var fieldBytes = GuaranteedInitializedPayloadBytes(
                            field.Type, program, visiting, ref remaining,
                            depth + 1);
                        if (field.Offset > (ulong)result.Length
                            || (ulong)fieldBytes.Length
                                > (ulong)result.Length - field.Offset
                            || field.Size != (ulong)fieldBytes.Length)
                        {
                            throw Invalid();
                        }

                        var fieldOffset = checked((int)field.Offset);
                        for (var index = 0; index < result.Length; index++)
                        {
                            var alternativeByte
                                = index >= fieldOffset
                                    && index - fieldOffset < fieldBytes.Length
                                    ? fieldBytes[index - fieldOffset]
                                    : (byte)0;
                            result[index] &= alternativeByte;
                        }
                    }

                    return result;
                }

                foreach (var field in structure.Fields)
                {
                    Count(ref remaining, depth + 1);
                    var fieldBytes = GuaranteedInitializedPayloadBytes(
                        field.Type, program, visiting, ref remaining,
                        depth + 1);
                    if (field.Offset > (ulong)result.Length
                        || (ulong)fieldBytes.Length
                            > (ulong)result.Length - field.Offset
                        || field.Size != (ulong)fieldBytes.Length)
                    {
                        throw Invalid();
                    }

                    fieldBytes.CopyTo(result, checked((int)field.Offset));
                }
            }
            finally
            {
                _ = visiting.Remove(type);
            }

            return result;
        }

        Array.Fill(result, (byte)1);
        return result;
    }

    private static int MaterializedPayloadSize(
        PrimitiveType type, BoundProgram program)
    {
        var size = NativeFixedArrayTypes.IsType(type)
            ? program.NativeFixedArrayTypes[
                NativeFixedArrayTypes.Index(type)].ByteExtent
            : ValueLayout.Size(type, program.Structures,
                program.CheckedReferenceTypes,
                program.NativeLoweringAgreement,
                program.NativeFixedArrayTypes, program.EnumDefinitions);
        return MaterializedPayloadSize(size);
    }

    private static int MaterializedPayloadSize(ulong size)
    {
        if (size > (ulong)ValueLayout.MaximumStructureSize)
        {
            throw Limit();
        }

        return checked((int)size);
    }

    private static int MaterializedPayloadOffset(ulong offset)
    {
        if (offset > int.MaxValue)
        {
            throw Limit();
        }

        return checked((int)offset);
    }

    private static bool HasFields(BoundProgram program, PrimitiveType type) =>
        ManagedClassTypes.IsClass(type)
            ? ManagedClassTypes.ClassIndex(type) < program.Classes.Length
            : (int)type >= 100 && (int)type < ManagedClassTypes.First
                && (int)type - 100 < program.Structures.Length;

    private static ImmutableArray<BoundStructField> Fields(BoundProgram program, PrimitiveType type) =>
        ManagedClassTypes.IsClass(type) ? program.Classes[ManagedClassTypes.ClassIndex(type)].Fields
            : program.Structures[(int)type - 100].Fields;

    private static bool CanAccessField(BoundFunction function, BoundProgram program, PrimitiveType type,
        int field) =>
        ManagedClassTypes.IsClass(type)
            ? !program.Classes[ManagedClassTypes.ClassIndex(type)].Fields[field].IsPrivate
                || function.DeclaringStruct == program.Classes[ManagedClassTypes.ClassIndex(type)].Name
            : CanAccessField(function, program.Structures[(int)type - 100], field);

    private static bool CanAccessField(BoundFunction function, BoundStruct structure, int field) =>
        !structure.Fields[field].IsPrivate || function.DeclaringStruct == structure.Name;

    private static bool CanAccessStaticField(BoundFunction function,
        BoundStaticFieldDefinition field, BoundProgram program)
    {
        if (field.IsFile
            && function.SourceInputOrdinal != field.SourceInputOrdinal)
        {
            return false;
        }
        if (!field.IsPrivate
            || StringComparer.Ordinal.Equals(function.DeclaringStruct,
                field.Owner.Name))
        {
            return true;
        }
        if (function.DeclaringStruct is not string declaringTypeName
            || !TryGetNominalType(program, declaringTypeName,
                out var declaringType))
        {
            return false;
        }
        return field.FriendTargets.Any(friend =>
            StaticFriendTargetMatches(friend, declaringType, program));
    }

    private static bool CanAccessFunction(BoundFunction caller,
        BoundFunction target, BoundProgram program)
    {
        if (StringComparer.Ordinal.Equals(caller.DeclaringStruct,
                target.DeclaringStruct))
        {
            return true;
        }
        if (caller.DeclaringStruct is not string declaringTypeName
            || !TryGetNominalType(program, declaringTypeName,
                out var declaringType))
        {
            return false;
        }
        return target.FriendTargets.Any(friend =>
            StaticFriendTargetMatches(friend, declaringType, program));
    }

    private static bool TryGetNominalType(BoundProgram program, string name,
        out PrimitiveType type)
    {
        for (var index = 0; index < program.Structures.Length; index++)
        {
            if (program.Structures[index].Name == name)
            {
                type = (PrimitiveType)(100 + index);
                return true;
            }
        }
        for (var index = 0; index < program.Classes.Length; index++)
        {
            if (program.Classes[index].Name == name)
            {
                type = (PrimitiveType)(ManagedClassTypes.First + index);
                return true;
            }
        }
        type = PrimitiveType.Void;
        return false;
    }

    private static bool StaticFriendTargetMatches(
        BoundFriendTarget friend, PrimitiveType declaringType,
        BoundProgram program)
    {
        if (friend.GenericDefinitionIndex < 0
            || friend.Type != PrimitiveType.Void)
        {
            return friend.Type == declaringType;
        }
        if ((int)declaringType < 100
            || (uint)((int)declaringType - 100)
                >= (uint)program.Structures.Length)
        {
            return false;
        }

        var structureIndex = (int)declaringType - 100;
        foreach (var instance in program.SourceGenericTypeInstances)
        {
            if (instance.StructureIndex != structureIndex
                || instance.DefinitionIndex
                    != friend.GenericDefinitionIndex
                || instance.TypeArguments.Length
                    != friend.TypeArguments.Length)
            {
                continue;
            }

            var matches = true;
            for (var argumentIndex = 0;
                argumentIndex < instance.TypeArguments.Length;
                argumentIndex++)
            {
                if (friend.TypeArguments[argumentIndex]
                    is PrimitiveType expected
                    && expected != instance.TypeArguments[argumentIndex])
                {
                    matches = false;
                    break;
                }
            }
            if (matches)
            {
                return true;
            }
        }
        return false;
    }

    private static bool IsStaticFieldReadAuthorized(
        BoundStaticFieldRead fieldRead, BoundFunction function,
        BoundProgram program)
    {
        if ((uint)fieldRead.Field >= (uint)program.StaticFields.Length)
        {
            return false;
        }

        var field = program.StaticFields[fieldRead.Field];
        if ((uint)field.EagerGroupIndex
            >= (uint)program.StaticInitializationGroups.Length)
        {
            return false;
        }
        var group = program.StaticInitializationGroups[
            field.EagerGroupIndex];
        switch (fieldRead.Authority)
        {
            case BoundStaticFieldAccessAuthority.EagerGroupCompletion:
                return function.StaticFieldInitializerIndex >= 0
                    ? (uint)function.StaticFieldInitializerIndex
                        < (uint)program.StaticFields.Length
                        && program.StaticFields[
                            function.StaticFieldInitializerIndex].IsLazy
                    : function.StaticConstructorIdentity is null;
            case BoundStaticFieldAccessAuthority.InitializationPhase:
                var initializerFieldIndex
                    = function.StaticFieldInitializerIndex;
                if (initializerFieldIndex >= 0
                    && (uint)initializerFieldIndex
                        < (uint)program.StaticFields.Length)
                {
                    var initializerField = program.StaticFields[
                        initializerFieldIndex];
                    return initializerField.EagerGroupIndex
                            == field.EagerGroupIndex
                        && !field.IsLazy
                        && field.DeclarationOrdinal
                            < initializerField.DeclarationOrdinal;
                }

                return function.StaticConstructorIdentity is
                        BoundStaticConstructorIdentity identity
                    && identity.OwnerName == field.Owner.Name
                    && group.StaticConstructorFunctionIndex >= 0
                    && program.Functions[
                        group.StaticConstructorFunctionIndex]
                        .StaticConstructorIdentity == identity
                    && !field.IsLazy;
            default:
                return false;
        }
    }

    private static void MarkOutMasks(InitializationState initialized, uint[] masks, BoundFunction function, BoundProgram program)
    {
        for (var i = 0; i < initialized.Length; i++)
        {
            var type = function.Variables[i].Type;
            if (initialized[i] && HasFields(program, type))
            {
                masks[i] = FullMask(program, type);
                initialized.SetPossibleFieldMask(i, masks[i]);
            }
        }
    }

    private static void SetNormalBackingFactoryObjectIdentity(
        BoundCall call, int variable, PrimitiveType type,
        InitializationState state, bool succeeds)
    {
        var program = state.Program;
        if (program.NativeLoweringAgreement
                != CompilationOptions.WindowsX64NormalBackingAgreement
            || (uint)call.Function >= (uint)program.Functions.Length
            || program.Functions[call.Function].Intrinsic
                != BoundIntrinsic.ClassTryCreate
            || !IsNormalBackingObjectType(type)
            || state.Dependencies is not BackingDependencies dependencies)
        {
            return;
        }
        if (!succeeds)
        {
            dependencies.SetNormalBackingObjects(variable,
                new HashSet<ProvenanceAnchor>(), mayBeUnknown: false);
            return;
        }
        var allocationSite = checked(call.Span.Start + 1);
        var objectIdentity = ProvenanceAnchor.ForNormalBackingObject(
            dependencies.FunctionActivation, allocationSite,
            new StorageInstance(state.ScopeActivation, allocationSite), type);
        dependencies.SetNormalBackingObjects(variable,
            new HashSet<ProvenanceAnchor> { objectIdentity },
            mayBeUnknown: false);
        dependencies.ApplyNormalBackingClassConstructorSummary(
            program.Functions[call.Function].ClassConstructor,
            objectIdentity, program);
    }

    private static InitializationState CloneOutcomeState(
        InitializationState state,
        RepeatSnapshotReservationScope? snapshotScope) =>
        snapshotScope is null ? state.Clone() : state.Clone(snapshotScope);

    private static RepeatSnapshotReservationScope?
        CreateRepeatSnapshotScopeIfNeeded(InitializationState state)
    {
        if (state.RepeatSnapshotScope is not null)
        {
            return null;
        }

        var stateBytes = state.GetRawUnionArrayStateBytes();
        var hasCallResultSnapshots
            = state.Dependencies is BackingDependencies dependencies
                && dependencies.HasRawUnionArrayCallResults;
        if (stateBytes.IsZero && !hasCallResultSnapshots)
        {
            return null;
        }

        var snapshotScope = new RepeatSnapshotReservationScope(
            state.RepeatResources);
        snapshotScope.TrackExistingState(state, stateBytes);
        return snapshotScope;
    }

    private static void ReleaseRepeatSnapshotStateIfTracked(
        InitializationState state)
    {
        if (state.RepeatSnapshotScope is RepeatSnapshotReservationScope scope
            && scope.TracksState(state))
        {
            scope.ReleaseState(state);
        }
    }

    private static bool IsStableBooleanInputCondition(
        BoundExpression expression, BoundFunction function,
        ref int remaining, int depth)
    {
        Count(ref remaining, depth);
        return expression switch {
            BoundConstant { Type: PrimitiveType.Bool } => true,
            BoundRead read => TryGetStableBooleanParameter(read, function,
                out _, out _),
            BoundUnary { Operator: TokenKind.Bang } unary
                => unary.Operand.Type == PrimitiveType.Bool
                    && IsStableBooleanInputCondition(unary.Operand,
                        function, ref remaining, depth + 1),
            BoundBinary {
                Operator: TokenKind.AmpersandAmpersand
                    or TokenKind.PipePipe
                    or TokenKind.Ampersand
                    or TokenKind.Pipe
                    or TokenKind.Caret,
                Type: PrimitiveType.Bool,
            } binary
                => binary.Left.Type == PrimitiveType.Bool
                    && binary.Right.Type == PrimitiveType.Bool
                    && IsStableBooleanInputCondition(binary.Left,
                        function, ref remaining, depth + 1)
                    && IsStableBooleanInputCondition(binary.Right,
                        function, ref remaining, depth + 1),
            BoundBinary comparison
                => IsStableIntegerInputComparison(comparison, function,
                    ref remaining, depth + 1),
            BoundConditional { Type: PrimitiveType.Bool } conditional
                => conditional.Condition.Type == PrimitiveType.Bool
                    && conditional.WhenTrue.Type == PrimitiveType.Bool
                    && conditional.WhenFalse.Type == PrimitiveType.Bool
                    && IsStableBooleanInputCondition(
                        conditional.Condition, function, ref remaining,
                        depth + 1)
                    && IsStableBooleanInputCondition(
                        conditional.WhenTrue, function, ref remaining,
                        depth + 1)
                    && IsStableBooleanInputCondition(
                        conditional.WhenFalse, function, ref remaining,
                        depth + 1),
            _ => false,
        };
    }

    private static bool IsStableIntegerInputComparison(
        BoundBinary comparison, BoundFunction function,
        ref int remaining, int depth)
    {
        Count(ref remaining, depth);
        return comparison.Type == PrimitiveType.Bool
            && (comparison.Operator is TokenKind.EqualsEquals
                or TokenKind.BangEquals or TokenKind.Less
                or TokenKind.LessEquals or TokenKind.Greater
                or TokenKind.GreaterEquals)
            && comparison.Left.Type == comparison.Right.Type
            && PrimitiveTypeFacts.IsIntegerOrWide(comparison.Left.Type)
            && IsStableIntegerInputOperand(comparison.Left, function,
                ref remaining, depth + 1)
            && IsStableIntegerInputOperand(comparison.Right, function,
                ref remaining, depth + 1);
    }

    private static bool AreEquivalentStableIntegerInputComparisons(
        BoundExpression left, BoundExpression right,
        BoundFunction function, ref int remaining, int depth)
    {
        Count(ref remaining, depth);
        return left is BoundBinary leftComparison
            && right is BoundBinary rightComparison
            && leftComparison.Operator == rightComparison.Operator
            && leftComparison.Left.Type == rightComparison.Left.Type
            && leftComparison.Right.Type == rightComparison.Right.Type
            && IsStableIntegerInputComparison(leftComparison, function,
                ref remaining, depth + 1)
            && IsStableIntegerInputComparison(rightComparison, function,
                ref remaining, depth + 1)
            && AreEquivalentStableIntegerInputOperands(
                leftComparison.Left, rightComparison.Left)
            && AreEquivalentStableIntegerInputOperands(
                leftComparison.Right, rightComparison.Right);
    }

    private static bool AreEquivalentStableIntegerInputOperands(
        BoundExpression left, BoundExpression right) =>
        (left, right) switch {
            (BoundRead leftRead, BoundRead rightRead)
                => leftRead.Variable == rightRead.Variable
                    && leftRead.Type == rightRead.Type,
            (BoundConstant leftConstant, BoundConstant rightConstant)
                => leftConstant.Type == rightConstant.Type
                    && leftConstant.Bits == rightConstant.Bits,
            _ => false,
        };

    private static bool IsStableIntegerInputOperand(
        BoundExpression expression, BoundFunction function,
        ref int remaining, int depth)
    {
        Count(ref remaining, depth);
        return expression switch {
            BoundConstant constant
                => PrimitiveTypeFacts.IsIntegerOrWide(constant.Type)
                    && constant.Bits.TryGetIntegerValue(
                        constant.Type, out _),
            BoundRead read
                => TryGetStableIntegerParameter(read, function),
            _ => false,
        };
    }

    private static bool TryGetStableIntegerParameter(BoundRead read,
        BoundFunction function)
    {
        var parameterOffset = function.IsConstructor ? 1 : 0;
        var parameterEnd = function.ParameterCount + parameterOffset;
        if (!PrimitiveTypeFacts.IsIntegerOrWide(read.Type)
            || read.Variable < parameterOffset
            || read.Variable >= parameterEnd
            || (uint)read.Variable >= (uint)function.Variables.Length)
        {
            return false;
        }

        var parameter = function.Variables[read.Variable];
        return parameter.Type == read.Type
            && !parameter.IsMutable && !parameter.IsOut
            && !parameter.IsInit && !parameter.IsImplicitRef
            && !parameter.IsImplicitReferenceTemporary
            && !parameter.IsInitializationLocal;
    }

    private static void ApplyConditionalOutputReadFacts(
        InitializationState state, BoundExpression currentCondition,
        bool currentResult, ref int remaining, int depth)
    {
        if (state.ConditionalInitializedTargets is not
                { Count: > 0 } conditionalTargets
            || state.Dependencies is not BackingDependencies dependencies)
        {
            return;
        }

        foreach (var (condition, targetsByResult)
            in conditionalTargets)
        {
            var result = EvaluateStableBooleanInputCondition(condition,
                dependencies.Function, state, ref remaining, depth + 1);
            if (result is not bool
                && currentCondition is BoundBinary currentComparison
                && IsStableIntegerInputComparison(currentComparison,
                    dependencies.Function, ref remaining, depth + 1)
                && AreEquivalentStableIntegerInputComparisons(condition,
                    currentComparison, dependencies.Function,
                    ref remaining, depth + 1))
            {
                result = currentResult;
            }
            if (result is not bool outcome)
            {
                continue;
            }

            foreach (var target in targetsByResult[outcome ? 1 : 0])
            {
                if (!state.HasActiveInitializationReservation(target))
                {
                    state.SetIncomingReferenceInitializationPossibilities(
                        target, 2, invalidateConditionalFacts: false);
                }
            }
        }
    }

    private static bool? EvaluateStableBooleanInputCondition(
        BoundExpression expression, BoundFunction function,
        InitializationState state, ref int remaining, int depth)
    {
        Count(ref remaining, depth);
        switch (expression)
        {
            case BoundConstant { Type: PrimitiveType.Bool } constant:
                return constant.Value == 1;
            case BoundRead read
                when TryGetStableBooleanParameter(read, function,
                    out var variable, out _)
                    && state.TryGetBooleanValue(variable,
                        out var value):
                return value;
            case BoundRead:
                return null;
            case BoundBinary comparison
                when IsStableIntegerInputComparison(comparison,
                    function, ref remaining, depth + 1):
                return EvaluateStableIntegerComparison(comparison,
                    state, ref remaining);
            case BoundUnary { Operator: TokenKind.Bang } unary:
                return EvaluateStableBooleanInputCondition(unary.Operand,
                    function, state, ref remaining, depth + 1) is bool
                        operand ? !operand : null;
            case BoundBinary {
                Operator: TokenKind.AmpersandAmpersand
                    or TokenKind.Ampersand,
                } and:
            {
                var left = EvaluateStableBooleanInputCondition(and.Left,
                    function, state, ref remaining, depth + 1);
                if (left == false)
                {
                    return false;
                }
                var right = EvaluateStableBooleanInputCondition(and.Right,
                    function, state, ref remaining, depth + 1);
                return left == true ? right
                    : right == false ? false : null;
            }
            case BoundBinary {
                Operator: TokenKind.PipePipe or TokenKind.Pipe,
            } or:
            {
                var left = EvaluateStableBooleanInputCondition(or.Left,
                    function, state, ref remaining, depth + 1);
                if (left == true)
                {
                    return true;
                }
                var right = EvaluateStableBooleanInputCondition(or.Right,
                    function, state, ref remaining, depth + 1);
                return left == false ? right
                    : right == true ? true : null;
            }
            case BoundBinary { Operator: TokenKind.Caret } xor:
            {
                var left = EvaluateStableBooleanInputCondition(xor.Left,
                    function, state, ref remaining, depth + 1);
                var right = EvaluateStableBooleanInputCondition(xor.Right,
                    function, state, ref remaining, depth + 1);
                return left is bool leftValue
                    && right is bool rightValue
                        ? leftValue ^ rightValue : null;
            }
            case BoundConditional conditional:
            {
                var condition = EvaluateStableBooleanInputCondition(
                    conditional.Condition, function, state,
                    ref remaining, depth + 1);
                if (condition is bool selected)
                {
                    return EvaluateStableBooleanInputCondition(
                        selected ? conditional.WhenTrue
                            : conditional.WhenFalse,
                        function, state, ref remaining, depth + 1);
                }
                var whenTrue = EvaluateStableBooleanInputCondition(
                    conditional.WhenTrue, function, state,
                    ref remaining, depth + 1);
                var whenFalse = EvaluateStableBooleanInputCondition(
                    conditional.WhenFalse, function, state,
                    ref remaining, depth + 1);
                return whenTrue is bool trueValue
                    && whenFalse == trueValue ? trueValue : null;
            }
            default:
                return null;
        }
    }

    private static bool? EvaluateStableIntegerComparison(
        BoundBinary comparison, InitializationState initialized,
        ref int remaining)
    {
        if (!TryGetIntegerInterval(comparison.Left, initialized,
                ref remaining, out var left)
            || !TryGetIntegerInterval(comparison.Right, initialized,
                ref remaining, out var right))
        {
            return null;
        }

        switch (comparison.Operator)
        {
            case TokenKind.EqualsEquals:
                if (left.Lower == left.Upper
                    && right.Lower == right.Upper
                    && left.Lower == right.Lower)
                {
                    return true;
                }
                if (left.Upper < right.Lower
                    || right.Upper < left.Lower)
                {
                    return false;
                }
                return null;
            case TokenKind.BangEquals:
                if (left.Lower == left.Upper
                    && right.Lower == right.Upper
                    && left.Lower == right.Lower)
                {
                    return false;
                }
                if (left.Upper < right.Lower
                    || right.Upper < left.Lower)
                {
                    return true;
                }
                return null;
            case TokenKind.Less:
                if (left.Upper < right.Lower)
                {
                    return true;
                }
                return left.Lower >= right.Upper ? false : null;
            case TokenKind.LessEquals:
                if (left.Upper <= right.Lower)
                {
                    return true;
                }
                return left.Lower > right.Upper ? false : null;
            case TokenKind.Greater:
                if (left.Lower > right.Upper)
                {
                    return true;
                }
                return left.Upper <= right.Lower ? false : null;
            case TokenKind.GreaterEquals:
                if (left.Lower >= right.Upper)
                {
                    return true;
                }
                return left.Upper < right.Lower ? false : null;
            default:
                return null;
        }
    }

    private static bool TryGetStableBooleanParameter(
        BoundExpression expression, BoundFunction function,
        out int variable, out bool expressionTrueMeansVariableTrue)
    {
        BoundRead read;
        if (expression is BoundRead directRead)
        {
            read = directRead;
            expressionTrueMeansVariableTrue = true;
        }
        else if (expression is BoundUnary {
                Operator: TokenKind.Bang,
                Operand: BoundRead negatedRead,
            })
        {
            read = negatedRead;
            expressionTrueMeansVariableTrue = false;
        }
        else
        {
            variable = -1;
            expressionTrueMeansVariableTrue = false;
            return false;
        }

        var parameterOffset = function.IsConstructor ? 1 : 0;
        var parameterEnd = function.ParameterCount + parameterOffset;
        if (read.Type != PrimitiveType.Bool
            || read.Variable < parameterOffset
            || read.Variable >= parameterEnd
            || (uint)read.Variable >= (uint)function.Variables.Length
            || function.Variables[read.Variable].IsMutable
            || function.Variables[read.Variable].IsOut)
        {
            variable = -1;
            expressionTrueMeansVariableTrue = false;
            return false;
        }

        variable = read.Variable;
        return true;
    }

    private static void RecordConditionalOutputReadFacts(
        BoundExpression condition,
        InitializationState thenState, bool thenCompletes,
        uint[] thenMasks,
        InitializationState elseState, bool elseCompletes,
        uint[] elseMasks,
        InitializationState joined, BoundFunction function,
        BoundProgram program, ref int remaining, int depth)
    {
        if (!joined.TracksConditionalOutputReadFacts
            || !thenCompletes || !elseCompletes
            || !IsStableBooleanInputCondition(condition, function,
                ref remaining, depth + 1)
            || thenState.Dependencies
                is not BackingDependencies thenDependencies
            || elseState.Dependencies
                is not BackingDependencies elseDependencies)
        {
            return;
        }

        var parameterOffset = function.IsConstructor ? 1 : 0;
        var parameterEnd = function.ParameterCount + parameterOffset;
        for (var parameterIndex = parameterOffset;
            parameterIndex < parameterEnd; parameterIndex++)
        {
            Count(ref remaining, depth);
            var parameter = function.Variables[parameterIndex];
            if (!CheckedReferenceTypeContract.IsValidType(parameter.Type,
                    program.CheckedReferenceTypes))
            {
                continue;
            }

            var reference = program.CheckedReferenceTypes[
                CheckedReferenceTypes.Index(parameter.Type)];
            if (!reference.IsInitialization || reference.IsOptional
                || reference.IsGarbageCollected)
            {
                continue;
            }

            var descriptor = new BoundRead(parameterIndex, parameter.Type,
                condition.Span);
            var thenTargets = ReferenceTargetsOfExpression(descriptor,
                thenDependencies, thenState, function, program,
                ref remaining, depth + 1, thenMasks);
            if (thenTargets.Count == 0)
            {
                continue;
            }
            var elseTargets = ReferenceTargetsOfExpression(descriptor,
                elseDependencies, elseState, function, program,
                ref remaining, depth + 1, elseMasks);
            if (!thenTargets.SetEquals(elseTargets)
                || thenTargets.Any(static target => target.Kind
                    is not (ProvenanceAnchorKind.IncomingReference
                        or ProvenanceAnchorKind.IncomingReferencePlace
                        or ProvenanceAnchorKind.IncomingReferenceField))
                || thenTargets.Any(thenState
                    .HasActiveInitializationReservation)
                || elseTargets.Any(elseState
                    .HasActiveInitializationReservation))
            {
                continue;
            }

            var thenComplete = true;
            var elseComplete = true;
            foreach (var target in thenTargets)
            {
                thenComplete &= ReferenceTargetIsInitialized(target,
                    reference.ReferentType, condition.Span, thenState,
                    thenMasks, function, program, ref remaining,
                    depth + 1);
                elseComplete &= ReferenceTargetIsInitialized(target,
                    reference.ReferentType, condition.Span, elseState,
                    elseMasks, function, program, ref remaining,
                    depth + 1);
            }
            if (thenComplete == elseComplete)
            {
                continue;
            }

            var initializedResult = thenComplete;
            foreach (var target in thenTargets)
            {
                joined.AddConditionalInitializedTarget(
                    condition, initializedResult, target);
            }
        }
    }

    private static InitializationState Outcome(BoundExpression expression,
        InitializationState initialized, bool result, ref int remaining,
        RepeatSnapshotReservationScope? snapshotScope = null)
    {
        snapshotScope ??= initialized.RepeatSnapshotScope;
        var booleanParameter = -1;
        var tracksStableInputCondition
            = initialized.TracksConditionalOutputReadFacts
                && initialized.Dependencies
                    is BackingDependencies booleanDependencies
                && IsStableBooleanInputCondition(expression,
                    booleanDependencies.Function, ref remaining,
                    depth: 1);
        var hasOutcomeEffects = HasOutcomeEffects(expression, initialized.FlowFacts, ref remaining);
        var hasInitializationPostconditionEffect
            = HasInitializationPostconditionFlowEffect(expression,
                initialized, ref remaining);
        var hasNativeOutputEffect = initialized.HasNativeOutputContracts
            && HasNativeOutputFlowEffect(expression, initialized, ref remaining);
        var hasNativePointerExtentEffect =
            HasNativePointerExtentFlowEffect(expression, initialized, ref remaining);
        var hasIntegerRangeRefinement = initialized.TracksIntegerFacts
            && HasIntegerRangeRefinement(expression, ref remaining);
        if (!hasOutcomeEffects && !hasInitializationPostconditionEffect
            && !hasNativeOutputEffect
            && !hasNativePointerExtentEffect
            && !hasIntegerRangeRefinement
            && !tracksStableInputCondition)
        {
            return CloneOutcomeState(initialized, snapshotScope);
        }
        Count(ref remaining, 0);
        if (expression is BoundBinary logical
            && TryGetLongLeftLogicalChain(logical, out var chain))
        {
            for (var index = 1; index < chain.Length; index++)
            {
                Count(ref remaining, 0);
            }

            var continueResult = logical.Operator == TokenKind.AmpersandAmpersand;
            var stopResult = !continueResult;
            var logicalState = initialized;
            InitializationState? stopState = null;
            for (var index = chain.Length; index >= 0; index--)
            {
                var operand = index == chain.Length
                    ? chain[^1].Left
                    : chain[index].Right;
                if (result == stopResult
                    && CanBe(operand, stopResult, ref remaining, logicalState))
                {
                    var operandStopState = Outcome(operand, logicalState,
                        stopResult, ref remaining, snapshotScope);
                    stopState = stopState is null
                        ? operandStopState
                        : Combine(stopState, true, operandStopState, true);
                }
                if (!CanBe(operand, continueResult, ref remaining, logicalState))
                {
                    return result == stopResult
                        ? stopState ?? CloneOutcomeState(initialized,
                            snapshotScope)
                        : CloneOutcomeState(initialized, snapshotScope);
                }
                logicalState = Outcome(operand, logicalState, continueResult,
                    ref remaining, snapshotScope);
            }
            return result == continueResult ? logicalState
                : stopState ?? CloneOutcomeState(initialized, snapshotScope);
        }
        if (expression is BoundUnary { Operator: TokenKind.Bang } unary)
        {
            return Outcome(unary.Operand, initialized, !result, ref remaining,
                snapshotScope);
        }
        if (expression is BoundUnsafeExpression unsafeExpression)
        {
            return Outcome(unsafeExpression.Expression, initialized, result,
                ref remaining, snapshotScope);
        }
        if (expression is BoundContractReturnValue)
        {
            return CloneOutcomeState(initialized, snapshotScope);
        }
        if (expression is BoundBinary { Operator: TokenKind.AmpersandAmpersand } and)
        {
            if (result)
            {
                var leftTrue = Outcome(and.Left, initialized, true,
                    ref remaining, snapshotScope);
                return Outcome(and.Right, leftTrue, true, ref remaining,
                    snapshotScope);
            }
            var firstFalsePossible = CanBe(and.Left, false, ref remaining, initialized);
            var rightFalsePossible = CanBe(and.Left, true, ref remaining, initialized)
                && CanBe(and.Right, false, ref remaining, initialized);
            if (firstFalsePossible && !rightFalsePossible)
            {
                return Outcome(and.Left, initialized, false, ref remaining,
                    snapshotScope);
            }
            if (!firstFalsePossible && rightFalsePossible)
            {
                var leftTrue = Outcome(and.Left, initialized, true,
                    ref remaining, snapshotScope);
                return Outcome(and.Right, leftTrue, false, ref remaining,
                    snapshotScope);
            }
            var leftTrueState = Outcome(and.Left, initialized, true,
                ref remaining, snapshotScope);
            var firstFalse = Outcome(and.Left, initialized, false,
                ref remaining, snapshotScope);
            var rightFalse = Outcome(and.Right, leftTrueState, false,
                ref remaining, snapshotScope);
            return Combine(firstFalse, firstFalsePossible, rightFalse, rightFalsePossible);
        }
        if (expression is BoundBinary { Operator: TokenKind.PipePipe } or)
        {
            if (!result)
            {
                var leftFalse = Outcome(or.Left, initialized, false,
                    ref remaining, snapshotScope);
                return Outcome(or.Right, leftFalse, false, ref remaining,
                    snapshotScope);
            }
            var firstTruePossible = CanBe(or.Left, true, ref remaining, initialized);
            var rightTruePossible = CanBe(or.Left, false, ref remaining, initialized)
                && CanBe(or.Right, true, ref remaining, initialized);
            if (firstTruePossible && !rightTruePossible)
            {
                return Outcome(or.Left, initialized, true, ref remaining,
                    snapshotScope);
            }
            if (!firstTruePossible && rightTruePossible)
            {
                var leftFalse = Outcome(or.Left, initialized, false,
                    ref remaining, snapshotScope);
                return Outcome(or.Right, leftFalse, true, ref remaining,
                    snapshotScope);
            }
            var leftFalseState = Outcome(or.Left, initialized, false,
                ref remaining, snapshotScope);
            var firstTrue = Outcome(or.Left, initialized, true,
                ref remaining, snapshotScope);
            var rightTrue = Outcome(or.Right, leftFalseState, true,
                ref remaining, snapshotScope);
            return Combine(firstTrue, firstTruePossible, rightTrue, rightTruePossible);
        }
        if (expression is BoundConditional conditional)
        {
            var whenTruePossible = CanBe(conditional.Condition, true, ref remaining, initialized)
                && CanBe(conditional.WhenTrue, result, ref remaining, initialized);
            var whenFalsePossible = CanBe(conditional.Condition, false, ref remaining, initialized)
                && CanBe(conditional.WhenFalse, result, ref remaining, initialized);
            if (whenTruePossible && !whenFalsePossible)
            {
                var trueConditionState = Outcome(conditional.Condition,
                    initialized, true, ref remaining, snapshotScope);
                return Outcome(conditional.WhenTrue, trueConditionState,
                    result, ref remaining, snapshotScope);
            }
            if (!whenTruePossible && whenFalsePossible)
            {
                var falseConditionState = Outcome(conditional.Condition,
                    initialized, false, ref remaining, snapshotScope);
                return Outcome(conditional.WhenFalse, falseConditionState,
                    result, ref remaining, snapshotScope);
            }
            var whenTrue = Outcome(conditional.Condition, initialized, true,
                ref remaining, snapshotScope);
            var whenFalse = Outcome(conditional.Condition, initialized,
                false, ref remaining, snapshotScope);
            return Combine(Outcome(conditional.WhenTrue, whenTrue, result,
                    ref remaining, snapshotScope),
                whenTruePossible,
                Outcome(conditional.WhenFalse, whenFalse, result,
                    ref remaining, snapshotScope),
                whenFalsePossible);
        }
        var state = CloneOutcomeState(initialized, snapshotScope);
        if (expression is BoundRead booleanRead
            && initialized.Dependencies is BackingDependencies
                booleanReadDependencies
            && TryGetStableBooleanParameter(booleanRead,
                booleanReadDependencies.Function, out booleanParameter,
                out _))
        {
            state.SetBooleanValue(booleanParameter, result);
        }
        var nativeOutputCalls = new Dictionary<BoundExpression, NativeOutputCallFact>(
            ReferenceEqualityComparer.Instance);
        if (hasNativeOutputEffect || hasNativePointerExtentEffect)
        {
            ApplyNativeOutputCalls(expression, state, nativeOutputCalls, ref remaining, 1);
        }
        if (expression is BoundReferenceInitializationTest referenceTest)
        {
            if (state.Dependencies is not BackingDependencies testDependencies)
            {
                throw InvalidEffect(referenceTest.Span,
                    "CheckedReference");
            }
            var targets = ReferenceTargetsOfExpression(
                referenceTest.Descriptor, testDependencies, state,
                testDependencies.Function, state.Program,
                ref remaining, 1);
            if (targets.Count != 1)
            {
                throw InvalidEffect(referenceTest.Span,
                    "CheckedReference");
            }
            var target = targets.Single();
            var selectedPossibility = result ? (byte)2 : (byte)1;
            if (target.Kind is ProvenanceAnchorKind.IncomingReference
                or ProvenanceAnchorKind.IncomingReferenceContents
                or ProvenanceAnchorKind.IncomingReferencePlace
                or ProvenanceAnchorKind.IncomingReferenceField)
            {
                var possibilities
                    = state.IncomingReferenceInitializationPossibilities(
                        target);
                var selected = (byte)(possibilities
                    & selectedPossibility);
                if (selected != 0)
                {
                    state.SetIncomingReferenceInitializationPossibilities(
                        target, selected,
                        invalidateConditionalFacts: false);
                }
            }
            else if (target.Kind is ProvenanceAnchorKind.ReferencePlace
                or ProvenanceAnchorKind.NormalBackingPlace
                && target.Storage is StorageKey targetStorage)
            {
                SetReferencePlaceInitializationState(target.Identity,
                    targetStorage.Projection, result, state,
                    state.PossibleFieldMasks,
                    testDependencies.Function, state.Program,
                    referenceTest.Span,
                    invalidateConditionalFacts: false);
            }
            else
            {
                throw InvalidEffect(referenceTest.Span,
                    "CheckedReference");
            }
            return state;
        }
        if (expression is BoundPrivatePlaceIsInitialized {
                Place: BoundPrivateLocalPlace initializationPlace,
            })
        {
            if (state.IsNativeOutputReserved(initializationPlace.Variable))
            {
                throw InvalidEffect(expression.Span, "NativeImport");
            }
            var possibilities = state.Possibilities(
                initializationPlace.Variable);
            state.SetPossibilities(initializationPlace.Variable,
                result ? (byte)(possibilities & 2)
                    : (byte)(possibilities & 5));
            return state;
        }
        if (expression is BoundPrivatePlaceIsInitialized {
                Place: BoundPrivateReferentPlace referentPlace,
            }
            && state.Dependencies is BackingDependencies referentDependencies)
        {
            var targets = ReferenceTargetsOfExpression(
                referentPlace.Descriptor, referentDependencies, state,
                referentDependencies.Function, state.Program,
                ref remaining, 1);
            if (targets.Count == 1)
            {
                var target = targets.Single();
                if (target.Kind is ProvenanceAnchorKind.IncomingReference
                    or ProvenanceAnchorKind.IncomingReferenceContents
                    or ProvenanceAnchorKind.IncomingReferencePlace
                    or ProvenanceAnchorKind.IncomingReferenceField)
                {
                    var possibilities
                        = state.IncomingReferenceInitializationPossibilities(
                            target);
                    var selected = (byte)(possibilities
                        & (result ? 2 : 1));
                    if (selected != 0)
                    {
                        state.SetIncomingReferenceInitializationPossibilities(
                            target, selected,
                            invalidateConditionalFacts: false);
                    }
                    return state;
                }
                if (target.Kind == ProvenanceAnchorKind.ReferencePlace
                    && target.Storage is StorageKey targetStorage
                    && (uint)target.Identity < (uint)state.Length)
                {
                    var mayBePartiallyInitialized
                        = HasFields(state.Program, referentPlace.Type);
                    if (result || !mayBePartiallyInitialized)
                    {
                        SetReferencePlaceInitializationState(
                            target.Identity, targetStorage.Projection,
                            result, state, state.PossibleFieldMasks,
                            referentDependencies.Function, state.Program,
                            expression.Span,
                            invalidateConditionalFacts: false);
                    }
                }
            }
            return state;
        }
        if (expression is BoundIsInitialized initializationTest)
        {
            if (state.IsNativeOutputReserved(initializationTest.Variable))
            {
                throw InvalidEffect(initializationTest.Span, "NativeImport");
            }
            var possibilities = state.Possibilities(initializationTest.Variable);
            state.SetPossibilities(initializationTest.Variable,
                result ? (byte)(possibilities & 2) : (byte)(possibilities & 5));
            return state;
        }
        if (expression is BoundIsVariablePattern variablePattern)
        {
            if (variablePattern.Value is BoundRead sourceRead)
            {
                if (result)
                {
                    state[sourceRead.Variable] = true;
                }
                else if (variablePattern.IncludeNull)
                {
                    state.SetPossibilities(sourceRead.Variable,
                        (byte)(state.Possibilities(sourceRead.Variable) & 5));
                }
            }
            else
            {
                VacateNestedOutputs(variablePattern.Value, state, ref remaining);
            }
            state.InvalidateNativeOutputVariable(variablePattern.Variable);
            state[variablePattern.Variable] = result;
            return state;
        }
        if (expression is BoundIsSome pattern)
        {
            VacateNestedOutputs(pattern.Value, state, ref remaining);
            state.InvalidateNativeOutputVariable(pattern.Variable);
            state[pattern.Variable] = result;
            return state;
        }
        if (expression is BoundCall call)
        {
            var target = (uint)call.Function
                < (uint)state.Program.Functions.Length
                ? state.Program.Functions[call.Function] : null;
            var parameterOffset = target?.IsConstructor == true ? 1 : 0;
            for (var argumentIndex = 0;
                argumentIndex < call.Arguments.Length; argumentIndex++)
            {
                var argument = call.Arguments[argumentIndex];
                if (argument is BoundOutArgument output)
                {
                    state.InvalidateNativeOutputVariable(output.Variable);
                    state.HavocIntegerVariable(output.Variable,
                        output.Type);
                    state[output.Variable] = call.Type != PrimitiveType.Bool || result;
                    SetNormalBackingFactoryObjectIdentity(call, output.Variable,
                        output.Type, state, succeeds: call.Type != PrimitiveType.Bool || result);
                }
                else if (target is not null
                    && IsInitializationReferenceOutputParameter(target,
                        call.ParameterIndex(argumentIndex) + parameterOffset,
                        state.Program))
                {
                    VacateNestedOutputs(argument, state, ref remaining);
                    if (call.Type != PrimitiveType.Bool)
                    {
                        ApplyInitializationReferenceOutputArgument(call,
                            target, argumentIndex, argument, state,
                            state.PossibleFieldMasks,
                            maybeInitialized: false, ref remaining,
                            depth: 1);
                    }
                }
                else
                {
                    VacateNestedOutputs(argument, state, ref remaining);
                }
            }
        }
        else
        {
            VacateNestedOutputs(expression, state, ref remaining);
        }
        InitializationPostconditionCallFact?
            initializationPostconditionCallFact = null;
        if (expression is BoundCall callExpression)
        {
            if (!state.TryGetInitializationPostconditionCallFact(
                callExpression, out initializationPostconditionCallFact!))
            {
                initializationPostconditionCallFact
                    = TryCreateInitializationPostconditionCallFact(
                        callExpression, state, ref remaining, 1);
            }
        }
        else if (expression is BoundRead initializationRead
            && (uint)initializationRead.Variable < (uint)state.Length)
        {
            initializationPostconditionCallFact
                = state.InitializationPostconditionResult(
                    initializationRead.Variable);
        }
        if (initializationPostconditionCallFact is not null)
        {
            ApplyInitializationPostconditionCallFact(
                initializationPostconditionCallFact, result, state);
            if (expression is BoundCall appliedCall)
            {
                state.ClearInitializationPostconditionCallFact(
                    appliedCall);
            }
        }
        else if (expression is BoundCall uncorrelatedCall
            && uncorrelatedCall.Type == PrimitiveType.Bool
            && (uint)uncorrelatedCall.Function
                < (uint)state.Program.Functions.Length)
        {
            var target = state.Program.Functions[uncorrelatedCall.Function];
            var parameterOffset = target.IsConstructor ? 1 : 0;
            for (var argumentIndex = 0;
                argumentIndex < uncorrelatedCall.Arguments.Length;
                argumentIndex++)
            {
                if (IsInitializationReferenceOutputParameter(target,
                        uncorrelatedCall.ParameterIndex(argumentIndex)
                            + parameterOffset, state.Program))
                {
                    ApplyInitializationReferenceOutputArgument(
                        uncorrelatedCall, target, argumentIndex,
                        uncorrelatedCall.Arguments[argumentIndex], state,
                        state.PossibleFieldMasks,
                        maybeInitialized: true, ref remaining, depth: 1);
                }
            }
        }
        ApplyNativeOutputCondition(expression, state, nativeOutputCalls, result, ref remaining);
        if (state.TracksIntegerFacts)
        {
            RefineIntegerComparison(expression, state, result, ref remaining);
        }
        if (tracksStableInputCondition)
        {
            ApplyConditionalOutputReadFacts(state, expression, result,
                ref remaining, depth: 1);
        }
        return state;
    }

    private static bool HasInitializationPostconditionFlowEffect(
        BoundExpression expression, InitializationState initialized,
        ref int remaining)
    {
        Count(ref remaining, 0);
        if (expression is BoundReferenceFormation {
                Place: BoundRead,
            }
            or BoundPrivateReferenceForm {
                Place: BoundPrivateLocalPlace,
            })
        {
            return false;
        }
        if (expression is BoundRead read
            && (uint)read.Variable < (uint)initialized.Length
            && initialized.InitializationPostconditionResult(
                read.Variable) is InitializationPostconditionCallFact
                    readFact
            && IsInitializationPostconditionCallFactCurrent(readFact,
                initialized))
        {
            return true;
        }
        if (expression is BoundCall call
            && initialized.TryGetInitializationPostconditionCallFact(
                call, out var callFact)
            && IsInitializationPostconditionCallFactCurrent(callFact,
                initialized))
        {
            return true;
        }
        var shape = InitializationPostconditionFlowShape(expression,
            initialized, ref remaining);
        if ((shape & (InitializationPostconditionShapeCallFact
            | InitializationPostconditionShapeOutputFact)) != 0)
        {
            return true;
        }
        if ((shape & InitializationPostconditionShapeReadFact) == 0)
        {
            return false;
        }
        foreach (var nested in expression.NestedExpressions)
        {
            if (HasInitializationPostconditionFlowEffect(nested,
                initialized, ref remaining))
            {
                return true;
            }
        }
        return false;
    }

    private static byte InitializationPostconditionFlowShape(
        BoundExpression expression, InitializationState initialized,
        ref int remaining)
    {
        Count(ref remaining, 0);
        if (initialized.TryGetInitializationPostconditionFlowShape(
                expression, out var cachedShape))
        {
            return cachedShape;
        }

        if (expression is BoundReferenceFormation {
                Place: BoundRead,
            }
            or BoundPrivateReferenceForm {
                Place: BoundPrivateLocalPlace,
            })
        {
            initialized.RecordInitializationPostconditionFlowShape(
                expression, InitializationPostconditionShapeAnalyzedFact);
            return InitializationPostconditionShapeAnalyzedFact;
        }

        var shape = (byte)(InitializationPostconditionShapeAnalyzedFact
            | (expression is BoundRead
                ? InitializationPostconditionShapeReadFact : (byte)0));
        if (expression is BoundCall call)
        {
            if (HasInitializationPostconditionCallCandidate(call,
                    initialized.Program, ref remaining, 1))
            {
                shape |= InitializationPostconditionShapeCallFact;
            }
            if (HasInitializationReferenceOutputCall(call,
                    initialized.Program))
            {
                shape |= InitializationPostconditionShapeOutputFact;
            }
        }
        if ((shape & (InitializationPostconditionShapeCallFact
                | InitializationPostconditionShapeOutputFact)) == 0)
        {
            foreach (var nested in expression.NestedExpressions)
            {
                var nestedShape = InitializationPostconditionFlowShape(
                    nested, initialized, ref remaining);
                shape |= (byte)(nestedShape
                    & (InitializationPostconditionShapeCallFact
                        | InitializationPostconditionShapeReadFact
                        | InitializationPostconditionShapeOutputFact));
                if ((shape & (InitializationPostconditionShapeCallFact
                        | InitializationPostconditionShapeOutputFact)) != 0)
                {
                    break;
                }
            }
        }

        initialized.RecordInitializationPostconditionFlowShape(
            expression, shape);
        return shape;
    }

    private static void VacateNestedOutputs(BoundExpression expression, InitializationState state, ref int remaining)
    {
        if (expression is BoundContractReturnValue
            or BoundIsInitialized
            or BoundPrivatePlaceIsInitialized {
                Place: BoundPrivateLocalPlace,
            }
            || (!HasOutcomeEffects(expression, state.FlowFacts, ref remaining)
                && !HasInitializationPostconditionFlowEffect(expression,
                    state, ref remaining)))
        {
            return;
        }
        Count(ref remaining, 0);
        using var repeatSnapshotState
            = CreateRepeatSnapshotScopeIfNeeded(state);
        switch (expression)
        {
            case BoundUnsafeExpression unsafeExpression:
                VacateNestedOutputs(unsafeExpression.Expression, state, ref remaining);
                break;
            case BoundCall call:
                var target = (uint)call.Function
                    < (uint)state.Program.Functions.Length
                    ? state.Program.Functions[call.Function] : null;
                var parameterOffset = target?.IsConstructor == true ? 1 : 0;
                for (var argumentIndex = 0;
                    argumentIndex < call.Arguments.Length; argumentIndex++)
                {
                    var argument = call.Arguments[argumentIndex];
                    if (argument is BoundOutArgument output)
                    {
                        if (call.Type == PrimitiveType.Bool)
                        {
                            state.MarkConditional(output.Variable);
                        }
                        else
                        {
                            state.MarkAssigned(output.Variable);
                        }
                    }
                    else if (target is not null
                        && IsInitializationReferenceOutputParameter(target,
                            call.ParameterIndex(argumentIndex)
                                + parameterOffset, state.Program))
                    {
                        VacateNestedOutputs(argument, state, ref remaining);
                        ApplyInitializationReferenceOutputArgument(call,
                            target, argumentIndex, argument, state,
                            state.PossibleFieldMasks,
                            maybeInitialized: call.Type == PrimitiveType.Bool,
                            ref remaining, depth: 1);
                    }
                    else
                    {
                        VacateNestedOutputs(argument, state, ref remaining);
                    }
                }
                break;
            case BoundIndirectCall call:
                VacateNestedOutputs(call.Target, state, ref remaining);
                foreach (var argument in call.Arguments)
                {
                    VacateNestedOutputs(argument, state, ref remaining);
                }
                break;
            case BoundBinary { Operator: TokenKind.AmpersandAmpersand or TokenKind.PipePipe } logical:
                var evaluateWhenTrue = logical.Operator == TokenKind.AmpersandAmpersand;
                var evaluatedPossible = CanBe(logical.Left, evaluateWhenTrue, ref remaining, state);
                var skippedPossible = CanBe(logical.Left, !evaluateWhenTrue, ref remaining, state);
                if (evaluatedPossible != skippedPossible)
                {
                    var feasible = Outcome(logical.Left, state, evaluatedPossible
                        ? evaluateWhenTrue : !evaluateWhenTrue, ref remaining);
                    if (evaluatedPossible)
                    {
                        VacateNestedOutputs(logical.Right, feasible, ref remaining);
                    }
                    feasible.CopyTo(state);
                    break;
                }
                var evaluated = Outcome(logical.Left, state, evaluateWhenTrue, ref remaining);
                VacateNestedOutputs(logical.Right, evaluated, ref remaining);
                var skipped = Outcome(logical.Left, state, !evaluateWhenTrue, ref remaining);
                var combined = Combine(evaluated, evaluatedPossible, skipped, skippedPossible);
                combined.CopyTo(state);
                break;
            case BoundBinary binary:
                VacateNestedOutputs(binary.Left, state, ref remaining);
                VacateNestedOutputs(binary.Right, state, ref remaining);
                break;
            case BoundConditional conditional:
                var whenTruePossible = CanBe(conditional.Condition, true, ref remaining, state);
                var whenFalsePossible = CanBe(conditional.Condition, false, ref remaining, state);
                if (whenTruePossible != whenFalsePossible)
                {
                    var feasible = Outcome(conditional.Condition, state, whenTruePossible, ref remaining);
                    VacateNestedOutputs(whenTruePossible ? conditional.WhenTrue : conditional.WhenFalse,
                        feasible, ref remaining);
                    feasible.CopyTo(state);
                    break;
                }
                var trueState = Outcome(conditional.Condition, state, true, ref remaining);
                VacateNestedOutputs(conditional.WhenTrue, trueState, ref remaining);
                var falseState = Outcome(conditional.Condition, state, false, ref remaining);
                VacateNestedOutputs(conditional.WhenFalse, falseState, ref remaining);
                var joined = Combine(trueState, whenTruePossible, falseState, whenFalsePossible);
                joined.CopyTo(state);
                break;
            case BoundCoalesce coalesce:
                var optionalPresence = KnownOptionalPresence(coalesce.Optional, state, ref remaining);
                VacateNestedOutputs(coalesce.Optional, state, ref remaining);
                if (optionalPresence == false)
                {
                    VacateNestedOutputs(coalesce.Fallback, state, ref remaining);
                }
                else if (optionalPresence is null)
                {
                    var absentState = state.Clone();
                    VacateNestedOutputs(coalesce.Fallback, absentState, ref remaining);
                    for (var index = 0; index < state.Length; index++)
                    {
                        state.Merge(index, absentState);
                    }
                }
                break;
            case BoundUnary unary:
                VacateNestedOutputs(unary.Operand, state, ref remaining);
                break;
            case BoundUpdate update:
                VacateNestedOutputs(update.Place, state, ref remaining);
                break;
            case BoundCompoundAssignment compound:
                VacateNestedOutputs(compound.Place, state, ref remaining);
                VacateNestedOutputs(compound.Right, state, ref remaining);
                break;
            case BoundNominalUpdate update:
                VacateNestedOutputs(update.Place, state, ref remaining);
                break;
            case BoundCast cast:
                VacateNestedOutputs(cast.Operand, state, ref remaining);
                break;
            case BoundOptionalLift lift:
                VacateNestedOutputs(lift.Value, state, ref remaining);
                break;
            case BoundReadonlyProjection projection:
                VacateNestedOutputs(projection.Value, state, ref remaining);
                break;
            case BoundIsNull test:
                VacateNestedOutputs(test.Value, state, ref remaining);
                break;
            case BoundNativeFixedArrayInitialization fixedArray:
                foreach (var element in fixedArray.Elements)
                {
                    VacateNestedOutputs(element, state, ref remaining);
                }
                break;
            case BoundNativeFixedArrayRepeatInitialization repeat:
                VacateNestedOutputs(repeat.Seed, state, ref remaining);
                break;
            case BoundNativeFixedArrayElement fixedArrayElement:
                VacateNestedOutputs(fixedArrayElement.Index, state, ref remaining);
                break;
            case BoundNativeFixedArrayPathElement pathElement:
                foreach (var projection in pathElement.Projections)
                {
                    VacateNestedOutputs(projection.Index, state,
                        ref remaining);
                }
                break;
            case BoundNativeFixedArrayPointerAddress pointerAddress:
                if (pointerAddress.Projections.IsDefaultOrEmpty)
                {
                    VacateNestedOutputs(pointerAddress.Index, state,
                        ref remaining);
                }
                else
                {
                    foreach (var projection in pointerAddress.Projections)
                    {
                        VacateNestedOutputs(projection.Index, state,
                            ref remaining);
                    }
                }
                break;
            case BoundNativeStorageAddress address:
                foreach (var nested in address.NestedExpressions)
                {
                    VacateNestedOutputs(nested, state, ref remaining);
                }
                break;
            case BoundNativeOutputReservation:
                break;
            case BoundNativePointerRead pointerRead:
                VacateNestedOutputs(pointerRead.Address, state, ref remaining);
                break;
            case BoundReferenceFormation formation:
                VacateNestedOutputs(formation.Place, state, ref remaining);
                break;
            case BoundReferenceReborrow reborrow:
                VacateNestedOutputs(reborrow.Descriptor, state, ref remaining);
                break;
            case BoundReferenceRead referenceRead:
                VacateNestedOutputs(referenceRead.Descriptor, state, ref remaining);
                break;
            case BoundReferenceWrite referenceWrite:
                VacateNestedOutputs(referenceWrite.Descriptor, state, ref remaining);
                VacateNestedOutputs(referenceWrite.Value, state, ref remaining);
                break;
            case BoundPrivateReferenceForm formation:
                foreach (var nested in formation.NestedExpressions)
                {
                    VacateNestedOutputs(nested, state, ref remaining);
                }
                break;
            case BoundPrivatePlaceRead read:
                foreach (var nested in read.NestedExpressions)
                {
                    VacateNestedOutputs(nested, state, ref remaining);
                }
                break;
            case BoundPrivatePlaceIsInitialized test:
                foreach (var nested in test.NestedExpressions)
                {
                    VacateNestedOutputs(nested, state, ref remaining);
                }
                break;
            case BoundInitializationAttenuation attenuation:
                VacateNestedOutputs(attenuation.Descriptor, state,
                    ref remaining);
                break;
            case BoundPrivateCheckedStore store:
                foreach (var nested in store.Destination.NestedExpressions)
                {
                    VacateNestedOutputs(nested, state, ref remaining);
                }
                VacateNestedOutputs(store.Value, state, ref remaining);
                break;
            case BoundImplicitReferenceMaterialize materialize:
                VacateNestedOutputs(materialize.Value, state,
                    ref remaining);
                break;
            case BoundNativePointerWrite pointerWrite:
                VacateNestedOutputs(pointerWrite.Address, state, ref remaining);
                VacateNestedOutputs(pointerWrite.Value, state, ref remaining);
                break;
            case BoundNativeFixedArrayWrite write:
                VacateNestedOutputs(write.Index, state, ref remaining);
                VacateNestedOutputs(write.Value, state, ref remaining);
                break;
            case BoundNativeFixedArrayPathWrite pathWrite:
                foreach (var projection in pathWrite.Projections)
                {
                    VacateNestedOutputs(projection.Index, state,
                        ref remaining);
                }
                VacateNestedOutputs(pathWrite.Value, state, ref remaining);
                break;
            case BoundIsInitialized:
                break;
            case BoundReferenceInitializationTest referenceTest:
                foreach (var nested in referenceTest.NestedExpressions)
                {
                    VacateNestedOutputs(nested, state, ref remaining);
                }
                break;
            case BoundIsSome pattern:
                VacateNestedOutputs(pattern.Value, state, ref remaining);
                state[pattern.Variable] = false;
                break;
            case BoundIsVariablePattern pattern:
                if (pattern.Value is not BoundRead)
                {
                    VacateNestedOutputs(pattern.Value, state, ref remaining);
                }
                state[pattern.Variable] = false;
                break;
            case BoundFieldRead field:
                VacateNestedOutputs(field.Receiver, state, ref remaining);
                break;
            case BoundBufferRead buffer:
                VacateNestedOutputs(buffer.Index, state, ref remaining);
                break;
            case BoundViewRead view:
                VacateNestedOutputs(view.Index, state, ref remaining);
                break;
            case BoundSpanLength length:
                VacateNestedOutputs(length.View, state, ref remaining);
                break;
            case BoundSpanRead read:
                VacateNestedOutputs(read.View, state, ref remaining);
                VacateNestedOutputs(read.Index, state, ref remaining);
                break;
            case BoundSpanAdvance advance:
                VacateNestedOutputs(advance.View, state, ref remaining);
                break;
            case BoundSnapshotSpan:
                break;
            case BoundViewLength:
            case BoundBufferLength:
            case BoundTypeIdentityQuery:
            case BoundLayoutQuery:
            case BoundConstant:
            case BoundPendingInterfaceDefault:
            case BoundNull:
            case BoundRead:
            case BoundReceiverLoan:
            case BoundMutableReceiverLoan:
            case BoundMutableFieldLoan:
            case BoundFieldLoan:
            case BoundNativePointerAddress:
                break;
            case BoundMove move:
                if (move.Variable < 0 || move.Variable >= state.Length)
                {
                    throw InvalidEffect(move.Span, "Ownership");
                }
                state.Retire(move.Variable, (long)move.Span.Start + 1);
                break;
            case BoundFieldMove:
                break;
            default:
                throw Invalid();
        }
    }

    private static bool HasOutcomeEffects(BoundExpression expression,
        Dictionary<BoundExpression, byte> flowFacts, ref int remaining) =>
        (FlowFacts(expression, flowFacts, ref remaining) & OutcomeEffectFact) != 0;

    private static bool HasInitializationTests(BoundExpression expression,
        Dictionary<BoundExpression, byte> flowFacts, ref int remaining) =>
        (FlowFacts(expression, flowFacts, ref remaining) & InitializationTestFact) != 0;

    // Structural facts are state-independent and shared across flow-state clones;
    // the work budget counts the first classification, not cache reads.
    // Unknown forms stay conservative for both properties.
    private static byte FlowFacts(BoundExpression expression,
        Dictionary<BoundExpression, byte> flowFacts, ref int remaining)
    {
        if (expression is null)
        {
            return AllFlowFacts;
        }
        if (flowFacts.TryGetValue(expression, out var facts))
        {
            return facts;
        }
        Count(ref remaining, 0);

        facts = expression switch {
            BoundUnsafeExpression unsafeExpression =>
                FlowFacts(unsafeExpression.Expression, flowFacts, ref remaining),
            BoundCall call => FlowFacts(call.Arguments, flowFacts, ref remaining),
            BoundIndirectCall call => FlowFacts([call.Target, .. call.Arguments], flowFacts, ref remaining),
            BoundBinary binary => AddFlowFact(AddFlowFact(0, binary.Left, flowFacts, ref remaining),
                binary.Right, flowFacts, ref remaining),
            BoundConditional conditional => AddFlowFact(
                AddFlowFact(AddFlowFact(0, conditional.Condition, flowFacts, ref remaining),
                    conditional.WhenTrue, flowFacts, ref remaining),
                conditional.WhenFalse, flowFacts, ref remaining),
            BoundCoalesce coalesce => AddFlowFact(AddFlowFact(0, coalesce.Optional, flowFacts, ref remaining),
                coalesce.Fallback, flowFacts, ref remaining),
            BoundUnary unary => FlowFacts(unary.Operand, flowFacts, ref remaining),
            BoundUpdate update => FlowFacts(update.Place, flowFacts, ref remaining),
            BoundCompoundAssignment compound => AddFlowFact(
                AddFlowFact(0, compound.Place, flowFacts, ref remaining), compound.Right, flowFacts, ref remaining),
            BoundNominalUpdate update => FlowFacts(update.Place, flowFacts, ref remaining),
            BoundCast cast => FlowFacts(cast.Operand, flowFacts, ref remaining),
            BoundOptionalLift lift => FlowFacts(lift.Value, flowFacts, ref remaining),
            BoundReadonlyProjection projection => FlowFacts(projection.Value, flowFacts, ref remaining),
            BoundIsNull test => FlowFacts(test.Value, flowFacts, ref remaining),
            BoundNativeFixedArrayInitialization fixedArray =>
                FlowFacts(fixedArray.Elements, flowFacts, ref remaining),
            BoundNativeFixedArrayRepeatInitialization repeat =>
                FlowFacts(repeat.Seed, flowFacts, ref remaining),
            BoundNativeFixedArrayElement fixedArrayElement =>
                FlowFacts(fixedArrayElement.Index, flowFacts, ref remaining),
            BoundNativeFixedArrayPathElement pathElement =>
                FlowFacts([.. pathElement.Projections.Select(
                    static projection => projection.Index)],
                    flowFacts, ref remaining),
            BoundNativeFixedArrayPointerAddress pointerAddress =>
                pointerAddress.Projections.IsDefaultOrEmpty
                    ? FlowFacts(pointerAddress.Index, flowFacts, ref remaining)
                    : FlowFacts([.. pointerAddress.Projections.Select(
                        static projection => projection.Index)],
                        flowFacts, ref remaining),
            BoundNativeFixedArrayWrite fixedArrayWrite => AddFlowFact(
                FlowFacts(fixedArrayWrite.Index, flowFacts, ref remaining),
                fixedArrayWrite.Value, flowFacts, ref remaining),
            BoundNativeFixedArrayPathWrite pathWrite =>
                FlowFacts([.. pathWrite.Projections.Select(
                    static projection => projection.Index), pathWrite.Value],
                    flowFacts, ref remaining),
            BoundNativeStorageAddress address =>
                FlowFacts(address.NestedExpressions, flowFacts,
                    ref remaining),
            BoundReferenceFormation formation => FlowFacts(formation.Place, flowFacts, ref remaining),
            BoundReferenceReborrow reborrow =>
                FlowFacts(reborrow.Descriptor, flowFacts, ref remaining),
            BoundReferenceRead referenceRead => FlowFacts(referenceRead.Descriptor, flowFacts, ref remaining),
            BoundReferenceWrite referenceWrite => AddFlowFact(
                FlowFacts(referenceWrite.Descriptor, flowFacts, ref remaining),
                referenceWrite.Value, flowFacts, ref remaining),
            BoundPrivateReferenceForm formation =>
                FlowFacts(formation.NestedExpressions, flowFacts,
                    ref remaining),
            BoundPrivatePlaceRead read =>
                FlowFacts(read.NestedExpressions, flowFacts, ref remaining),
            BoundPrivatePlaceIsInitialized =>
                AllFlowFacts,
            BoundReferenceInitializationTest =>
                AllFlowFacts,
            BoundInitializationAttenuation attenuation =>
                FlowFacts(attenuation.Descriptor, flowFacts, ref remaining),
            BoundPrivateCheckedStore store =>
                FlowFacts([.. store.Destination.NestedExpressions,
                    store.Value], flowFacts, ref remaining),
            BoundImplicitReferenceMaterialize materialize =>
                FlowFacts(materialize.Value, flowFacts, ref remaining),
            BoundNativePointerAddress => 0,
            BoundTypeIdentityQuery or BoundLayoutQuery => 0,
            BoundNativePointerRead pointerRead => FlowFacts(pointerRead.Address, flowFacts, ref remaining),
            BoundNativePointerWrite pointerWrite => AddFlowFact(
                FlowFacts(pointerWrite.Address, flowFacts, ref remaining),
                pointerWrite.Value, flowFacts, ref remaining),
            BoundIsSome test => (byte)(OutcomeEffectFact | FlowFacts(test.Value, flowFacts, ref remaining)),
            BoundIsVariablePattern or BoundIsInitialized => AllFlowFacts,
            BoundGenericTypePropertyTest => 0,
            BoundOutArgument or BoundMove or BoundFieldMove => OutcomeEffectFact,
            BoundFieldRead field => FlowFacts(field.Receiver, flowFacts, ref remaining),
            BoundBufferRead buffer => FlowFacts(buffer.Index, flowFacts, ref remaining),
            BoundViewRead view => FlowFacts(view.Index, flowFacts, ref remaining),
            BoundSpanLength length => FlowFacts(length.View, flowFacts, ref remaining),
            BoundSpanRead read => AddFlowFact(AddFlowFact(0, read.View, flowFacts, ref remaining),
                read.Index, flowFacts, ref remaining),
            BoundSpanAdvance advance => FlowFacts(advance.View, flowFacts, ref remaining),
            BoundSnapshotSpan => 0,
            BoundViewLength or BoundBufferLength or BoundConstant
                or BoundPendingInterfaceDefault or BoundNull
                or BoundRead or BoundReceiverLoan
                or BoundMutableReceiverLoan or BoundMutableFieldLoan or BoundFieldLoan => 0,
            _ => AllFlowFacts,
        };
        flowFacts.Add(expression, facts);
        return facts;
    }

    private static byte FlowFacts(ImmutableArray<BoundExpression> expressions,
        Dictionary<BoundExpression, byte> flowFacts, ref int remaining)
    {
        byte facts = 0;
        foreach (var expression in expressions)
        {
            if (expression is BoundOutArgument)
            {
                facts |= OutcomeEffectFact;
            }
            facts = AddFlowFact(facts, expression, flowFacts, ref remaining);
            if (facts == AllFlowFacts)
            {
                break;
            }
        }
        return facts;
    }

    private static byte AddFlowFact(byte facts, BoundExpression expression,
        Dictionary<BoundExpression, byte> flowFacts, ref int remaining) =>
        facts == AllFlowFacts ? facts : (byte)(facts | FlowFacts(expression, flowFacts, ref remaining));

    private const byte MayNotCompleteNormallyFact = 1;
    private const byte CompletionDependsOnFlowStateFact = 2;

    private static byte CompletionShape(BoundExpression expression,
        InitializationState initialized, BoundProgram program, ref int remaining, int depth)
    {
        if (expression is null)
        {
            return 0;
        }

        var facts = initialized.CompletionShapeFacts;
        if (facts.TryGetValue(expression, out var shape))
        {
            return shape;
        }

        Count(ref remaining, depth);
        shape = expression switch {
            BoundCall call when (uint)call.Function < (uint)program.Functions.Length
                && program.Functions[call.Function].DoesNotReturn
                => MayNotCompleteNormallyFact,
            BoundIndirectCall call
                when call.Target is not null
                    && NativeFunctionPointerTypes.IsType(call.Target.Type)
                    && (uint)NativeFunctionPointerTypes.Index(call.Target.Type)
                        < (uint)program.NativeFunctionPointerSignatures.Length
                    && (program.NativeFunctionPointerSignatures[
                        NativeFunctionPointerTypes.Index(call.Target.Type)].EffectsMask & 2) != 0
                => MayNotCompleteNormallyFact,
            BoundNominalUpdate update when (uint)update.Function < (uint)program.Functions.Length
                && program.Functions[update.Function].DoesNotReturn
                => MayNotCompleteNormallyFact,
            BoundBinary { Operator: TokenKind.AmpersandAmpersand or TokenKind.PipePipe }
                or BoundConditional or BoundCoalesce
                => CompletionDependsOnFlowStateFact,
            _ => 0,
        };
        if ((shape & MayNotCompleteNormallyFact) == 0)
        {
            foreach (var nested in expression.NestedExpressions)
            {
                shape |= CompletionShape(nested, initialized, program,
                    ref remaining, depth + 1);
            }
        }

        facts.Add(expression, shape);
        return shape;
    }

    // A false result means no evaluated path produces a normal value.
    private static bool CanCompleteNormally(BoundExpression expression,
        InitializationState initialized, BoundProgram program, ref int remaining, int depth)
    {
        if (expression is null || !initialized.HasDoesNotReturnFunctions)
        {
            return true;
        }
        var shape = CompletionShape(expression, initialized, program, ref remaining, depth + 1);
        if ((shape & MayNotCompleteNormallyFact) == 0)
        {
            return true;
        }

        var cacheable = (shape & CompletionDependsOnFlowStateFact) == 0;
        if (cacheable
            && initialized.CompletionFacts.TryGetValue(expression, out var completesNormally))
        {
            return completesNormally;
        }

        using var repeatSnapshotState
            = CreateRepeatSnapshotScopeIfNeeded(initialized);
        completesNormally = CanCompleteNormallyCore(expression, initialized,
            program, ref remaining, depth);
        if (cacheable)
        {
            initialized.CompletionFacts.Add(expression, completesNormally);
        }
        return completesNormally;
    }

    private static bool CanCompleteNormallyCore(BoundExpression expression,
        InitializationState initialized, BoundProgram program, ref int remaining, int depth)
    {
        Count(ref remaining, depth);
        switch (expression)
        {
            case BoundCall call:
                if ((uint)call.Function >= (uint)program.Functions.Length || call.Arguments.IsDefault)
                {
                    return true;
                }
                foreach (var argument in call.Arguments)
                {
                    if (!CanCompleteNormally(argument, initialized, program,
                        ref remaining, depth + 1))
                    {
                        return false;
                    }
                }
                return !program.Functions[call.Function].DoesNotReturn;
            case BoundIndirectCall call:
                if (call.Target is null || call.Arguments.IsDefault
                    || !CanCompleteNormally(call.Target, initialized, program,
                    ref remaining, depth + 1))
                {
                    return false;
                }
                foreach (var argument in call.Arguments)
                {
                    if (!CanCompleteNormally(argument, initialized, program,
                        ref remaining, depth + 1))
                    {
                        return false;
                    }
                }
                var callType = call.Target.Type;
                return !NativeFunctionPointerTypes.IsType(callType)
                    || (uint)NativeFunctionPointerTypes.Index(callType)
                        >= (uint)program.NativeFunctionPointerSignatures.Length
                    || (program.NativeFunctionPointerSignatures[
                        NativeFunctionPointerTypes.Index(callType)].EffectsMask & 2) == 0;
            case BoundBinary { Operator: TokenKind.AmpersandAmpersand or TokenKind.PipePipe } logical:
                return CanCompleteAs(logical, true, initialized, program, ref remaining, depth + 1)
                    || CanCompleteAs(logical, false, initialized, program, ref remaining, depth + 1);
            case BoundConditional conditional:
                if (conditional.Condition is null || conditional.WhenTrue is null
                    || conditional.WhenFalse is null)
                {
                    return true;
                }
                return (CanCompleteAs(conditional.Condition, true, initialized, program,
                            ref remaining, depth + 1)
                        && CanCompleteNormally(conditional.WhenTrue,
                            Outcome(conditional.Condition, initialized, true, ref remaining),
                            program, ref remaining, depth + 1))
                    || (CanCompleteAs(conditional.Condition, false, initialized, program,
                            ref remaining, depth + 1)
                        && CanCompleteNormally(conditional.WhenFalse,
                            Outcome(conditional.Condition, initialized, false, ref remaining),
                            program, ref remaining, depth + 1));
            case BoundCoalesce coalesce:
                if (coalesce.Optional is null || coalesce.Fallback is null)
                {
                    return true;
                }
                if (!CanCompleteNormally(coalesce.Optional, initialized, program,
                    ref remaining, depth + 1))
                {
                    return false;
                }
                return KnownOptionalPresence(coalesce.Optional, initialized, ref remaining) != false
                    || CanCompleteNormally(coalesce.Fallback, initialized, program,
                        ref remaining, depth + 1);
            case BoundNominalUpdate update:
                return CanCompleteNormally(update.Place, initialized, program,
                    ref remaining, depth + 1)
                    && ((uint)update.Function >= (uint)program.Functions.Length
                        || !program.Functions[update.Function].DoesNotReturn);
            default:
                foreach (var nested in expression.NestedExpressions)
                {
                    if (!CanCompleteNormally(nested, initialized, program,
                        ref remaining, depth + 1))
                    {
                        return false;
                    }
                }
                return true;
        }
    }

    private static bool CanCompleteAs(BoundExpression expression, bool result,
        InitializationState initialized, BoundProgram program, ref int remaining, int depth)
    {
        if (expression is null)
        {
            return true;
        }
        using var repeatSnapshotState
            = CreateRepeatSnapshotScopeIfNeeded(initialized);
        Count(ref remaining, depth);
        if (expression is BoundBinary logical
            && TryGetLongLeftLogicalChain(logical, out var chain))
        {
            for (var index = 1; index < chain.Length; index++)
            {
                Count(ref remaining, depth + index);
            }

            var continueWhenTrue = logical.Operator == TokenKind.AmpersandAmpersand;
            var continueResult = continueWhenTrue;
            var stopResult = !continueResult;
            var state = initialized;
            for (var index = chain.Length; index >= 0; index--)
            {
                var operand = index == chain.Length
                    ? chain[^1].Left
                    : chain[index].Right;
                var operandDepth = index == chain.Length
                    ? depth + chain.Length
                    : depth + index + 1;
                if (result == stopResult
                    && CanCompleteAs(operand, stopResult, state, program,
                        ref remaining, operandDepth))
                {
                    return true;
                }
                if (!CanCompleteAs(operand, continueResult, state, program,
                    ref remaining, operandDepth))
                {
                    return false;
                }
                state = Outcome(operand, state, continueResult, ref remaining);
            }
            return result == continueResult;
        }
        switch (expression)
        {
            case BoundUnsafeExpression unsafeExpression:
                return CanCompleteAs(unsafeExpression.Expression, result, initialized,
                    program, ref remaining, depth + 1);
            case BoundUnary { Operator: TokenKind.Bang } unary:
                return CanCompleteAs(unary.Operand, !result, initialized,
                    program, ref remaining, depth + 1);
            case BoundBinary { Operator: TokenKind.AmpersandAmpersand } and:
                return result
                    ? (CanCompleteAs(and.Left, true, initialized, program, ref remaining, depth + 1)
                        && CanCompleteAs(and.Right, true,
                            Outcome(and.Left, initialized, true, ref remaining),
                            program, ref remaining, depth + 1))
                    : (CanCompleteAs(and.Left, false, initialized, program, ref remaining, depth + 1)
                        || (CanCompleteAs(and.Left, true, initialized, program, ref remaining, depth + 1)
                            && CanCompleteAs(and.Right, false,
                                Outcome(and.Left, initialized, true, ref remaining),
                                program, ref remaining, depth + 1)));
            case BoundBinary { Operator: TokenKind.PipePipe } or:
                return result
                    ? (CanCompleteAs(or.Left, true, initialized, program, ref remaining, depth + 1)
                        || (CanCompleteAs(or.Left, false, initialized, program, ref remaining, depth + 1)
                            && CanCompleteAs(or.Right, true,
                                Outcome(or.Left, initialized, false, ref remaining),
                                program, ref remaining, depth + 1)))
                    : (CanCompleteAs(or.Left, false, initialized, program, ref remaining, depth + 1)
                        && CanCompleteAs(or.Right, false,
                            Outcome(or.Left, initialized, false, ref remaining),
                            program, ref remaining, depth + 1));
            case BoundConditional conditional when conditional.Type == PrimitiveType.Bool:
                if (conditional.Condition is null || conditional.WhenTrue is null
                    || conditional.WhenFalse is null)
                {
                    return true;
                }
                return (CanCompleteAs(conditional.Condition, true, initialized, program,
                            ref remaining, depth + 1)
                        && CanCompleteAs(conditional.WhenTrue, result,
                            Outcome(conditional.Condition, initialized, true, ref remaining),
                            program, ref remaining, depth + 1))
                    || (CanCompleteAs(conditional.Condition, false, initialized, program,
                            ref remaining, depth + 1)
                        && CanCompleteAs(conditional.WhenFalse, result,
                            Outcome(conditional.Condition, initialized, false, ref remaining),
                            program, ref remaining, depth + 1));
            default:
                return CanCompleteNormally(expression, initialized, program,
                    ref remaining, depth + 1)
                    && CanBe(expression, result, ref remaining, initialized);
        }
    }

    private static bool EvaluateExpression(BoundExpression expression,
        InitializationState initialized, uint[] fieldMasks, HashSet<int> declarations,
        BoundFunction function, BoundProgram program, ref int remaining, int depth,
        FailureEdges? failures, bool statementCompound = false,
        BoundBinary? cleanupCounterStep = null)
    {
        using var repeatSnapshotState
            = CreateRepeatSnapshotScopeIfNeeded(initialized);
        var completesNormally = CanCompleteNormally(expression, initialized, program,
            ref remaining, depth);
        if (completesNormally)
        {
            Expression(expression, initialized, fieldMasks, declarations, function, program,
                ref remaining, depth, failures, statementCompound, cleanupCounterStep);
            return true;
        }

        var beforeExpression = initialized.Clone();
        var beforeMasks = (uint[])fieldMasks.Clone();
        Expression(expression, initialized, fieldMasks, declarations, function, program,
            ref remaining, depth, failures, statementCompound, cleanupCounterStep);
        beforeExpression.CopyTo(initialized);
        beforeMasks.CopyTo(fieldMasks, 0);
        return false;
    }

    private static void ValidateUnreachableExpression(BoundExpression expression,
        InitializationState initialized, uint[] fieldMasks, HashSet<int> declarations,
        BoundFunction function, BoundProgram program, ref int remaining, int depth)
    {
        using var repeatSnapshotState
            = CreateRepeatSnapshotScopeIfNeeded(initialized);
        var unreachableState = initialized.Clone();
        var unreachableMasks = (uint[])fieldMasks.Clone();
        var unreachableFunction = function.IsPureEvaluationProof
            ? function with {
                NoFailureProof = false,
                IsPureEvaluationProof = false,
            }
            : function;
        Expression(expression, unreachableState, unreachableMasks, declarations,
            unreachableFunction, program, ref remaining, depth, null);
    }

    private static bool CanBe(BoundExpression expression, bool result, ref int remaining,
        InitializationState initialized)
    {
        using var repeatSnapshotState
            = CreateRepeatSnapshotScopeIfNeeded(initialized);
        var callResultFact = expression switch {
            BoundCall call when initialized
                .TryGetInitializationPostconditionCallFact(call,
                    out var fact) => fact,
            BoundRead read when (uint)read.Variable
                < (uint)initialized.Length
                => initialized.InitializationPostconditionResult(
                    read.Variable),
            _ => null,
        };
        if (callResultFact is not null
            && IsInitializationPostconditionCallFactCurrent(
                callResultFact, initialized))
        {
            Count(ref remaining, 0);
            return result ? callResultFact.CanReturnTrue
                : callResultFact.CanReturnFalse;
        }
        if (initialized.TracksConditionalOutputReadFacts
            && expression is BoundRead booleanRead
            && initialized.Dependencies is BackingDependencies
            booleanDependencies
            && TryGetStableBooleanParameter(booleanRead,
            booleanDependencies.Function, out var booleanVariable,
            out _)
            && initialized.TryGetBooleanValue(booleanVariable,
            out var knownBooleanValue))
        {
            Count(ref remaining, 0);
            return result == knownBooleanValue;
        }
        if (expression is BoundCall unprocessedCall
            && TryCreateInitializationPostconditionCallFact(
                unprocessedCall, initialized, ref remaining, 1)
                is InitializationPostconditionCallFact unprocessedFact)
        {
            initialized.SetInitializationPostconditionCallFact(
                unprocessedCall, unprocessedFact);
            Count(ref remaining, 0);
            return result ? unprocessedFact.CanReturnTrue
                : unprocessedFact.CanReturnFalse;
        }

        if (expression is BoundBinary logical
            && TryGetLongLeftLogicalChain(logical, out var chain))
        {
            for (var index = 0; index < chain.Length; index++)
            {
                Count(ref remaining, 0);
            }

            var continueResult = logical.Operator == TokenKind.AmpersandAmpersand;
            var stopResult = !continueResult;
            var state = initialized;
            for (var index = chain.Length; index >= 0; index--)
            {
                var operand = index == chain.Length
                    ? chain[^1].Left
                    : chain[index].Right;
                if (result == stopResult
                    && CanBe(operand, stopResult, ref remaining, state))
                {
                    return true;
                }
                if (!CanBe(operand, continueResult, ref remaining, state))
                {
                    return false;
                }
                state = Outcome(operand, state, continueResult, ref remaining);
            }
            return result == continueResult;
        }
        if (expression is BoundGenericTypePropertyTest propertyTest
            && propertyTest.KnownResult is bool knownResult)
        {
            Count(ref remaining, 0);
            return result == knownResult;
        }
        if (expression is BoundIsNull nullTest
            && KnownOptionalPresence(nullTest.Value, initialized, ref remaining) is bool nullPresence)
        {
            Count(ref remaining, 0);
            return result != nullPresence;
        }
        if (expression is BoundIsSome someTest
            && KnownOptionalPresence(someTest.Value, initialized, ref remaining) is bool somePresence)
        {
            Count(ref remaining, 0);
            return result == somePresence;
        }
        if (expression is BoundIsInitialized initializationTest)
        {
            Count(ref remaining, 0);
            if (initialized.IsNativeOutputReserved(initializationTest.Variable))
            {
                throw InvalidEffect(initializationTest.Span, "NativeImport");
            }
            var possibilities = initialized.Possibilities(initializationTest.Variable);
            return result ? (possibilities & 2) != 0 : (possibilities & 5) != 0;
        }
        if (expression is BoundReferenceInitializationTest referenceTest)
        {
            Count(ref remaining, 0);
            if (initialized.Dependencies
                is not BackingDependencies dependencies)
            {
                throw InvalidEffect(referenceTest.Span,
                    "CheckedReference");
            }
            var targets = ReferenceTargetsOfExpression(
                referenceTest.Descriptor, dependencies, initialized,
                dependencies.Function, initialized.Program,
                ref remaining, 1);
            if (targets.Count != 1)
            {
                throw InvalidEffect(referenceTest.Span,
                    "CheckedReference");
            }
            var target = targets.Single();
            return result
                ? ReferenceTargetMayBeLive(target, initialized,
                    initialized.PossibleFieldMasks, initialized.Program)
                : ReferenceTargetMayBeVacant(target, initialized,
                    initialized.PossibleFieldMasks, initialized.Program);
        }
        if (expression is BoundUnary { Operator: TokenKind.Bang } unary)
        {
            Count(ref remaining, 0);
            return CanBe(unary.Operand, !result, ref remaining, initialized);
        }
        if (expression is BoundBinary { Operator: TokenKind.AmpersandAmpersand } and
            && HasInitializationTests(and, initialized.FlowFacts, ref remaining))
        {
            Count(ref remaining, 0);
            if (result)
            {
                if (!CanBe(and.Left, true, ref remaining, initialized))
                {
                    return false;
                }
                var leftTrue = Outcome(and.Left, initialized, true, ref remaining);
                return CanBe(and.Right, true, ref remaining, leftTrue);
            }
            if (CanBe(and.Left, false, ref remaining, initialized))
            {
                return true;
            }
            if (!CanBe(and.Left, true, ref remaining, initialized))
            {
                return false;
            }
            var leftTrueState = Outcome(and.Left, initialized, true, ref remaining);
            return CanBe(and.Right, false, ref remaining, leftTrueState);
        }
        if (expression is BoundBinary { Operator: TokenKind.PipePipe } or &&
            HasInitializationTests(or, initialized.FlowFacts, ref remaining))
        {
            Count(ref remaining, 0);
            if (result)
            {
                if (CanBe(or.Left, true, ref remaining, initialized))
                {
                    return true;
                }
                if (!CanBe(or.Left, false, ref remaining, initialized))
                {
                    return false;
                }
                var leftFalse = Outcome(or.Left, initialized, false, ref remaining);
                return CanBe(or.Right, true, ref remaining, leftFalse);
            }
            if (!CanBe(or.Left, false, ref remaining, initialized))
            {
                return false;
            }
            var rightFalse = Outcome(or.Left, initialized, false, ref remaining);
            return CanBe(or.Right, false, ref remaining, rightFalse);
        }
        if (expression is BoundConditional conditional &&
            HasInitializationTests(conditional, initialized.FlowFacts, ref remaining))
        {
            Count(ref remaining, 0);
            if (CanBe(conditional.Condition, true, ref remaining, initialized))
            {
                var conditionTrue = Outcome(conditional.Condition, initialized, true, ref remaining);
                if (CanBe(conditional.WhenTrue, result, ref remaining, conditionTrue))
                {
                    return true;
                }
            }
            if (!CanBe(conditional.Condition, false, ref remaining, initialized))
            {
                return false;
            }
            var conditionFalse = Outcome(conditional.Condition, initialized, false, ref remaining);
            return CanBe(conditional.WhenFalse, result, ref remaining, conditionFalse);
        }
        if (expression is BoundIsVariablePattern pattern)
        {
            Count(ref remaining, 0);
            if (!ManagedClassTypes.IsOptional(pattern.Value.Type)
                && !CheckedReferenceTypes.IsType(pattern.Value.Type))
            {
                return result;
            }
            if (pattern.Value is BoundRead sourceRead)
            {
                var possibilities = initialized.Possibilities(sourceRead.Variable);
                return result ? (possibilities & 2) != 0
                    : !pattern.IncludeNull || (possibilities & 5) != 0;
            }
            return result;
        }
        if (expression is BoundPrivatePlaceIsInitialized {
                Place: BoundPrivateLocalPlace initializationPlace,
            })
        {
            Count(ref remaining, 0);
            if (initialized.IsNativeOutputReserved(
                    initializationPlace.Variable))
            {
                throw InvalidEffect(expression.Span, "NativeImport");
            }
            var possibilities = initialized.Possibilities(
                initializationPlace.Variable);
            return result ? (possibilities & 2) != 0
                : (possibilities & 5) != 0;
        }
        if (expression is BoundPrivatePlaceIsInitialized {
                Place: BoundPrivateReferentPlace referentPlace,
            }
            && initialized.Dependencies
                is BackingDependencies referentDependencies)
        {
            Count(ref remaining, 0);
            var targets = ReferenceTargetsOfExpression(
                referentPlace.Descriptor, referentDependencies,
                initialized, referentDependencies.Function,
                initialized.Program,
                ref remaining, 1);
            if (targets.Count == 0)
            {
                throw InvalidEffect(expression.Span, "CheckedReference");
            }
            foreach (var target in targets)
            {
                var isInitialized = ReferenceTargetIsInitialized(target,
                    referentPlace.Type, expression.Span, initialized,
                    initialized.PossibleFieldMasks,
                    referentDependencies.Function,
                    initialized.Program, ref remaining, 1);
                if (result
                    ? ReferenceTargetMayBeLive(target, initialized,
                        initialized.PossibleFieldMasks, initialized.Program)
                    : !isInitialized)
                {
                    return true;
                }
            }
            return false;
        }
        return CanBe(expression, result, ref remaining, initialized.CanBeFacts);
    }

    private static bool? KnownOptionalPresence(BoundExpression expression, InitializationState initialized,
        ref int remaining)
    {
        using var repeatSnapshotState
            = CreateRepeatSnapshotScopeIfNeeded(initialized);
        Count(ref remaining, 0);
        if (!ManagedClassTypes.IsOptional(expression.Type)
            && !CheckedReferenceTypes.IsType(expression.Type))
        {
            return null;
        }
        var structuralPresenceAnalyzed = TryGetOptionalPresence(expression,
            initialized.CanBeFacts, out var structuralPresence);
        if (structuralPresenceAnalyzed && structuralPresence is bool knownPresence)
        {
            return knownPresence;
        }
        if (expression is BoundCoalesce coalesce)
        {
            var optionalPresence = KnownOptionalPresence(coalesce.Optional, initialized, ref remaining);
            if (optionalPresence == true)
            {
                return true;
            }
            if (optionalPresence == false)
            {
                var optionalState = Outcome(coalesce.Optional, initialized, true, ref remaining);
                return KnownOptionalPresence(coalesce.Fallback, optionalState, ref remaining);
            }
            return null;
        }
        if (expression is not BoundConditional conditional)
        {
            if (expression is BoundUnsafeExpression unsafeExpression)
            {
                return KnownOptionalPresence(unsafeExpression.Expression, initialized, ref remaining);
            }
            return structuralPresenceAnalyzed
                ? null : KnownOptionalPresence(expression, initialized.CanBeFacts, ref remaining);
        }

        var whenTruePossible = CanBe(conditional.Condition, true, ref remaining, initialized);
        var whenFalsePossible = CanBe(conditional.Condition, false, ref remaining, initialized);
        bool? whenTrue = null;
        bool? whenFalse = null;
        if (whenTruePossible)
        {
            var trueState = Outcome(conditional.Condition, initialized, true, ref remaining);
            whenTrue = KnownOptionalPresence(conditional.WhenTrue, trueState, ref remaining);
        }
        if (whenFalsePossible)
        {
            var falseState = Outcome(conditional.Condition, initialized, false, ref remaining);
            whenFalse = KnownOptionalPresence(conditional.WhenFalse, falseState, ref remaining);
        }
        if (!whenTruePossible)
        {
            return whenFalse;
        }
        if (!whenFalsePossible)
        {
            return whenTrue;
        }
        return whenTrue is bool presence && whenFalse == presence ? presence : null;
    }

    private static bool CanBe(BoundExpression expression, bool result, ref int remaining,
        Dictionary<BoundExpression, byte> remainingCanBeFacts)
    {
        Count(ref remaining, 0);
        var known = result ? (byte)1 : (byte)4;
        var possible = result ? (byte)2 : (byte)8;
        if (remainingCanBeFacts.TryGetValue(expression, out var facts) && (facts & known) != 0)
        {
            return (facts & possible) != 0;
        }

        if (expression is BoundBinary logical
            && TryGetLongLeftLogicalChain(logical, out var chain))
        {
            for (var index = 0; index < chain.Length; index++)
            {
                Count(ref remaining, 0);
            }

            var continueResult = logical.Operator == TokenKind.AmpersandAmpersand;
            var stopResult = !continueResult;
            var logicalCanBe = true;
            for (var index = chain.Length; index >= 0; index--)
            {
                var operand = index == chain.Length
                    ? chain[^1].Left
                    : chain[index].Right;
                if (result == stopResult
                    && CanBe(operand, stopResult, ref remaining, remainingCanBeFacts))
                {
                    logicalCanBe = true;
                    break;
                }
                if (!CanBe(operand, continueResult, ref remaining, remainingCanBeFacts))
                {
                    logicalCanBe = false;
                    break;
                }
                if (index == 0)
                {
                    logicalCanBe = result == continueResult;
                }
            }
            remainingCanBeFacts[expression] = (byte)(facts | known | (logicalCanBe ? possible : 0));
            return logicalCanBe;
        }

        var canBe = expression switch {
            BoundConstant { Type: PrimitiveType.Bool } constant => constant.Value != (result ? 0 : 1),
            BoundUnsafeExpression unsafeExpression =>
                CanBe(unsafeExpression.Expression, result, ref remaining, remainingCanBeFacts),
            BoundUnary { Operator: TokenKind.Bang } unary =>
                CanBe(unary.Operand, !result, ref remaining, remainingCanBeFacts),
            BoundIsNull test => KnownOptionalPresence(test.Value, remainingCanBeFacts,
                ref remaining) is not bool isPresent || result != isPresent,
            BoundIsSome test => KnownOptionalPresence(test.Value, remainingCanBeFacts,
                ref remaining) is not bool isPresent || result == isPresent,
            BoundBinary { Operator: TokenKind.AmpersandAmpersand } and => result
                ? CanBe(and.Left, true, ref remaining, remainingCanBeFacts)
                    && CanBe(and.Right, true, ref remaining, remainingCanBeFacts)
                : CanBe(and.Left, false, ref remaining, remainingCanBeFacts)
                    || (CanBe(and.Left, true, ref remaining, remainingCanBeFacts)
                        && CanBe(and.Right, false, ref remaining, remainingCanBeFacts)),
            BoundBinary { Operator: TokenKind.PipePipe } or => result
                ? CanBe(or.Left, true, ref remaining, remainingCanBeFacts)
                    || (CanBe(or.Left, false, ref remaining, remainingCanBeFacts)
                        && CanBe(or.Right, true, ref remaining, remainingCanBeFacts))
                : CanBe(or.Left, false, ref remaining, remainingCanBeFacts)
                    && CanBe(or.Right, false, ref remaining, remainingCanBeFacts),
            BoundConditional conditional =>
                (CanBe(conditional.Condition, true, ref remaining, remainingCanBeFacts)
                    && CanBe(conditional.WhenTrue, result, ref remaining, remainingCanBeFacts))
                || (CanBe(conditional.Condition, false, ref remaining, remainingCanBeFacts)
                    && CanBe(conditional.WhenFalse, result, ref remaining, remainingCanBeFacts)),
            _ => true,
        };
        remainingCanBeFacts[expression] = (byte)(facts | known | (canBe ? possible : 0));
        return canBe;
    }

    private static bool? KnownOptionalPresence(BoundExpression expression,
        Dictionary<BoundExpression, byte> remainingCanBeFacts, ref int remaining)
    {
        Count(ref remaining, 0);
        if (!ManagedClassTypes.IsOptional(expression.Type)
            && !CheckedReferenceTypes.IsType(expression.Type))
        {
            return null;
        }
        if (TryGetOptionalPresence(expression, remainingCanBeFacts, out var cachedPresence))
        {
            return cachedPresence;
        }

        var presence = expression switch {
            BoundNull => (bool?)false,
            BoundOptionalLift => true,
            BoundCoalesce coalesce => KnownOptionalPresence(coalesce.Optional,
                remainingCanBeFacts, ref remaining) switch {
                true => true,
                false => KnownOptionalPresence(coalesce.Fallback, remainingCanBeFacts, ref remaining),
                null => null,
            },
            BoundConditional conditional =>
                KnownOptionalPresence(conditional.WhenTrue, remainingCanBeFacts, ref remaining) is bool whenTrue
                    && KnownOptionalPresence(conditional.WhenFalse, remainingCanBeFacts, ref remaining) == whenTrue
                    ? whenTrue : null,
            _ => null,
        };
        var presenceFacts = presence switch {
            true => (byte)(OptionalPresenceAnalyzed | OptionalPresencePresent),
            false => (byte)(OptionalPresenceAnalyzed | OptionalPresenceAbsent),
            null => OptionalPresenceAnalyzed,
        };
        _ = remainingCanBeFacts.TryGetValue(expression, out var existingFacts);
        remainingCanBeFacts[expression] = (byte)(existingFacts | presenceFacts);
        return presence;
    }

    private static bool TryGetOptionalPresence(BoundExpression expression,
        Dictionary<BoundExpression, byte> remainingCanBeFacts, out bool? presence)
    {
        if (remainingCanBeFacts.TryGetValue(expression, out var facts)
            && (facts & OptionalPresenceAnalyzed) != 0)
        {
            presence = (facts & OptionalPresencePresent) != 0 ? true
                : (facts & OptionalPresenceAbsent) != 0 ? false : null;
            return true;
        }
        presence = null;
        return false;
    }

    private static InitializationState Combine(InitializationState left, bool leftFeasible,
        InitializationState right, bool rightFeasible)
    {
        if (!leftFeasible)
        {
            return right;
        }
        if (!rightFeasible)
        {
            return left;
        }
        for (var i = 0; i < left.Length; i++)
        {
            left.Merge(i, right);
        }
        left.JoinBooleanValues(left, true, right, true);
        left.JoinConditionalInitializedTargets(left, true, right, true);
        left.MergeGenericUniqueProperties(left, right);
        return left;
    }

    private static void Count(ref int remaining, int depth)
    {
        if (depth > MaximumDepth || --remaining < 0)
        {
            throw Limit();
        }
    }

    private static ulong AlignLayout(ulong value, int alignment)
    {
        if (alignment <= 0 || (alignment & (alignment - 1)) != 0)
        {
            throw Invalid();
        }

        var wideAlignment = checked((ulong)alignment);
        var remainder = value & (wideAlignment - 1);
        if (remainder == 0)
        {
            return value;
        }

        var padding = wideAlignment - remainder;
        if (value > ulong.MaxValue - padding)
        {
            throw Invalid();
        }

        return value + padding;
    }

    private static bool IsValidPropertyAccessor(BoundFunction function,
        string propertyName, int declaringType, BoundProgram program,
        IReadOnlyDictionary<string, BoundFunction> propertyGetters,
        Func<int, string, bool> hasFieldName)
    {
        if (string.IsNullOrEmpty(propertyName)
            || function.DeclaringStruct is not string owner
            || function.IsConstructor || function.IsClassConstructor
            || function.IsCleanup || function.DoesNotReturn)
        {
            return false;
        }

        var getterName = owner + ".#get:" + propertyName;
        var getterPrefix = owner + ".#get:";
        var getterIdentity = function.Name.StartsWith(getterPrefix,
                StringComparison.Ordinal)
            ? function.Name[getterPrefix.Length..] : null;
        var isIndexerGetter = propertyName == "this"
            && getterIdentity is not null
            && (getterIdentity == "this"
                || getterIdentity.EndsWith(":this",
                    StringComparison.Ordinal));
        var isGetter = function.Name == getterName
            || function.Name == owner + ".$producer.#get:"
                + propertyName
            || isIndexerGetter;
        if (isGetter
            && !IsClassArgumentType(function.ReturnType, program))
        {
            return false;
        }
        if (function.IsStatic)
        {
            return isGetter && declaringType >= 0
                && (declaringType < ManagedClassTypes.First
                    ? !program.Structures[declaringType].IsUnique
                    : declaringType < ManagedClassTypes.First
                        + program.Classes.Length)
                && function.ParameterCount == 0
                && (function.ReturnType is PrimitiveType.Bool
                    or PrimitiveType.Char16 or PrimitiveType.Char8
                    or PrimitiveType.Char32 or PrimitiveType.Rune
                    or PrimitiveType.Int8 or PrimitiveType.Int16
                    or PrimitiveType.Int32 or PrimitiveType.UInt8
                    or PrimitiveType.UInt16 or PrimitiveType.UInt32
                    or PrimitiveType.Int64 or PrimitiveType.UInt64
                    or PrimitiveType.Float32 or PrimitiveType.Float64
                    || IsCopyStruct(program, function.ReturnType))
                && !hasFieldName(declaringType, propertyName);
        }

        if (function.Variables.IsEmpty
            || IsUnique(program, function.Variables[0].Type))
        {
            return false;
        }

        if (isGetter)
        {
            if (propertyName == "this"
                && function.ParameterCount > 1)
            {
                if (function.ParameterCount
                    > function.Variables.Length)
                {
                    return false;
                }
                for (var index = 1;
                    index < function.ParameterCount; index++)
                {
                    if (function.Variables[index].IsOut)
                    {
                        return false;
                    }
                }
                return true;
            }

            return function.ParameterCount == 1
                && (declaringType < 0
                    || !hasFieldName(declaringType, propertyName));
        }

        if (function.PropertyAccessorKind is
            BoundPropertyAccessorKind.Setter
            or BoundPropertyAccessorKind.Initializer)
        {
            if (function.IsStatic
                || !StringComparer.Ordinal.Equals(function.Name,
                    owner + (function.PropertyAccessorKind
                        == BoundPropertyAccessorKind.Setter
                            ? ".#set:" : ".#init:") + propertyName)
                || !propertyGetters.TryGetValue(getterName,
                    out var namedGetter)
                || namedGetter.PropertyAccessorKind
                    != BoundPropertyAccessorKind.Getter
                || namedGetter.PropertyName != propertyName
                || namedGetter.IsStatic
                || namedGetter.ParameterCount != 1
                || function.ReturnType != PrimitiveType.Void
                || function.ParameterCount != 2
                || function.ParameterCount > function.Variables.Length
                || function.Variables[1].Type != namedGetter.ReturnType
                || function.Variables[1].IsOut
                || function.Variables[1].IsInit
                || function.Variables[1].IsImplicitRef
                || function.Variables[1]
                    .IsCanonicalImplicitReference)
            {
                return false;
            }

            if (function.PropertyAccessorKind
                    == BoundPropertyAccessorKind.Initializer
                && declaringType >= ManagedClassTypes.First
                    && declaringType
                        < ManagedClassTypes.First + program.Classes.Length)
            {
                return program.Classes[
                        ManagedClassTypes.ClassIndex(
                            function.Variables[0].Type)].Fields.Count(
                        field => field.BackingPropertyName == propertyName)
                    == 1;
            }

            return function.PropertyAccessorKind
                == BoundPropertyAccessorKind.Setter;
        }

        if (propertyName != "this"
            || declaringType >= ManagedClassTypes.First
                + program.Classes.Length)
        {
            return false;
        }

        var setterPrefix = owner + ".#set:";
        if (!function.Name.StartsWith(setterPrefix,
                StringComparison.Ordinal))
        {
            return false;
        }
        var accessorIdentity = function.Name[setterPrefix.Length..];
        if (accessorIdentity != "this"
            && !accessorIdentity.EndsWith(":this",
                StringComparison.Ordinal))
        {
            return false;
        }
        var expectedGetterName = owner + ".#get:"
            + accessorIdentity;
        if (!propertyGetters.TryGetValue(expectedGetterName,
                out var getter)
            || getter.PropertyName != propertyName
            || getter.IsStatic
            || getter.ParameterCount < 2
            || getter.ParameterCount > getter.Variables.Length
            || function.ReturnType != PrimitiveType.Void
            || function.ParameterCount != getter.ParameterCount + 1
            || function.ParameterCount > function.Variables.Length
            || function.Variables[function.ParameterCount - 1].Type
                != getter.ReturnType
            || function.Variables[function.ParameterCount - 1].IsOut
            || function.Variables[function.ParameterCount - 1]
                .IsImplicitRef
            || function.Variables[function.ParameterCount - 1]
                .IsCanonicalImplicitReference)
        {
            return false;
        }

        for (var index = 1; index < getter.ParameterCount; index++)
        {
            var getterParameter = getter.Variables[index];
            var setterParameter = function.Variables[index];
            if (getterParameter.Type != setterParameter.Type
                || getterParameter.IsOut != setterParameter.IsOut
                || getterParameter.IsInit != setterParameter.IsInit
                || getterParameter.IsImplicitRef
                    != setterParameter.IsImplicitRef
                || getterParameter.IsCanonicalImplicitReference
                    != setterParameter.IsCanonicalImplicitReference
                || getterParameter.IsOut)
            {
                return false;
            }
        }

        return true;
    }

    private static ArgumentException Invalid() =>
        new("Invalid bound program.", "program");
    private static ArgumentException Invalid(TextSpan span)
    {
        var exception = Invalid();
        exception.Data[SourceSpanKey] = span;
        return exception;
    }
    private static ArgumentException InvalidEffect(TextSpan span, string contract = "NoThrow")
    {
        var exception = Invalid(span);
        exception.Data[InvalidEffectKey] = contract;
        return exception;
    }

    private static ArgumentException InvalidNoFailureEffect(BoundFunction function, TextSpan span) =>
        InvalidEffect(span, function.NoFailureProof ? "NoThrow" : "NativeCallable");

    private static NotSupportedException Limit() => new("Bound program exceeds native resource limits.");
}
